window.DTCX=window.DTCX||{};DTCX.B0=[{"c":"B0001","t":"Fahrer-Frontairbag Stufe 1 Auslösesteuerung","e":"Driver Frontal Stage 1 Deployment Control","d":"Das Airbag-Steuergerät prüft den Zündkreis der ersten Treibsatzstufe im Fahrerairbag; das Modul sitzt in der Lenkradnabe und hängt über die Wickelfeder am Kabelbaum. B0001 wird abgelegt, wenn dieser Kreis unterbrochen, kurzgeschlossen oder außerhalb seines Widerstandsfensters ist – das angehängte Fehlerbyte nennt die Art. Belegt ist der Code bei Mercedes-Benz (B000113: Zündpille Stufe 1 unterbrochen), Honda (Civic 2013, B0001-13), Mitsubishi (Fahrerairbagmodul), FCA (Zündpille 1) und GM: Bei den großen Pick-ups und SUVs 2020–21 trieben Rostpartikel am Airbagstecker den Widerstand hoch (B0001-1B, Bulletin 21-NA-005). Die erste Stufe zündet bei jeder Auslösung; fällt sie aus, fehlt dem Fahrer womöglich der Frontairbag. Die Airbag-Warnleuchte bleibt an.","u":[["h","Korrodierter oder schlecht sitzender Stecker zwischen Lenkradkabelbaum und Airbagmodul"],["m","Gerissene oder verschlissene Leiterbahn in der Wickelfeder"],["m","Innerer Fehler im Fahrerairbagmodul (Zündpille Stufe 1)"],["l","Durchgescheuerte Leitung im Lenkrad- oder Lenksäulenkabelbaum"]],"s":["Airbag-Warnleuchte oder Meldung „Airbag prüfen“ dauerhaft an","Fahrer-Frontairbag löst im Crash möglicherweise nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["driver_airbag_module","clock_spring","srs_wiring","srs_control_module"],"r":["shop_only",0,[150,1200],[1,3]],"f":"","x":["B0002","B0003","B0010"]},{"c":"B0002","t":"Fahrer-Frontairbag Stufe 2 Auslösesteuerung","e":"Driver Frontal Stage 2 Deployment Control","d":"Zweistufige Fahrerairbags tragen eine zweite Ladung, die das Steuergerät nur bei schweren Unfällen oder verzögert zündet, damit das Kissen härter oder länger gefüllt bleibt; ein Nissan-Patent macht das an der Geschwindigkeitsänderung und am Gurtstatus fest. B0002 meldet einen Fehler im Zündkreis dieser zweiten Stufe. Land Rover beschreibt B0002-13 beim Evoque als offenen Stufe-2-Kreis, der auch nach einem Steuergerätetausch mit zu alter Software auftrat (SSM 74577). Mercedes-Benz, Mitsubishi und FCA führen ihn als Zündpille bzw. Modul 2 des Fahrers, GM als Lenkradmodul Stufe 2. Da beide Stufen Stecker und Wickelfeder teilen, steht B0002 oft neben B0001; allein deutet er auf Leitung oder Zündpille der Stufe 2. Die angepasste Füllung entfällt, die Airbag-Leuchte brennt.","u":[["h","Unterbrochene Zuleitung der Zündpille Stufe 2 am Airbagstecker"],["m","Leiterbahn der Stufe 2 in der Wickelfeder gerissen"],["l","Ersatz-Airbagsteuergerät mit unpassender Software bespielt (Land Rover SSM 74577)"]],"s":["Airbag-Warnleuchte an","Fahrerairbag verliert die zweite Stufe für schwere Unfälle","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["driver_airbag_module","clock_spring","srs_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[0.5,3]],"f":"","x":["B0001","B0003","B0011"]},{"c":"B0003","t":"Fahrer-Frontairbag Stufe 3 Auslösesteuerung","e":"Driver Frontal Stage 3 Deployment Control","d":"Manche Fahrerairbags besitzen neben den beiden Treibsatzstufen ein drittes pyrotechnisches Element; B0003 betrifft dessen Zündkreis. FCA führt den Code als Zündpille 3 des Fahrer-Frontairbags; im STAR-Fall S2108000180 stand B0003-2B (Leitungen untereinander kurzgeschlossen) neben B0001 und B0002, weil Steckersicherungen hinter dem Lenkrad nicht eingerastet waren. Mercedes-Benz nutzt B000313 für die Zündpille des Abströmventils im Fahrerairbag, das Gas ablässt und das Kissen weicher macht. Ein FCA-Patent beschreibt eine solche aktive Entlüftung, die die Airbagelektronik je nach Insassenerkennung öffnet oder geschlossen hält. Ist dieser Kreis gestört, fehlen dritte Stufe bzw. Abströmsteuerung; die beiden Treibsatzstufen können weiter funktionieren. Die Airbag-Warnleuchte ist an.","u":[["h","Steckersicherung (CPA) am Airbagmodul nicht eingerastet"],["m","Dritte Zündpille bzw. Zündpille des Abströmventils im Airbagmodul defekt"],["l","Beschädigte Leiterbahn der Wickelfeder für den dritten Kreis"]],"s":["Airbag-Warnleuchte an, oft zusammen mit B0001 oder B0002","Abströmsteuerung bzw. dritte Auslösestufe nicht verfügbar","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["driver_airbag_module","clock_spring","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,1200],[0.5,3]],"f":"","x":["B0001","B0002","B0012"]},{"c":"B0004","t":"Fahrer-Kniepolster (Knieairbag) Auslösesteuerung","e":"Driver Knee Bolster Deployment Control","d":"Der Knieairbag, auch aktives Kniepolster genannt, sitzt in der unteren Armaturentafel unter der Lenksäule. Er füllt den Raum vor den Knien des Fahrers und hält den Unterkörper im Frontalaufprall zurück, vor allem bei nicht angeschnallten Insassen. B0004 meldet einen Fehler in seinem Zündkreis. Mercedes-Benz legt B000413 für eine unterbrochene Zündpille des Fahrer-Kniebags ab. Ford nennt B0004:1A zusammen mit dem Beifahrer-Code B0013 beim Ranger 2024 und führt ihn auf bestimmte Airbagstecker zurück, erkennbar an einer Formnummer an der Verriegelung (TSB 24-2444). Eine IIHS-Auswertung von über 400 Crashtests fand für angeschnallte Dummys nur einen kleinen Nutzen. Das Steuergerät überwacht den Kreis trotzdem, die Airbag-Leuchte bleibt bis zur Reparatur an.","u":[["h","Fehlerhafter oder loser Knieairbag-Stecker unter der Armaturentafel (Ford TSB 24-2444)"],["m","Kabelbaum bei Arbeiten unter der Lenksäule eingeklemmt oder beschädigt"],["l","Innerer Fehler im Knieairbagmodul"]],"s":["Airbag-Warnleuchte an","Fahrer-Knieairbag löst im Frontalcrash womöglich nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["knee_airbag_module","srs_wiring","srs_control_module"],"r":["shop_only",0,[100,900],[1,3]],"f":"","x":["B0013","B0001","B0014"]},{"c":"B0005","t":"Zusammenschiebbare Lenksäule Auslösesteuerung","e":"Collapsible Steering Column Deployment Control","d":"Manche Lenksäulen können verändern, wie viel Energie sie beim Zusammenschieben im Frontalaufprall aufnehmen. In einem Delphi/Nexteer-Patent zündet ein Steuergerät pyrotechnische Aktoren, die einen Absorberstreifen in eine engere Bahn zwingen oder weitere Absorber zuschalten – passend zu Fahrergröße und Unfallschwere. B0005 ist der Code des Airbagsteuergeräts für den Zündkreis eines solchen Aktors. Land Rover belegt B0005-56 (Konfiguration ungültig oder unpassend) beim Evoque ab 2018, wenn ein Ersatz-Steuergerät ältere Software als ab Werk erhalten hatte; ein manueller Patch des Diagnosegeräts behebt das (SSM 74577). FMVSS 204 begrenzt den Rückweg der Säule im 48-km/h-Barrierentest auf 127 mm. Bei gestörtem Kreis bleibt die Säule im festen Grundverhalten, die Airbag-Leuchte ist an.","u":[["h","Konfiguration oder Software des Airbagsteuergeräts passt nicht zum Fahrzeug (Land Rover SSM 74577)"],["m","Unterbrochene oder kurzgeschlossene Leitung zum pyrotechnischen Lenksäulenaktor"],["l","Defekter Aktor in der Lenksäule"]],"s":["Airbag-Warnleuchte an","Angepasste Energieaufnahme der Lenksäule nicht verfügbar, normales Lenken unbeeinflusst","Sicherheitshinweis: Der Lenksäulenaktor ist pyrotechnisch; Prüfungen und Steckerarbeiten der Werkstatt überlassen, Batterie vorher abklemmen"],"k":["collapsible_steering_column","squib_circuit","srs_control_module"],"r":["shop_only",0,[100,1500],[0.5,4]],"f":"","x":["B0001","B0004"]},{"c":"B0006","t":"Fahrer-Frontairbag Auslösekreis Kurzschluss nach Masse","e":"Driver Frontal Deployment Loop Short to Ground","d":"B0006 fehlt in den öffentlichen J2012-Codelisten, die von B0005 direkt zu B0010 springen. Die einzige gefundene Verwendung hat mit Airbags nichts zu tun: Beim Ram 1500 Modelljahr 2025 legt das Karosseriesteuergerät B0006-11 für einen Masseschluss in der Verriegelungsansteuerung des linken RamBox-Staufachdeckels ab, behoben per Software-Update (Flash 08-204-24). Der Titel beschreibt einen Masseschluss im Zündkreis des Fahrer-Frontairbags. Heutige Airbagsteuergeräte melden das als Fehlerbyte am Stufen-Code, etwa GM B0012 02 beim Saab 9-4X 2011 nach zwei Sekunden Masseschluss. Ein solcher Kurzschluss kann die Zündung der Stufe verhindern; deshalb zuerst klären, welches Steuergerät B0006 gespeichert hat, bevor jemand am Airbag arbeitet.","u":[["m","Beim Ram 1500 (2025) gehört der Code zum Verriegelungskreis des linken Staufachdeckels im Karosseriesteuergerät, nicht zum Airbag"],["m","Zündpillenleitung des Fahrerairbags an Metall durchgescheuert (Masseschluss)"],["l","Isolationsschaden in der Wickelfeder"]],"s":["Airbag-Warnleuchte an, wenn das Airbagsteuergerät den Code speichert","Beim Ram 1500 (2025) öffnet der Staufachdeckel elektrisch nicht, Alarm kann auslösen","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["driver_airbag_module","srs_wiring","clock_spring"],"r":["shop_only",0,[80,1000],[0.5,3]],"f":"","x":["B0007","B0001","B0016"]},{"c":"B0007","t":"Fahrer-Frontairbag Auslösekreis Kurzschluss nach Plus","e":"Driver Frontal Deployment Loop Short to Battery","d":"Wie B0006 fehlt auch diese Nummer in den öffentlichen J2012-Listen. FCA nutzt B0007-11 beim Ram 1500 (2025) für die Verriegelungsansteuerung des rechten RamBox-Staufachdeckels – ebenfalls ein Masseschluss im Karosseriesteuergerät, behoben mit demselben Flash 08-204-24; eine Airbag-Bedeutung ist nirgends belegt. Der Titel nennt einen Kurzschluss nach Plus im Zündkreis des Fahrer-Frontairbags. Airbagsteuergeräte führen das als Fehlerart am Stufen-Code: GM setzt beim Saab 9-4X B0012 01 oder B0013 01, wenn der Lenkradairbagkreis zwei Sekunden an Versorgungsspannung liegt. Plusschluss ist der heiklere Fall, weil ein zweiter Fehler die Zündpille bestromen könnte; Steuergeräte sperren dann meist die Stufe und schalten die Leuchte ein. Vor jeder Reparatur das speichernde Steuergerät feststellen.","u":[["m","Beim Ram 1500 (2025) gehört der Code zum Verriegelungskreis des rechten Staufachdeckels im Karosseriesteuergerät"],["m","Zündpillenleitung berührt eine spannungsführende Leitung im Lenksäulen- oder Lenkradkabelbaum"],["l","Feuchtigkeit überbrückt Kontakte in einem Stecker des Airbagkreises"]],"s":["Airbag-Warnleuchte an, betroffene Stufe vom Steuergerät gesperrt","Beim Ram 1500 (2025) rechter Staufachdeckel ohne Funktion","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["driver_airbag_module","srs_wiring","clock_spring"],"r":["shop_only",0,[80,1000],[0.5,3]],"f":"","x":["B0006","B0002","B0017"]},{"c":"B0010","t":"Beifahrer-Frontairbag Stufe 1 Auslösesteuerung","e":"Passenger Frontal Stage 1 Deployment Control","d":"Der Beifahrer-Frontairbag in der Armaturentafel ist meist wie der Fahrerairbag zweistufig, hängt aber zusätzlich an der Insassenerkennung: FMVSS 208 erlaubt, ihn für kleine Insassen abzuschalten, und verlangt eine Bereitschaftsanzeige, die das System überwacht. B0010 meldet einen Fehler im Zündkreis der ersten Stufe. Mercedes-Benz legt B001013 für eine unterbrochene Zündpille Stufe 1 des Beifahrerairbags ab, Mitsubishi führt B0010 beim Beifahrerairbagmodul mit mehreren Fehlerbytes. Eine gewollte Abschaltung ist kein Fehler und setzt den Code nicht; B0010 heißt, dass Leitung oder Zündpille der Stufe 1 elektrisch außerhalb der Grenzen liegen. Typische Stellen sind der Stecker hinter der Armaturentafel und die Leitung am Handschuhfach. Der Beifahrerairbag löst womöglich nicht aus, die Leuchte bleibt an.","u":[["h","Loser, korrodierter oder nicht verriegelter Stecker am Beifahrerairbagmodul"],["m","Kabelbaum bei Arbeiten an Armaturentafel oder Handschuhfach beschädigt"],["l","Innerer Fehler im Beifahrerairbagmodul (Zündpille Stufe 1)"]],"s":["Airbag-Warnleuchte an","Beifahrer-Frontairbag löst im Crash womöglich nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["passenger_airbag_module","srs_wiring","srs_control_module"],"r":["shop_only",0,[100,1300],[0.5,4]],"f":"","x":["B0011","B0012","B0001"]},{"c":"B0011","t":"Beifahrer-Frontairbag Stufe 2 Auslösesteuerung","e":"Passenger Frontal Stage 2 Deployment Control","d":"B0011 ist das Gegenstück zu B0002 auf der Beifahrerseite: Es geht um die zweite Treibsatzstufe des Armaturentafel-Airbags, die das Steuergerät bei schweren Unfällen zuschaltet oder verzögert zündet. Mercedes-Benz legt B001113 für eine unterbrochene Zündpille Stufe 2 des Beifahrerairbags ab, Mitsubishi nennt B0011 das Beifahrerairbagmodul 2. Stufe 1 desselben Airbags hat den eigenen Code B0010, ein drittes Element B0012. Da beide Stufen über einen Stecker laufen, deutet ein Fehler nur an Stufe 2 meist auf deren Kontakte, Leitung oder Zündpille und weniger auf den ganzen Stecker. Ältere GM-Steuergeräte (Saab 9-3 bis 2011) führten Fehler der Beifahrerstufe 2 dagegen unter B0012 bis B0014. Die Leuchte ist an, die angepasste Füllung für den Beifahrer entfällt.","u":[["h","Schlechter Kontakt an den Stufe-2-Pins oder unterbrochene Stufe-2-Leitung"],["m","Zündpille Stufe 2 im Beifahrerairbagmodul defekt"],["l","Endstufe im Airbagsteuergerät defekt"]],"s":["Airbag-Warnleuchte an","Beifahrerairbag verliert die zweite Stufe für schwere Unfälle","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["passenger_airbag_module","srs_wiring","srs_control_module"],"r":["shop_only",0,[100,1300],[0.5,4]],"f":"","x":["B0010","B0012","B0002"]},{"c":"B0012","t":"Beifahrer-Frontairbag Stufe 3 Auslösesteuerung","e":"Passenger Frontal Stage 3 Deployment Control","d":"In der J2012-Reihenfolge ist B0012 das dritte Element des Beifahrer-Frontairbags. Mercedes-Benz nutzt B001213 für die Zündpille des Abströmventils dieses Airbags, Mitsubishi führt B0012 als Beifahrerairbagmodul 3. GM belegt die Nummer anders: Seine neueren Airbagsteuergeräte ordnen B0012 der Stufe 1 des Lenkradairbags zu; laut Handbuch des Saab 9-4X 2011 genügen zwei Sekunden Kontakt zu Plus oder Masse, eine Unterbrechung, mehr als 4,4 oder weniger als 1,7 Ohm. GM-Bulletins verbinden ihn mit durchgescheuerten Wickelfederleitungen im Cobalt 2009 und zu geringer Kontaktkraft am Wickelfederstecker im CTS 2015. Ältere Saab-9-3-Steuergeräte meldeten mit B0012 einen zu kleinen Widerstand im Beifahrerkreis Stufe 2. Vor der Suche den Code mit dem Herstellertester einordnen.","u":[["m","Dritte Zündpille (Abströmventil) im Beifahrerairbag unterbrochen oder kurzgeschlossen (J2012-Bedeutung)"],["h","Bei GM zu geringe Kontaktkraft oder durchgescheuerte Leitungen an der Lenkrad-Wickelfeder"],["l","Fehler im Airbagsteuergerät"]],"s":["Airbag-Warnleuchte an","Je nach Hersteller Abströmsteuerung des Beifahrerairbags oder bei GM Fahrerairbag Stufe 1 betroffen","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["passenger_airbag_module","driver_airbag_module","clock_spring","srs_wiring","srs_control_module"],"r":["shop_only",0,[100,1300],[0.5,4]],"f":"","x":["B0010","B0011","B0003"]},{"c":"B0013","t":"Beifahrer-Kniepolster (Knieairbag) Auslösesteuerung","e":"Passenger Knee Bolster Deployment Control","d":"B0013 gehört zum Knieairbag auf der Beifahrerseite, der aus dem unteren Handschuhfachbereich auslöst und verhindert, dass Knie und Oberschenkel unter die Armaturentafel rutschen. Mercedes-Benz legt B001313 für eine unterbrochene Zündpille des Beifahrer-Kniebags ab. Ford stellt B0013:1A beim Ranger 2024 neben den Fahrer-Code B0004; laut TSB werden alle vier Airbagstecker geprüft, der Beifahrer-Knieairbag hängt an C2433, Stecker mit falscher Formnummer werden ersetzt. GM nutzt dieselbe Nummer anders: In seinen neueren Steuergeräten ist B0013 die Stufe 2 des Lenkradairbags, mit denselben Fehlerbytes wie B0012 (Saab 9-4X 2011, GM-Kulanz Wickelfeder Cobalt 2009). Bei GM also am Lenkrad suchen, bei anderen Herstellern am Beifahrer-Knieairbag. Die Airbag-Leuchte ist an.","u":[["h","Fehlerhafter Stecker am Beifahrer-Knieairbag (Ford TSB 24-2444)"],["m","Bei GM Fehler im Kreis Stufe 2 des Fahrerairbags oder in der Wickelfeder"],["l","Innerer Fehler im Beifahrer-Knieairbag"]],"s":["Airbag-Warnleuchte an","Beifahrer-Knieairbag (bei GM Fahrerairbag Stufe 2) löst womöglich nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["knee_airbag_passenger","squib_circuit","srs_control_module"],"r":["shop_only",0,[100,900],[1,3]],"f":"","x":["B0004","B0010","B0015"]},{"c":"B0014","t":"Fahrer-Knieairbag Auslösesteuerung","e":"Driver Knee Airbag Deployment Control","d":"B0014 steht nicht in den öffentlichen J2012-Codelisten; dort hat der Fahrer-Knieairbag B0004 und der Beifahrer-Knieairbag B0013. Belegt ist die Nummer nur bei General Motors, und zwar mit anderer Bedeutung: GM-Steuergeräte ab etwa 2010 verwenden B0014 für den Seitenairbag im Fahrersitz; das Handbuch des Saab 9-4X 2011 hängt je Fehlerart ein Byte an, vom Kurzschluss oder offenen Kreis bis zu hohem (0D, über 4,2 Ohm) oder niedrigem Messwert (0E, unter 1,4 Ohm). GM-Bulletins nennen durchgescheuerte oder lose Sitzkabelstecker und zu hohen Übergangswiderstand bei Silverado und Tahoe 2014–15, Equinox, Traverse und Bolt EV. Ältere Saab-9-3-Steuergeräte meldeten mit B0014 einen Kurzschluss im Beifahrerkreis Stufe 2. Eine Knieairbag-Bedeutung ist für diesen Code öffentlich nicht nachweisbar.","u":[["h","Bei GM loser oder hochohmiger Seitenairbagstecker unter oder im Fahrersitz"],["m","Sitzkabelbaum an Sitzrahmen, Motor oder Polster durchgescheuert"],["l","Innerer Fehler im Airbagmodul dieses Kreises"]],"s":["Airbag-Warnleuchte oder Meldung „Airbag prüfen“, oft sporadisch","Betroffener Airbag löst womöglich nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["knee_airbag_module","driver_side_airbag","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0004","B0015","B0020"]},{"c":"B0015","t":"Beifahrer-Knieairbag Auslösesteuerung","e":"Passenger Knee Airbag Deployment Control","d":"B0015 erscheint nicht in den öffentlichen J2012-Codelisten, die den Beifahrer-Knieairbag unter B0013 führen. Nur General Motors dokumentiert die Nummer, und zwar als Zündkreis des Gurtstraffers am Aufrollautomaten des Fahrers. Im Saab-9-4X-Handbuch von 2011 teilt sich dieser Straffer eine Diagnoseseite mit B001A, dem Straffer am Endbeschlag; beide werden gesetzt, wenn ihr Kreis zwei Sekunden außerhalb des zulässigen Widerstandsbands liegt oder Plus bzw. Masse berührt. Beim Impala 2009–11 weist GM darauf hin, dass B0015 den Aufrollstraffer meint, während ein zweiter Straffer am Gurtanker sitzt (PIC5396A). Beim Equinox scheuerte eine Leitung unter dem elektrischen Sitz am Sitzmotor, setzte B0014 und B0015 und ließ die Sitzsicherung durchbrennen (PIT4898C). Ein Beifahrer-Knieairbag unter dieser Nummer ist öffentlich nicht belegt.","u":[["h","Bei GM loser oder korrodierter Stecker am Gurtstraffer des Fahrers"],["m","Kabelbaum unter dem elektrischen Sitz scheuert an Rahmen oder Sitzmotor (GM PIT4898C)"],["l","Innerer Fehler im Straffer bzw. Airbag dieses Kreises"]],"s":["Airbag-Warnleuchte an, teils sporadisch","Bei GM zündet der Gurtstraffer womöglich nicht; bei Kurzschluss im Kabelbaum fällt der elektrische Sitz aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["knee_airbag_module","driver_seatbelt_pretensioner","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,700],[0.5,3]],"f":"","x":["B0013","B0014","B001A"]},{"c":"B0016","t":"Beifahrer-Frontairbag Auslösekreis Kurzschluss nach Masse","e":"Right Front/Passenger Frontal Deployment Loop Short to Ground","d":"B0016 steht nicht in den öffentlichen J2012-Codelisten. General Motors nutzte ihn in zwei Generationen mit unterschiedlicher Bedeutung. In älteren Steuergeräten, belegt für Saab 9-5 (2006) und Saab 9-3 bis 2011, heißt B0016 zu kleiner Widerstand im Beifahrer-Frontkreis Stufe 1: gemessen werden unter 1,5 Ohm (±0,2) für zwei Sekunden. Das liegt nahe am Titel, denn ein Masseschluss oder ein Schluss zwischen den Leitungen drückt den Messwert ebenfalls nach unten. In neueren GM-Steuergeräten (Saab 9-4X 2011) ist B0016 der Kreis des linken Dachrahmen-Kopfairbags, mit eigenen Bytes für Masseschluss (02) und Widerstand unter 1,4 Ohm (0E). GM-Bulletin 08-09-41-002H zählt B0016 zu den Codes, die nicht eingerastete Steckersicherungen bei vielen GM-Modellen 2005–14 auslösten. Die Airbag-Leuchte ist jeweils an.","u":[["h","Zündpillenleitungen im Beifahrer-Frontkreis untereinander oder gegen Masse geschlossen (ältere GM)"],["m","Steckersicherung nicht eingerastet (GM 08-09-41-002H)"],["m","Bei neueren GM-Fahrzeugen Fehler im Kreis des linken Kopfairbags"]],"s":["Airbag-Warnleuchte an","Beifahrer-Frontairbag Stufe 1 (ältere GM) bzw. linker Kopfairbag (neuere GM) löst womöglich nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["passenger_airbag_module","srs_wiring"],"r":["shop_only",0,[80,1200],[0.5,4]],"f":"","x":["B0017","B0010","B0006"]},{"c":"B0017","t":"Beifahrer-Frontairbag Auslösekreis Kurzschluss nach Plus","e":"Right Front/Passenger Frontal Deployment Loop Short to Battery","d":"Auch B0017 fehlt in den öffentlichen J2012-Codelisten. In älteren GM-Steuergeräten (Saab 9-5 2006, Saab 9-3 bis 2011) steht er für einen unterbrochenen Beifahrer-Frontkreis Stufe 1, gesetzt bei mehr als 4,5 Ohm (±0,2) über zwei Sekunden – das Bauteil passt zum Titel, die Fehlerart nicht. Neuere GM-Fahrzeuge führen B0017 mit den üblichen GM-Fehlerbytes, bei denen 01 Plusschluss bedeutet. Bei Acadia, XT4 und verwandten Modellen 2020–22 führte GM B0017 01 zusammen mit B0024 01 und B001E 01 auf fehlerhafte Software im Airbagsteuergerät zurück, nicht auf die Verkabelung: Code löschen, Steuergerät neu programmieren (PIT5827, 21-NA-176). Als Teile nennt GM dort den Knieairbag und den inneren Seitenairbag des Fahrersitzes. Die Airbag-Leuchte ist an.","u":[["h","Bei GM-Modellen 2020–22 fehlerhafte Steuergerätesoftware, behoben durch Neuprogrammierung (21-NA-176)"],["m","Unterbrochener Beifahrer-Frontkreis Stufe 1 (ältere GM-Bedeutung)"],["l","Zündpillenleitung berührt eine spannungsführende Leitung"]],"s":["Airbag-Warnleuchte an oder OnStar-Hinweis zum Rückhaltesystem ohne Leuchte","Betroffene Airbagstufe womöglich gesperrt","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["passenger_airbag_module","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,1200],[0.5,3]],"f":"","x":["B0016","B0011","B0007"]},{"c":"B0018","t":"Mittlerer Frontairbag Stufe 1 Auslösesteuerung","e":"Center Frontal Stage 1 Deployment Control","d":"In der J2012-Reihenfolge der Sitzplätze (Fahrer, Beifahrer, Mitte, dann zweite und dritte Reihe) betrifft B0018 die Stufe 1 eines Frontairbags für den mittleren Platz der ersten Reihe. FMVSS 208 verlangt Frontairbags nur an den äußeren Vordersitzen, solche Airbags sind daher selten, und kein Hersteller dokumentiert B0018 öffentlich in dieser Bedeutung. Gemeint ist nicht der GM-Mittelairbag von 2013, der bei Seitenaufprall aus der Innenseite des Fahrersitzes kommt (SAE 2013-01-1156). GM nutzte B0018 selbst in älteren Steuergeräten: Beim Saab 9-5 2006 meldet er Spannung außerhalb des Bereichs im Beifahrer-Frontkreis Stufe 1, über 4,1 V oder unter 1,0 V an Pin 44 für zwei Sekunden, beim Saab 9-3 Plus- oder Masseschluss in diesem Kreis. Erst klären, welches Steuergerät den Code gespeichert hat.","u":[["m","Kreis Stufe 1 eines mittleren Frontairbags der ersten Reihe unterbrochen oder kurzgeschlossen (J2012-Bedeutung)"],["m","Bei älteren GM/Saab Plus- oder Masseschluss im Beifahrer-Frontkreis Stufe 1"],["l","Fehler im Airbagsteuergerät"]],"s":["Airbag-Warnleuchte an","Betroffene Frontairbag-Stufe löst womöglich nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["center_frontal_airbag","squib_circuit","srs_control_module"],"r":["shop_only",0,[100,1300],[0.5,4]],"f":"","x":["B0019","B001A","B0010"]},{"c":"B0019","t":"Mittlerer Frontairbag Stufe 2 Auslösesteuerung","e":"Center Frontal Stage 2 Deployment Control","d":"B0019 ist das Stufe-2-Glied der Reihe B0018 bis B001A für den mittleren Frontairbag der ersten Reihe, gedacht für die zweite Treibladung eines solchen Airbags. Kein Hersteller dokumentiert den Code öffentlich in dieser Bedeutung. General Motors verwendet B0019 häufig, aber für den Zündkreis Stufe 1 des Beifahrerairbags in der Armaturentafel: Beim Saab 9-4X 2011 stehen die Unterbytes 01 und 02 für Kurzschlüsse, 04 für Unterbrechung, 0D für dauerhaft zu hohen und 0E für zu niedrigen Kreiswiderstand; Stufe 2 dieses Airbags ist B0020. Beim Chevrolet HHR 2009–10 ließ Reibkorrosion im Zwischenstecker zwischen Karosserie- und Armaturentafelkabelbaum den Widerstand steigen und setzte B0019 0D oder 04 (PI0117B, Kundenzufriedenheitsaktion). Bei GM also zuerst den Beifahrerairbag prüfen. Die Airbag-Leuchte ist an.","u":[["h","Bei GM Reibkorrosion im Zwischenstecker des Beifahrerairbags (HHR PI0117B)"],["l","Fehler im Kreis Stufe 2 eines mittleren Frontairbags der ersten Reihe (J2012-Bedeutung)"],["l","Innerer Fehler im Airbagmodul dieses Kreises"]],"s":["Airbag-Warnleuchte an","Bei GM löst Stufe 1 des Beifahrer-Frontairbags womöglich nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["center_frontal_airbag","passenger_airbag_module","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,1300],[0.5,4]],"f":"","x":["B0018","B001A","B0010"]},{"c":"B001A","t":"Mittlerer Frontairbag Stufe 3 Auslösesteuerung","e":"Center Frontal Stage 3 Deployment Control","d":"B001A schließt die Reihe für den mittleren Frontairbag der ersten Reihe ab und steht für dessen dritte Stufe – analog zu B0003 beim Fahrer und B0012 beim Beifahrer. Kein Hersteller dokumentiert ihn öffentlich in diesem Sinn. Bei General Motors gehört die Nummer zum Endbeschlag-Gurtstraffer des Fahrers, einem zweiten Straffer am unteren Gurtanker neben dem Aufrollstraffer mit Code B0015. Die Grenzen gleichen den übrigen GM-Zündkreisen: Liegt der Strafferkreis zwei Sekunden oberhalb von 4,2 Ohm oder unterhalb von 1,4 Ohm, wird der Code gesetzt, ebenso bei Kurzschluss und Unterbrechung. GM-Bulletins melden ihn beim Impala 2009–11 mit eingeklemmtem oder falsch verlegtem Strafferkabel (PIC5396A, 15-NA-074) und bei Equinox und Traverse 2018 (PIE0438). Bei GM also zuerst am unteren Gurtanker suchen. Die Airbag-Leuchte ist an.","u":[["h","Bei GM eingeklemmtes, falsch verlegtes oder korrodiertes Kabel des Endbeschlagstraffers"],["l","Fehler im Kreis der dritten Stufe eines mittleren Frontairbags der ersten Reihe (J2012-Bedeutung)"],["l","Innerer Fehler im Gurtstraffer"]],"s":["Airbag-Warnleuchte an","Bei GM zündet der Endbeschlagstraffer des Fahrers womöglich nicht","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["center_frontal_airbag","driver_seatbelt_pretensioner","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,2.5]],"f":"","x":["B0018","B0019","B0015"]},{"c":"B0020","t":"Seitenairbag links Auslösesteuerung","e":"Left Side Airbag Deployment Control","d":"Hinter B0020 steht der Zündkreis des linken vorderen Seitenairbags, meist ein Thoraxairbag in der äußeren Wange der Fahrersitzlehne. Toyota führt beim Tundra 2022 B002011 und B002012 als Masse- bzw. Plusschluss; dort löste das kabellose Handy-Ladefach Fehleinträge aus, die neue SRS-Software beseitigt (TSB005722). FCA versteht B0020-13 bei Cherokee 2014–17 und Chrysler 200 2015–17 als offene Zündpille im linken Sitz und tauscht die Zwischenkabel in den Sitzen (10-001-20). Honda sammelte Teile von Accord, CR-V und TLX mit demselben Byte 13; Mitsubishi bestätigt jeden Fehler nach 2 Sekunden. GM-Steuergeräte etwa der Jahre 2007–14 belegen B0020 dagegen mit Beifahrer-Frontairbag Stufe 2 – also prüfen, welches Bauteil der Tester nennt. Die Airbag-Leuchte brennt.","u":[["h","Schlechter Kontakt oder Korrosion am Seitenairbagstecker bzw. Zwischenkabel unter oder im Sitz"],["m","Innerer Fehler im linken Sitz-Seitenairbagmodul"],["m","Eingeklemmte oder durchgescheuerte Seitenairbagleitung im Sitzgestell"],["l","Steuergerätesoftware reagiert auf Störungen, z. B. Toyota Tundra 2022 mit kabellosem Ladefach"]],"s":["Airbag-Warnleuchte an","Linker vorderer Seitenairbag löst bei einem Seitenaufprall eventuell nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["left_side_airbag_module","srs_control_module","srs_seat_wiring","seat_harness_connector"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0028","B0021","B0030"]},{"c":"B0021","t":"Kopfairbag links Auslösesteuerung 1","e":"Left Curtain Deployment Control 1","d":"Nach der J2012-Reihenfolge ist B0021 der erste Zündkreis des linken Kopfairbags, der sich vom Dachrahmen über die Seitenscheiben entfaltet. Mitsubishi ordnet ihn dem linken Curtain-Modul zu und legt Byte 11, 12, 13 oder einen Schluss zu einem anderen Kreis ab, sobald der Zustand 2 Sekunden besteht. Mercedes-Benz liest B002113 bei A-Klasse, CLA und GLB als offene Zündpille des linken Windowbags; Ursache war erhöhter Übergangswiderstand am Stecker des Airbagsteuergeräts (LI54.21-P-070658). Kreis 1 gehört zum einzigen bzw. vorderen Gasgenerator des Vorhangs, B0022 zum zweiten. GM-Steuergeräte der Global-A-Generation nutzen B0021 dagegen für den Seitenairbag im Beifahrersitz (Bulletins PI1469, 23-NA-030). Airbag-Leuchte an; der linke Kopfairbag zündet womöglich nicht.","u":[["h","Erhöhter Übergangswiderstand am Kopfairbag- oder Steuergerätestecker"],["m","Beschädigte Leitung an A-, B-, C-Säule oder Dachrahmen"],["m","Innerer Fehler im linken Kopfairbagmodul"],["l","Fehler oder unpassende Software im Airbagsteuergerät"]],"s":["Airbag-Warnleuchte an","Linker Kopfairbag löst bei Seitenaufprall oder Überschlag eventuell nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["left_curtain_airbag","srs_roof_wiring","srs_control_module"],"r":["shop_only",0,[100,1000],[1,4]],"f":"","x":["B0022","B0029","B0020","B0046"]},{"c":"B0022","t":"Kopfairbag links Auslösesteuerung 2","e":"Left Curtain Deployment Control 2","d":"B0022 gehört zu einem zweiten Zündkreis des linken Kopfairbags. Wie das aussieht, zeigt Mercedes-Benz: Bei A-Klasse, CLA und GLB meldet B002213 eine offene Zündpille im linken hinteren Windowbag, also im Vorhangteil für die Rücksitze, während B0021 den vorderen Teil betrifft (LI54.21-P-070658, Fassung 1 von 2019 und Fassung 4 von 2020). Fahrzeuge mit nur einem Gasgenerator im Vorhang setzen den Code nie. Bei General Motors hat die Nummer ältere Bedeutungen: Der Saab 9-5 von 2006 meldet damit Widerstand unter 2,0 Ohm im Fahrer-Frontairbag Stufe 1, Global-A-Steuergeräte den Gurtstraffer am Beifahrer-Aufrollautomaten, etwa beim Impala 2009–11 (PIC5396A) oder Saab 9-4X. Welches Teil gemeint ist, zeigen Steuergerät und Klartext im Tester. Airbag-Leuchte an.","u":[["h","Erhöhter Übergangswiderstand am Steuergerätestecker (Mercedes LI54.21-P-070658)"],["m","Beschädigte Leitung zum hinteren Vorhangteil an C-Säule oder Dachrahmen"],["l","Innerer Fehler im hinteren linken Kopfairbagmodul"],["l","Fehler oder unpassende Software im Airbagsteuergerät"]],"s":["Airbag-Warnleuchte an","Kopfschutz für den linken Rücksitzplatz fehlt womöglich","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["left_curtain_airbag","srs_roof_wiring","srs_control_module"],"r":["shop_only",0,[100,1000],[1,4]],"f":"","x":["B0021","B002A","B0046"]},{"c":"B0023","t":"Seitenairbag links Stufe 1 Auslösekreis Kurzschluss nach Masse","e":"Left Side Deployment Stage 1 Loop Short to Ground","d":"In den J2012-Listen fehlt B0023 – sie springen von B0022 auf B0028 –, und kein Hersteller beschreibt ihn als Masseschluss einer linken Seitenairbagstufe. Belegt ist er bei General Motors mit anderer Bedeutung: Im Handbuch des Saab 9-4X 2011 steht B0023 für den Kreis des rechten Dachrahmen-Kopfairbags, mit Bytes für Plusschluss (01), Masseschluss (02), Unterbrechung (04) sowie Widerstand über 4,2 bzw. unter 1,4 Ohm (0D, 0E), jeweils nach 2 Sekunden bestätigt. Laut GM-Bulletin 08-09-41-002H entstand B0023 bei vielen Modellen 2005–14 durch Steckersicherungen, die nicht richtig eingerastet waren. Ein echter Masseschluss im Zündkreis kann die Auslösung verhindern; deshalb zuerst Steuergerät und Klartext im Tester lesen. Airbag-Leuchte an.","u":[["h","Steckersicherung nicht eingerastet, Kurzschlussbrücken überbrücken den Kreis (GM 08-09-41-002H)"],["m","Durchgescheuerte Leitung mit Kontakt zur Karosseriemasse"],["l","Innerer Fehler im betroffenen Airbagmodul"]],"s":["Airbag-Warnleuchte an","Der Airbag am betroffenen Kreis löst eventuell nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["driver_side_airbag","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0020","B0021","B0016"]},{"c":"B0024","t":"Seitenairbag rechts Auslösekreis","e":"Right Side Deployment Control","d":"In den öffentlichen J2012-Listen fehlt B0024; der rechte vordere Seitenairbag hat dort B0028. General Motors hat die Nummer zweimal vergeben. Ältere Steuergeräte wie im Saab 9-5 von 2006 und im Saab 9-3 meinen damit Fahrer-Frontairbag Stufe 1: Beim 9-5 verlässt die Spannung am Steuergerätepin 2 Sekunden lang das Fenster 1,0 bis 4,1 Volt, beim 9-3 hat der Kreis Masse- oder Plusschluss. 2021 nannte GM B0024 01 zusammen mit B0017 01 und B001E 01 bei Cadillac XT4 bis XT6, Blazer, Camaro, Malibu und Acadia als Softwarefehler des Steuergeräts, bezogen auf Knieairbag und inneren Seitenairbag am Fahrersitz; Abhilfe ist neue SDM-Software (PIT5827, 21-NA-176). Eine Bedeutung als rechter Seitenairbag ist nicht öffentlich belegt. Airbag-Leuchte an.","u":[["h","Softwarefehler im Airbagsteuergerät bei GM-Modellen 2021 (PIT5827, 21-NA-176)"],["m","Masse- oder Plusschluss im Kreis Fahrer-Frontairbag Stufe 1 (ältere GM/Saab)"],["m","Verschlissene Wickelfeder im Fahrerairbagkreis (ältere GM/Saab)"]],"s":["Airbag-Warnleuchte an","Je nach Fahrzeug ist der Fahrerairbag oder ein Sitz-Seitenairbag betroffen","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["right_side_airbag_module","srs_control_module","srs_wiring","seat_harness_connector"],"r":["shop_only",0,[0,900],[0.5,3]],"f":"","x":["B0028","B0020","B0001"]},{"c":"B0025","t":"Seitenairbag links Stufe 2 Auslösesteuerung","e":"Left Side Deployment Stage 2 Control","d":"B0025 steht in keiner öffentlichen J2012-Liste, und kein Hersteller beschreibt unter dieser Nummer eine zweite Stufe des linken Seitenairbags. Die einzige Spur führt zu General Motors: Das Handbuch des Saab 9-4X 2011 fasst B0025 mit den Dachrahmen-Kopfairbag-Codes B0016 und B0023 zusammen, nennt aber keinen Klartext dazu. Zweistufige Seitenairbags sind ohnehin selten. Ein Ford-Patent hält fest, dass Thorax-, Becken- und Kopfairbags wegen ihrer geringen Größe meist nur eine Füllart kennen, und der von Autoliv beschriebene Zweikammer-Seitenairbag teilt ein Kissen in Brust- und Beckenbereich, statt zweimal zu zünden. Taucht B0025 auf, entscheiden Klartext und Steuergerätename im Tester, was gemeint ist. Airbag-Leuchte an; der betroffene Airbag löst womöglich nicht aus.","u":[["m","Offener, kurzgeschlossener oder hochohmiger Zündkreis des Airbags, den das Steuergerät diesem Code zuordnet"],["m","Stecker oder Steckersicherung nicht vollständig eingerastet"],["l","Fehler oder unpassende Software im Airbagsteuergerät"]],"s":["Airbag-Warnleuchte an","Seiten- bzw. Kopfschutz auf der betroffenen Seite eventuell eingeschränkt","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["driver_side_airbag","srs_control_module"],"r":["shop_only",0,[80,1000],[0.5,3]],"f":"","x":["B0020","B0023","B0026"]},{"c":"B0026","t":"Seitenairbag links Stufe 2 Auslösekreis unterbrochen","e":"Left Side Deployment Stage 2 Loop Open","d":"In den öffentlichen J2012-Listen fehlt B0026. General Motors belegt ihn in älteren Airbagsteuergeräten mit einer anderen Bedeutung als der Titel: Beim Saab 9-5 von 2006 ist B0026 eine Unterbrechung im Fahrer-Frontairbag Stufe 1, gesetzt, wenn der gemessene Widerstand 2 Sekunden lang über 4,5 Ohm (±0,2) liegt; die Saab-9-3-Handbücher ergänzen Bytes für offenen Kreis und zu hohen Widerstand im selben Fahrerkreis. Das GM-Bulletin 08-09-41-002H führt B0026 bei Modellen 2005–14 wie Cobalt, Pontiac G5 und GMC Envoy auf nicht vollständig verriegelte Steckersicherungen zurück. Eine offene zweite Stufe des linken Seitenairbags ist unter diesem Code nicht öffentlich dokumentiert. Ist der Fahrerkreis offen, zündet der Lenkradairbag womöglich nicht. Airbag-Leuchte an.","u":[["h","Airbagstecker oder Steckersicherung nicht vollständig eingerastet (GM 08-09-41-002H)"],["m","Gerissene Leiterbahn in der Wickelfeder (Fahrerkreis bei älteren GM/Saab)"],["l","Unterbrochene Zündpille im Airbagmodul"]],"s":["Airbag-Warnleuchte an","Je nach Fahrzeug löst der Fahrerairbag eventuell nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["driver_side_airbag","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0022","B0024","B0001"]},{"c":"B0028","t":"Seitenairbag rechts Auslösesteuerung","e":"Right Side Airbag Deployment Control","d":"B0028 ist das rechte Gegenstück zu B0020: der Zündkreis des rechten vorderen Seitenairbags, meist in der äußeren Wange des Beifahrersitzes. Honda forderte Teile von Accord und CR-V 2018–20 sowie vom TLX 2015 mit B0028-13 an, also offenem oder erhöhtem Widerstand im Gasgenerator des Beifahrer-Seitenairbags. FCA führt B0028-13 bei Cherokee und Chrysler 200 auf das Zwischenkabel im Sitz zurück, und beim Toyota Tundra 2022 entstanden B002811 oder B002812, weil das kabellose Ladefach das Steuergerät störte. Mitsubishi bestätigt einen Masseschluss nach 2 Sekunden. Die ältere GM-Nummerierung weicht ab: Saab 9-5 (2006) und 9-3 meinen mit B0028 zu niedrigen Widerstand unter 1,5 Ohm im Kreis des Beifahrer-Seitenairbags. Airbag-Leuchte an.","u":[["h","Schlechter Kontakt oder Korrosion am Seitenairbagstecker bzw. Zwischenkabel unter oder im Sitz"],["m","Innerer Fehler im Gasgenerator des rechten Sitz-Seitenairbags"],["m","Leitung durch Sitzverstellung eingeklemmt oder überdehnt"],["l","Steuergerätesoftware reagiert auf Störungen (Toyota Tundra 2022)"]],"s":["Airbag-Warnleuchte an","Rechter vorderer Seitenairbag löst bei einem Seitenaufprall eventuell nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["right_side_airbag_module","srs_control_module","srs_seat_wiring","seat_harness_connector"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0020","B0029","B0038"]},{"c":"B0029","t":"Kopfairbag rechts Auslösesteuerung 1","e":"Right Curtain Deployment Control 1","d":"B0029 bezeichnet den ersten Zündkreis des rechten Kopfairbags. FCA deutet B0029-11 im STAR-Fall S2010000001 zum Ram-Schwerlastpickup 2019 als Masseschluss der Zündpille 1 im rechten Vorhang und schickt den Techniker zur Verkabelung an den Befestigungen der C-Säulen-Verkleidung. Mitsubishi führt das rechte Curtain-Modul unter B0029 und setzt den Masseschluss nach 2 Sekunden. Bei A-Klasse, CLA und GLB speichert Mercedes-Benz B002913 für eine offene Zündpille im rechten Windowbag. Ältere GM-Steuergeräte nutzten die Nummer für den Beifahrer-Seitenairbag: Der Saab 9-5 von 2006 setzt sie, wenn der Widerstand 2 Sekunden über 4,5 Ohm bleibt. Der zweite rechte Vorhangkreis ist B002A. Airbag-Leuchte an; der Kopfairbag öffnet bei Seitenaufprall oder Überschlag womöglich nicht.","u":[["h","Leitung an Säulenverkleidungs-Befestigungen eingeklemmt oder durchgescheuert (FCA S2010000001)"],["m","Erhöhter Übergangswiderstand am Kopfairbag- oder Steuergerätestecker"],["l","Innerer Fehler im rechten Kopfairbagmodul"]],"s":["Airbag-Warnleuchte an","Rechter Kopfairbag löst bei Seitenaufprall oder Überschlag eventuell nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["right_curtain_airbag","srs_roof_wiring","srs_control_module"],"r":["shop_only",0,[100,1000],[1,4]],"f":"","x":["B002A","B0021","B0028"]},{"c":"B002A","t":"Kopfairbag rechts Auslösesteuerung 2","e":"Right Curtain Deployment Control 2","d":"B002A ist der zweite Zündkreis des rechten Kopfairbags und kommt nur vor, wo rechts zwei Gasgeneratoren im Vorhang oder ein eigener Vorhangteil für die Rücksitze verbaut sind. So verwendet ihn Mercedes-Benz in A-Klasse, CLA und GLB: B002A13 zeigt eine offene Zündpille im rechten hinteren Windowbag an, der vordere Teil meldet sich über B0029; bekannter Auslöser war ein schlechter Kontakt am Steckanschluss des Steuergeräts (LI54.21-P-070658). Ein Patent von TRW und Ford beschreibt Vorhänge für erste und zweite Reihe, die getrennt gefüllt werden und an der B-Säule verbunden sein können. Lösen Kopfairbags auch beim Überschlag aus, verlangt FMVSS 226 eine für den Fahrer sichtbare Bereitschaftsanzeige. Airbag-Leuchte an; dem rechten Fondplatz fehlt womöglich der Kopfschutz.","u":[["h","Erhöhter Übergangswiderstand am Steuergerätestecker (Mercedes LI54.21-P-070658)"],["m","Beschädigte Leitung zum hinteren Vorhangteil an C-Säule oder Dachrahmen"],["l","Innerer Fehler im hinteren rechten Kopfairbagmodul"]],"s":["Airbag-Warnleuchte an","Kopfschutz für den rechten Rücksitzplatz fehlt womöglich","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["right_curtain_airbag","squib_circuit","srs_roof_wiring"],"r":["shop_only",0,[100,1000],[1,4]],"f":"","x":["B0029","B0022","B0038"]},{"c":"B0030","t":"Seitenairbag zweite Sitzreihe links Auslösesteuerung","e":"Second Row Left Side Airbag Deployment Control","d":"Bei J2012 umfasst der Block B003x die zweite Sitzreihe; B0030 ist der linke hintere Seitenairbag in der Fondtür oder der äußeren Rücklehne. Mitsubishi ordnet B0030 dem hinteren linken Seitenairbagmodul zu und setzt einen Schluss zu einem anderen Kreis nach 2 Sekunden. Mercedes-Benz deutet B003013 an A-Klasse, CLA und GLB als unterbrochene Zündpille im linken Fond-Sidebag, häufig wegen zu hohen Kontaktwiderstands an der Steuergeräte-Steckverbindung (LI54.21-P-070658). Die ältere GM-Nummerierung weicht ab: Beim Saab 9-5 von 2006 ist B0030 ein Kreis des Beifahrer-Seitenairbags, dessen Pinspannung 2 Sekunden lang außerhalb 1,0 bis 4,1 Volt liegt, beim Saab 9-3 ein Kurzschluss dort. Das rechte Gegenstück hinten ist B0038. Airbag-Leuchte an.","u":[["h","Erhöhter Übergangswiderstand am Steuergeräte- oder Fond-Seitenairbagstecker"],["m","Beschädigte Leitung im Fondtürübergang oder in der Rücklehne"],["l","Innerer Fehler im hinteren linken Seitenairbagmodul"]],"s":["Airbag-Warnleuchte an","Hinterer linker Seitenairbag löst bei einem Seitenaufprall eventuell nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["second_row_left_side_airbag","srs_control_module","srs_wiring"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0038","B0020","B0040"]},{"c":"B0031","t":"Frontairbag zweite Sitzreihe links Stufe 1 Auslösesteuerung","e":"Second Row Left Frontal Stage 1 Deployment Control","d":"B0031 meldet die erste Zündstufe eines Frontairbags für den Fahrgast hinten links und kann daher nur auftreten, wo es ein solches Bauteil gibt. Bekanntes Serienbeispiel ist die Mercedes-Benz S-Klasse ab 2020: Ein Fond-Airbag (aufpreispflichtig, beim Maybach serienmäßig) entfaltet sich aus der Rückseite der Vordersitzlehne für die beiden äußeren Rücksitze; ein gasgefülltes Schlauchgerüst spannt das Kissen auf, das sich mit Umgebungsluft füllt. Mit dieser Bedeutung dokumentiert kein Hersteller den Code öffentlich. GM vergab die Nummer anders – die Saab-9-4X-Anleitung von 2011 fasst B0031 mit den Codes der Vordersitz-Seitenairbags zusammen. Stufe 2 und 3 desselben Airbags sind B0032 und B0033. Die Airbag-Leuchte brennt.","u":[["h","Lockerer oder korrodierter Stecker der Airbagleitung in der Vordersitzlehne"],["m","Innerer Fehler im Fond-Airbagmodul in der Vordersitzlehne"],["m","Leitung durch Sitzschiene oder Klappmechanismus gedehnt oder eingeklemmt"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Fahrgast hinten links hat bei einem Frontalaufprall womöglich keinen Airbagschutz","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["second_row_left_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B0032","B0033","B0039","B0030"]},{"c":"B0032","t":"Frontairbag zweite Sitzreihe links Stufe 2 Auslösesteuerung","e":"Second Row Left Frontal Stage 2 Deployment Control","d":"B0032 betrifft einen zweiten Zünder des linken Fond-Frontairbags. Mit einer zweiten Stufe kann das Steuergerät je nach Unfallschwere und Insasse hinter dem Sitz später nachfüllen oder darauf verzichten; eine Anmeldung von Mercedes-Benz für einen Airbag in der Vordersitzlehne sieht eigene Auslöseeinheiten für die Kammern vor, damit sie nacheinander zünden. In der S-Klasse wird das Schlauchgerüst mit Druckgas gefüllt, die Mitte saugt Außenluft an. Keine veröffentlichte Codetabelle ordnet B0032 so zu. Die Global-A-Steuergeräte von GM nutzen die Nummer für den Gurtstraffer hinten links; der Saab 9-4X 2011 setzt sie nach 2 Sekunden Schluss, Unterbrechung, über 4,2 Ohm oder unter 1,4 Ohm. Airbag-Leuchte an.","u":[["m","Unterbrechung oder Schluss nur im Leitungspaar der Stufe 2 zum Fond-Airbag"],["h","Lockerer oder korrodierter Stecker der Airbagleitung in der Vordersitzlehne"],["m","Defekter zweiter Zünder im Fond-Airbagmodul"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Fond-Airbag bläst womöglich schwächer oder gar nicht auf","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["second_row_left_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B0031","B0033","B003A"]},{"c":"B0033","t":"Frontairbag zweite Sitzreihe links Stufe 3 Auslösesteuerung","e":"Second Row Left Frontal Stage 3 Deployment Control","d":"B0033 ist das dritte Auslöseelement eines Frontairbags für den linken Platz der zweiten Reihe. Ein dritter Zünder kann eine weitere Gaskammer sein: Ein Breed-Patent beschreibt einen Gasgenerator mit je einem Zünder pro Kammer, deren Reihenfolge und Abstand von 0 bis 25 ms das Steuergerät festlegt. Mercedes-Benz belegt den Stufe-3-Platz seiner vorderen Airbags mit der Zündpille des Abströmventils (B000313, B001213) – ein Hinweis, was Stufe 3 auch hinter einem Sitz bedeuten kann. Für einen Fond-Airbag dokumentiert kein Hersteller B0033. In GMs Bulletin 08-09-41-002H zu losen Steckersicherungen (zahlreiche Pkw und Pick-ups 2005–14) erscheint B0033 mit Byte 04, 0D und 0E – als anderer GM-Kreis. Airbag-Leuchte an.","u":[["h","Steckersicherung fehlt oder sitzt nicht, der Stecker lockert sich"],["m","Beschädigte Leitung oder Zünder der Stufe 3 im Fond-Airbag"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Angepasstes Aufblasen des linken Fond-Airbags entfällt","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["second_row_left_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B0031","B0032","B003B"]},{"c":"B0034","t":"Seitenairbag rechts Stufe 2 Auslösesteuerung","e":"Right Side Deployment Stage 2 Control","d":"B0034 fehlt in den öffentlichen J2012-Listen, die im Block der zweiten Sitzreihe von B0033 auf B0038 springen, und kein Hersteller und kein Bulletin dokumentiert ihn öffentlich; einem realen Fahrzeug lässt er sich nicht zuordnen. Der Titel beschreibt eine zweite Zündstufe des rechten Seitenairbags. Solche Airbags sind selten: Ein Ford-Patent zum Seitenaufprall auf der Gegenseite behandelt Thorax-, Becken- und Kopfairbags ihrer Größe halber als einstufig, und der bei Autoliv beschriebene Zweikammer-Seitenairbag schützt Brust und Becken mit einem Kissen statt mit zwei Stufen. Der rechte vordere Seitenairbag trägt bei J2012 den Code B0028; Mitsubishi etwa prüft diesen Kreis 2 Sekunden, bevor ein Fehler abgelegt wird. Wird B0034 gelesen, zählt, welches Steuergerät und welcher Klartext angezeigt werden. Die Airbag-Leuchte brennt.","u":[["m","Fehler im Zündkreis, den das Steuergerät diesem Code zuordnet"],["h","Schlechter Kontakt oder Korrosion am Seitenairbagstecker bzw. Zwischenkabel unter oder im Sitz"],["l","Fehler oder unpassende Software im Airbagsteuergerät"]],"s":["Airbag-Warnleuchte an","Schutz durch den rechten Seitenairbag eventuell eingeschränkt","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["passenger_side_airbag","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0028","B0036","B0025"]},{"c":"B0036","t":"Seitenairbag rechts Stufe 2 Auslösekreis Kurzschluss nach Masse","e":"Right Side Deployment Stage 2 Loop Short to Ground","d":"B0036 findet sich weder in den öffentlichen J2012-Listen noch in einer zugänglichen Herstellerunterlage; der Code ist öffentlich nicht nachweisbar. Sein Titel beschreibt einen Masseschluss in einer zweiten Stufe des rechten Seitenairbags. Wie Steuergeräte so einen Fehler behandeln, zeigen andere Codes: Mitsubishi legt B0028-11 ab, wenn der Kreis des rechten vorderen Seitenairbags 2 Sekunden an Masse liegt, und das GM-Handbuch zum Saab 9-4X setzt Byte 02 am Code B0021 für den Seitenairbag im Beifahrersitz nach einem ebenso langen Masseschluss. GM ergänzt, dass eine schlecht eingerastete Steckersicherung die Kurzschlussbrücken beide Zündleitungen verbinden lässt; bei Byte 02 werden daher zuerst die Stecker geprüft. Zweistufige Seitenairbags sind selten. Airbag-Leuchte an; der Airbag löst womöglich nicht aus.","u":[["h","Durchgescheuerte Seitenairbagleitung mit Kontakt zu Sitzgestell oder Karosserie"],["m","Steckersicherung nicht eingerastet, Kurzschlussbrücken überbrücken den Kreis"],["l","Innerer Kurzschluss im Seitenairbagmodul"]],"s":["Airbag-Warnleuchte an","Rechter Seitenairbag löst bei einem Seitenaufprall eventuell nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["passenger_side_airbag","srs_seat_wiring"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0034","B0028","B0023"]},{"c":"B0038","t":"Seitenairbag zweite Sitzreihe rechts Auslösesteuerung","e":"Second Row Right Side Airbag Deployment Control","d":"B0038 überwacht den Zündkreis des Seitenairbags für den rechten Platz der zweiten Sitzreihe, eingebaut in der hinteren Türverkleidung oder in der äußeren Wange der Rücksitzlehne. Mitsubishi führt ihn genau mit diesem J2012-Wortlaut als hinteres Seitenairbagmodul rechts und speichert B0038-12, wenn der Kreis 2 Sekunden lang Schluss nach Plus hat. Bei den kompakten Mercedes-Benz-Modellen (A-Klasse, CLA, GLB) bedeutet B003813 eine offene Zündpille im rechten hinteren Sidebag. Eine GM-Patentschrift gibt den Seitenairbags der hinteren Reihe eigene Gasgeneratoren, getrennt vom System vorn. Die Saab-9-4X-Werkstattanleitung von 2011 behandelt B0038 zusammen mit den Vordersitz-Seitenairbags. Linkes Gegenstück: B0030. Die Airbag-Leuchte leuchtet.","u":[["h","Schlechter Kontakt am hinteren Seitenairbagstecker in Tür oder Rücksitz"],["m","Innerer Fehler im rechten hinteren Seitenairbagmodul"],["l","Leitung an einer spannungsführenden Leitung durchgescheuert, z. B. an Rücksitzklappung oder B-Säule"]],"s":["Airbag-Warnleuchte an","Fahrgast hinten rechts hat womöglich keinen Seitenairbagschutz","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["second_row_right_side_airbag","squib_circuit","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0030","B0028","B0048"]},{"c":"B0039","t":"Frontairbag zweite Sitzreihe rechts Stufe 1 Auslösesteuerung","e":"Second Row Right Frontal Stage 1 Deployment Control","d":"B0039 gehört zur Stufe 1 des rechten Fond-Frontairbags, also zur Hauptladung, die das Steuergerät bei jedem ausreichend schweren Frontalaufprall zündet. Der Airbag sitzt in der Rückseite des Beifahrersitzes; Mercedes-Benz bietet diese Bauart in der S-Klasse an und baut sie im Maybach serienmäßig ein, um Kopf und Nacken angegurteter Fondgäste auf den Außenplätzen zu entlasten. Schon eine ältere Daimler-Anmeldung beschreibt einen Airbag an der Rückseite eines Vordersitzes, der ein Kanalgerüst aufspannt und sich mit Umgebungsluft füllt. Keine öffentliche Codetabelle verbindet B0039 mit diesem Airbag. GM-Steuergeräte der Global-A-Reihe nutzen B0039 für den Gurtstraffer hinten rechts (Saab 9-4X 2011). Airbag-Leuchte an.","u":[["h","Lockerer oder korrodierter Stecker der Airbagleitung in der Vordersitzlehne"],["m","Innerer Fehler im rechten Fond-Airbagmodul"],["m","Leitung durch Sitzschiene oder Klappmechanismus gedehnt oder eingeklemmt"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Fahrgast hinten rechts verliert womöglich den Frontairbagschutz","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["second_row_right_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B003A","B003B","B0031","B0038"]},{"c":"B003A","t":"Frontairbag zweite Sitzreihe rechts Stufe 2 Auslösesteuerung","e":"Second Row Right Frontal Stage 2 Deployment Control","d":"B003A betrifft Stufe 2 des rechten Fond-Frontairbags. Mit der zweiten Ladung kann das Steuergerät das Aufblasen abschwächen oder verstärken; hinten ist das wichtig, weil hinter dem Vordersitz ein Erwachsener, ein Kind oder ein Kindersitz in beliebiger Richtung sitzen kann – darauf wies Mercedes-Benz bei der Vorstellung des S-Klasse-Fondairbags 2020 hin. Die Mercedes-Anmeldung für einen Airbag an einer verschiebbaren Vordersitzlehne sieht eigene Auslöseeinheiten vor, damit die Kammern nacheinander zünden. Kein Fahrzeughersteller dokumentiert B003A, im NHTSA-Bulletinbestand fehlt er. Steht nur ein Stufe-2-Code, liegt der Fehler eher an Leitung oder Zünder dieser Stufe als am ganzen Airbag. Airbag-Leuchte an.","u":[["m","Unterbrechung oder Schluss nur im Leitungspaar der Stufe 2"],["h","Lockerer oder korrodierter Stecker der Airbagleitung in der Vordersitzlehne"],["m","Defekter zweiter Zünder im rechten Fond-Airbag"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Fond-Airbag passt sein Aufblasen womöglich nicht an den Insassen an","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["second_row_right_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B0039","B003B","B0032"]},{"c":"B003B","t":"Frontairbag zweite Sitzreihe rechts Stufe 3 Auslösesteuerung","e":"Second Row Right Frontal Stage 3 Deployment Control","d":"B003B ist das dritte Zündelement des rechten Fond-Frontairbags. Bei den vorderen Airbags nutzt Mercedes-Benz diesen dritten Platz für die Zündpille, die ein Abströmventil öffnet und Gas entweichen lässt (B000313 Fahrer, B001213 Beifahrer); ein Breed-Patent zeigt die andere Möglichkeit, eine dritte Gaskammer mit eigenem Zünder, die das Steuergerät später zünden kann, etwa bei einem Zweitaufprall. Welche Lösung ein Fond-Airbag nutzen würde, ist nicht veröffentlicht, und kein Hersteller dokumentiert B003B. Ist er gespeichert, liegt Widerstand oder Spannung des dritten Elements außerhalb des Sollbereichs. Stufe 1 und 2 desselben Airbags melden sich als B0039 und B003A. Die Airbag-Leuchte bleibt an.","u":[["m","Beschädigte Leitung oder Ventilzündpille der Stufe 3 im rechten Fond-Airbag"],["h","Lockerer oder korrodierter Stecker der Airbagleitung in der Vordersitzlehne"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Rechter Fond-Airbag zündet womöglich ohne seine dritte Stufe","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["second_row_right_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B0039","B003A","B0033"]},{"c":"B0040","t":"Seitenairbag dritte Sitzreihe links Auslösesteuerung","e":"Third Row Left Side Airbag Deployment Control","d":"B0040 ist für einen Seitenairbag am linken Platz einer dritten Sitzreihe vorgesehen, wie ihn manche siebensitzigen SUVs und Vans haben; meist schützt dort nur ein verlängerter Kopfairbag. Ein Patent von Joyson (TK Holdings) nennt sein Seitenairbagmodul in der Lehne ausdrücklich für jede Reihe einschließlich der dritten, eine GM-Anmeldung gibt den hinteren Seitenairbags eigene Gasgeneratoren und lässt die hintere Reihe auch die dritte sein. Mit dieser Bedeutung dokumentiert kein Hersteller B0040. Frühere GM-Steuergeräte belegen ihn anders: Die Saab-Anleitungen für 9-5 (2006) und 9-3 werten B0040 als zu kleinen Widerstand im Kreis des Fahrer-Seitenairbags, unter 1,5 Ohm bei 0,2 Toleranz über 2 Sekunden; GMs Rundschreiben 08-09-41-002H über nicht gesicherte Stecker nennt ihn ebenfalls. Airbag-Leuchte an.","u":[["h","Schlechter Kontakt am Seitenairbagstecker des Sitzes der dritten Reihe oder der Seitenverkleidung hinten"],["m","Leitung durch Umklappen oder Ausbauen des Sitzes der dritten Reihe belastet"],["l","Innerer Fehler im Seitenairbag der dritten Reihe"]],"s":["Airbag-Warnleuchte an","Insasse links in der dritten Reihe hat womöglich keinen Seitenairbagschutz","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["third_row_left_side_airbag","squib_circuit","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0048","B0030","B0041"]},{"c":"B0041","t":"Frontairbag dritte Sitzreihe links Stufe 1 Auslösesteuerung","e":"Third Row Left Frontal Stage 1 Deployment Control","d":"B0041 würde die erste Stufe eines Frontairbags für den linken Platz der dritten Reihe melden, der sich aus der Lehne des Vordermanns in Reihe zwei entfalten müsste. Solche Airbags stehen in Patenten, etwa in einer Daimler-Anmeldung für einen Airbag an der Rückseite eines Vordersitzes und in einer Mercedes-Benz-Anmeldung, die einen verschiebbaren Sitz mit gestapelten Kammern ausgleicht; ein Serienfahrzeug mit Frontairbags für die dritte Reihe ist aber nicht bekannt, der Fond-Airbag der S-Klasse schützt nur die zweite Reihe. Kein Hersteller dokumentiert B0041. Die alte GM-Nummerierung hat damit nichts zu tun: Beim Saab 9-5 2006 heißt B0041 offener Kreis des Fahrer-Seitenairbags, über 4,5 Ohm (±0,2) für 2 Sekunden. Airbag-Leuchte an.","u":[["m","Lockerer Stecker der Airbagleitung in der Lehne der zweiten Reihe"],["m","Leitung beim Klappen oder Verschieben des Sitzes der zweiten Reihe belastet"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Frontairbag für den linken Platz der dritten Reihe löst womöglich nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["third_row_left_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B0042","B0043","B0049","B0040"]},{"c":"B0042","t":"Frontairbag dritte Sitzreihe links Stufe 2 Auslösesteuerung","e":"Third Row Left Frontal Stage 2 Deployment Control","d":"B0042 steht für die zweite Stufe eines Frontairbags für den Fahrgast links in der dritten Reihe. Eine zweite Stufe setzt einen Gasgenerator mit zwei getrennt zündbaren Ladungen voraus, wie im Mehrkammer-Entwurf von Breed, bei dem das Steuergerät wählt, welche Kammer zuerst zündet und mit welchem Abstand die nächste folgt. Kein Hersteller dokumentiert B0042 für die dritte Reihe, ein Serienauto mit solchem Airbag ist nicht bekannt. Die ältere GM-Bedeutung ist eindeutig: Für den 9-5 des Jahrgangs 2006 und den 9-3 beschreibt Saab B0042 als Widerstand unter 1,5 Ohm über 2 Sekunden im Kreis der Fahrer-Frontairbagstufe 2; das Steckersicherungs-Bulletin 08-09-41-002H von GM schließt ihn ein. Airbag-Leuchte an.","u":[["m","Unterbrechung oder Schluss nur in der Leitung der Stufe 2"],["m","Steckersicherung am Airbagstecker nicht eingerastet"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Zweistufiges Aufblasen für diesen Platz steht nicht zur Verfügung","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["third_row_left_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B0041","B0043","B004A"]},{"c":"B0043","t":"Frontairbag dritte Sitzreihe links Stufe 3 Auslösesteuerung","e":"Third Row Left Frontal Stage 3 Deployment Control","d":"B0043 schließt die linke Frontgruppe der dritten Reihe als Element der Stufe 3 ab. Nach dem Vorbild der vorderen Airbags kann das eine Zündpille für ein Abströmventil sein, wie Mercedes-Benz sie unter B000313 und B001213 führt, oder eine weitere Gaskammer wie die dritte Kammer im Breed-Patent, die für einen Zweitaufprall bereitsteht. Keine öffentliche Quelle verbindet B0043 mit einem Airbag der dritten Reihe. GM hat der Nummer in älteren Steuergeräten eine eigene, belegte Bedeutung gegeben: Der Saab 9-5 2006 speichert B0043, wenn die Spannung am Pin der Stufe 2 des Fahrer-Frontairbags 2 Sekunden über 4,1 oder unter 1,0 Volt liegt, der 9-3 unterscheidet Schluss nach Plus, nach Masse oder zu einem anderen Zündkreis. Airbag-Leuchte an.","u":[["m","Beschädigte Leitung oder Zündpille der Stufe 3"],["l","Schluss zwischen zwei Zündkreisen in einem gemeinsamen Kabelstrang"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Drittes Auslöseelement dieses Airbags ist abgeschaltet","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["third_row_left_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B0041","B0042","B004B"]},{"c":"B0046","t":"Kopfairbag links Auslösekreis unterbrochen","e":"Left Curtain Deployment Loop Open","d":"B0046 steht in keiner der zugänglichen J2012-Codelisten, die von B0043 direkt zu B0048 springen, und weder ein Hersteller noch ein Bulletin nutzt ihn öffentlich; der Code lässt sich keinem Fahrzeug zuordnen. Sein Titel beschreibt einen unterbrochenen Zündkreis des linken Kopfairbags, der aus dem Dachrahmen herausklappt. J2012 bildet diesen Fehler sonst als B0021 mit Fehlertyp 13 ab: Mitsubishi legt B0021-13 ab, wenn der Kreis des linken Curtain-Airbags 2 Sekunden offen ist, Mercedes-Benz liest B002113 als offene Zündpille des linken Windowbags. Die Global-A-Steuergeräte von GM melden denselben Fehler als B0016 04 beim linken Dachrahmen-Airbag. Wird B0046 ausgelesen, zählt der Klartext des Testers. Airbag-Leuchte an.","u":[["h","Abgezogener oder lockerer Kopfairbagstecker an Säule oder Dachrahmen"],["m","Gebrochene Leitung im Dachrahmen-Kabelstrang, z. B. nach Arbeiten am Dachhimmel"],["l","Offener Zünder im linken Kopfairbag"]],"s":["Airbag-Warnleuchte an","Linker Kopfairbag löst bei Seitenaufprall oder Überschlag womöglich nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["left_curtain_airbag","srs_roof_wiring","srs_control_module"],"r":["shop_only",0,[100,1000],[1,4]],"f":"","x":["B0047","B0021","B0022"]},{"c":"B0047","t":"Kopfairbag links Auslösekreis Kurzschluss nach Masse","e":"Left Curtain Deployment Loop Short to Ground","d":"Auch B0047 fehlt in den zugänglichen J2012-Listen, und weder ein Fahrzeughersteller noch ein NHTSA-Bulletin dokumentiert ihn; öffentlich ist er nicht nachweisbar. Der Titel nennt einen Masseschluss im Zündkreis des linken Kopfairbags, des aufblasbaren Vorhangs, der bei Seitenaufprall und Überschlag die Seitenscheiben abdeckt. Nach J2012 wird dieser Fehler sonst als B0021 mit Byte 11 gespeichert: Mitsubishi setzt B0021-11, sobald der Kreis des Vorhangairbags links 2 Sekunden lang Masse hat. GM Global A verwendet B0016 02 für einen Masseschluss im Kreis des linken Dachrahmen-Airbags, ebenfalls nach 2 Sekunden. Ein Masseschluss liegt oft dort, wo der Dachkabelstrang an scharfen Blechkanten oder Verkleidungsclips vorbeiführt. Airbag-Leuchte an.","u":[["h","Isolierung der Kopfairbagleitung an der Karosserie durchgescheuert"],["m","Leitung durch Säulenverkleidung oder Dachhimmelclip eingeklemmt"],["l","Innerer Schluss zum Gehäuse im linken Kopfairbag"]],"s":["Airbag-Warnleuchte an","Auslösung des linken Kopfairbags ist womöglich blockiert","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["left_curtain_airbag","srs_roof_wiring","srs_control_module"],"r":["shop_only",0,[100,1000],[1,4]],"f":"","x":["B0046","B0021","B0029"]},{"c":"B0048","t":"Seitenairbag dritte Sitzreihe rechts Auslösesteuerung","e":"Third Row Right Side Airbag Deployment Control","d":"B0048 ist das rechte Gegenstück zu B0040: der Auslösekreis eines Seitenairbags für den rechten Platz der dritten Reihe. Nur wenige Fahrzeuge haben ihn, weil die dritte Reihe meist mit einem bis zur D-Säule reichenden Kopfairbag auskommt. Die Technik beschreiben Patente: Das Seitenairbagmodul von Joyson in der Lehne ist für jede Sitzreihe einschließlich der dritten gedacht, und die GM-Anmeldung behandelt jede hintere Reihe als eigenes System mit eigenem Gasgenerator, das untätig bleiben darf, wenn ein anderes zündet. Kein Hersteller dokumentiert B0048, bei NHTSA liegt kein Bulletin dazu. Für den rechten Seitenairbag der zweiten Reihe zeigt Mitsubishi unter B0038 die übliche Logik mit Bestätigung nach 2 Sekunden. Airbag-Leuchte an.","u":[["h","Schlechter Kontakt am rechten Seitenairbagstecker der dritten Reihe"],["m","Leitung durch Klappen, Verschieben oder Ausbauen des Sitzes der dritten Reihe beschädigt"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Insasse rechts in der dritten Reihe hat womöglich keinen Seitenairbagschutz","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["third_row_right_side_airbag","squib_circuit","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0040","B0038","B0049"]},{"c":"B0049","t":"Frontairbag dritte Sitzreihe rechts Stufe 1 Auslösesteuerung","e":"Third Row Right Frontal Stage 1 Deployment Control","d":"B0049 kennzeichnet Stufe 1 eines Frontairbags für den rechten Platz der dritten Reihe, also die Hauptladung eines Airbags, der aus der Lehne des davor stehenden Sitzes der zweiten Reihe kommen müsste. Die Daimler-Anmeldung für einen Airbag hinter einem Vordersitz und der spätere Mercedes-Benz-Entwurf mit Kammern, die einen wechselnden Sitzabstand überbrücken, zeigen den möglichen Aufbau; in Serie bietet Mercedes Fond-Frontairbags nur für die äußeren Plätze der zweiten Reihe in S-Klasse und Maybach an. Kein Hersteller dokumentiert B0049, kein Bulletin nennt ihn. Ein Frontcode der dritten Reihe an einem Fahrzeug ohne diese Ausstattung deutet auf ein Steuergerät mit falscher Variantencodierung. Airbag-Leuchte an.","u":[["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"],["m","Lockerer Stecker der Airbagleitung in der Lehne der zweiten Reihe"],["m","Leitung beim Klappen oder Verschieben des Sitzes der zweiten Reihe belastet"]],"s":["Airbag-Warnleuchte an","Frontairbag für den rechten Platz der dritten Reihe löst womöglich nicht aus","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["third_row_right_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B004A","B004B","B0041","B0048"]},{"c":"B004A","t":"Frontairbag dritte Sitzreihe rechts Stufe 2 Auslösesteuerung","e":"Third Row Right Frontal Stage 2 Deployment Control","d":"B004A ist der Kreis der zweiten Stufe des rechten Frontairbags der dritten Reihe. Stufe 2 ist eine getrennt gezündete Ladung: Das Breed-Patent zeigt einen Gasgenerator, dessen Kammern je einen eigenen Zünder haben und einzeln, gemeinsam oder mit vom Steuergerät gewähltem Versatz gezündet werden; die Mercedes-Benz-Anmeldung für den Fond-Airbag erlaubt je Kammer eine Auslöseeinheit zum Füllen nacheinander. Keine veröffentlichte Codetabelle, kein Hersteller und kein Bulletin verbindet B004A mit einem echten Fahrzeug. Taucht er auf, liegt der Kreis der Stufe 2 außerhalb des Sollbereichs, während Stufe 1 (B0049) noch in Ordnung sein kann; links entspricht ihm B0042. Airbag-Leuchte an.","u":[["m","Unterbrechung oder Schluss nur in der Leitung der Stufe 2"],["m","Lockerer Stecker in der Lehne der zweiten Reihe"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"]],"s":["Airbag-Warnleuchte an","Zweistufiges Aufblasen für den rechten Platz der dritten Reihe entfällt","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["third_row_right_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B0049","B004B","B0042"]},{"c":"B004B","t":"Frontairbag dritte Sitzreihe rechts Stufe 3 Auslösesteuerung","e":"Third Row Right Frontal Stage 3 Deployment Control","d":"B004B ist der letzte Code des Frontblocks der dritten Reihe: Stufe 3 des rechten Airbags. Was ein drittes Element tut, bestimmt der Hersteller. Mercedes-Benz zeigt bei den vorderen Airbags eine Antwort, dort ist der dritte Platz eine Ventilzündpille (B000313, B001213); das Breed-Patent zeigt eine andere, eine dritte Kammer, die für einen späteren Zweitaufprall zurückgehalten wird. Die Mercedes-Benz-Anmeldung zum Fond-Airbag koppelt zudem eine zusätzliche Kammer über Ventile oder Drosseln an die erste. Kein Fahrzeughersteller dokumentiert B004B, in keinem NHTSA-Bulletin taucht er auf. Ein Fehler hier lässt den Airbag ohne sein drittes Element; Stufe 1 und 2 sind B0049 und B004A. Airbag-Leuchte an.","u":[["m","Beschädigte Leitung oder Zündpille der Stufe 3"],["l","Steuergerät auf Ausstattung codiert, die das Fahrzeug nicht hat (falsches Teil oder falsche Codierung)"],["l","Lockerer Stecker in der Lehne der zweiten Reihe"]],"s":["Airbag-Warnleuchte an","Rechter Airbag der dritten Reihe zündet womöglich ohne drittes Element","Sicherheitshinweis: Airbagkreis nicht selbst durchmessen; Airbagstecker nur bei abgeklemmter Batterie und nach der vorgeschriebenen Wartezeit trennen"],"k":["third_row_right_frontal_airbag","squib_circuit","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,1200],[1,4]],"f":"","x":["B0049","B004A","B0043"]},{"c":"B0050","t":"Gurtsensor Fahrer","e":"Driver Seat Belt Sensor","d":"B0050 überwacht den Schalter im Gurtschloss des Fahrers, der dem Airbagsteuergerät meldet, ob der Gurt eingerastet ist; das Steuergerät braucht das für den Gurtwarner und für die Wahl der Airbag- und Gurtstrafferreaktion. Meist ist es ein zweiadriger Hallsensor, dessen Strom sich ändert, wenn die Stahlzunge im Schloss steckt. FCA dokumentiert B0050 mit diesem Wortlaut: Teilehinweise von 2016–17 für Dart, Cherokee und Chrysler 200 nennen B0050-13 als offenen Kreis des Fahrergurtsensors, und TSB 10-001-23 für Renegade und Fiat 500X 2015–22 führt B0050-13 und B0050-1D (außerhalb des Bereichs) auf korrodierte Kontakte am Zwischenstecker des Gurtschlosses unter dem Sitz zurück. Mitsubishi nutzt B0052 für das Beifahrergurtschloss. Die Airbag-Leuchte geht an.","u":[["h","Korrodierte Kontakte am Zwischenstecker zwischen Gurtschloss und Sitzkabelstrang"],["m","Defekter Hallsensor oder Schalter im Fahrergurtschloss"],["m","Gurtschlossleitung durch die Sitzschiene eingeklemmt oder gedehnt"],["l","Fremdkörper im Gurtschloss stört den Sensor"]],"s":["Airbag-Warnleuchte an","Gurtwarner für den Fahrer warnt womöglich falsch oder gar nicht","Steuergerät behandelt den Fahrer womöglich als nicht angeschnallt und passt Airbag- und Straffer-Auslösung an","Sicherheitshinweis: Der Gurtschlossstecker liegt unter dem Sitz neben Seitenairbag- und Gurtstrafferstecker; vor dem Trennen Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","seat_harness_connector","srs_control_module"],"r":["shop_only",0,[60,450],[0.5,2]],"f":"","x":["B0051","B0052","B0070"]},{"c":"B0051","t":"Gurtsensor erste Sitzreihe Mitte","e":"First Row Center Seat Belt Sensor","d":"B0051 gehört zum Gurtschlosssensor eines Mittelplatzes in der ersten Reihe, wie es ihn in Pick-ups und Transportern mit Dreiersitzbank vorn gibt. FMVSS 208 verlangt einen Gurtwarner nur für die äußeren Vordersitze; ein Sensor für die Mitte ist also Zusatzausstattung, die dem Airbagsteuergerät und gegebenenfalls einer Gurterinnerung für diesen Platz Daten liefert. Üblich ist ein berührungsloser Hall-Gurtschlossschalter, wie ihn CTS anbietet und Allegro beschreibt. Mit dieser Bedeutung dokumentiert kein Hersteller B0051; Mitsubishi nutzt dasselbe J2012-Muster für das Beifahrergurtschloss, B0052, mit offenem oder ungültigem Signal über 2 Sekunden. Ältere GM-Steuergeräte (Saab 9-5 2006, 9-3) speichern B0051 als Auslösung angefordert, also als Unfallvermerk. Airbag-Leuchte an.","u":[["h","Lockerer oder korrodierter Stecker des Mittelgurtschlosses unter der Sitzbank"],["m","Defekter Hallschalter im Mittelgurtschloss"],["l","Leitung durch umklappbaren Mittelsitz oder Konsole belastet"]],"s":["Airbag-Warnleuchte an","Gurterinnerung für den Mittelplatz ist womöglich falsch oder fehlt","Sicherheitshinweis: Der Gurtschlossstecker liegt unter dem Sitz neben Seitenairbag- und Gurtstrafferstecker; vor dem Trennen Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[60,450],[0.5,2]],"f":"","x":["B0050","B0052","B0071"]},{"c":"B0052","t":"Gurtsensor Beifahrer","e":"Passenger Seat Belt Sensor","d":"B0052 betrifft den Sensor im Gurtschloss des Beifahrers, der dem Airbagsteuergerät meldet, ob die Gurtzunge eingerastet ist. Das Steuergerät braucht diese Information für den Gurtwarner, den FMVSS 208 an den äußeren Vordersitzen vorschreibt, und für die Wahl, wie Beifahrerairbag und Gurtstraffer zünden. Mitsubishi dokumentiert den Code mit dieser Bedeutung: Das SRS-Handbuch legt B0052 mit Byte 11, 12, 13, 29 oder 2B ab – Masseschluss, Schluss nach Plus, Unterbrechung, ungültiges Signal oder Schluss zu einer anderen Leitung, jeweils nach 2 Sekunden bei eingeschalteter Zündung. FCA führt B0052-13 in Hinweisen zum Rückhalte-Steuergerät von Dart, Cherokee und Chrysler 200 als offenen Beifahrergurtsensor. Die Global-A-Steuergeräte von GM (2011) nutzen die Nummer dagegen als Auslösevermerk. Airbag-Leuchte an.","u":[["h","Lockerer oder korrodierter Gurtschlossstecker unter dem Beifahrersitz"],["m","Defekter Hallsensor im Beifahrergurtschloss"],["m","Gurtschlossleitung durch Sitzschienen oder Mattenbefestigung gequetscht oder abgerissen"],["l","Eingangsfehler im Airbagsteuergerät"]],"s":["Airbag-Warnleuchte an","Gurtwarner Beifahrer meldet trotz angelegtem Gurt oder bleibt stumm","Auslösestrategie für Beifahrerairbag und Gurtstraffer geht womöglich von einem nicht angeschnallten Insassen aus","Sicherheitshinweis: Der Gurtschlossstecker liegt unter dem Sitz neben Airbag- und Strafferstecker; nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[60,450],[0.5,2]],"f":"","x":["B0050","B0051","B0053","B0072"]},{"c":"B0053","t":"Gurtsensor zweite Sitzreihe links","e":"Second Row Left Seat Belt Sensor","d":"B0053 ist der J2012-Platz für den Gurtschlosssensor am linken Sitz der zweiten Reihe. Solche Sensoren speisen die Gurterinnerung hinten: Für Fahrzeuge ab Baudatum September 2028 verlangt FMVSS 208 S7.5(c), dass beim Start für jeden Rücksitz angezeigt wird, welche Gurte angelegt sind oder nicht, und dass eine Warnung kommt, wenn während der Fahrt einer geöffnet wird. Mit dieser Bedeutung dokumentiert kein Hersteller B0053 öffentlich; am nächsten liegt Mitsubishis Beifahrercode B0052, der bei einem 2 Sekunden lang offenen, kurzgeschlossenen oder ungültigen Gurtschlosssignal gesetzt wird. Ältere GM-Airbagsteuergeräte belegen die Nummer anders: Saab 9-3 und Saab 9-5 (2006) speichern B0053, wenn eine Auslösung angefordert wurde, während ein Zündkreisfehler vorlag – nach einer Frontairbag-Auslösung lässt er sich nicht löschen.","u":[["h","Lockerer oder korrodierter Gurtschlossstecker unter dem linken Rücksitz"],["m","Defekter Schalter oder Hallsensor im linken hinteren Gurtschloss"],["m","Leitung durch Umklappen oder Verschieben des Sitzes der zweiten Reihe beschädigt"],["l","Älteres GM-/Saab-Steuergerät: Auslösevermerk bei Zündkreisfehler, Steuergerät muss getauscht werden"]],"s":["Airbag- oder Gurtwarnleuchte hinten an","Gurtanzeige hinten zeigt den linken Platz fälschlich als angeschnallt oder offen","Sicherheitshinweis: Der Gurtschlossstecker liegt unter dem Sitz nahe Straffer- und Seitenairbagsteckern; nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[60,450],[0.5,2]],"f":"","x":["B0054","B0055","B0073","B0052"]},{"c":"B0054","t":"Gurtsensor zweite Sitzreihe Mitte","e":"Second Row Center Seat Belt Sensor","d":"B0054 ist für den Gurtschlosssensor des Mittelplatzes der zweiten Reihe vorgesehen. Dort sitzt das Schloss oft in einer geteilten Bank oder unter einer klappbaren Mittelarmlehne, die Leitung läuft also durch bewegliche Sitzteile. Die hintere Gurtwarnung nach FMVSS 208 S7.5(c) für Fahrzeuge ab September 2028 umfasst jeden hinteren Sitzplatz, auch den mittleren. Fords Patent zur Gurtüberwachung hinten zählt die eingerasteten Gurte, sobald das Auto bei geschlossenen Türen 3 mph überschreitet, und warnt erst, wenn diese Zahl sinkt – wer nur den Platz wechselt, löst nichts aus. Der Sensor selbst ist meist ein Hallschalter, der die Stahlzunge im Schloss erkennt. Öffentlich dokumentiert kein Hersteller B0054; wie ein solcher Gurtschlossfehler gesetzt wird, zeigt Mitsubishis Beifahrercode B0052.","u":[["h","Leitung des Mittelgurtschlosses an geteilter Bank oder Armlehnengelenk überlastet"],["m","Lockerer oder korrodierter Stecker des Mittelgurtschlosses"],["m","Defekter Hallschalter im Mittelgurtschloss"]],"s":["Airbag- oder Gurtwarnleuchte hinten an","Mittlerer Rücksitz wird in der Gurtanzeige falsch dargestellt","Sicherheitshinweis: Gurtschlossstecker unter der Rückbank liegen nahe der Strafferverkabelung; nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[60,450],[0.5,2.5]],"f":"","x":["B0053","B0055","B0074"]},{"c":"B0055","t":"Gurtsensor zweite Sitzreihe rechts","e":"Second Row Right Seat Belt Sensor","d":"B0055 steht für den Gurtschlosssensor des rechten Sitzes der zweiten Reihe, also hinter dem Beifahrer und bei Vans oft neben der Schiebetür. Ist dieser Sitz ein herausnehmbarer Einzelsitz, braucht die Gurtschlossleitung eine Trennstelle; IEE weist in einem Patent darauf hin, dass ein Funk-Gurtsensor allein dem Steuergerät nicht sagt, ob der Sitz eingebaut ist – ein fehlendes Signal kann Fehler oder schlicht leeren Boden bedeuten. Ein wieder eingesetzter Sitz mit offenem Stecker ist daher ein häufiger Auslöser. CTS liefert berührungslose Hall-Gurtschlossschalter für solche Anwendungen. Die hintere Gurtwarnung aus FMVSS 208, Abschnitt S7.5(c), gilt für diesen Platz bei Fahrzeugen, die nach dem 1. September 2028 gebaut werden. Öffentlich dokumentiert kein Hersteller B0055; nächstes belegtes Vorbild ist Mitsubishis Beifahrercode B0052.","u":[["h","Sitzstecker nach dem Wiedereinbau des herausnehmbaren Sitzes nicht gesteckt"],["m","Korrodierter Gurtschlossstecker, etwa durch nassen Boden an der Schiebetür"],["m","Defekter Sensor im rechten hinteren Gurtschloss"]],"s":["Airbag- oder Gurtwarnleuchte hinten an","Rechter Rücksitz fehlt in der Gurtanzeige oder wird falsch angezeigt","Sicherheitshinweis: Sitz- und Gurtschlossstecker unter dem Sitz liegen nahe Straffer- und Seitenairbagleitungen; nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[60,450],[0.5,2]],"f":"","x":["B0053","B0054","B0075"]},{"c":"B0056","t":"Gurtsensor dritte Sitzreihe links","e":"Third Row Left Seat Belt Sensor","d":"B0056 gehört zum Gurtschlosssensor am linken Sitz der dritten Reihe, wie es ihn in großen SUVs, Vans und Siebensitzer-Kombis gibt. Sitze der dritten Reihe lassen sich meist flach im Boden versenken; die Gurtschlossleitung läuft daher durch die Klappmechanik und wird bei jedem Vergrößern des Laderaums gebogen. Im Ford-Patent zur Gurtüberwachung hinten ist die Bank der dritten Reihe der fest verdrahtete Teil, nur die herausnehmbare zweite Reihe braucht eine Funkverbindung. FMVSS 208 S7.5(c) dehnt die Gurtwarnung für Fahrzeuge ab Baudatum September 2028 auf alle hinteren Reihen aus. Übliche Technik ist ein Hallschalter, der die eingerastete Zunge erkennt. Mit diesem Wortlaut dokumentiert kein Hersteller B0056 öffentlich, auch kein Bulletin nennt ihn; belegtes Vorbild für diesen Fehlertyp ist Mitsubishis B0052.","u":[["h","Gurtschlossleitung in der Klappmechanik der dritten Reihe gebrochen oder durchgescheuert"],["m","Lockerer oder korrodierter Stecker am Sitz der dritten Reihe"],["l","Defekter Sensor im linken Gurtschloss der dritten Reihe"]],"s":["Airbag- oder Gurtwarnleuchte hinten an","Fehler tritt womöglich nur bei umgeklappter oder aufgestellter dritter Reihe auf","Sicherheitshinweis: Gurtschlossstecker der dritten Reihe können nahe der Strafferverkabelung liegen; nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,2.5]],"f":"","x":["B0057","B0058","B0076"]},{"c":"B0057","t":"Gurtsensor dritte Sitzreihe Mitte","e":"Third Row Center Seat Belt Sensor","d":"Nach J2012 ist B0057 der Gurtschlosssensor des Mittelplatzes in der dritten Reihe – einen solchen Platz haben nur Achtsitzer-Vans und -SUVs. FMVSS 208 S7.5(c) verlangt dort ab September 2028 eine Gurtwarnung. Mit dieser Bedeutung dokumentiert kein Hersteller B0057 öffentlich. Ältere GM-Airbagsteuergeräte nutzten die Nummer anders: Saab 9-5 (2006) und Saab 9-3 legen B0057 ab, wenn der Zündkreis des Beifahrer-Gurtstraffers 2 Sekunden lang unter 1,5 Ohm (±0,2) liegt. GM-Bulletin 14609 nennt B0057 zusammen mit B0058, B0059 und B0064 bis B0066 bei Colorado und Canyon mit Extended Cab 2004–09: Dort ermüden Leitungen im Kabelstrang der hinteren Tür, brechen und können die vorderen Gurtstraffer lahmlegen; GM verlängerte die Kulanz auf 10 Jahre. Bei älteren GM-Fahrzeugen zuerst den Straffer-Zündkreis prüfen.","u":[["m","Defekter Gurtschlosssensor oder defekte Leitung am Mittelplatz der dritten Reihe"],["m","Ältere GM-Pick-ups: gebrochene Leitung im Türkabelstrang hinten zum Straffer (Bulletin 14609)"],["l","Älteres GM-/Saab-Steuergerät: Kurzschluss an Zündpille oder Stecker des Beifahrer-Straffers"]],"s":["Airbag-Warnleuchte an","Je nach Steuergerät: falscher Gurtstatus am Mittelplatz der dritten Reihe oder Beifahrer-Gurtstraffer womöglich außer Funktion","Sicherheitshinweis: Nahe den Gurtschloss- und Straffersteckern laufen Zündkreise; nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","passenger_seatbelt_pretensioner","srs_control_module"],"r":["shop_only",0,[60,600],[0.5,3]],"f":"","x":["B0056","B0058","B0077","B0064"]},{"c":"B0058","t":"Gurtsensor dritte Sitzreihe rechts","e":"Third Row Right Seat Belt Sensor","d":"B0058 ist der J2012-Code für den Gurtschlosssensor am rechten Sitz der dritten Reihe. Der Sensor meldet einen eingerasteten oder freien Gurt an das Steuergerät, das die Gurtanzeige hinten führt – nach FMVSS 208 S7.5(c) ab September 2028 für jeden Rücksitz Pflicht. Klappbare dritte Reihen und der Einstieg über die rechte Schiebetür setzen die Leitung unter Belastung. Mit dieser Bedeutung dokumentiert kein Hersteller B0058 öffentlich. Ältere GM-Steuergeräte weichen auch hier ab: Beim Saab 9-5 (2006) steht B0058 für einen unterbrochenen Zündkreis des Beifahrer-Gurtstraffers, über 4,5 Ohm (±0,2) für 2 Sekunden, der Saab 9-3 kennt zusätzlich eine Variante mit zu hohem Widerstand. GM-Bulletin 14609 zu Colorado und Canyon Extended Cab 2004–09 führt B0058 unter den Straffercodes, die gebrochene Leitungen in der hinteren Tür auslösen.","u":[["m","Gurtschlossleitung des rechten Sitzes der dritten Reihe durch Klappen oder Beladen beschädigt"],["m","Älteres GM-/Saab-Steuergerät: unterbrochener Zündkreis des Beifahrer-Straffers, etwa gebrochene Leitung in der hinteren Tür"],["l","Defekter Sensor im rechten Gurtschloss der dritten Reihe"]],"s":["Airbag-Warnleuchte an","Je nach Steuergerät: rechter Sitz der dritten Reihe falsch angezeigt oder Beifahrer-Gurtstraffer zündet womöglich nicht","Sicherheitshinweis: Nahe den Gurtschloss- und Straffersteckern laufen Zündkreise; nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","passenger_seatbelt_pretensioner","srs_control_module"],"r":["shop_only",0,[60,600],[0.5,3]],"f":"","x":["B0056","B0057","B0078"]},{"c":"B0060","t":"Gurtkraftsensor Fahrer","e":"Driver Seat Belt Tension Sensor","d":"B0060 betrifft einen Gurtkraftsensor im Fahrergurt – ein Kraftmesser, meist am unteren Gurtbeschlag verschraubt, durch den das Gurtband läuft. Bei Delphi bewegt sich ein federbelasteter Schieber gegen den Gurtzug, und ein Hallelement zwischen zwei Magneten macht aus dem Weg eine Spannung; die Federn geben bei etwa 5 bis 15 lb nach. CTS, nach eigener Angabe Marktführer, baut solche Sensoren in verschiedenen Einbauformen. Ein zweites Delphi-Patent lässt den Sensor seinen Wert in 3-lb-Stufen über eine Zweidrahtleitung melden und Werte außerhalb des gültigen Bands als Fehler hoch oder niedrig kennzeichnen. Die Gurtkraftmessung dient vor allem dem Beifahrersitz; am Fahrerplatz ist sie selten. Kein Hersteller dokumentiert B0060 öffentlich; die älteren Saab-Airbagsteuergeräte führen ihn nicht. Airbag-Leuchte an.","u":[["h","Lockerer oder korrodierter Stecker am Gurtkraftsensor am Beschlag"],["m","Ausgang des Gurtkraftsensors hängt oder liegt außerhalb des Bereichs, etwa durch klemmenden Schieber"],["m","Sensorleitung unter dem Sitz oder an der Schwellerverkleidung eingeklemmt"]],"s":["Airbag-Warnleuchte an","Steuergerät greift für den Fahrer womöglich auf eine Standard-Auslösestrategie zurück","Sicherheitshinweis: Der Sensorstecker liegt neben dem Sitz nahe Straffer- und Seitenairbagsteckern; nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_tension_sensor","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,500],[0.5,2]],"f":"","x":["B0061","B0050","B00B5"]},{"c":"B0061","t":"Gurtkraftsensor Beifahrer","e":"Passenger Seat Belt Tension Sensor","d":"B0061 gilt dem Gurtkraftsensor des Beifahrersitzes, einer wichtigen Eingangsgröße der Insassenklassifizierung. FMVSS 208 erlaubt, die Kindersitz-Anforderungen an moderne Airbags mit einer automatischen Abschaltung zu erfüllen, die den Beifahrerairbag bei kleinen Insassen deaktiviert. Ein straff festgezurrter Kindersitz drückt ins Polster und kann auf dem Gewichtssensor wie ein Erwachsener wirken; der Gurtkraftsensor deckt das auf. Im Delphi-Patent zieht das Insassenmodul die Gurtkraft vom Sitzgewicht ab und schaltet den Airbag oberhalb eines kalibrierten Zugs von etwa 30 lb ab; Werte außerhalb des Bereichs meldet der Sensor als Fehler. Mit dieser Bedeutung dokumentiert kein Hersteller B0061 öffentlich. Steuergeräte des Saab 9-3 nutzen ihn für zu niedrigen Widerstand im Kreis des Fahrer-Kopfairbags.","u":[["h","Lockerer oder korrodierter Stecker am Gurtkraftsensor des Beifahrers"],["m","Messwert des Gurtkraftsensors außerhalb des Bereichs oder eingefroren"],["l","Eingangsfehler im Insassenklassifizierungs- oder Airbagsteuergerät"]],"s":["Airbag-Warnleuchte an","Statusanzeige des Beifahrerairbags zeigt womöglich unerwartet an oder aus","Ein straff befestigter Kindersitz wird womöglich nicht sicher erkannt","Sicherheitshinweis: Der Sensorstecker liegt neben dem Beifahrersitz nahe Airbag- und Strafferstecker; nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["seat_belt_tension_sensor","occupant_detection_module","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,2]],"f":"","x":["B0060","B0052","B00A0"]},{"c":"B0062","t":"Knieairbag Auslösekreis Kurzschluss nach Masse","e":"Knee Airbag Deployment Loop Short to Ground","d":"B0062 steht in keiner der zugänglichen J2012-Codelisten, die von B0061 direkt zu B0070 springen, und kein Hersteller dokumentiert ihn mit der Knieairbag-Bedeutung des Titels. J2012 führt die Zündkreise der Knieairbags unter B0004 für den Fahrer und B0013 für den Beifahrer, die Fehlerart steht im angehängten Byte; Mercedes-Benz legt Fehler der Kniebag-Zündpillen als B000413 und B001313 ab; ein Masseschluss trüge in diesem Schema Byte 11. Öffentlich genutzt wird B0062 nur bei Saab: Airbagsteuergeräte des 9-3 (Handbücher 2003 und 2007) legen ihn für den Kreis von Kopfairbag bzw. Überrollbügel auf der Fahrerseite ab, mit Byte 04 für Unterbrechung und 0E für zu hohen Widerstand. Knieairbags sitzen in der unteren Instrumententafel; eine IIHS-Studie mit 414 Crashtests fand für angeschnallte Fahrer kaum Gesamtnutzen.","u":[["h","Leitung des Knieairbags an Armaturenträger oder Lenksäulenteil durchgescheuert"],["m","Beschädigter Knieairbagstecker nach Arbeiten unter der Instrumententafel"],["l","Saab 9-3: stattdessen Fehler im Kreis von Kopfairbag oder Überrollbügel auf der Fahrerseite"]],"s":["Airbag-Warnleuchte an","Knieairbag bleibt bei einem Frontalaufprall womöglich inaktiv","Sicherheitshinweis: Knieairbagstecker sitzen unter der Instrumententafel; Kreis nicht selbst messen, nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["knee_airbag","srs_wiring","srs_control_module"],"r":["shop_only",0,[100,900],[1,3]],"f":"","x":["B0004","B0013"]},{"c":"B0064","t":"Gurtstraffer Fahrer Zündkreis Widerstand zu niedrig","e":"Driver Seat Belt Pretensioner Deployment Loop Resistance Low","d":"B0064 fehlt in den zugänglichen J2012-Codelisten, in denen B0060 den Gurtkraftsensor des Fahrers bezeichnet. Belegt ist die Nummer bei General Motors in älteren Airbagsteuergeräten: Beim Saab 9-5 (2006) wird B0064 gesetzt, sobald der Widerstand im Zündkreis des Fahrer-Gurtstraffers 2 Sekunden unter 1,5 ± 0,2 Ohm bleibt; B0065 steht dort für Unterbrechung, B0066 für eine Spannung an Pin 34 außerhalb von 1,0 bis 4,1 V. Die Handbücher des Saab 9-3 von 2003 und 2007 führen denselben Fehler als zu niedrigen Widerstand des Fahrer-Gurtstraffers. Bei einem Unfall versucht das Steuergerät trotzdem zu zünden. GM-Bulletin 14609 nennt B0064 unter den Codes bei Colorado und Canyon Extended Cab 2004–09 mit gebrochenen Leitungen im Kabelstrang der hinteren Tür. Airbag-Leuchte an.","u":[["h","Strafferleitungen untereinander kurzgeschlossen, etwa gequetschter Kabelstrang an der B-Säule"],["m","Colorado/Canyon Extended Cab: ermüdete Leitungen im Kabelstrang der hinteren Tür (Bulletin 14609)"],["m","Beschädigter oder verschmutzter Strafferstecker"],["l","Innerer Fehler der Zündpille im Fahrer-Gurtstraffer"]],"s":["Airbag-Warnleuchte an","Fahrer-Gurtstraffer arbeitet bei einem Unfall womöglich nicht richtig","Sicherheitshinweis: Strafferstecker sitzen an der B-Säule oder unter dem Sitz; Kreis nicht selbst messen, nur spannungsfrei trennen – Batterie abklemmen und Wartezeit einhalten"],"k":["driver_seatbelt_pretensioner","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,700],[0.5,3]],"f":"","x":["B0060","B0070","B0057"]},{"c":"B0070","t":"Fahrer-Gurtstraffer A Auslösesteuerung","e":"Driver Seat Belt Pretensioner A Deployment Control","d":"Gemeint ist der Zündkreis des ersten Gurtstraffers (Stufe A) am Fahrersitz – die Zündpille, mit der das Airbagsteuergerät bei einem Aufprall die Gurtlose herauszieht. Erkennt das Steuergerät dort Unterbrechung oder Kurzschluss, gilt der Straffer als nicht verfügbar, und die Airbag-Leuchte geht an. Toyota verwendet den Code genau so: Das Bulletin T-SB-0057-22 zum Tundra 2022 nennt B007011 (Masseschluss) und B007012 (Schluss nach Plus); Auslöser war dort die induktive Qi-Ladeschale, behoben wird per Neuprogrammierung des SRS-Steuergeräts. Welches Bauteil Stufe A ist, legt J2012 nicht fest – laut GM kann ein Vordersitz einen Aufroll-, Schloss- oder Endbeschlagstraffer haben, auch mehrere. Mitsubishi führt seine vorderen Aufrollerstraffer unter eigenen Nummern (B1029/B102A). Im Saab 9-3 steht B0070 für den Kreis des Beifahrer-Kopfairbags.","u":[["h","Lockerer oder korrodierter Stecker am Fahrer-Gurtstraffer (B-Säulenfuß oder Sitzseite)"],["m","Zündleitung durch Sitzschienen oder Verkleidungsclips durchgescheuert"],["l","Störeinkopplung durch Zusatzelektronik, etwa eine Qi-Ladeschale (Toyota Tundra 2022, Steuergeräte-Update)"],["l","Interner Fehler der Zündpille im Gurtstraffer"]],"s":["Airbag-Warnleuchte an","Fahrergurt wird bei einem Unfall nicht gestrafft; die Airbags selbst sind meist nicht betroffen","Sicherheitshinweis: Der Gurtstraffer ist ein pyrotechnisches Bauteil; nur spannungsfrei (Batterie ab, Wartezeit) und am besten in einer Fachwerkstatt daran arbeiten"],"k":["driver_seatbelt_pretensioner","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,700],[0.5,2.5]],"f":"","x":["B0079","B007E","B0072","B0050"]},{"c":"B0071","t":"Gurtstraffer erste Reihe Mitte Auslösesteuerung","e":"First Row Center Seat Belt Pretensioner Deployment Control","d":"Der Code ist für einen Gurtstraffer am mittleren Platz der ersten Reihe vorgesehen – den gibt es nur bei einer durchgehenden Dreier-Sitzbank vorn. Das Airbagsteuergerät würde diese Zündpille wie jeden Auslösekreis auf Unterbrechung, Kurzschluss und unzulässigen Widerstand prüfen. Öffentlich dokumentiert kein Hersteller B0071 in dieser Bedeutung. Dass es ein solches Bauteil gibt, zeigt Mercedes-Benz: Die Information LI54.21-P-070658 (gültig für A-Klasse, CLA, GLB) nennt eine Unterbrechung am Gurtstraffer-Aufroller in der Mitte der ersten Sitzreihe – allerdings unter dem eigenen Code B1B36. GM beschreibt Schlossstraffer an der Innenseite eines Vordersitzes. In den Airbagsteuergeräten des Saab 9-3 (2003, 2007) bedeutet B0071 dagegen einen Kurzschluss im Kreis des Beifahrer-Kopfairbags bzw. Überrollbügels.","u":[["h","Stecker unter dem mittleren Vordersitz locker oder korrodiert"],["m","Kabelbaum beim Umklappen oder Ausbau von Mittelsitz bzw. Konsole beschädigt"],["l","Airbagsteuergerät auf einen mittleren Gurtstraffer codiert, den das Fahrzeug nicht hat"],["l","Interner Fehler des mittleren Gurtstraffers"]],"s":["Airbag-Warnleuchte an","Mittlerer Insasse vorn erhält bei einem Unfall keine Gurtstraffung","Sicherheitshinweis: pyrotechnisches Bauteil – Batterie abklemmen, vorgeschriebene Wartezeit einhalten und die Arbeit einer Fachwerkstatt überlassen"],"k":["first_row_center_pretensioner","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,700],[0.5,3]],"f":"","x":["B0070","B0072","B0074"]},{"c":"B0072","t":"Beifahrer-Gurtstraffer A Auslösesteuerung","e":"Passenger Seat Belt Pretensioner A Deployment Control","d":"B0072 meldet einen Fehler im Auslösekreis des Gurtstraffers der Stufe A am Beifahrersitz. Solange der Kreis gestört ist, kann sich das Airbagsteuergerät nicht auf die Zündung verlassen; es schaltet die Warnleuchte ein und speichert den Code. Toyota nutzt die Nummer in diesem Sinn: T-SB-0057-22 (Tundra und Tundra Hybrid 2022) führt B007212 – Schluss nach Plus – unter den Codes, die die kabellose Ladeschale auslösen kann; Abhilfe ist ein Software-Update des SRS-Steuergeräts. Am Beifahrerplatz sitzen oft weitere Straffer: Mercedes legt Endbeschlag- und Aufrollerstraffer des Beifahrers unter B007A und B007F ab, FCA ordnet B007F dem Aufroller an der B-Säule zu. Wie Schloss- und Aufrollerstraffer die Gurtlose beseitigen, beschreibt die NHTSA-Auswertung von 2013. Mit gespeichertem B0072 ist die Straffung am Beifahrersitz nicht gesichert.","u":[["h","Stecker am Beifahrer-Gurtstraffer nicht eingerastet oder korrodiert"],["m","Leitung am Beifahrersitz-Unterbau oder an der B-Säulenverkleidung eingeklemmt"],["l","Störeinkopplung durch Zusatzelektronik wie eine Qi-Ladeschale"],["l","Zündpille des Gurtstraffers intern defekt"]],"s":["Airbag-Warnleuchte an","Beifahrergurt bleibt bei einem Unfall womöglich locker","Sicherheitshinweis: Der Straffer ist pyrotechnisch; nur spannungsfrei anfassen (Batterie ab, Wartezeit) und in einer Fachwerkstatt instand setzen lassen"],"k":["passenger_seatbelt_pretensioner","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,700],[0.5,2.5]],"f":"","x":["B007A","B007F","B0070","B0052"]},{"c":"B0073","t":"Gurtstraffer zweite Reihe links Auslösesteuerung","e":"Second Row Left Seat Belt Pretensioner Deployment Control","d":"B0073 betrifft den Gurtstraffer am linken Außenplatz der zweiten Reihe, meist im hinteren Gurtaufroller untergebracht. Mitsubishi dokumentiert ihn genau unter diesem Namen: Bei eingeschalteter Zündung legt das Airbagsteuergerät B0073 mit Byte 11, 12, 13, 1A oder 1B ab – Masseschluss, Schluss nach Plus, Unterbrechung, Schluss der Leitungen untereinander oder zu hoher Widerstand –, mit Byte 55, wenn die gespeicherte Konfiguration nicht zum Fahrzeug passt; jeder Fehler muss 2 Sekunden anstehen. Toyota nennt im Tundra-Bulletin T-SB-0057-22 B007311 und B007312. Crashtests des IIHS mit einem Dummy hinten links zeigen, warum solche Straffer zunehmend auch hinten verbaut werden. GM belegt die Nummer anders: Bulletin 22-NA-170 zu Equinox und Terrain verknüpft B0073 mit Wasser im Stecker X320 des rechten Vordersitz-Kabelbaums.","u":[["h","Stecker am linken hinteren Aufroller nach Verkleidungs- oder Sitzausbau locker oder beschädigt"],["m","Leitung zum linken hinteren Straffer mit Masse- oder Plusschluss"],["l","Codierung des Airbagsteuergeräts passt nicht zu den verbauten hinteren Straffern (Mitsubishi Byte 55)"],["l","Interner Fehler des linken hinteren Straffers oder des Airbagsteuergeräts"]],"s":["Airbag-Warnleuchte an","Insasse hinten links erhält bei einem Unfall keine Gurtstraffung","Sicherheitshinweis: pyrotechnisches Bauteil im hinteren Aufroller; nur im spannungsfreien Zustand und am besten in der Fachwerkstatt arbeiten"],"k":["second_row_left_pretensioner","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,2.5]],"f":"","x":["B0075","B007B","B00E3","B0053"]},{"c":"B0074","t":"Gurtstraffer zweite Reihe Mitte Auslösesteuerung","e":"Second Row Center Seat Belt Pretensioner Deployment Control","d":"B0074 stünde für den Auslösekreis eines Gurtstraffers am Mittelplatz der zweiten Reihe. Eigene Straffer für den hinteren Mittelgurt sind selten; die Rücksitz-Crashtests des IIHS betrachten die Außenplätze, und kein Hersteller veröffentlicht B0074 mit der J2012-Bedeutung. Häufig ist der Code bei GM, aber in älterer Belegung: Der Saab 9-4X (2011) setzt B0074 00/04, wenn das Modul der Sitzbelegungserkennung die Sensormatte verliert, das Impala-Bulletin PIE0485A (2015–2018) behandelt B0074-0D, und die Aktion N182188910 zum Buick Verano 2017 führt B0074 0D/0E auf eine eingeklemmte Leitung der Sitzbelegungserkennung zurück, die den Beifahrerairbag abschaltet. Bei GM führt B0074 also zur Sitzbelegungserkennung vorn rechts. Wo der Code wirklich einen hinteren Mittelstraffer meint, leuchtet die Airbag-Lampe und der Straffer ist außer Funktion.","u":[["h","Bei GM-Fahrzeugen Fehler in der Sensormatte der Sitzbelegungserkennung oder deren eingeklemmter Leitung (ältere GM-Belegung)"],["m","Stecker des hinteren Mittelstraffers beim Umklappen oder Ausbau der Rückbank gelöst"],["l","Unterbrechung oder Kurzschluss in der Leitung zum hinteren Mittelsitz"]],"s":["Airbag-Warnleuchte an","Bei GM zusätzlich Beifahrerairbag-Anzeige OFF, obwohl ein Erwachsener sitzt","Sicherheitshinweis: Rückhalte-Bauteile können pyrotechnisch sein oder die Airbagsteuerung betreffen – Batterie abklemmen, Wartezeit einhalten, Fachwerkstatt aufsuchen"],"k":["second_row_center_pretensioner","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B0073","B0075","B007D","B00E5"]},{"c":"B0075","t":"Gurtstraffer zweite Reihe rechts Auslösesteuerung","e":"Second Row Right Seat Belt Pretensioner Deployment Control","d":"B0075 ist das Gegenstück zu B0073 auf der rechten Seite: der Gurtstraffer am rechten Außenplatz der zweiten Reihe. Mitsubishi führt ihn als PRE-TEN REAR RH mit dem J2012-Titel und prüft den Kreis bei jeder eingeschalteten Zündung; Byte 11 bedeutet Masseschluss, Byte 13 Unterbrechung, weitere Bytes stehen für Schluss nach Plus, Leitungsschluss untereinander, zu hohen Widerstand oder falsche Konfiguration – jeweils nach 2 Sekunden. Toyota nennt im Qi-Ladeschalen-Bulletin zum Tundra 2022 B007512, einen Schluss nach Plus. Die Leitung zum hinteren Aufroller verläuft durch Sitz- und Verkleidungsbereiche, die bei Innenraumarbeiten geöffnet werden; ein gelöster Stecker ist deshalb der erste Verdacht. Ist der Code aktiv, leuchtet die Airbag-Lampe, und der Mitfahrer hinten rechts wird bei einem Unfall womöglich nicht in den Sitz gezogen.","u":[["h","Stecker am rechten hinteren Aufroller nach Innenraumarbeiten nicht ganz eingerastet"],["m","Durchgescheuerte Leitung zum rechten hinteren Straffer (Masse- oder Plusschluss)"],["l","Störeinkopplung durch Zusatzelektronik, behoben per Steuergeräte-Update (Toyota Tundra 2022)"],["l","Interner Fehler des rechten hinteren Straffers"]],"s":["Airbag-Warnleuchte an","Insasse hinten rechts ohne Gurtstraffung bei einem Unfall","Sicherheitshinweis: Der hintere Aufroller enthält eine pyrotechnische Ladung; nur spannungsfrei und durch eine Fachwerkstatt bearbeiten"],"k":["second_row_right_pretensioner","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,2.5]],"f":"","x":["B0073","B007C","B00E4","B0055"]},{"c":"B0076","t":"Gurtstraffer dritte Reihe links Auslösesteuerung","e":"Third Row Left Seat Belt Pretensioner Deployment Control","d":"B0076 gehört zum Gurtstraffer am linken Platz der dritten Sitzreihe, die es nur in Fahrzeugen mit drei Reihen gibt. Kein Hersteller veröffentlicht B0076 in dieser Bedeutung. Wie Straffer der dritten Reihe tatsächlich erfasst werden, zeigt Mercedes: LI54.21-P-070658 führt Unterbrechungen an den Gurtstraffer-Aufrollern links und rechts in der dritten Reihe als B00E7 und B00E6, also auf den Plätzen der Stufe C – auf diesen Modellen ist B0076 nicht zu erwarten. Technisch handelt es sich um eine Zündpille, die das Airbagsteuergerät auf Unterbrechung, Kurzschluss und Widerstandsabweichung überwacht, wie bei den Aufroll- und Schlossstraffern vorn, die GM und NHTSA beschreiben. Ist B0076 gespeichert, leuchtet die Airbag-Lampe, und der Insasse links in der dritten Reihe wird womöglich nicht gestrafft.","u":[["h","Stecker am linken Gurt der dritten Reihe durch Umklappen oder Ausbau des Sitzes gelöst"],["m","Leitung durch Gepäck oder Verkleidungsarbeiten im Laderaum beschädigt"],["l","Airbagsteuergerät auf einen nicht verbauten Straffer der dritten Reihe codiert"]],"s":["Airbag-Warnleuchte an","Insasse dritte Reihe links bei einem Unfall ohne Gurtstraffung","Sicherheitshinweis: pyrotechnisches Gurtbauteil – vor dem Anfassen Batterie abklemmen und warten, Reparatur in der Fachwerkstatt"],"k":["third_row_left_pretensioner","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,3]],"f":"","x":["B0077","B0078","B00E7"]},{"c":"B0077","t":"Gurtstraffer dritte Reihe Mitte Auslösesteuerung","e":"Third Row Center Seat Belt Pretensioner Deployment Control","d":"B0077 steht für den Gurtstraffer am Mittelplatz der dritten Reihe. Kaum ein Fahrzeug hat einen, und kein Hersteller dokumentiert B0077 mit dieser J2012-Bedeutung; Mercedes, das manche Modelle mit Aufrollerstraffern in der dritten Reihe ausstattet, führt dort nur einen linken und einen rechten (B00E7/B00E6). Häufiger begegnet die Nummer bei älteren Saab aus GM-Zeit: Der Saab 9-5 von 2006 speichert B0077, wenn das Airbagsteuergerät wegen Unterbrechung oder Kurzschluss nicht mit dem Seitenaufprallsensor der Fahrerseite kommunizieren kann, und die Steuergeräte des Saab 9-3 (2003, 2007) nutzen sie für den B-Säulen-Sensor links. Dort liegt der Fehler also am Tür- bzw. Säulensensor, nicht an einem Gurt hinten. Bei einem echten Mittelstraffer der dritten Reihe bedeutet der Code: Airbag-Lampe an, Straffer außer Funktion.","u":[["h","Bei älteren Saab 9-3/9-5 Fehler am Seitenaufprall- bzw. B-Säulen-Sensor links (ältere GM-Belegung)"],["m","Stecker des mittleren Straffers der dritten Reihe beim Umklappen oder Ausbau gelöst"],["l","Airbagsteuergerät auf einen nicht vorhandenen Mittelstraffer codiert"]],"s":["Airbag-Warnleuchte an","Beim Saab ist die Auslösung der Seitenairbags auf der Fahrerseite womöglich beeinträchtigt","Sicherheitshinweis: Airbagsensoren und Gurtstraffer gehören zum pyrotechnischen Rückhaltesystem; nur spannungsfrei und in einer Fachwerkstatt arbeiten"],"k":["third_row_center_pretensioner","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,3]],"f":"","x":["B0076","B0078","B00E8"]},{"c":"B0078","t":"Gurtstraffer dritte Reihe rechts Auslösesteuerung","e":"Third Row Right Seat Belt Pretensioner Deployment Control","d":"B0078 bezieht sich auf den rechten Platz der dritten Reihe und dessen Gurtstraffer. In dieser J2012-Bedeutung veröffentlicht ihn kein Hersteller; Mercedes-Modelle mit Aufrollerstraffern in der dritten Reihe legen den rechten Straffer als B00E6 ab. Wie B0077 ist die Nummer in den älteren Saab-Steuergeräten von GM ein Sensorcode: Der Saab 9-5 (2006) setzt B0078 bei Unterbrechung oder Kurzschluss in der Verbindung zum Seitenaufprallsensor der Beifahrerseite, das Airbagsteuergerät des 9-3 (2003, 2007) für den rechten B-Säulen-Sensor – mit Bytes für gestörte Kommunikation, Schluss nach Plus oder Masse und falsch verbauten Sensor. Betrifft der Code tatsächlich den rechten Straffer der dritten Reihe, ist die Airbag-Lampe an, und der Platz bleibt bis zur Reparatur des Kreises ohne Straffung.","u":[["h","Bei älteren Saab 9-3/9-5 Fehler am Seitenaufprall- bzw. B-Säulen-Sensor rechts (ältere GM-Belegung)"],["m","Stecker am rechten Gurt der dritten Reihe beim Umklappen oder Ausbau gelöst"],["l","Interner Fehler des rechten Straffers der dritten Reihe"]],"s":["Airbag-Warnleuchte an","Insasse dritte Reihe rechts ohne Straffung, beim Saab beeinträchtigte Seitenaufprallerkennung rechts","Sicherheitshinweis: pyrotechnische Rückhalteteile; nur bei abgeklemmter Batterie nach der Wartezeit und in einer Fachwerkstatt bearbeiten"],"k":["third_row_right_pretensioner","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,3]],"f":"","x":["B0076","B0077","B00E6"]},{"c":"B0079","t":"Fahrer-Gurtstraffer B Auslösesteuerung","e":"Driver Seat Belt Pretensioner B Deployment Control","d":"B0079 kennzeichnet den zweiten Gurtstraffer (Stufe B) am Fahrersitz. Mercedes-Benz nutzt den Code genau so: In LI54.21-P-070658 zu A-Klasse, CLA und GLB ist B007913 eine Unterbrechung an der Zündpille des Endbeschlagstraffers auf der Fahrerseite; der Aufrollerstraffer desselben Sitzes erscheint als B007E. Ein Endbeschlag- oder Verankerungsstraffer zieht am unteren Gurtanker an der Sitzaußenseite und strafft so den Beckengurt – beschrieben im Rettungsleitfaden von GM und in einem Hyundai-Kia-Patent. Ältere Saab belegen die Nummer anders: Der Saab 9-5 (2006) speichert B0079, wenn ein falscher Seitenaufprallsensor auf der Fahrerseite eingebaut ist. Mit gespeichertem B0079 leuchtet die Airbag-Lampe, und der Beckengurtstraffer des Fahrers zündet womöglich nicht.","u":[["h","Stecker am Endbeschlagstraffer neben dem Fahrersitz locker oder korrodiert"],["m","Leitung zum Endbeschlagstraffer von der Sitzschiene eingeklemmt"],["l","Beim Saab 9-5 (2006) falscher Seitenaufprallsensor verbaut (ältere GM-Belegung)"],["l","Interner Fehler der Zündpille im Endbeschlagstraffer"]],"s":["Airbag-Warnleuchte an","Beckengurt des Fahrers wird bei einem Unfall nicht gestrafft","Sicherheitshinweis: Der Endbeschlagstraffer ist pyrotechnisch; nie unter Spannung messen – Batterie ab, Wartezeit, Fachwerkstatt"],"k":["driver_pretensioner_b","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,2.5]],"f":"","x":["B0070","B007E","B007A","B0080"]},{"c":"B007A","t":"Beifahrer-Gurtstraffer B Auslösesteuerung","e":"Passenger Seat Belt Pretensioner B Deployment Control","d":"B007A ist das Gegenstück zu B0079 auf der Beifahrerseite und betrifft den zweiten Gurtstraffer am Beifahrersitz. Mercedes führt B007A13 bei A-, CLA- und GLB-Klasse für eine Unterbrechung an der Zündpille des Endbeschlagstraffers des Beifahrers; den Aufrollerstraffer dieses Platzes hält es getrennt unter B007F. Ein solcher Becken- oder Verankerungsstraffer zündet zusammen mit dem Aufroller – so beschreibt es Joyson für seinen Beckengurtstraffer – und zieht den Beckengurt aufs Becken, damit der Insasse nicht darunter durchrutscht. Mitsubishi legt vergleichbare Beckengurtstraffer unter eigenen Codes (B1001, B1002) ab statt auf J2012-Plätzen; dort ist B007A nicht zu erwarten. Ist B007A gesetzt, leuchtet die Airbag-Lampe, und das Steuergerät vermerkt, dass die Beckenstraffung am Beifahrerplatz fehlt.","u":[["h","Stecker am Endbeschlagstraffer des Beifahrers gelöst, etwa nach Sitzausbau"],["m","Leitung zum Beckengurtstraffer unter dem Beifahrersitz eingeklemmt"],["l","Interner Fehler des Beckengurtstraffers am Beifahrersitz"]],"s":["Airbag-Warnleuchte an","Beckengurt des Beifahrers wird nicht gestrafft, höheres Risiko des Durchrutschens","Sicherheitshinweis: pyrotechnischer Straffer neben dem Sitz – Batterie abklemmen, Wartezeit beachten, Reparatur durch eine Fachwerkstatt"],"k":["passenger_pretensioner_b","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,2.5]],"f":"","x":["B0072","B007F","B0079","B0082"]},{"c":"B007B","t":"Gurtstraffer B zweite Reihe links Auslösesteuerung","e":"Second Row Left Seat Belt Pretensioner B Deployment Control","d":"B007B wäre ein zweiter Gurtstraffer am linken Außenplatz der zweiten Reihe, etwa ein Beckengurtstraffer zusätzlich zum Aufroller. Kein Hersteller veröffentlicht B007B. Die dokumentierten Fälle hinten nutzen andere Plätze: Mitsubishi legt den linken hinteren Aufrollerstraffer unter B0073 ab, Mercedes den linken hinteren Gurtstraffer-Aufroller als B00E3, also auf Stufe C. Welche Hardware eine Stufe B sein könnte, zeigt Joysons Beckengurtstraffer, der gemeinsam mit einem Aufrollerstraffer zündet. In Frontalcrashtests des IIHS mit Dummy hinten links rutschte der Dummy bei einigen Fahrzeugen mit hinteren Straffern unter dem Beckengurt durch – genau dagegen hilft ein Beckenstraffer. Ist B007B gespeichert, leuchtet die Airbag-Lampe und diese Stufe fällt aus.","u":[["h","Stecker des linken hinteren Becken- oder Verankerungsstraffers beim Ausbau der Rückbank gelöst"],["m","Airbagsteuergerät auf einen nicht verbauten hinteren Straffer der Stufe B codiert"],["l","Bodenkabelbaum zum linken Rücksitz beschädigt"]],"s":["Airbag-Warnleuchte an","Beckengurt hinten links wird bei einem Unfall nicht gestrafft","Sicherheitshinweis: pyrotechnisches Teil am Rücksitz; nur spannungsfrei (Batterie ab, warten) und in einer Fachwerkstatt arbeiten"],"k":["second_row_left_pretensioner_b","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,3]],"f":"","x":["B0073","B007C","B00E3"]},{"c":"B007C","t":"Gurtstraffer B zweite Reihe rechts Auslösesteuerung","e":"Second Row Right Seat Belt Pretensioner B Deployment Control","d":"B007C ist das rechte Gegenstück zu B007B: eine zusätzliche Straffer-Stufe am rechten Außenplatz der zweiten Reihe. Kein Hersteller veröffentlicht den Code. An diesem Platz verwendet Mitsubishi B0075 für den Aufrollerstraffer und Mercedes B00E4 für den rechten hinteren Gurtstraffer-Aufroller – für B007C bleibt bei beiden keine Aufgabe. Eine Stufe B wäre typischerweise ein Schloss- oder Verankerungsstraffer am Beckengurt; die NHTSA-Auswertung von 2013 erklärt, wie ein Schlossstraffer das Gurtschloss über Seilzug und Kolben nach unten zieht, Joyson beschreibt Beckengurtstraffer im Zusammenspiel mit dem Aufroller. Hinten sind Beckenstraffer weit seltener als vorn, der Code ist deshalb ungewöhnlich. Taucht er auf, bleibt die Airbag-Lampe an, und auf diese Stufe ist kein Verlass.","u":[["h","Stecker des rechten hinteren Schloss- oder Verankerungsstraffers bei Sitzarbeiten gelöst"],["m","Konfiguration des Airbagsteuergeräts enthält eine nicht verbaute Stufe"],["l","Interner Fehler des rechten hinteren Straffers der Stufe B"]],"s":["Airbag-Warnleuchte an","Beckengurt hinten rechts wird bei einem Unfall nicht vorgespannt","Sicherheitshinweis: Der Straffer enthält eine pyrotechnische Ladung; nur bei abgeklemmter Batterie und in einer Fachwerkstatt daran arbeiten"],"k":["second_row_right_pretensioner_b","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,3]],"f":"","x":["B0075","B007B","B00E4"]},{"c":"B007D","t":"Gurtstraffer B zweite Reihe Mitte Auslösesteuerung","e":"Second Row Center Seat Belt Pretensioner B Deployment Control","d":"B007D bezeichnet einen zweiten Gurtstraffer am Mittelplatz der zweiten Reihe. Kein Hersteller dokumentiert ihn – schon ein einzelner Straffer hinten in der Mitte ist ungewöhnlich, eine zweite Stufe dort noch seltener. Wo es eine gibt, würde Stufe B am Gurtschloss oder am Gurtanker angreifen, vergleichbar mit dem Schlossstraffer mit Seilrolle aus dem Autoliv-Patent US7360795B2 oder den Schlossstraffern, die GM an der Innenseite der Vordersitze zeigt. Die Leitung zum hinteren Mittelplatz läuft durch Sitzunterbau oder Boden und kann beim Umklappen oder Ausbau einer geteilten Rückbank leiden. Überwacht wird der Zündkreis wie jeder andere. Mit gespeichertem B007D leuchtet die Airbag-Lampe, und das Steuergerät behandelt diese Stufe als nicht verfügbar.","u":[["h","Stecker am hinteren mittleren Schloss- oder Verankerungsstraffer durch Umklappen der Rückbank gelöst"],["m","Airbagsteuergerät auf eine nicht vorhandene hintere mittlere Stufe B codiert"],["l","Kabelbaum unter der Rückbank durchgescheuert oder eingeklemmt"]],"s":["Airbag-Warnleuchte an","Insasse hinten Mitte ohne zweite Straffer-Stufe","Sicherheitshinweis: pyrotechnische Gurtteile – System spannungsfrei machen (Batterie ab, Wartezeit) und die Arbeit einer Fachwerkstatt überlassen"],"k":["second_row_center_pretensioner_b","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,3]],"f":"","x":["B0074","B007B","B007C","B00E5"]},{"c":"B007E","t":"Fahrer-Gurtstraffer C Auslösesteuerung","e":"Driver Seat Belt Pretensioner C Deployment Control","d":"B007E ist der Kreis des dritten Gurtstraffers (Stufe C) am Fahrersitz. Mercedes-Benz belegt diesen Platz mit dem Aufroller: In LI54.21-P-070658 für A-, CLA- und GLB-Klasse bedeutet B007E13 eine Unterbrechung an der Zündpille des Fahrer-Gurtstraffer-Aufrollers; B0079 steht dort für den Endbeschlagstraffer, B0080 für den Gurtkraftbegrenzer des Fahrers. Der Aufrollerstraffer sitzt in der B-Säule oder im Sitz und dreht die Gurtspule zurück, um die Lose aus dem Schultergurt zu ziehen – so erklären es GM und Joyson. Dieselbe Mercedes-Liste legt die hinteren Aufroller auf die C-Codes B00E3, B00E4, B00E6 und B00E7; Stufe C heißt dort also durchgehend Aufroller. Mit gespeichertem B007E ist die Airbag-Lampe an, und der Schultergurt des Fahrers wird nicht vorgespannt.","u":[["h","Aufrollerstecker unten an der B-Säule links locker oder Kontakte aufgeweitet"],["m","Kabelbaum von B-Säulen- oder Schwellerverkleidung eingeklemmt"],["l","Interner Fehler des Fahrer-Aufrollerstraffers"]],"s":["Airbag-Warnleuchte an","Schultergurt des Fahrers wird bei einem Unfall nicht gestrafft","Sicherheitshinweis: Der Aufroller enthält eine pyrotechnische Ladung – Batterie abklemmen, warten und die Arbeit einer Fachwerkstatt überlassen"],"k":["driver_pretensioner_c","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,700],[0.5,2.5]],"f":"","x":["B0070","B0079","B007F","B0080"]},{"c":"B007F","t":"Beifahrer-Gurtstraffer C Auslösesteuerung","e":"Passenger Seat Belt Pretensioner C Deployment Control","d":"B007F betrifft den dritten Gurtstraffer (Stufe C) am Beifahrersitz und ist der am besten belegte Code dieser Reihe. Mercedes führt B007F13 als Unterbrechung an der Zündpille des Gurtstraffer-Aufrollers auf der Beifahrerseite (A-, CLA- und GLB-Klasse). FCA belegt den Platz mit demselben Bauteil: STAR-Fall S2008000193 zum Ram 1500 (2020–2021) verknüpft B007F-2B mit einem lockeren oder aufgeweiteten Aufrollerstecker unten an der rechten B-Säule, instand gesetzt mit Satz 68148100AA; Fall S2008000137 zum Jeep Grand Cherokee 2020 meldet B007F-11, Masseschluss, durch einen von der B-Säulenverkleidung eingeklemmten Karosseriekabelbaum. Der Aufroller ist ein pyrotechnisches Bauteil, das bei einem Unfall das Gurtband zurückspult. Mit gesetztem B007F leuchtet die Airbag-Lampe, und der Schultergurt des Beifahrers wird nicht vorgespannt.","u":[["h","Aufrollerstecker unten an der rechten B-Säule locker oder mit aufgeweiteten Kontakten (FCA S2008000193)"],["m","Karosseriekabelbaum zwischen Halter der B-Säulenverkleidung und Karosserie eingeklemmt (FCA S2008000137)"],["l","Interner Fehler des Beifahrer-Aufrollerstraffers"]],"s":["Airbag-Warnleuchte an, oft nach kurz zurückliegender Innenraum- oder Karosseriearbeit","Schultergurt des Beifahrers wird bei einem Unfall nicht gestrafft","Sicherheitshinweis: pyrotechnischer Aufroller in der B-Säule; nur spannungsfrei (Batterie ab, Wartezeit) und in einer Fachwerkstatt bearbeiten"],"k":["passenger_pretensioner_c","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,700],[0.5,2.5]],"f":"","x":["B0072","B007A","B007E","B0082"]},{"c":"B0080","t":"Fahrer-Gurtkraftbegrenzer Auslösesteuerung","e":"Driver Seat Belt Load Limiter Deployment Control","d":"B0080 meldet einen Fehler im Zündkreis, der den Gurtkraftbegrenzer des Fahrers umschaltet. Bei adaptiven Aufrollern zündet das Airbag-Steuergerät dazu eine kleine Pille, die festlegt, ab welcher Kraft das Gurtband nachgibt – passend zu Unfallschwere und Insasse. Mercedes-Benz belegt genau diese Bedeutung: Die Information LI54.21-P-070658 (A-Klasse, CLA, GLB) führt B008013 als Unterbrechung an der Zündpille des Fahrer-Gurtkraftbegrenzers, Ursache war erhöhter Übergangswiderstand am Steckverbinder des Steuergeräts. Ford zählt B0080 bei Fusion/MKZ 2017–2018 zu den Codes, die eine Neuprogrammierung des Rückhaltemoduls behebt, ohne Bedeutung. Ältere Saab von GM (9-3, 9-5) nutzen B0080 dagegen für einen inneren Fehler des Seiten- bzw. B-Säulen-Sensors links. Die Airbag-Leuchte brennt.","u":[["h","Erhöhter Übergangswiderstand am Stecker des Airbag-Steuergeräts (Mercedes LI54.21-P-070658)"],["m","Durchgescheuerte oder getrennte Leitung zum Fahrer-Aufroller an der B-Säule"],["l","Software des Rückhaltemoduls benötigt ein Update (Ford Fusion/MKZ)"],["l","Interner Fehler der Zündpille des Gurtkraftbegrenzers im Aufroller"]],"s":["Airbag-Warnleuchte an, teils mit SRS-Meldung im Kombiinstrument","Fahrergurt behält bei einem Unfall nur die Grundstufe der Kraftbegrenzung","Sicherheitshinweis: pyrotechnisches Bauteil im Fahrer-Aufroller; nur spannungsfrei (Batterie ab, Wartezeit) in einer Fachwerkstatt bearbeiten"],"k":["driver_load_limiter","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,900],[0.5,3]],"f":"","x":["B0079","B007E","B0081","B0082"]},{"c":"B0081","t":"Gurtkraftbegrenzer erste Reihe Mitte Auslösesteuerung","e":"First Row Center Seat Belt Load Limiter Deployment Control","d":"B0081 gehört zu einem umschaltbaren Kraftbegrenzer am Mittelsitz einer dreisitzigen Vorderbank. Kein Hersteller veröffentlicht den Code in dieser Bedeutung. Mercedes-Benz legt einen Gurtstraffer-Aufroller in der Mitte der ersten Reihe unter dem eigenen Code B1B36 ab, und die NHTSA-Studie von 2013 hält fest, dass Kraftbegrenzer nur an den beiden äußeren Vordersitzen Standard wurden. Meist trägt die Nummer eine GM-Bedeutung: Bei Global-A-Fahrzeugen wie dem Saab 9-4X steht sie für einen Fehler des Beifahrer-Präsenzmoduls (00) oder ein falsch verbautes Modul (3A), der Beifahrerairbag wird abgeschaltet; dazu gibt es die Sonderkulanz N182188910 (Buick Verano 2017) und PIE0407B (Impala). Saab 9-3/9-5 melden damit einen falschen Seitensensor rechts. Erst die Marke klären.","u":[["h","Bei GM Fehler oder falsche Ausführung des Beifahrer-Präsenzmoduls im Sitz (andere Bedeutung)"],["m","Leitung zum Aufroller des vorderen Mittelsitzes im Sitzunterbau beschädigt"],["l","Interner Fehler der Zündpille am Kraftbegrenzer des Mittelsitzes"]],"s":["Airbag-Warnleuchte an","Bei GM zeigt die Beifahrerairbag-Anzeige AUS, obwohl ein Erwachsener sitzt","Sicherheitshinweis: Airbag-System mit pyrotechnischen Bauteilen; nur spannungsfrei in einer Fachwerkstatt prüfen und instand setzen"],"k":["first_row_center_load_limiter","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,800],[0.5,3]],"f":"","x":["B0071","B0080","B0082","B0084"]},{"c":"B0082","t":"Beifahrer-Gurtkraftbegrenzer Auslösesteuerung","e":"Passenger Seat Belt Load Limiter Deployment Control","d":"B0082 betrifft den Zündkreis des umschaltbaren Gurtkraftbegrenzers am Beifahrersitz. Zwei Hersteller belegen diese Bedeutung. Mercedes-Benz führt B008213 als Unterbrechung an der Zündpille des Beifahrer-Gurtkraftbegrenzers (A-Klasse, CLA, GLB). Fords Sonder-Servicemeldung 51998 nennt Escape, Corsair, Bronco Sport und Maverick des Modelljahrs 2023, die B0082:1A wegen des Beifahrer-Gurtaufrollers am Stecker C303B ablegen; zeigt sich dort ein Verbindungsfehler, wird Aufroller samt Straffer vor jeder Kabelreparatur getauscht. Patente von Autoliv zeigen, warum Aufroller und Begrenzer zusammengehören: Das Gas des Straffers kann die höhere Begrenzungsstufe wählen. Bei GM Global A (Saab 9-4X) steht B0082 dagegen für den Gurtwarnsensor im Beifahrersitz. Die Airbag-Leuchte bleibt an.","u":[["h","Schlechte Verbindung am Stecker des Beifahrer-Aufrollers (Ford C303B, SSM 51998)"],["m","Erhöhter Widerstand am Stecker des Airbag-Steuergeräts (Mercedes LI54.21-P-070658)"],["l","Interner Fehler der Beifahrer-Aufrollereinheit mit Kraftbegrenzer"]],"s":["Airbag-Warnleuchte an","Beifahrergurt kann die Stufe der Kraftbegrenzung bei einem Unfall nicht umschalten","Sicherheitshinweis: pyrotechnischer Aufroller an der rechten B-Säule; nur spannungsfrei (Batterie ab, Wartezeit) in einer Fachwerkstatt bearbeiten"],"k":["passenger_load_limiter","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,900],[0.5,3]],"f":"","x":["B0072","B007A","B007F","B0080"]},{"c":"B0083","t":"Gurtkraftbegrenzer zweite Reihe links Auslösesteuerung","e":"Second Row Left Seat Belt Load Limiter Deployment Control","d":"B0083 ist für einen umschaltbaren Kraftbegrenzer am linken Rücksitz vorgesehen. Kein Hersteller veröffentlicht ihn in dieser J2012-Bedeutung. Kraftbegrenzer hinten gibt es durchaus: In einer 2020 vorgestellten Rücksitz-Testreihe der IIHS hatten zehn Fahrzeuge hinten Straffer und Begrenzer, eines nur einen Begrenzer. Weit häufiger ist B0083 ein GM-Code für ein anderes Bauteil. Bei Global-A-Modellen (Saab 9-4X, 2011) bezeichnet er den linken Frontaufprallsensor mit Fehlerbytes für Kurzschluss, Unterbrechung, zu geringen Strom, inneren Fehler, falsches Teil und ungültige Daten; eine Unterbrechung gilt, wenn der Sensor über 375 ms schweigt. GM-Bulletin PI1480 (Colorado/Canyon 2015) führt B0083/B0084 mit Byte 05 auf korrodierte Sensoren oder nicht eingerastete Steckersicherungen zurück. Saab 9-3/9-5 meinen damit den Sitzpositionssensor rechts.","u":[["h","Bei GM korrodierter linker Frontaufprallsensor oder nicht eingerastete Steckersicherung (PI1480, andere Bedeutung)"],["m","Leitung zum linken hinteren Aufroller unter Verkleidung oder Sitz beschädigt"],["l","Interner Fehler der Zündpille am hinteren Kraftbegrenzer"]],"s":["Airbag-Warnleuchte an, teils nur zeitweise","Linker hinterer Gurt behält bei einem Unfall eine feste Begrenzungsstufe","Sicherheitshinweis: Rückhaltesystem mit pyrotechnischen Teilen; nur spannungsfrei in einer Fachwerkstatt arbeiten"],"k":["second_row_left_load_limiter","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,800],[0.5,3]],"f":"","x":["B0073","B007B","B0084","B0085"]},{"c":"B0084","t":"Gurtkraftbegrenzer zweite Reihe Mitte Auslösesteuerung","e":"Second Row Center Seat Belt Load Limiter Deployment Control","d":"B0084 bezeichnet einen per Zündpille umgeschalteten Kraftbegrenzer am mittleren Rücksitz. Weder ein Hersteller noch ein Bulletin zeigt ihn in dieser Bedeutung, und das Bauteil ist selten: Die NHTSA-Auswertung von 2013 nennt Kraftbegrenzer nur an den äußeren Vordersitzen als Standard, der Mittelgurt hinten ist oft ein einfacher Aufroller. Ein Delphi-Patent für Rücksitze ohne Airbag wählt zwischen etwa 4–6 kN und 2–3 kN sogar rein mechanisch, ganz ohne Zündkreis. Meist begegnet B0084 bei GM. Global-A-Fahrzeuge (Saab 9-4X, 2011) legen ihn für den rechten Frontaufprallsensor ab, wenn Kurzschluss, Unterbrechung oder fehlerhafte Daten zehn Sekunden anstehen; PI1480 behandelt ihn bei Colorado/Canyon 2015. Saab 9-3/9-5 meinen den Fahrersitz-Positionssensor und schalten dann Stufe 2 des Lenkradairbags ab.","u":[["h","Bei GM Fehler am rechten Frontaufprallsensor oder dessen Stecker (andere Bedeutung)"],["m","Bei Saab 9-3/9-5 Unterbrechung oder Kurzschluss im Kreis des Fahrersitz-Positionssensors (andere Bedeutung)"],["l","Beschädigte Leitung zu einem hinteren Mittelsitz-Begrenzer, falls verbaut"]],"s":["Airbag-Warnleuchte an","Bei Saab 9-3/9-5 ist die zweite Stufe des Fahrerairbags abgeschaltet","Sicherheitshinweis: Airbag-System mit pyrotechnischen Teilen; nur spannungsfrei in einer Fachwerkstatt prüfen"],"k":["second_row_center_load_limiter","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,700],[0.5,2.5]],"f":"","x":["B0074","B007D","B0083","B0085"]},{"c":"B0085","t":"Gurtkraftbegrenzer zweite Reihe rechts Auslösesteuerung","e":"Second Row Right Seat Belt Load Limiter Deployment Control","d":"B0085 verweist auf den Zündkreis eines umschaltbaren Kraftbegrenzers am rechten Rücksitz. Kein Hersteller belegt ihn in dieser Bedeutung. Joyson bietet zweistufige Begrenzer mit degressivem oder adaptivem Verhalten an, und ein Autoliv-Patent schaltet vom steifen auf den weichen Torsionsabschnitt um, sobald das Steuergerät nach Überschreiten einer Verzögerungsschwelle eine Pille zündet; im Fond würde ein solcher Kreis wie jeder andere überwacht. In den IIHS-Rücksitztests wurde rechts hinten seltener gemessen als links (16 gegenüber 27 Versuchen). Praktisch bezeichnet B0085 beim Saab 9-4X von 2011 (GM Global A) den vorderen linken Seitenaufprallsensor, gemeldet bei Kurzschluss, Unterbrechung, Strom über 23 mA, innerem Fehler, falschem Teil oder ungültigen Daten. Erst die Marke klärt das Bauteil.","u":[["h","Bei GM linker vorderer Seitenaufprallsensor oder dessen Türleitung defekt (andere Bedeutung)"],["m","Leitung zum rechten hinteren Aufroller von Sitz oder Verkleidung eingeklemmt"],["l","Interner Fehler der Zündpille am rechten hinteren Begrenzer"]],"s":["Airbag-Warnleuchte an","Bei GM verschwindet der gespeicherte Eintrag erst nach 100 fehlerfreien Zündzyklen","Sicherheitshinweis: pyrotechnische Rückhalteteile; nur spannungsfrei in einer Fachwerkstatt arbeiten"],"k":["second_row_right_load_limiter","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,800],[0.5,3]],"f":"","x":["B0075","B007C","B0083","B0084"]},{"c":"B0086","t":"Gurtkraftbegrenzer dritte Reihe links Auslösesteuerung","e":"Third Row Left Seat Belt Load Limiter Deployment Control","d":"B0086 ist für einen umschaltbaren Kraftbegrenzer am linken Sitz der dritten Reihe reserviert. Kein Hersteller dokumentiert ihn, ein elektrisch gezündeter Begrenzer so weit hinten ist ungewöhnlich. Das Delphi-Patent für Rücksitze erklärt den Grund: Ohne Airbag und Gewichtserkennung in den hinteren Reihen wählt es die Stufe nach der Länge des ausgezogenen Gurtbands – etwa 4–6 kN für große Insassen oder einen Kindersitz, 2–3 kN für kleine. Auch die NHTSA-Studie von 2013 zählt Kraftbegrenzer nur an den äußeren Vordersitzen zum Standard. Im Saab 9-4X von 2011, einem Global-A-Modell, steht B0086 für den rechten vorderen Seitenaufprallsensor; Kurzschlüsse, Unterbrechung, Stromunterschreitung, Elektronikdefekt, Fehlbestückung und gestörte Botschaften müssen dafür zehn Sekunden anstehen. Wo ein solcher Kreis existiert, leuchtet die Airbag-Lampe.","u":[["h","Bei GM rechter vorderer Seitenaufprallsensor oder Leitung defekt (andere Bedeutung)"],["m","Kabelbaum der dritten Reihe durch Umklappen oder Ausbau des Sitzes belastet"],["l","Interner Fehler der Zündpille am Begrenzer der dritten Reihe"]],"s":["Airbag-Warnleuchte an","Linker Gurt der dritten Reihe begrenzt die Kraft nur auf fester Stufe","Sicherheitshinweis: Rückhaltesystem mit pyrotechnischen Teilen; nur spannungsfrei in einer Fachwerkstatt arbeiten"],"k":["third_row_left_load_limiter","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,800],[0.5,3]],"f":"","x":["B0076","B0087","B0088"]},{"c":"B0087","t":"Gurtkraftbegrenzer dritte Reihe Mitte Auslösesteuerung","e":"Third Row Center Seat Belt Load Limiter Deployment Control","d":"B0087 würde den Zündkreis eines umschaltbaren Kraftbegrenzers am Mittelsitz der dritten Reihe melden. Diese Kombination ist fast nur theoretisch: Kein Hersteller dokumentiert den Code, und die NHTSA-Studie von 2013 datiert die vollständige Ausstattung mit Kraftbegrenzern (bis Modelljahr 2007) nur für die äußeren Vordersitze. Joyson beschreibt die Technik: lineare Begrenzer, abgestimmt auf den Crashpuls des Fahrzeugs, und zweistufige Ausführungen für adaptive oder degressive Kraft. Im GM-Global-A-Modell Saab 9-4X (2011) bezeichnet B0087 den linken hinteren Seitenaufprallsensor. GM setzt ihn, wenn ein Fehler zehn Sekunden ansteht oder das Steuergerät länger als 375 ms nichts vom Sensor hört. Ein gespeicherter Eintrag erlischt dort nach 100 fehlerfreien Zündzyklen. Zuerst die Marke klären.","u":[["h","Bei GM linker hinterer Seitenaufprallsensor oder dessen Stecker defekt (andere Bedeutung)"],["l","Beschädigte Leitung zu einem Mittelsitz-Begrenzer der dritten Reihe, falls verbaut"]],"s":["Airbag-Warnleuchte an","Bei GM schaltet das Kombiinstrument auf Anforderung des Moduls die AIR-BAG-Anzeige ein","Sicherheitshinweis: Airbag-System mit pyrotechnischen Teilen; nur spannungsfrei in einer Fachwerkstatt prüfen"],"k":["third_row_center_load_limiter","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,700],[0.5,2.5]],"f":"","x":["B0077","B0086","B0088"]},{"c":"B0088","t":"Gurtkraftbegrenzer dritte Reihe rechts Auslösesteuerung","e":"Third Row Right Seat Belt Load Limiter Deployment Control","d":"B0088 schließt die Reihe der Kraftbegrenzer mit dem rechten Sitz der dritten Reihe ab. Kein Hersteller belegt ihn in dieser Bedeutung. Ist ein solcher pillengeschalteter Begrenzer verbaut, prüft das Steuergerät seinen Kreis wie jeden Zünder auf Unterbrechung, Kurzschluss und Widerstand außerhalb des Fensters; ein Autoliv-Patent zeigt das Prinzip, bei dem Gas aus einer Pille einen Sperrring freigibt, sodass der weichere Torsionsabschnitt übernimmt. Der Delphi-Aufroller für Rücksitze schaltet dagegen rein mechanisch. Beim Saab 9-4X (2011) meldet B0088 dagegen den rechten hinteren Seitenaufprallsensor, mit denselben Fehlerbytes wie die Nachbarn: Kurzschlüsse, Unterbrechung oder hoher Widerstand, zu geringer Strom, innerer Fehler, falsches Teil und ungültige Daten. Die Airbag-Lampe leuchtet.","u":[["h","Bei GM rechter hinterer Seitenaufprallsensor oder Leitung defekt (andere Bedeutung)"],["m","Kabelbaum zum rechten Sitz der dritten Reihe durch Umklappen belastet"],["l","Interner Fehler der Zündpille am rechten Begrenzer der dritten Reihe"]],"s":["Airbag-Warnleuchte an","Rechter Gurt der dritten Reihe kann die Begrenzungsstufe nicht wechseln","Sicherheitshinweis: pyrotechnische Rückhalteteile; nur spannungsfrei in einer Fachwerkstatt arbeiten"],"k":["third_row_right_load_limiter","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,800],[0.5,3]],"f":"","x":["B0078","B0086","B0087"]},{"c":"B0090","t":"Crashsensor vorne links","e":"Left Frontal Restraints Sensor","d":"B0090 betrifft den linken Frontcrashsensor, einen Beschleunigungs-Satelliten in der vorderen Knautschzone, der dem Airbag-Steuergerät früh meldet, wie heftig die Front getroffen wird. Laut Bosch verbessern solche Vorfeldsensoren die Frontcrash-Erkennung. Mehrere Hersteller nutzen den Code genau so. Acura-Bulletin 18-016 (ILX 2017) nennt B0090-87, kein Signal vom linken Frontaufprallsensor, weil durch abweichenden Leitungsquerschnitt Wasser in den Stecker dringt; Sensor und Motorraum-Kabelbaum werden erneuert. Für den Ram 1500 meldet FCA B0090-49, innerer Elektronikfehler des linken Frontbeschleunigungssensors: Nach einem Sensortausch muss die Teilenummer zum Rückhalte-Steuergerät passen (STAR S2408000050), und TSB 08-150-26 (Ram 1500, 2025) programmiert das Steuergerät neu. Die Airbag-Leuchte geht an.","u":[["h","Wasser im Stecker des linken Frontsensors, Kabelbaum beschädigt (Acura 18-016)"],["m","Teilenummer des Ersatzsensors passt nicht zum Rückhalte-Steuergerät (FCA S2408000050)"],["m","Software des Rückhalte-Steuergeräts muss neu aufgespielt werden (FCA TSB 08-150-26)"],["l","Sensor durch Frontschaden oder fehlerhaften Wiedereinbau nach Karosseriearbeit beschädigt"]],"s":["Airbag-Warnleuchte an, oft nach Frontreparatur oder Wassereintritt","Frontcrash-Erkennung stützt sich nur noch auf den internen Sensor des Steuergeräts","Sicherheitshinweis: Airbag-System; vor Arbeiten an Sensor oder Leitung Batterie abklemmen und Wartezeit einhalten, Fachwerkstatt"],"k":["left_front_crash_sensor","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,700],[0.5,3]],"f":"","x":["B0094","B0095","B0091"]},{"c":"B0091","t":"Seitencrashsensor links 1","e":"Left Side Restraints Sensor 1","d":"B0091 betrifft den ersten linken Seitencrashsensor, den Mitsubishi in die Vordertür setzt und als DOOR SATEL SENS LH mit dem J2012-Titel in Klammern führt. Das Airbag-Steuergerät prüft ihn bei eingeschalteter Zündung und speichert nach zwei Sekunden Verzögerung einen Untertyp: -11 bei Masseschluss, -55, wenn die im Gerät abgelegte Konfiguration nicht zum Fahrzeug passt, -81 bei Kommunikationsstörung, dazu weitere Bytes. Solche Türsatelliten messen meist Druck: Bosch erklärt, dass der abgeschlossene Türhohlraum als Messvolumen dient, eine Verformung also den Druck hebt und das Steuergerät binnen etwa 5 ms entscheiden kann. Continental bietet einen Drucksatelliten für dieselbe Aufgabe an. Mit gesetztem B0091 leuchtet die Airbag-Lampe, die Seitencrash-Erkennung links kann geschwächt sein.","u":[["h","Kurzschluss oder schlechter Kontakt im Türkabelbaum oder Sensorstecker"],["m","Interner Fehler des Satellitensensors in der Vordertür"],["m","Konfiguration des Airbag-Steuergeräts passt nicht zum Fahrzeug (Mitsubishi Untertyp -55)"],["l","Interner Fehler des Airbag-Steuergeräts"]],"s":["Airbag-Warnleuchte an","Seiten- und Kopfairbags links lösen bei einem Seitenaufprall womöglich spät oder nicht aus","Sicherheitshinweis: Airbag-System; vor Arbeiten in der Tür Batterie abklemmen und Wartezeit einhalten, dann in einer Fachwerkstatt prüfen lassen"],"k":["left_side_impact_sensor_1","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,2.5]],"f":"","x":["B0092","B0093","B0096","B0090"]},{"c":"B0092","t":"Seitencrashsensor links 2","e":"Left Side Restraints Sensor 2","d":"B0092 gehört zum zweiten Crashsensor auf der linken Seite. Mitsubishi setzt ihn an die linke B-Säule und führt ihn als B-PILLAR SAT SEN LH mit dem J2012-Titel Left Side Restraints Sensor 2; im Index steht nur der Untertyp -55, gesetzt zwei Sekunden nachdem das Steuergerät feststellt, dass seine gespeicherte Konfiguration nicht zum Fahrzeug passt. Für eine Säule eignet sich ein Beschleunigungs-Satellit: Bosch montiert solche Sensoren an steifen Bauteilen wie Schweller, Sitzquerträger oder B- und C-Säule, und sein Chip SMA773 misst zwei Achsen bis 60 g und spricht über eine zweiadrige PSI5-Leitung mit dem Steuergerät. Saab-Modelle von GM nutzen die Nummer anders: Der 9-5 (2006) und der 9-3 legen B0092 für einen allgemeinen Fehler der Beifahrer-Präsenzerkennung ab und werten das Airbag-System dann als gestört. Die Airbag-Lampe brennt.","u":[["h","Konfiguration des Airbag-Steuergeräts passt nicht zu den verbauten Sensoren (Mitsubishi Untertyp -55)"],["m","Lockerer oder korrodierter Stecker am B-Säulen-Sensor nach Verkleidungs- oder Karosseriearbeit"],["m","Bei Saab von GM Fehler der Beifahrer-Präsenzerkennung (andere Bedeutung)"],["l","Interner Fehler des Satellitensensors an der B-Säule"]],"s":["Airbag-Warnleuchte an","Seitencrash-Erkennung links stützt sich nur noch auf die übrigen Sensoren","Sicherheitshinweis: Airbag-System; vor dem Abnehmen der Säulenverkleidung Batterie abklemmen und Wartezeit einhalten, Fachwerkstatt"],"k":["left_side_impact_sensor_2","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,2.5]],"f":"","x":["B0091","B0093","B009A","B0097"]},{"c":"B0093","t":"Seitencrashsensor links 3","e":"Left Side Restraints Sensor 3","d":"B0093 ist der dritte Crashsensor links. Mitsubishi setzt ihn an die linke C-Säule, nennt ihn C-PILLAR SAT SEN LH und gibt den J2012-Wortlaut Left Side Restraints Sensor 3 an. Anders als beim B-Säulen-Sensor ist hier der volle Satz an Untertypen belegt: -11 bei Masseschluss der Sensorleitung, -55 bei unpassender Konfiguration, -81 bei gestörter Kommunikation und weitere, jeweils nach zwei Sekunden bei eingeschalteter Zündung bestätigt. Ein so weit hinten sitzender Sensor kann dem Steuergerät Treffer hinter der Vordertür früh anzeigen. Bosch nennt C-Säulen als Einbauort seiner Beschleunigungs-Satelliten, und Continentals gSAT misst zum selben Zweck die Beschleunigung in steifer Struktur. Solange B0093 gespeichert ist, brennt die Airbag-Lampe.","u":[["h","Sensorleitung mit Masseschluss oder schlechter Kontakt am C-Säulen-Stecker (Untertypen -11/-81)"],["m","Interner Fehler des Satellitensensors an der C-Säule"],["m","Konfiguration des Airbag-Steuergeräts passt nicht zum Fahrzeug (Untertyp -55)"],["l","Interner Fehler des Airbag-Steuergeräts"]],"s":["Airbag-Warnleuchte an","Seitencrash-Erkennung links hinter der Vordertür ist eingeschränkt","Sicherheitshinweis: Airbag-System; vor Arbeiten an der hinteren Säule Batterie abklemmen und Wartezeit einhalten, nur Fachwerkstatt"],"k":["left_side_impact_sensor_3","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,2.5]],"f":"","x":["B0091","B0092","B0098","B009A"]},{"c":"B0094","t":"Crashsensor vorne Mitte","e":"Center Frontal Restraints Sensor","d":"B0094 betrifft einen einzelnen Crashsensor in der Mitte der Fahrzeugfront – für Autos mit einem zentralen Frontsatelliten statt eines linken und rechten. Mitsubishi zeigt ihn als CRASH ZONE SENS mit dem J2012-Namen Center Frontal Restraints Sensor. Der Index kennt neun Untertypen, je nach zwei Sekunden bei Zündung an gesetzt: -11/-12 Schluss nach Masse oder Plus, -88 Unterbrechung, -81 Kommunikationsausfall, -25 fehlgeschlagene Eigendiagnose, -28 Nullpunktfehler, -93 Reset-Fehler, -55 unpassende Konfiguration und -86, wenn Sensor und Steuergerät nicht die vorgesehenen Teile sind. B0090 und B0095 fehlen dort, der Mittelsensor ist also der einzige Frontsatellit. Laut Bosch verbessern Beschleunigungssensoren in der Knautschzone die Frontcrash-Erkennung. Die Airbag-Leuchte geht an.","u":[["h","Unterbrechung, Kurzschluss oder korrodierter Kontakt in der Leitung zum mittleren Frontsensor (Untertypen -11/-12/-88)"],["m","Interner Fehler des Crashzonen-Sensors, z. B. Nullpunkt- oder Eigendiagnosefehler (Untertypen -25/-28)"],["m","Sensor oder Airbag-Steuergerät nicht das vorgesehene Teil oder falsch konfiguriert (Untertypen -86/-55)"],["l","Sensor oder Halter durch Frontschaden verbogen oder nach Karosseriearbeit schlecht montiert"]],"s":["Airbag-Warnleuchte an","Frontcrash-Erkennung stützt sich nur noch auf die Sensoren im Airbag-Steuergerät","Sicherheitshinweis: Airbag-System; vor Arbeiten am Frontsensor Batterie abklemmen und Wartezeit einhalten, nur Fachwerkstatt"],"k":["center_front_crash_sensor","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,2.5]],"f":"","x":["B0090","B0095","B0091","B0096"]},{"c":"B0095","t":"Crashsensor vorne rechts","e":"Right Frontal Restraints Sensor","d":"B0095 ist das rechte Gegenstück zu B0090: ein Beschleunigungs-Satellit in der rechten vorderen Knautschzone, mit dem das Airbag-Steuergerät früh abschätzt, wie schwer ein Frontaufprall ist. Honda nutzt den Code so bei Fit und HR-V 2016–2017: B0095-87 heißt, vom rechten Frontaufprallsensor kommt kein Signal; mit AER17060A bat Honda, solche Autos vor jeder Reparatur zu melden. Beim Ram 1500 legt FCA B0095-49 für einen inneren Elektronikfehler des rechten Front-Beschleunigungssensors ab. Der STAR-Fall S2408000050 führt Wiederholfehler auf einen Ersatzsensor zurück, dessen Teilenummer nicht zum Rückhalte-Steuergerät passt; TSB 08-150-26 programmiert das Steuergerät beim Modelljahr 2025 neu. Mitsubishi rief einst Lancer zurück, weil Salzwasser die Frontsensoren korrodierte. Die Airbag-Leuchte brennt.","u":[["h","Teilenummer des Ersatzsensors passt nicht zum Rückhalte-Steuergerät (FCA S2408000050)"],["m","Wasser oder Streusalz im Sensorgehäuse oder Stecker vorne rechts"],["m","Software des Rückhalte-Steuergeräts muss neu aufgespielt werden (FCA TSB 08-150-26)"],["l","Innerer Defekt des rechten Front-Beschleunigungssensors"]],"s":["Airbag-Warnleuchte an, oft nach einer Frontreparatur","Frontaufpralle rechts werden später oder ungenauer bewertet","Sicherheitshinweis: Airbag-System; vor Arbeiten am Sensor Batterie abklemmen und Wartezeit einhalten, nur Fachwerkstatt"],"k":["right_front_crash_sensor","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,700],[0.5,3]],"f":"","x":["B0090","B0094","B0096"]},{"c":"B0096","t":"Seitencrashsensor rechts 1","e":"Right Side Restraints Sensor 1","d":"B0096 betrifft den ersten Crashsensor auf der rechten Seite, das Spiegelbild zu B0091. Mitsubishi setzt ihn in die rechte Vordertür, nennt ihn DOOR SATEL SENS RH und druckt den J2012-Titel daneben; das Airbag-Steuergerät prüft ihn bei Zündung an und speichert nach zwei Sekunden etwa -11 für Masseschluss, -81, wenn vom Sensor keine Daten mehr kommen, und -55 für eine Konfiguration, die nicht zum Auto passt – insgesamt neun Untertypen. Honda legt bei Fit und HR-V 2016–2017 B0096-87 ab, kein Signal vom ersten rechten Seitenaufprallsensor. In der Tür arbeitet meist ein Drucksensor: Bosch beschreibt, wie eine Delle den Luftdruck im Türinneren ändert, sodass die ganze Tür zum Messfühler wird. Saab 9-3 und 9-5 vergeben B0096 dagegen an den Kreis des Gurtschloss-Schalters am Beifahrersitz. Die Airbag-Leuchte geht an.","u":[["h","Durchgescheuerte Ader oder schlechter Kontakt im Türkabelbaum zwischen Karosserie und rechter Vordertür"],["m","Interner Fehler des Satellitensensors in der rechten Vordertür"],["l","Konfiguration des Airbag-Steuergeräts passt nicht zum Fahrzeug (Mitsubishi Untertyp -55)"],["l","Bei Saab 9-3/9-5 Fehler im Gurtschloss-Schalterkreis Beifahrer (andere Bedeutung)"]],"s":["Airbag-Warnleuchte an, teils erst nach Öffnen oder Arbeiten an der rechten Vordertür","Seiten- und Kopfairbags rechts lösen bei einem Seitenaufprall womöglich verspätet aus","Sicherheitshinweis: Airbag-System; vor dem Abnehmen der Türverkleidung Batterie abklemmen und Wartezeit einhalten, nur Fachwerkstatt"],"k":["right_side_impact_sensor_1","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,2.5]],"f":"","x":["B0091","B0097","B0098","B0095"]},{"c":"B0097","t":"Seitencrashsensor rechts 2","e":"Right Side Restraints Sensor 2","d":"B0097 ist der zweite Crashsensor rechts. Mitsubishi befestigt ihn an der rechten B-Säule, führt ihn als B-PILLAR SAT SEN RH und nennt als J2012-Bezeichnung Right Side Restraints Sensor 2. Belegt ist dort nur der Untertyp -55: Nach zwei Sekunden bei Zündung an meldet das Steuergerät, dass seine gespeicherte Konfiguration nicht zu den verbauten Sensoren passt. Honda bestätigt die Zählung mit B0097-87, kein Signal vom zweiten rechten Seitenaufprallsensor (Fit/HR-V 2016–2017). An einer Säule sitzt meist ein Beschleunigungs-Satellit; Bosch montiert solche an B- und C-Säule, Schweller oder Sitzquerträger. Nicht jeder nutzt den Code: FCA meldet den rechten B-Säulen-Sensor beim Ram 1500 (2025) als B2764, Saab 9-3/9-5 belegen B0097 mit dem Gurtschloss-Schalterkreis des Fahrers. Die Airbag-Leuchte bleibt an.","u":[["h","Konfiguration des Airbag-Steuergeräts passt nicht zu den verbauten Sensoren, etwa nach Gerätetausch (Mitsubishi Untertyp -55)"],["m","Stecker am rechten B-Säulen-Sensor nach Verkleidungs- oder Gurtarbeiten lose oder beschädigt"],["m","Rechter B-Säulen-Sensor sendet kein Signal (Honda Untertyp -87)"],["l","Bei Saab 9-3/9-5 Fehler im Gurtschloss-Schalterkreis Fahrer (andere Bedeutung)"]],"s":["Airbag-Warnleuchte an","Seitenaufpralle rechts im Bereich der B-Säule erkennen nur noch die übrigen Sensoren","Sicherheitshinweis: Airbag-System; vor dem Abnehmen der Säulenverkleidung Batterie abklemmen und Wartezeit einhalten, nur Fachwerkstatt"],"k":["right_side_impact_sensor_2","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,2.5]],"f":"","x":["B0092","B0096","B0098","B009D"]},{"c":"B0098","t":"Seitencrashsensor rechts 3","e":"Right Side Restraints Sensor 3","d":"B0098 gehört zum dritten Crashsensor rechts, im Airbag-Index von Mitsubishi der C-PILLAR SAT SEN RH mit dem J2012-Wortlaut Right Side Restraints Sensor 3. Es gilt der volle Satz von neun Untertypen, jeweils zwei Sekunden nach dem Erkennen bei Zündung an gesetzt; neben Masseschluss (-11), unpassender Konfiguration (-55) und Kommunikationsausfall (-81) stehen Schluss nach Plus (-12), Unterbrechung (-88), Nullpunktfehler (-28) und Reset-Fehler (-93) darin. Ein so weit hinten montierter Sensor bemerkt Treffer an Hintertür und Fondbereich früh; Continentals gSAT liefert dafür Beschleunigungswerte aus steifer Struktur. FCA nutzt für den rechten C-Säulen-Sensor des Ram 1500 den eigenen Code B2765, und das Saab-9-3-Airbagmodul meldet mit B0098, dass die Beifahrer-Präsenzerkennung insgesamt gestört ist. Die Airbag-Leuchte geht an.","u":[["h","Unterbrochene oder kurzgeschlossene Leitung oder schlechter Kontakt am rechten C-Säulen-Stecker (Untertypen -11/-12/-88/-81)"],["m","Interner Fehler des rechten C-Säulen-Sensors, z. B. Nullpunkt- oder Reset-Fehler (Untertypen -28/-93)"],["l","Konfiguration des Airbag-Steuergeräts passt nicht zum Fahrzeug (Untertyp -55)"],["l","Beim Saab 9-3 Fehler der Beifahrer-Präsenzerkennung (andere Bedeutung)"]],"s":["Airbag-Warnleuchte an","Seitencrash-Erkennung rechts an der Hintertür ist eingeschränkt","Sicherheitshinweis: Airbag-System; vor Arbeiten an der hinteren Säule Batterie abklemmen und Wartezeit einhalten, nur Fachwerkstatt"],"k":["right_side_impact_sensor_3","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,2.5]],"f":"","x":["B0093","B0096","B0097","B009D"]},{"c":"B0099","t":"Überschlagsensor","e":"Roll Over Sensor","d":"B0099 meldet einen Fehler der Überschlagerkennung, die entscheidet, ob Kopfairbags und Gurtstraffer zünden, wenn ein Fahrzeug kippt. Bosch integriert Überschlagsensoren in sein Basis-Airbag-Steuergerät; der Sensor ist also oft Teil des Moduls. Ein Delphi-Patent zeigt das Prinzip: Drehrate und Vertikalbeschleunigung ergeben Rollwinkel und -rate, die mit Auslöse- und Sperrkurven verglichen werden; ein Querbeschleunigungssensor gibt unabhängig frei. FMVSS 226 verlangt eine überwachte Bereitschaftsanzeige, wenn der Schutz gegen Herausschleudern bei Überschlag auslöst; Karma rief den Revero 2018 zurück, weil dessen Überschlagerkennung nicht aktiv war. FCA nutzt den Code: Beim Rückruf Y79 (Grand Cherokee 2021, Wagoneer 2022) prüft die Werkstatt vor dem Neuprogrammieren auf B0099-96, ohne ihn zu erklären. Die Airbag-Leuchte brennt.","u":[["h","Interner Fehler des im Airbag-Steuergerät integrierten Überschlagsensors (Gerätetausch)"],["m","Airbag-Steuergerät locker, schräg montiert oder nach einem Unfall außerhalb der Einbaulage"],["l","Leitungs- oder Steckerfehler, wo ein separater Überschlagsensor verbaut ist"],["l","Software oder Konfiguration des Rückhalte-Steuergeräts passt nicht zum Fahrzeug"]],"s":["Airbag-Warnleuchte an","Kopfairbags und Gurtstraffer lösen bei einem Überschlag womöglich nicht aus","Sicherheitshinweis: Airbag-Steuergerät mit Überschlagerkennung; nur spannungsfrei (Batterie ab, Wartezeit) in einer Fachwerkstatt bearbeiten"],"k":["rollover_sensor","srs_control_module"],"r":["shop_only",0,[100,1200],[0.5,3]],"f":"","x":["B0090","B0091","B0095","B0096"]},{"c":"B009A","t":"Seitencrashsensor links 4","e":"Left Side Restraints Sensor 4","d":"B009A setzt die linke Sensorreihe über die drei Plätze hinaus fort, die die meisten Autos nutzen. Kein Hersteller dokumentiert diesen Code öffentlich. Der Airbag-Index von Mitsubishi endet links bei B0093 (C-Säule), FCA nummeriert seine Säulensatelliten im eigenen Bereich B276x – den vierten Platz belegt also keiner. Ein vierter Sensor links lohnt sich bei langen Karosserien oder zusätzlichen Sitzreihen: Laut Bosch sitzen Beschleunigungs-Satelliten an Schweller, Sitzquerträger, B- und C-Säule oder im Heck, Drucksensoren überwachen einen Türhohlraum. Setzt ein Fahrzeug B009A, bekommt das Airbag-Steuergerät von diesem Satelliten kein plausibles Signal oder erkennt Kurzschluss, Unterbrechung oder falsche Konfiguration; Untertyp und Einbauort stehen nur in der Herstellerdokumentation. Die Airbag-Leuchte geht an.","u":[["h","Beschädigte Leitung oder Stecker zum vierten Sensor links, oft nach Sitz- oder Verkleidungsausbau"],["m","Interner Fehler des vierten linken Crash-Satelliten"],["l","Airbag-Steuergerät für eine Sensorbestückung codiert, die das Fahrzeug nicht hat"]],"s":["Airbag-Warnleuchte an","Seitencrash-Erkennung links im Bereich des ausgefallenen Sensors ist schwächer","Sicherheitshinweis: Airbag-System; vor Arbeiten an Sensoren oder Leitungen Batterie abklemmen und Wartezeit einhalten, nur Fachwerkstatt"],"k":["left_side_restraints_sensor_4","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,3]],"f":"","x":["B009B","B009C","B0093","B009D"]},{"c":"B009B","t":"Seitencrashsensor links 5","e":"Left Side Restraints Sensor 5","d":"B009B bezeichnet einen fünften Crashsensor links. Kein Hersteller dokumentiert diesen Code öffentlich; die gesichteten Bulletins und Airbag-Indizes enden lange davor. Warum Autos mehrere Seitensatelliten tragen, zeigt FMVSS 214: Insassen müssen beim Aufprall einer fahrenden Barriere und beim Pfahltest geschützt sein, und ein schmaler Pfahl kann die Flanke überall treffen. Continental bietet dafür zwei Satelliten an: Der gSAT meldet Beschleunigung aus steifer Struktur, der pSAT reagiert auf den Druckanstieg in einer eingedrückten Tür. Ein fünfter Sensor links würde vermutlich eine Hintertür oder eine weitere Sitzreihe überwachen. Ist B009B gespeichert, hat das Steuergerät Signal oder Kreis dieses Sensors verworfen, und Seiten- oder Kopfairbags reagieren links womöglich später. Die Airbag-Leuchte brennt.","u":[["h","Leitungs- oder Steckerfehler auf dem Weg zum fünften Sensor links"],["m","Interner Fehler des fünften linken Satelliten (Druck- oder Beschleunigungsausführung)"],["l","Ersatzsensor mit falscher Teilenummer nach einer Karosseriereparatur"]],"s":["Airbag-Warnleuchte an","Seiten- und Kopfairbags links lösen bei einem Seitenaufprall womöglich später aus","Sicherheitshinweis: Airbag-System; vor Arbeiten Zündung aus, Batterie abklemmen und Wartezeit einhalten, nur Fachwerkstatt"],"k":["left_side_restraints_sensor_5","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,3]],"f":"","x":["B009A","B009C","B009E"]},{"c":"B009C","t":"Seitencrashsensor links 6","e":"Left Side Restraints Sensor 6","d":"B009C ist der sechste und letzte linke Platz im J2012-Sensorblock. Kein Hersteller dokumentiert diesen Code öffentlich. Echte Fahrzeuge zeigen, wie viele Seitensatelliten üblich sind: Der FCA-Rückruf 19V-449 (Jeep Cherokee 2019) nennt zwei Sensoren im Motorraum und vier für B- und C-Säulen, also höchstens drei je Seite, und FCA führt diese Säulensensoren als B2761 bis B2765 statt im Block B009x. Ein sechster Sensor links passt daher nur zu langen Transportern, Bussen oder Fahrzeugen mit mehreren hinteren Reihen, wo auch Boschs Variante mit Satelliten im Heck greift. Taucht B009C auf, zuerst klären, welchen Sensor der Hersteller damit meint; bei einem Auto mit weniger Sensoren deutet der Eintrag eher auf eine falsche Konfiguration des Steuergeräts. Die Airbag-Leuchte geht an.","u":[["m","Airbag-Steuergerät auf mehr Seitensensoren konfiguriert, als verbaut sind"],["m","Beschädigter Heck-Kabelbaum oder Stecker zum sechsten Sensor links"],["l","Interner Fehler des sechsten linken Satelliten"]],"s":["Airbag-Warnleuchte an","Seitencrash-Erkennung hinten links ist eingeschränkt","Sicherheitshinweis: Airbag-System; Batterie abklemmen und Wartezeit einhalten, dann in einer Fachwerkstatt diagnostizieren lassen"],"k":["left_side_restraints_sensor_6","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,3]],"f":"","x":["B009A","B009B","B009F"]},{"c":"B009D","t":"Seitencrashsensor rechts 4","e":"Right Side Restraints Sensor 4","d":"B009D eröffnet die zweite Hälfte der rechten Sensorreihe nach B0096 bis B0098. Kein Hersteller dokumentiert diesen Code öffentlich; Mitsubishi endet rechts beim C-Säulen-Sensor B0098, Hondas Fit und HR-V kommen mit zwei Seitensensoren je Seite aus. Was ein ausgefallener Seitensatellit bedeutet, zeigt der FCA-Rückruf 19V-449: Beim Jeep Cherokee 2019 konnte das Rückhalte-Steuergerät den Kontakt zu Beschleunigungssensoren verlieren, die Airbag-Leuchte ging an, eine späte oder ausbleibende Auslösung drohte – die Sensoren wurden getauscht. Boschs SMA773 mit PSI5-Anbindung ist ein Beispiel für solche Satelliten und misst zwei Achsen bis 60 g. Ein gespeicherter B009D heißt also, dass das Steuergerät einen vierten Sensor rechts verloren oder verworfen hat; den Einbauort nennt der Hersteller. Die Airbag-Leuchte ist an.","u":[["h","Kommunikation mit dem vierten Sensor rechts durch Leitung, Stecker oder Sensor gestört"],["m","Interner Fehler des vierten rechten Crash-Satelliten"],["l","Airbag-Steuergerät für eine Sensorbestückung codiert, die das Fahrzeug nicht hat"]],"s":["Airbag-Warnleuchte an","Seitencrash-Erkennung rechts im Bereich dieses Sensors ist schwächer","Sicherheitshinweis: Airbag-System; vor Arbeiten an Sensoren Batterie abklemmen und Wartezeit einhalten, nur Fachwerkstatt"],"k":["right_side_restraints_sensor_4","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,3]],"f":"","x":["B009E","B009F","B0098","B009A"]},{"c":"B009E","t":"Seitencrashsensor rechts 5","e":"Right Side Restraints Sensor 5","d":"B009E steht für einen fünften Crashsensor auf der rechten Fahrzeugseite. Kein Hersteller dokumentiert diesen Code öffentlich: Der Airbag-Index von Mitsubishi schließt die rechte Reihe mit dem C-Säulen-Sensor B0098 ab, und im NHTSA-Bulletinindex taucht B009E überhaupt nicht auf. Sinnvoll wäre ein fünfter Sensor rechts vor allem bei langen Karosserien, Transportern mit Schiebetür oder zusätzlichen Sitzreihen. Zwei Messprinzipien stehen zur Wahl: Boschs peripherer Drucksensor sitzt im Türhohlraum und spricht an, wenn die eingedrückte Tür den Luftdruck steigen lässt; Satelliten wie Continentals gSAT messen den Stoß in steifer Struktur. FMVSS 214 erklärt den Bedarf, denn ein Pfahl kann die Flanke an vielen Stellen treffen. Ist B009E gespeichert, leuchtet die Airbag-Lampe, und nahe diesem Sensor kann die Auslösung zu spät kommen.","u":[["h","Unterbrochene, kurzgeschlossene oder korrodierte Leitung bzw. Stecker zum fünften Sensor rechts, oft nach Arbeiten an Tür oder Verkleidung"],["m","Interner Fehler des fünften rechten Crashsensors (Druck- oder Beschleunigungsausführung)"],["l","Airbag-Steuergerät auf einen Sensor codiert, den das Fahrzeug nicht hat"]],"s":["Airbag-Warnleuchte an","Seiten- und Kopfairbags rechts reagieren im Bereich dieses Sensors womöglich später","Sicherheitshinweis: Airbag-System; Sensorstecker nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit); nach dem Tausch Konfiguration prüfen lassen, nur Fachwerkstatt"],"k":["right_side_restraints_sensor_5","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,3]],"f":"","x":["B009D","B009F","B009B","B0098"]},{"c":"B009F","t":"Seitencrashsensor rechts 6","e":"Right Side Restraints Sensor 6","d":"B009F wäre der sechste und letzte rechte Rückhaltesensor im J2012-Block. Kein Hersteller dokumentiert ihn öffentlich in dieser Bedeutung. Bei GM taucht die Nummer auf, aber für ein anderes Bauteil: Bei den Two-Mode-Hybriden Tahoe, Yukon, Escalade, Silverado und Sierra (2008–2013) führt das Bulletin PIT4614C einen Nichtstart mit B009F im Gateway-Modul auf Wasser zurück, das an der Dichtung des Hochvolt-Aufprallsensors am unteren Kühlerträger eindringt; Sensor und Kontakte werden geprüft und erneuert. Das ist ein Crashschalter zum Abtrennen der Hybridbatterie, kein Airbag-Satellit. Ein echter sechster Sensor rechts wäre ein Beschleunigungsaufnehmer, etwa ein per PSI5 angebundener Bosch SMA773 an hinterer Säule oder Schweller. Fällt er aus, geht die Airbag-Leuchte an.","u":[["h","Beschädigter Heck-Kabelbaum oder Stecker zum sechsten Sensor rechts"],["m","Interner Fehler des sechsten rechten Beschleunigungssatelliten"],["l","Bei GM-Two-Mode-Hybriden Wasser oder Korrosion am Hochvolt-Aufprallsensor (andere Bedeutung, PIT4614C)"]],"s":["Airbag-Warnleuchte an","Bei GM-Two-Mode-Hybriden stattdessen kein Anlassen oder die Meldung Service Hybrid","Sicherheitshinweis: Airbag- und bei Hybriden Hochvoltsystem; Stecker nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit); nach Sensortausch prüfen bzw. anlernen lassen, nur Fachwerkstatt"],"k":["right_side_restraints_sensor_6","srs_wiring","srs_control_module"],"r":["shop_only",0,[60,500],[0.5,3]],"f":"","x":["B009E","B009D","B009C"]},{"c":"B00A0","t":"Insassenklassifizierungssystem","e":"Occupant Classification System","d":"B00A0 ist der Sammelcode des Insassenklassifizierungssystems, das am Beifahrersitz entscheidet, ob und wie stark der Beifahrerairbag zünden darf – so verlangt es FMVSS 208 für adaptive Airbags. Mitsubishi führt ihn als OCCUPANT SENS UNIT mit zehn Untertypen, etwa Sensorfehler (-02/-09), Unterspannung oder nicht abgeschlossener Nullabgleich (-22, Batterie 9 V oder weniger), Kommunikationsausfall (-83/-86/-87/-88) und Reset-Fehler (-93); meist gilt eine Verzögerung von 2 s bei Zündung an, bei -88 5 s, bei -87 10 s. Mazda führt B00A0:09 bei CX-3 und CX-5 auf einen Sensor zurück, der beim Anlassen zu schnell auf Unterspannung ansprach, und tauscht das Sitzpolster (08-002/23). Nissan programmiert das OCS-Gerät neu, wenn der Nullabgleich scheitert (NTB19-071D). Die Airbag-Leuchte geht an.","u":[["h","Schlechter Kontakt oder Unterbrechung im Kabelbaum bzw. Stecker des Beifahrersitzes, oft nach Sitzausbau"],["m","Niedrige Batteriespannung oder Einbruch beim Anlassen (Mitsubishi -22, Mazda B00A0:09)"],["m","Nullabgleich nach Sitzarbeiten nicht durchgeführt oder nicht möglich (Nissan programmiert das Gerät neu)"],["m","Interner Fehler von Klassifizierungssensor oder -steuergerät, oft mit dem Sitzpolster getauscht"]],"s":["Airbag-Warnleuchte an","Statusanzeige des Beifahrerairbags zeigt den falschen Zustand, oder der Beifahrerairbag bleibt abgeschaltet","Fehler tritt eventuell nur nach Kaltstarts mit schwacher Batterie auf","Sicherheitshinweis: Airbag-System; Sitz- und Sensorstecker nur spannungsfrei trennen; nach Tausch von Sitzsensoren oder Steuergerät Nullabgleich/Kalibrierung durchführen, nur Fachwerkstatt"],"k":["occupant_classification_module","occupant_classification_sensor","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,1200],[0.5,3]],"f":"","x":["B00A1","B00B0","B00C0"]},{"c":"B00A1","t":"Insassenpositionssystem","e":"Occupant Position System","d":"B00A1 betrifft das Insassenpositionssystem, das nicht das Gewicht, sondern die Sitzhaltung erfasst, damit ein Airbag gesperrt werden kann, wenn jemand zu nah davor ist. FMVSS 208 lässt das als dynamische automatische Abschaltung zu, die den Airbag sperren muss, bevor Kopf, Hals oder Rumpf in eine vom Hersteller festgelegte Zone neben der Abdeckung geraten. Den Code B00A1 selbst veröffentlicht kein Hersteller. Hondas OPDS zeigt das Prinzip: Sensoren in der Beifahrer-Rückenlehne melden Größe und Neigung, der Seitenairbag wird abgeschaltet und die Anzeige Side Airbag Off leuchtet; nach dem Tausch von Lehnenteilen oder Steuergerät muss das System initialisiert werden. Patente beschreiben weitere Wege, etwa Ultraschall vom Dachhimmel oder einen Sensor an der Airbagklappe. Ein Fehler schaltet die Airbag-Leuchte ein.","u":[["h","System nach Tausch von Sitzbezug, Lehnensensor oder Steuergerät nicht initialisiert"],["m","Beschädigter Sitzkabelbaum oder lockerer Stecker unter dem Sitz"],["m","Defekter Positionssensor oder defektes Positionssteuergerät"],["l","Feuchter Sitz, Zubehör-Sitzbezüge oder Gegenstände, die die Sensoren stören"]],"s":["Airbag-Warnleuchte an","Airbag-Aus-Anzeige bleibt an, obwohl der Insasse aufrecht sitzt","Sicherheitshinweis: Airbag-System; Sitz- und Sensorstecker nur spannungsfrei trennen; nach Sensor- oder Steuergerätetausch System initialisieren/kalibrieren, nur Fachwerkstatt"],"k":["occupant_position_module","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,1000],[0.5,3]],"f":"","x":["B00A0","B00B7","B00C7"]},{"c":"B00B0","t":"Fahrersitz Insassenklassifizierungssensor A","e":"Driver Seat Occupant Classification Sensor A","d":"B00B0 ist der erste von fünf Klassifizierungseingängen am Fahrersitz. Kein Hersteller veröffentlicht diesen Code, und J2012 überlässt dem Hersteller, welchen Sensor der Buchstabe A meint. Üblich ist die Klassifizierung im Beifahrersitz; ein Bosch-Patent hält fest, dass sie auf der Fahrerseite entfallen kann, weil man dort von Erwachsenen ausgeht, oder ebenfalls verbaut wird. Ein Sensortyp für einen solchen Platz ist eine Schaltmatte unter dem Polster: Autoliv hat eine Matte mit 28 Kuppelschaltern in fünf Zonen patentiert, ausgewählt aus einer Prüfmatte mit 2.016 Zellen, die mit FMVSS-208-Dummys und Kindersitzen bei mehreren Lehnenwinkeln belastet wurde. Ist B00B0 gespeichert, verwirft das Rückhaltesteuergerät diesen Eingang, die angepasste Stufung des Fahrerairbags kann entfallen, und die Airbag-Leuchte brennt.","u":[["h","Unterbrechung oder schlechter Kontakt im Fahrersitz-Kabelbaum bzw. Stecker zu Eingang A"],["m","Sensormatte im Polster geknickt oder beschädigt, z. B. nach Bezugsarbeiten"],["l","Sensor oder Sitz ohne den nötigen Nullabgleich getauscht"]],"s":["Airbag-Warnleuchte an","Fahrerairbag zündet womöglich mit fester statt angepasster Stufe","Sicherheitshinweis: Airbag-System; Sitz- und Sensorstecker nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit); Sensor nach dem Tausch kalibrieren, nur Fachwerkstatt"],"k":["driver_classification_sensor_a","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B00B1","B00B2","B00B3","B00B4","B00A0"]},{"c":"B00B1","t":"Fahrersitz Insassenklassifizierungssensor B","e":"Driver Seat Occupant Classification Sensor B","d":"B00B1 bezeichnet den zweiten der fünf Klassifizierungssensoren am Fahrersitz. Kein Hersteller dokumentiert ihn öffentlich, und der Buchstabe ist keiner festen Stelle zugeordnet. Sitzgewichtssysteme messen oft an den Ecken: Ein CTS-Patent setzt je Ecke einen Dickschicht-Dehnungsmessstreifen zwischen Sitzwanne und Gleitschiene, sodass das ganze Gewicht durch vier Messbrücken läuft, deren Leitungen sich in einem Verteiler vor dem Airbag-Steuergerät treffen. Bei so einem Aufbau könnte jede Ecke einen eigenen Buchstaben tragen, was eine Reihe ab A erklären würde; eine öffentliche Quelle bestätigt diese Reihenfolge aber nicht. Ein gespeicherter B00B1 heißt also, dass ein Lasteingang offen, außerhalb des Bereichs oder unplausibel ist; typisch sind falsch angezogene Sitzschrauben und Zug am Kabelbaum nach Sitzausbau. Die Airbag-Leuchte geht an.","u":[["h","Sitz mit falschem Schraubenanzugsmoment oder verspannt montiert, Sensor ungleich belastet"],["m","Gezerrte oder durchgescheuerte Leitung zu Lasteingang B unter dem Sitz"],["m","Interner Fehler des Dehnungsmesssensors"]],"s":["Airbag-Warnleuchte an","Gewichtsabhängige Anpassung des Fahrerairbags nicht verfügbar","Sicherheitshinweis: Airbag-System; Sitz- und Sensorstecker nur spannungsfrei bearbeiten (Zündung aus, Batterie ab, Wartezeit); Sitzsensoren nach Tausch oder Sitzeinbau kalibrieren, nur Fachwerkstatt"],"k":["driver_classification_sensor_b","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B00B0","B00B2","B00B3","B00B4","B00A0"]},{"c":"B00B2","t":"Fahrersitz Insassenklassifizierungssensor C","e":"Driver Seat Occupant Classification Sensor C","d":"B00B2 ist der dritte Klassifizierungssensor des Fahrersitzes in der J2012-Liste. Kein Hersteller dokumentiert den Code öffentlich. Ein verbreiteter Sensortyp ist Boschs iBolt: Die Schrauben an den vier Befestigungspunkten des Sitzgestells werden durch Sensorbolzen ersetzt, Magnet und Hall-Element erfassen die Durchbiegung eines Biegebalkens, und das Steuergerät ermittelt daraus Gewicht und Verteilung – leerer Sitz, Einjähriges, Kinder von drei und sechs Jahren, 5-Perzentil-Frau und 50-Perzentil-Mann. Ein Bosch-Patent ergänzt einen Beschleunigungssensor in der Lehne, der die Klassifizierung einfriert, solange Stöße die Bolzenwerte verfälschen würden. Welchen Bolzen der Buchstabe C meint, ist nicht veröffentlicht. Bei gespeichertem B00B2 brennt die Airbag-Leuchte, und die angepasste Auslösung kann sich nicht auf diesen Eingang stützen.","u":[["m","Interner Fehler des Hall-Sensorbolzens am Befestigungspunkt C"],["m","Sensorbolzen überlastet oder Sitzgestell verzogen, z. B. nach Unfall oder falschem Anzugsmoment"],["m","Unterbrechung oder schlechter Kontakt in der Leitung zu Eingang C"]],"s":["Airbag-Warnleuchte an","Fahrerairbag kann nicht an die Insassengröße angepasst werden","Sicherheitshinweis: Airbag-System; Sitz- und Sensorstecker nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit); Gewichtssensoren nach dem Tausch kalibrieren, nur Fachwerkstatt"],"k":["driver_classification_sensor_c","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[100,900],[0.5,3]],"f":"","x":["B00B1","B00B3","B00B0","B00B4","B00A0"]},{"c":"B00B3","t":"Fahrersitz Insassenklassifizierungssensor D","e":"Driver Seat Occupant Classification Sensor D","d":"B00B3 betrifft Eingang D, den vierten Klassifizierungssensor des Fahrersitzes. Öffentlich nutzt ihn kein Hersteller, die Zuordnung der Buchstaben ist offen. Ein vierter Eingang kann auf einem anderen Prinzip beruhen: Delphi hat ein silikongefülltes Kissen zwischen Polsterschaum und Sitzgestell patentiert, mit Drucksensor und kapazitiven Folien, deren Abstand unter Last schrumpft – so werden Gewicht und Verteilung geschätzt und gegeneinander geprüft. Hondas Arbeitshilfe zu den Gewichtssensoren im Beifahrersitz zeigt die Werkstattseite: Die Sensoren sitzen in Sitzunterbau oder Gestell, brauchen nach Sensor- oder Steuergerätetausch eine Neukalibrierung, und ein klemmender Sensor lässt sich durch Lösen, Rütteln und Nachziehen des Sitzes befreien. Ein gespeicherter B00B3 schaltet die Airbag-Leuchte ein.","u":[["h","Sitzkabelbaum durch Sitzverstellung verschlissen, Unterbrechung oder Wackelkontakt zu Eingang D"],["m","Sensor im Sitzaufbau verklemmt oder vorgespannt"],["m","Neukalibrierung nach Sensor- oder Steuergerätetausch unterblieben"],["l","Interner Sensorfehler, z. B. undichtes Kissen oder ausgefallene Druckzelle"]],"s":["Airbag-Warnleuchte an","Klassifizierung des Fahrers steht für die Airbagstufung nicht zur Verfügung","Sicherheitshinweis: Airbag-System; Sitz- und Sensorstecker nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit); nach jedem Sensortausch neu kalibrieren, nur Fachwerkstatt"],"k":["driver_classification_sensor_d","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B00B2","B00B4","B00B1","B00B0","B00A0"]},{"c":"B00B4","t":"Fahrersitz Insassenklassifizierungssensor E","e":"Driver Seat Occupant Classification Sensor E","d":"B00B4 ist der fünfte und letzte Klassifizierungssensor des Fahrersitzes. Kein Hersteller dokumentiert den Code öffentlich. Ein fünfter Eingang muss gar nichts wiegen: IEEs BodySense misst kapazitiv in der Sitzfläche, über der Sitzheizung zwischen Schaum und Bezug, und unterscheidet Kinderrückhaltesystem und sitzende Person unabhängig von Gurtspannung, Haltung, Gewicht oder Größe; laut IEE muss der Fahrzeughersteller nichts kalibrieren, und das System dient den FMVSS-208-Regeln für adaptive Airbags. Andere Auslegungen ergänzen einen Gurtkraftsensor, damit ein stramm festgezurrter Kindersitz nicht als schwerer Erwachsener gilt. Ob E einen solchen Feldsensor, eine Matte oder eine weitere Lastzelle meint, entscheidet der Hersteller. Ist B00B4 gespeichert, leuchtet die Airbag-Lampe, und der Eingang bleibt unberücksichtigt.","u":[["h","Unterbrechung oder schlechter Kontakt im Sitzkabelbaum bzw. Stecker zu Eingang E"],["m","Beschädigte Sitzheizung oder Bezug, wo die kapazitive Elektrode dieselbe Lage nutzt"],["l","Interner Fehler des fünften Klassifizierungssensors oder seiner Elektronik"]],"s":["Airbag-Warnleuchte an","Möglicherweise begleitende Fehler der Sitzheizung desselben Sitzes","Sicherheitshinweis: Airbag-System; Sitz- und Sensorstecker nur spannungsfrei bearbeiten; nach Sensor- oder Bezugstausch die Kalibrierung des Herstellers durchführen, nur Fachwerkstatt"],"k":["driver_classification_sensor_e","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B00B3","B00B2","B00B1","B00B0","B00A0"]},{"c":"B00B5","t":"Fahrersitz-Schienenpositionssensor (Rückhaltesystem)","e":"Driver Seat Track Position Restraints Sensor","d":"B00B5 meldet einen Fehler des Schienenpositionssensors am Fahrersitz, der dem Airbag-Steuergerät sagt, ob der Sitz weit nach vorn zum Lenkrad geschoben ist. FCA nutzt den Code genau so: GPOP-Hinweise zu Dodge Dart (PF), Jeep Cherokee (KL) und Chrysler 200 (UF) nennen B00B5-13 (Unterbrechung) unter den Codes, die vor dem Tausch des Rückhaltesteuergeräts mit der Technik abzuklären sind; ein Hinweis von 2024 für Pacifica und Voyager (RU) verlangt zuerst die Prüfung von Leitung, Stecker und Unterspannung. Allegro beschreibt die übliche Technik: einen zweiadrigen Hall-Schalter, den die Stahlschiene beim Vorbeigleiten vom Magneten abschirmt, woraus Zonen entstehen. Honda verringert in der vorderen Zone die Kraft des Fahrerairbags. Saab 9-3/9-5 führen diesen Sensor als B0084 und schalten dann die zweite Airbagstufe ab. Die Airbag-Leuchte brennt.","u":[["h","Unterbrechung oder verbogene/korrodierte Kontakte im Sitzkabelbaum zum Schienensensor (FCA-Untertyp -13)"],["m","Sensor an der Schiene locker oder falsch positioniert, sodass der Hall-Schalter die Schienenkante nicht mehr erkennt"],["l","Niedrige Bordspannung (FCA verlangt diese Prüfung vor dem Steuergerätetausch)"],["l","Interner Fehler des Hall-Schienensensors"]],"s":["Airbag-Warnleuchte an","Fahrerairbag zündet womöglich ohne Anpassung an die Sitzposition (z. B. zweite Stufe gesperrt)","Sicherheitshinweis: Airbag-System; Sitz- und Sensorstecker nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit); nach Sensortausch Positionssignal prüfen bzw. kalibrieren, nur Fachwerkstatt"],"k":["driver_seat_track_sensor","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[50,400],[0.5,2]],"f":"","x":["B00B6","B00C5","B0084","B00A0"]},{"c":"B00B6","t":"Fahrersitz-Lehnenpositionssensor (Rückhaltesystem)","e":"Driver Seat Recline Position Restraints Sensor","d":"B00B6 betrifft einen Sensor, der dem Rückhaltesystem meldet, wie weit die Fahrersitzlehne geneigt ist. Kein Hersteller dokumentiert den Code öffentlich, und im NHTSA-Bulletinindex fehlt er ganz. Patente zeigen, warum der Winkel zählt: Ein ATI-Patent lässt das Steuergerät den Airbag allein aus Sitzposition, Lehnenwinkel und Gurtauszug sperren oder schwächer zünden, ohne den Insassen selbst zu erfassen; eine Bosch-Anmeldung bestimmt die Neigung mit einem Dreiachs-Beschleunigungssensor in der Lehne, entscheidet an einer 45-Grad-Grenze, welche Airbags zünden, und gibt den Winkel an die Insassenklassifizierung weiter. Autoliv hat seine Klassifizierungsmatte sogar bei mehreren Lehnenwinkeln abgeglichen. Ist B00B6 gespeichert, fehlt dem Steuergerät dieser Eingang; die Airbag-Leuchte bleibt an, bis Sensor oder Leitung instand gesetzt sind.","u":[["h","Leitung am Lehnengelenk eingeklemmt oder gebrochen, wo sie bei jeder Verstellung gebogen wird"],["m","Interner Fehler oder lockere Befestigung des Lehnensensors"],["l","Sensor oder Lehne ohne den nötigen Nullabgleich getauscht"]],"s":["Airbag-Warnleuchte an","Anpassung des Airbags an eine zurückgelehnte Sitzhaltung nicht verfügbar","Sicherheitshinweis: Airbag-System; Sitz- und Sensorstecker nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit); Sensor nach dem Tausch kalibrieren, nur Fachwerkstatt"],"k":["driver_recline_sensor","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[60,600],[0.5,3]],"f":"","x":["B00B5","B00C6","B00A1"]},{"c":"B00B7","t":"Fahrersitz Insassenpositionssensor A","e":"Driver Seat Occupant Position Sensor A","d":"B00B7 ist der erste von fünf Insassenpositionssensoren am Fahrersitz. Kein Hersteller veröffentlicht den Code, und J2012 sagt nicht, welchen Sensor der Buchstabe A meint. Die Positionserkennung dient der Option einer dynamischen automatischen Abschaltung nach FMVSS 208: Auch für den Fahrer muss der Airbag gesperrt sein, bevor Kopf, Hals oder Rumpf eine vom Hersteller festgelegte Zone vor der Abdeckung erreichen. Ultraschall ist ein Weg, diese Zone zu überwachen; ein Patent von Automotive Systems Laboratory kreuzt Strahlen von Sendern im Dachhimmel etwa acht Zoll vor der Airbagklappe, verlangt eine Aktualisierung binnen 10 ms und wertet jeden ungeklärten Fehler als Grund, den Airbag zu sperren. Ein gespeicherter B00B7 bedeutet also, dass dem Steuergerät dieser Blick fehlt; die Airbag-Leuchte ist an.","u":[["h","Unterbrechung oder schlechter Kontakt in der Leitung zu Positionssensor A (z. B. Dachhimmel- oder Verkleidungskabelbaum)"],["m","Sensorfläche verdeckt, verschmutzt oder nach Verkleidungsarbeiten verstellt"],["l","Interner Fehler von Positionssensor A"]],"s":["Airbag-Warnleuchte an","Abschaltung des Fahrerairbags bei falscher Sitzhaltung nicht verfügbar","Sicherheitshinweis: Airbag-System; Sensor- und Sitzstecker nur spannungsfrei trennen; Positionssensoren nach dem Tausch kalibrieren bzw. initialisieren, nur Fachwerkstatt"],"k":["driver_occupant_position_sensor_a","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,800],[0.5,3]],"f":"","x":["B00B8","B00B9","B00BA","B00BB","B00A1"]},{"c":"B00B8","t":"Fahrersitz Insassenpositionssensor B","e":"Driver Seat Occupant Position Sensor B","d":"B00B8 bezeichnet den zweiten Insassenpositionssensor am Fahrersitz. Kein Hersteller dokumentiert den Code öffentlich, die Buchstabenzuordnung trifft der Hersteller. Statt vom Dach herabzuschauen, kann ein Positionssensor direkt an der Airbagabdeckung sitzen: Ein 1998 zuerst eingereichtes Patent von Automotive Systems Laboratory, heute bei Joyson, setzt einen aktiven Infrarot-, Ultraschall- oder Feldsensor in oder neben die Airbagklappe, hält den Airbag gesperrt, solange ein größeres Körperteil in der Gefahrenzone ist, und verweist auf NHTSA-Befunde, wonach Verletzungen sinken, wenn der Airbag bei rund 4 bis 10 Zoll Abstand zur Klappe aus bleibt. FMVSS 208 lässt eine solche dynamische Abschaltung für den Fahrerairbag zu. Ein gespeicherter B00B8 heißt, dass dieser Eingang ausgefallen ist; die Airbag-Leuchte geht an.","u":[["m","Fehler in der Leitung zu einem Sensor an Lenkrad oder Abdeckung, z. B. über die Wickelfeder"],["m","Sensorfenster durch Aufkleber, Bezüge oder Schmutz verdeckt"],["m","Interner Fehler von Positionssensor B"]],"s":["Airbag-Warnleuchte an","Airbag kann nicht gesperrt werden, wenn der Fahrer sehr nah an der Abdeckung ist","Sicherheitshinweis: Airbag-System; an Lenkrad, Abdeckung oder Sensorsteckern nur spannungsfrei arbeiten (Zündung aus, Batterie ab, Wartezeit); Sensor nach dem Tausch kalibrieren, nur Fachwerkstatt"],"k":["driver_occupant_position_sensor_b","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,800],[0.5,3]],"f":"","x":["B00B7","B00B9","B00BA","B00BB","B00A1"]},{"c":"B00B9","t":"Fahrersitz Insassenpositionssensor C","e":"Driver Seat Occupant Position Sensor C","d":"B00B9 ist der dritte Insassenpositionssensor des Fahrersitzes. Kein Hersteller veröffentlicht ihn. Ein dritter Eingang könnte die Haltung über die Lehne beurteilen: Ein heute bei Joyson liegendes Patent setzt zwei Feldelektroden unter den Lehnenbezug, eine quer über die obere Mitte und die Innenseite, eine entlang der Außenkante, und verknüpft sie mit dem Sitzgewicht, um den Seitenairbag zu sperren, wenn sich ein kleiner Insasse in dessen Weg lehnt. Honda nutzte dasselbe Prinzip auf der Beifahrerseite mit OPDS-Sensoren in der Lehne; sie müssen nach Bezugs- oder Sensortausch initialisiert werden, und ein feuchter Sitz kann sie stören. Ob ein Fahrersitz den Buchstaben C für eine solche Elektrode nutzt, ist nicht dokumentiert. Ein gespeicherter B00B9 schaltet die Airbag-Leuchte ein.","u":[["h","Lehnenbezug oder Sensor ohne Initialisierung getauscht"],["m","Beschädigter Lehnenkabelbaum oder Stecker unter dem Sitz"],["m","Feuchter Sitz oder Zubehörbezug stört das elektrische Feld"]],"s":["Airbag-Warnleuchte an","Abschaltung des Seitenairbags bei seitlich gelehnten Insassen nicht verfügbar","Sicherheitshinweis: Airbag-System mit Sitz-Seitenairbag; Sitzstecker nur spannungsfrei trennen; nach Sensor- oder Bezugstausch initialisieren/kalibrieren, nur Fachwerkstatt"],"k":["driver_occupant_position_sensor_c","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B00B8","B00BA","B00B7","B00BB","B00A1"]},{"c":"B00BA","t":"Fahrersitz Insassenpositionssensor D","e":"Driver Seat Occupant Position Sensor D","d":"B00BA betrifft Positionseingang D, den vierten Sensor am Fahrersitz. Öffentlich beschreibt kein Hersteller den Code. Frühe Konzepte gegen falsche Sitzhaltung kombinierten mehrere Sensorarten: Ein Patent von Automotive Systems Laboratory aus dem Jahr 1989 erkennt die Anwesenheit pyroelektrisch, misst den Abstand zu Lenkrad und Armaturenbrett per Ultraschall und das Gewicht mit einem Druckaufnehmer unter dem Insassen, empfiehlt je Art redundante Sensoren gegen Fehlmessungen, warnt per Leuchte und zündet einen Fahrer-Gasgenerator mit mehreren Kartuschen stufenweise passend zu Größe und Position. Ein vierter Platz eignet sich also für einen redundanten oder anders arbeitenden Sensor; was D bedeutet, bestätigt aber kein Hersteller. B00BA zeigt einen Fehler dieses Eingangs; die Airbag-Leuchte ist an, die angepasste Auslösung eingeschränkt.","u":[["h","Unterbrochene oder kurzgeschlossene Leitung zu Positionssensor D"],["m","Signal widerspricht den anderen Positionseingängen, z. B. Sensor verschmutzt oder verstellt"],["l","Interner Fehler von Positionssensor D"]],"s":["Airbag-Warnleuchte an","Positionsabhängige Stufung des Fahrerairbags eingeschränkt","Sicherheitshinweis: Airbag-System; Sensor- und Sitzstecker nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit); Positionssensoren nach dem Tausch kalibrieren, nur Fachwerkstatt"],"k":["driver_occupant_position_sensor_d","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,800],[0.5,3]],"f":"","x":["B00B9","B00BB","B00B8","B00B7","B00A1"]},{"c":"B00BB","t":"Fahrersitz Insassenpositionssensor E","e":"Driver Seat Occupant Position Sensor E","d":"B00BB ist der fünfte und letzte Insassenpositionssensor des Fahrersitzes im J2012-Block. Kein Hersteller veröffentlicht diesen Code. Die Position muss nicht am Körper gemessen werden: Eine ATI-Patentfamilie, die bis 1992 zurückreicht, leitet sie vom Sitz ab – mit Potentiometer oder anderem Schienensensor, einem Lehnenwinkelsensor und dem Gurtauszug über einen Drehgeber im Aufroller – und kann den Airbag sperren oder schwächer zünden, wenn der Sitz ganz vorn steht. FMVSS 208 überlässt Abschaltzone und Sensorwahl dem Hersteller. Da J2012 für diese indirekten Sitzdaten eigene Codes hat, B00B5 für die Schiene und B00B6 für die Lehne, meint E vermutlich einen weiteren direkten Sensor; belegt ist das nicht. Ist B00BB gespeichert, brennt die Airbag-Leuchte.","u":[["h","Unterbrochene, kurzgeschlossene oder lose Leitung zu Positionssensor E"],["m","Rückhaltesteuergerät für einen fünften Positionssensor konfiguriert, der nicht verbaut ist"],["l","Interner Fehler von Positionssensor E"]],"s":["Airbag-Warnleuchte an","Positionsabhängige Anpassung des Fahrerairbags teilweise nicht verfügbar","Sicherheitshinweis: Airbag-System; Sensor- und Sitzstecker nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit); Sensor nach dem Tausch kalibrieren, nur Fachwerkstatt"],"k":["driver_occupant_position_sensor_e","srs_wiring","srs_control_module"],"r":["shop_only",0,[80,800],[0.5,3]],"f":"","x":["B00BA","B00B9","B00B8","B00B7","B00B5"]},{"c":"B00C0","t":"Beifahrersitz Insassenklassifizierungssensor A","e":"Passenger Seat Occupant Classification Sensor A","d":"B00C0 meldet den ersten von bis zu fünf Klassifizierungseingängen im Beifahrersitz. Ihre Aufgabe folgt aus FMVSS 208: Der Beifahrerairbag muss gesperrt bleiben, wenn ein 12 Monate alter Dummy in einem gelisteten Kindersitz sitzt oder ein Neugeborenen-Dummy in einer Babywanne liegt, für eine Frau der 5-%-Perzentile aber scharf sein; eine gelbe Leuchte PASSENGER AIR BAG OFF zeigt die Sperre an. Hondas Fit 2013 zeigt eine übliche Gewichtslösung: Sensoren im Sitz schalten den Airbag bei 29 kg oder weniger ab, nahe dieser Grenze kann die Aus-Leuchte flackern, und Taschen an der Lehne oder ein Fondpassagier, der gegen sie drückt, verfälschen die Messung. Kein Hersteller veröffentlicht B00C0; welchen Sensor der Buchstabe A meint, bleibt offen. Die Airbag-Leuchte geht an, die Klassifizierung fällt auf einen sicheren Ersatzwert zurück.","u":[["h","Lockerer Stecker oder durchgescheuerte Leitung zu Eingang A unter dem Beifahrersitz, oft nach Sitzausbau"],["m","Klassifizierungssensor A selbst liefert kein oder ein unplausibles Signal"],["l","Gegenstände unter dem Sitz, Lasten an der Lehne oder Druck von hinten stören die Messung"]],"s":["Airbag-Warnleuchte an","Beifahrerairbag-Aus-Leuchte zeigt einen Zustand, der nicht zum Insassen passt","Sicherheitshinweis: Beifahrerairbag womöglich falsch frei- oder abgeschaltet; Sitz- und Sensorstecker nur spannungsfrei trennen, Klassifizierung nach der Reparatur neu kalibrieren, nur Fachwerkstatt"],"k":["passenger_classification_sensor_a","srs_seat_wiring","occupant_classification_module"],"r":["shop_only",0,[80,900],[0.5,3]],"f":"","x":["B00C1","B00C2","B00A0","B00D5","B00B0"]},{"c":"B00C1","t":"Beifahrersitz Insassenklassifizierungssensor B","e":"Passenger Seat Occupant Classification Sensor B","d":"B00C1 meldet den zweiten Klassifizierungseingang des Beifahrersitzes. Kein Hersteller veröffentlicht den Code, doch Toyota zeigt, warum ein Sitz mehrere solcher Sensoren trägt: Bei Camry, Prius c und Yaris 2012–2013 sowie Avalon 2013 sitzen ein linker und ein rechter Gewichtsaufnehmer zwischen Sitzrahmen und Schienen. Ihre Werte entscheiden, ob der Beifahrerairbag scharf ist, und dienen zugleich der Aufprallerkennung. In der Aktion F0B (rund 753.200 Fahrzeuge in den USA) stellte Toyota fest, dass manche Sitzhaltungen oder schlechte Straßen als Heckaufprall galten; Airbag-Leuchte und AIR BAG OFF gingen an. Die Händler bauten neue Sensoren ein, zogen sie mit 30 N·m an und führten Nullabgleich und Empfindlichkeitsprüfung durch. Ob B einen solchen rechten Aufnehmer meint, ist nicht belegt. Bei B00C1 leuchtet die Airbag-Leuchte.","u":[["m","Lastzelle B beschädigt oder driftend, etwa nach Gewalteinwirkung auf den Sitz"],["m","Sitzwanne oder Sensorschrauben verspannt bzw. mit falschem Drehmoment montiert, Zelle vorbelastet"],["m","Nullabgleich nach Arbeiten an Sensor oder Sitz nicht durchgeführt"],["l","Schlechter Kontakt am Stecker von Sensor B"]],"s":["Airbag-Warnleuchte an","Beifahrerairbag-Aus-Leuchte an, obwohl ein Erwachsener sitzt","Sicherheitshinweis: Status des Beifahrerairbags womöglich falsch; Sitzsensoren nur spannungsfrei trennen, Anzugsmomente einhalten und Nullabgleich mit dem Diagnosegerät durchführen, nur Fachwerkstatt"],"k":["passenger_classification_sensor_b","srs_seat_wiring","occupant_classification_module"],"r":["shop_only",0,[100,1000],[1,3]],"f":"","x":["B00C0","B00C2","B00A0","B00B1"]},{"c":"B00C2","t":"Beifahrersitz Insassenklassifizierungssensor C","e":"Passenger Seat Occupant Classification Sensor C","d":"B00C2 bezeichnet den dritten Klassifizierungseingang des Beifahrersitzes. Kein Hersteller veröffentlicht ihn, und der Buchstabe ist keinem bekannten Bauteil zugeordnet. Neben Lastzellen ist eine Matte im Polster ein verbreiteter Sensortyp. Hyundai verlängerte die Garantie der OCS-Matte im Accent 2006–2011 auf 15 Jahre ohne Kilometergrenze: Die Matte soll Kindersitze und kleine Insassen erkennen, eine defekte könnte den Airbag bei einem Kind zünden lassen; dann leuchtet die Lampe mit den Hyundai-eigenen Codes B1447/B1448. Subaru weist für den Forester 2014–2016 darauf hin, dass verschüttete Getränke, Regen durch ein offenes Fenster oder hohe Luftfeuchte an der Matte die Insassenerkennungscodes B1760 und B1650 auslösen. Wäre C eine solche Matte, stünden Nässe und Verschleiß obenan. Ein gespeicherter B00C2 schaltet die Airbag-Leuchte ein.","u":[["h","Flüssigkeit, Regen oder Kondenswasser im Sitzpolster und Sensor"],["m","Sensormatte durch jahrelanges Ein- und Aussteigen gebrochen oder verschlissen"],["m","Beschädigte Leitung oder Stecker zwischen Matte und Klassifizierungsgerät"]],"s":["Airbag-Warnleuchte an","Fehler kann mit dem Wetter oder nach dem Reinigen des Sitzes kommen und gehen","Sicherheitshinweis: Ein Kind auf dem Beifahrersitz wird womöglich nicht erkannt; Matten nur als Herstellersatz und spannungsfrei tauschen, danach neu kalibrieren, nur Fachwerkstatt"],"k":["passenger_classification_sensor_c","srs_seat_wiring","occupant_classification_module"],"r":["shop_only",0,[150,1200],[1,4]],"f":"","x":["B00C1","B00C3","B00A0","B00B2"]},{"c":"B00C3","t":"Beifahrersitz Insassenklassifizierungssensor D","e":"Passenger Seat Occupant Classification Sensor D","d":"B00C3 ist der vierte Klassifizierungseingang des Beifahrersitzes. Kein Hersteller dokumentiert ihn unter dieser Nummer. Manche Klassifizierungssignale sind kein Gewicht, sondern eine Frequenz und daher anfällig für elektrische Störungen. Tesla meldete für das Model 3 der Jahre 2017–2019, dass die OCS-Frequenz wegen Einstreuungen im Kabelbaum des Beifahrersitzes ihren gültigen Bereich verlassen konnte; das Airbag-Symbol erschien dann auf dem Bildschirm. Abhilfe war zunächst eine Kabelverlängerung mit Ferritfilter am OCS-Modul, das vorn unter dem Sitz sitzt, später ein eigenes Filtermodul, jeweils mit etwa 0,15 h Arbeitszeit. Ob ein Hersteller ein solches Signal als D führt, ist nicht bekannt. Ein gespeicherter B00C3 heißt, dieser Eingang fehlt oder liegt außerhalb des Bereichs; die Airbag-Leuchte bleibt an, bis die Ursache gefunden ist.","u":[["m","Elektrische Einstreuung in den Sitzkabelbaum (Sitzheizung, Motoren, Verlegung neben anderen Leitungen)"],["m","Kabelbaum unter Zug oder Stecker am Klassifizierungsmodul locker, wenn der Sitz verfahren wird"],["l","Interner Fehler von Sensor D oder Klassifizierungsmodul"]],"s":["Airbag-Warnleuchte oder Airbag-Symbol im Display","Fehler kann von der Sitzstellung oder von zugeschalteten Verbrauchern abhängen","Sicherheitshinweis: Insassenklassifizierung unzuverlässig; am Sitzkabelbaum nur spannungsfrei arbeiten, vorhandene Filter- oder Nacharbeitssätze des Herstellers verwenden, nur Fachwerkstatt"],"k":["passenger_classification_sensor_d","srs_seat_wiring","occupant_classification_module"],"r":["shop_only",0,[60,800],[0.3,3]],"f":"","x":["B00C2","B00C4","B00A0","B00B3"]},{"c":"B00C4","t":"Beifahrersitz Insassenklassifizierungssensor E","e":"Passenger Seat Occupant Classification Sensor E","d":"B00C4 steht für den fünften und letzten Klassifizierungseingang des Beifahrersitzes. Kein Hersteller veröffentlicht diesen Code. Zwei Fälle aus der Praxis zeigen, was außer der Verkabelung schiefgehen kann. Mazda stellte bei Modellen 2016–2019 fest, dass ein Handy, Tablet oder Laptop auf dem leeren Beifahrersitz als Person erkannt werden konnte: Die Gurtwarnung für den Beifahrer ging an, PASS AIRBAG OFF blieb dunkel, und der Rat lautete, keine Geräte auf den Sitz zu legen. Land Rover sperrte Range Rover Sport SV des Modelljahrs 2025, weil die OCS-Module mit falschem Gewicht kalibriert waren und der Airbag bei Kindersitz entgegen FMVSS 208 aktiv bleiben konnte; neue Module dauerten 1,1 h. Kalibrierung und Plausibilität zählen also so viel wie der Sensor. Bei B00C4 leuchtet die Airbag-Leuchte, Eingang E gilt als unzuverlässig.","u":[["m","Klassifizierungsmodul nach dem Tausch falsch oder gar nicht kalibriert"],["m","Unterbrechung oder Übergangswiderstand an der Leitung zu Eingang E"],["l","Elektronische Geräte oder andere Gegenstände auf dem Sitz stören die Erkennung"]],"s":["Airbag-Warnleuchte an","Gurtwarnung oder Airbag-Statusleuchte passt nicht dazu, wer oder was auf dem Sitz ist","Sicherheitshinweis: Beifahrerairbag bleibt bei Kindersitz womöglich aktiv; nur spannungsfrei trennen, nach Modultausch nach Herstellervorgabe kalibrieren, nur Fachwerkstatt"],"k":["passenger_classification_sensor_e","srs_seat_wiring","occupant_classification_module"],"r":["shop_only",0,[80,1200],[0.5,3]],"f":"","x":["B00C3","B00C0","B00A0","B00D1","B00B4"]},{"c":"B00C5","t":"Beifahrersitz-Schienenpositionssensor (Rückhaltesystem)","e":"Passenger Seat Track Position Restraints Sensor","d":"B00C5 meldet einen Fehler des Sensors, der dem Rückhaltesteuergerät die Lage des Beifahrersitzes auf seinen Schienen mitteilt. FCA nutzt den Code genau mit diesem Namen. Ein STAR-Fall von 2022 zum Dodge Durango 2021 behandelt B00C5-13, Kreis offen, bei leuchtender Airbag-Lampe: Den gelben 30-poligen Stecker I6634A unter dem Beifahrersitz prüfen und sicherstellen, dass die Rückleitung R730 des Schienensensors in Kammer B11 fest sitzt, mit Zug-Druck-Zug-Probe. Die GPOP-Hinweise 68264880A und 9003579 für Dart, Cherokee und Chrysler 200 führen B00C5-13 unter den Codes, bei denen vor dem Tausch des ORC die Technik zu fragen ist, und verlangen die Prüfung auf verbogene, korrodierte oder aufgeweitete Kontakte. Solche Sensoren sind meist zweiadrige Hall-Schalter, die umschalten, wenn die Schiene vorbeigleitet.","u":[["h","Kontakt im Stecker unter dem Sitz zurückgeschoben oder locker (FCA Durango, Rückleitung R730)"],["m","Leitung zum Schienensensor vom verfahrenden Sitz eingeklemmt oder abgerissen"],["m","Schienenpositionssensor defekt oder Abstand zur Schiene nach Sitzarbeiten falsch"],["l","Interner Fehler des Rückhaltesteuergeräts, erst nach Ausschluss von Leitung und Sensor"]],"s":["Airbag-Warnleuchte an","Auslösung des Beifahrerairbags lässt sich nicht mehr an die Sitzstellung anpassen","Sicherheitshinweis: Airbag-System; Stecker unter dem Sitz nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit), Rückhaltesteuergerät nicht vor der Kontaktprüfung tauschen, nur Fachwerkstatt"],"k":["passenger_seat_track_sensor","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[60,400],[0.5,2]],"f":"","x":["B00B5","B00C6","B00A0"]},{"c":"B00C6","t":"Beifahrersitz-Lehnenpositionssensor (Rückhaltesystem)","e":"Passenger Seat Recline Position Restraints Sensor","d":"B00C6 betrifft den Sensor, der meldet, wie weit die Lehne des Beifahrersitzes geneigt ist. Kein Hersteller dokumentiert diesen Code, und im NHTSA-Bulletinindex gibt es keinen Eintrag. Auf der Beifahrerseite zählt der Winkel vor allem für die Klassifizierung, denn eine geneigte Lehne trägt einen Teil des Körpergewichts. Ein 1997 eingereichtes Patent nennt Zahlen: Ein Polstersensor maß für ein Kind von 60 lb bei drei Lehnenstellungen 42, 39 und 27 lb, für einen Erwachsenen von 120 lb 74, 64 und 49 lb; deshalb speist ein Lehnensensor eine Kennfeldtabelle, unter etwa 95 lb wird der Airbag dort gesperrt. Ein Delphi-Patent von 2010 korrigiert den Druck einer Blase mit dem Lehnenwinkel aus Beschleunigungssensor oder Potentiometer. Fehlt dieser Eingang, kann ein kleiner Erwachsener als Kind gelten. B00C6 schaltet die Airbag-Leuchte ein.","u":[["h","Leitung zum Lehnensensor am Lehnengelenk gedehnt oder gebrochen"],["m","Lehnenpotentiometer oder Neigungssensor verschlissen oder defekt"],["l","Winkelreferenz nach Tausch von Lehne oder Sensor nicht eingelernt"]],"s":["Airbag-Warnleuchte an","Beifahrerairbag-Aus-Leuchte geht womöglich bei einem Erwachsenen mit geneigter Lehne an","Sicherheitshinweis: Airbag-System; an Lehne und Sensor nur spannungsfrei arbeiten (Zündung aus, Batterie ab, Wartezeit), danach anlernen bzw. kalibrieren, nur Fachwerkstatt"],"k":["passenger_recline_sensor","srs_seat_wiring","occupant_classification_module"],"r":["shop_only",0,[80,600],[0.5,3]],"f":"","x":["B00B6","B00C5","B00A0"]},{"c":"B00C7","t":"Beifahrersitz Insassenpositionssensor A","e":"Passenger Seat Occupant Position Sensor A","d":"B00C7 ist der erste von fünf Insassenpositionssensoren des Beifahrersitzes. Kein Hersteller veröffentlicht den Code. Am Beifahrersitz kam die Positionserkennung in die Serie: Hondas OPDS setzt Sensoren in die Beifahrerlehne, die Sitzhöhe und ein Anlehnen eines Kindes zur Tür erkennen, sperrt dann den Seitenairbag im Sitz und schaltet eine Anzeige für den abgeschalteten Seitenairbag ein. Hondas Patent von 1998 beschreibt das Prinzip: Bandelektroden im Lehnenbezug werden mit Hochfrequenz gespeist, ein naher Körper erhöht den Strom, sodass sich Schultern, Kopf und Neigung zur Tür unterscheiden lassen; das Gerät überwacht sich zudem selbst. Honda verlangt, das System nach dem Tausch von Lehnenteilen zu initialisieren. Ob ein Hersteller einen solchen Sensor als A führt, ist nicht belegt. B00C7 schaltet die Airbag-Leuchte ein.","u":[["h","Positionssystem nach Tausch von Bezug, Lehnensensor oder Steuergerät nicht initialisiert"],["m","Elektrode oder Leitung in der Lehne beschädigt, etwa durch Fremdbezug oder Reparaturen"],["l","Feuchte Lehne oder dagegen gedrückte Gegenstände"]],"s":["Airbag-Warnleuchte an","Anzeige für abgeschalteten Seitenairbag an, obwohl der Beifahrer aufrecht sitzt","Sicherheitshinweis: Seitenairbag womöglich falsch frei- oder gesperrt; an der Lehne nur spannungsfrei arbeiten und das System danach initialisieren, nur Fachwerkstatt"],"k":["passenger_occupant_position_sensor_a","srs_seat_wiring","occupant_position_module"],"r":["shop_only",0,[100,1000],[0.5,3]],"f":"","x":["B00C8","B00A1","B00B7"]},{"c":"B00C8","t":"Beifahrersitz Insassenpositionssensor B","e":"Passenger Seat Occupant Position Sensor B","d":"B00C8 steht für Positionssensor B am Beifahrersitz; öffentlich führt ihn kein Hersteller. Ein Positionseingang muss die Person nicht ansehen, er kann auch aus der Lastverteilung auf dem Sitz stammen. In einer Honda-Anmeldung von 2002 trägt je eine Gewichtseinheit links und rechts unter dem Sitz vier Dehnmessstreifen als Brücke; der Vergleich der vorderen und hinteren Paare zeigt, ob der Insasse auf der Vorderkante sitzt, der Vergleich beider Seiten eine Neigung nach links oder rechts. FMVSS 208 erlaubt für den Beifahrer eine dynamische Abschaltung: Der Airbag muss bereits gesperrt sein, wenn Kopf, Hals oder Rumpf eines Dummys von 3 oder 6 Jahren in eine Zone vor der Abdeckung geraten, die jeder Hersteller selbst festlegt. Ob B ein solches Signal meint, ist offen. B00C8 schaltet die Airbag-Leuchte ein.","u":[["h","Stecker oder Leitung zu Sensor B beim Verfahren oder Ausbau des Sitzes beschädigt"],["m","Dehnmessbrücke bzw. Positionssensor B defekt oder temperaturabhängig driftend"],["l","Sitzrahmen verspannt montiert, sodass die Lastverteilung unplausibel wirkt"]],"s":["Airbag-Warnleuchte an","Beifahrerairbag wird womöglich ohne Rücksicht auf die Sitzposition gesperrt oder freigegeben","Sicherheitshinweis: Airbag-System; Sitzsensoren nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit), nach Sitzarbeiten neu kalibrieren, nur Fachwerkstatt"],"k":["passenger_occupant_position_sensor_b","srs_seat_wiring","occupant_position_module"],"r":["shop_only",0,[100,900],[0.5,3]],"f":"","x":["B00C7","B00C9","B00A1","B00B8"]},{"c":"B00C9","t":"Beifahrersitz Insassenpositionssensor C","e":"Passenger Seat Occupant Position Sensor C","d":"B00C9 bezeichnet Positionssensor C des Beifahrersitzes; kein Hersteller führt ihn öffentlich. Ein Konzept für einen dritten Eingang beobachtet den Abstand zwischen Rumpf und Lehne: Ein 1998 von Automotive Systems Laboratory eingereichtes Patent, heute bei Joyson, kombiniert einen Feldsensor im Polster mit einem kapazitiven oder Radar-Näherungssensor in der Lehne, gerichtet auf den Bereich etwa 10 bis 18 Zoll über dem Polster. Liegt der Rumpf bis etwa 2 Zoll an der Lehne, darf der Airbag zünden; war er länger als 50 ms weiter entfernt, wird er gesperrt. Sieht der Lehnensensor dauerhaft jemanden, den der Polstersensor nicht erkennt, wertet das Patent dies als Fehler. FMVSS 208 überlässt die Wahl solcher Sensoren dem Hersteller. B00C9 schaltet die Airbag-Leuchte ein.","u":[["h","Leitung zum Lehnensensor am Gelenk oder nach Arbeiten an der Verkleidung gebrochen"],["m","Näherungssensor C defekt oder sein Signal widerspricht dem Polstersensor"],["l","Dicke Zubehörbezüge oder nasse Lehne schwächen das Feldsignal"]],"s":["Airbag-Warnleuchte an","Airbag-Statusleuchte wechselt womöglich, wenn sich der Beifahrer vorbeugt","Sicherheitshinweis: Airbag-System; an Lehne und Sensor nur spannungsfrei arbeiten (Zündung aus, Batterie ab, Wartezeit), keine Fremdbezüge über Sensoren, nur Fachwerkstatt"],"k":["passenger_occupant_position_sensor_c","srs_seat_wiring","occupant_position_module"],"r":["shop_only",0,[100,900],[0.5,3]],"f":"","x":["B00C8","B00CA","B00A1","B00B9"]},{"c":"B00CA","t":"Beifahrersitz Insassenpositionssensor D","e":"Passenger Seat Occupant Position Sensor D","d":"B00CA ist Positionseingang D, der vierte am Beifahrersitz. Kein Hersteller dokumentiert seine Verwendung. Denkbar ist hier optische Erfassung: Eine Patentfamilie von Automotive Technologies International, zurückgehend auf 1995, setzt Bildsensoren mit Infrarotbeleuchtung an die A-Säule, in den Dachhimmel oder oben auf die Armaturentafel, zwei Sensoren mit Abstand für die Tiefe, und wertet einen Insassen als falsch sitzend, sobald Kopf oder Brust näher als etwa 5 Zoll an die Airbagklappe kommen. Mustererkennung trennt rückwärts gerichtete Kindersitze von Personen; Ultraschall mit rund 10 ms je Messung gilt dort als zu langsam für den Crash. FMVSS 208 lässt diese dynamische Abschaltung für den Beifahrer zu, ohne ein Verfahren vorzuschreiben. B00CA heißt, dieser Eingang ist ausgefallen; die Airbag-Leuchte brennt.","u":[["h","Leitung zu Sensor D an Säule, Dachhimmel oder Armaturentafel nach Verkleidungs- oder Scheibenarbeiten beschädigt"],["m","Sicht des Sensors verdeckt oder Optik verschmutzt, etwa durch Aufkleber oder Zubehör"],["m","Interner Fehler von Positionssensor D"]],"s":["Airbag-Warnleuchte an","Abschaltung bei falscher Sitzposition des Beifahrers nicht mehr verfügbar","Sicherheitshinweis: Airbag-System; an Säule, Dachhimmel oder Armaturentafel nur spannungsfrei arbeiten (Zündung aus, Batterie ab, Wartezeit), Sensorausrichtung danach prüfen, nur Fachwerkstatt"],"k":["passenger_occupant_position_sensor_d","srs_roof_wiring","occupant_position_module"],"r":["shop_only",0,[100,1000],[0.5,3]],"f":"","x":["B00C9","B00CB","B00A1","B00BA"]},{"c":"B00CB","t":"Beifahrersitz Insassenpositionssensor E","e":"Passenger Seat Occupant Position Sensor E","d":"B00CB ist der fünfte und letzte Insassenpositionssensor des Beifahrersitzes. Kein Hersteller veröffentlicht ihn. Die Lage allein genügt nicht immer; ein Patent von Automotive Technologies International, zuerst 1992 eingereicht, will auch wissen, wie schnell sich der Insasse dem Airbag nähert. Es nutzt Ultraschallimpulse um 50 kHz, gewinnt den Abstand aus der Echolaufzeit und die Geschwindigkeit aus der Dopplerverschiebung, oder moduliertes Infrarot und Radar, montiert im Dachhimmel, am Spiegel oder auf der Airbagabdeckung. Bei einem Barrierecrash mit 30 mph bleiben für jemanden in 9 Zoll Abstand nur etwa 8 ms zum Messen, bei 24 Zoll 57 ms. FMVSS 208 lässt den Hersteller die Abschaltzone festlegen, die solche Sensoren überwachen. Ob E Geschwindigkeit oder einen weiteren Abstand misst, ist offen. B00CB schaltet die Airbag-Leuchte ein.","u":[["h","Unterbrochene oder kurzgeschlossene Leitung zu Sensor E in Dachhimmel, Spiegelfuß oder Armaturentafel"],["m","Wandler von Sensor E defekt oder abgedeckt"],["l","Rückhaltesteuergerät auf einen Sensor codiert, den das Fahrzeug nicht hat"]],"s":["Airbag-Warnleuchte an","Beifahrerairbag zündet ohne positionsabhängige Sperre oder Stufung","Sicherheitshinweis: Airbag-System; Sensoren nur spannungsfrei trennen (Zündung aus, Batterie ab, Wartezeit), nach dem Tausch Konfiguration prüfen, nur Fachwerkstatt"],"k":["passenger_occupant_position_sensor_e","srs_roof_wiring","occupant_position_module"],"r":["shop_only",0,[100,1000],[0.5,3]],"f":"","x":["B00CA","B00C7","B00A1","B00BB"]},{"c":"B00D0","t":"Gurtwarnleuchte Fahrer","e":"Driver Seat Belt Indicator","d":"B00D0 meldet einen Fehler der Gurtwarnung für den Fahrer, also an Leuchte, Leitung oder dem Ausgang bzw. der Botschaft, die sie ansteuert, nicht am Gurtschloss. Kein Hersteller dokumentiert ihn öffentlich. Die Warnung selbst ist Pflicht: FMVSS 208 S7.3 verlangt beim Einschalten der Zündung für einen nicht angeschnallten Fahrer einen Ton von 4 bis 8 s und eine Leuchte von mindestens 60 s oder eine Leuchte von 4 bis 8 s mit gurtabhängigem Ton; ab September 2028 lässt S7.5 die Leuchte brennen, solange der Gurt offen ist, mit zweiter Tonphase über 10 km/h. FMVSS 101 verbietet, die Kontrollleuchte vorzeitig abzuschalten. UN R16 fordert eine erste optische Stufe von mindestens 4 s und eine zweite mit Ton von 30 s oder mehr, spätestens ab 25 km/h, 500 m oder 60 s. Bei B00D0 fehlt dem Fahrer womöglich jede Erinnerung.","u":[["h","Unterbrochene oder kurzgeschlossene Lampenleitung bzw. Stecker zwischen Rückhaltesteuergerät und Kombiinstrument"],["m","Warnleuchte bzw. LED im Kombiinstrument ausgefallen"],["l","Gurtwarnbotschaft erreicht das Kombiinstrument nicht, etwa nach Tausch ohne Konfiguration"]],"s":["Fahrer-Gurtwarnleuchte bleibt dunkel oder brennt unabhängig vom Gurt","Airbag- bzw. Rückhaltesystem-Warnleuchte kann an sein","Sicherheitshinweis: Vorgeschriebene Warnung fehlt; trotzdem anschnallen, Kombiinstrument und Rückhalteleitungen nur spannungsfrei (Zündung aus, Batterie ab, Wartezeit), Fachwerkstatt"],"k":["driver_belt_indicator","instrument_cluster","srs_control_module"],"r":["medium",0,[40,500],[0.3,2]],"f":"","x":["B00D1","B0050","B00D2"]},{"c":"B00D1","t":"Gurtwarnleuchte Beifahrer","e":"Passenger Seat Belt Indicator","d":"B00D1 betrifft die Gurtwarnung für den Beifahrer. Anders als beim Fahrer ergibt sie nur Sinn, wenn das Fahrzeug weiß, dass der Sitz belegt ist; sie stützt sich daher auf die Insassenerkennung. Kein Hersteller dokumentiert den Code. Fords F-150 von 2014 entscheidet mit dem Beifahrer-Erkennungssystem, wer Belt-Minder-Erinnerungen bekommt: Über 6 mph und nach 1 bis 2 Minuten melden sich Leuchte und Ton für sechs Sekunden alle 25 Sekunden, etwa fünf Minuten lang. Hondas Fit 2013 zeigt die Beifahrerwarnung etwa 6 s nach Zündung an, nicht aber für ein Kind oder kleine Erwachsene, die die Gewichtssensoren nicht erfassen. Mazda beobachtete die Beifahrerwarnung bei leerem Sitz mit Laptop oder Handy. FMVSS 208 S7.5 verlangt ab September 2028 eine für den Fahrer sichtbare Beifahrerwarnung. B00D1 zielt auf die Anzeigeseite, nicht auf das Gurtschloss.","u":[["h","Unterbrochene oder kurzgeschlossene Leitung zur Beifahrer-Gurtleuchte bzw. ihrem Anzeigefeld"],["m","Leuchte, LED oder Anzeigeeinheit der Beifahrerwarnung ausgefallen"],["l","Belegungsinformation fehlt oder ist falsch, sodass die Warnlogik nicht arbeiten kann"]],"s":["Keine Gurterinnerung für den Beifahrer oder eine Erinnerung bei leerem Sitz","Airbag- bzw. Rückhaltesystem-Warnleuchte kann an sein","Sicherheitshinweis: Beifahrer fährt womöglich unangeschnallt ohne Warnung; Arbeiten an Leitungen nur spannungsfrei (Zündung aus, Batterie ab, Wartezeit), Fachwerkstatt"],"k":["passenger_belt_indicator","instrument_cluster","srs_control_module"],"r":["medium",0,[40,500],[0.3,2]],"f":"","x":["B00D0","B0052","B00A0","B00C0"]},{"c":"B00D2","t":"Rückhaltesystem-Störungsanzeige 1","e":"Restraint System Malfunction Indicator 1","d":"B00D2 bedeutet, dass das Rückhaltesteuergerät einen Fehler im Kreis seiner Hauptwarnleuchte gefunden hat, der Airbag- bzw. SRS-Leuchte. FMVSS 208 S4.5.2 verlangt diese Bereitschaftsanzeige, vom Fahrersitz sichtbar und selbstüberwachend, und FMVSS 101 lässt sie andere Meldungen aus einer geteilten Anzeige verdrängen. Kein Hersteller veröffentlicht B00D2. Saab zeigt unter eigenen, älteren Nummern, wie die Prüfung aussieht: Beim 9-3 von 1998 entsteht B1227, wenn der Lampenausgang 1,25 s lang über 5 V liegt, ein Schluss nach Plus, der die 3 bis 4 s lange Lampenprobe verhindert, und B1228 bei unter 1 V oder über 10 kOhm im ausgeschalteten Zustand, eine Unterbrechung oder ein Masseschluss, bei dem stattdessen die Zentralwarnleuchte angeht. Bis zur Reparatur sieht der Fahrer weitere Airbagfehler womöglich nicht.","u":[["h","Glühlampe oder LED der Airbag-Warnleuchte ausgefallen"],["m","Lampenleitung unterbrochen, mit Masse oder Batteriespannung kurzgeschlossen, oder lockerer Stecker am Kombiinstrument"],["l","Interner Fehler auf der Platine des Kombiinstruments"]],"s":["Airbag-Leuchte macht beim Einschalten keine Lampenprobe oder bleibt an","Eine Ersatzwarnung wie Zentralwarnleuchte oder Warnton kann erscheinen","Sicherheitshinweis: Airbagfehler bleiben womöglich unbemerkt; an Kombiinstrument und Rückhalteleitungen nur spannungsfrei arbeiten (Zündung aus, Batterie ab, Wartezeit), nur Fachwerkstatt"],"k":["srs_indicator_1","instrument_cluster","srs_control_module"],"r":["medium",0,[40,600],[0.3,2]],"f":"","x":["B00D3","B00D4","B00D5"]},{"c":"B00D3","t":"Rückhaltesystem-Störungsanzeige 2","e":"Restraint System Malfunction Indicator 2","d":"B00D3 verweist auf eine zweite Störungsanzeige des Rückhaltesystems. Kein Hersteller dokumentiert, welche Leuchte das ist, die Bedeutung muss also erschlossen werden. Eine Lesart ist ein Ersatz für die Hauptleuchte: Der Saab 900 von 1995 nennt seine SRS-Leuchte Warnleuchte 1 und schaltet bei einem Fehler in deren Kreis die Zentralwarnleuchte dauerhaft ein. Saturn patentierte 1991 eine ähnliche Rückfallebene und nutzt die Gurtwarnleuchte als zweite SIR-Anzeige, sobald eine Spannungsprüfung oder Fotozelle den Ausfall der Airbag-Leuchte zeigt: zehnmal blinken, dann zehn Minuten Dauerlicht, oder ständiges Blinken. Möglich ist auch eine eigene Kontrollleuchte, denn FMVSS 101 kennt neben der Airbag-Leuchte eine für Seitenairbag-Störungen. In beiden Fällen meldet B00D3 einen Fehler in diesem zweiten Anzeigekreis, nicht in den Airbags selbst.","u":[["h","Unterbrochene oder kurzgeschlossene Leitung zur zweiten Rückhalte-Anzeige"],["m","Zweite Anzeigeleuchte bzw. LED ausgefallen"],["l","Rückhaltesteuergerät oder Kombiinstrument auf eine nicht vorhandene Anzeige konfiguriert"]],"s":["Airbag-Leuchte an, zweite Anzeige dunkel oder ohne Lampenprobe","Ersatzwarnung fehlt, falls auch die Hauptleuchte ausfällt","Sicherheitshinweis: Rückhalte-Warnungen unvollständig; an Kombiinstrument und Leitungen nur spannungsfrei arbeiten (Zündung aus, Batterie ab, Wartezeit), nur Fachwerkstatt"],"k":["srs_indicator_2","instrument_cluster","srs_control_module"],"r":["medium",0,[40,600],[0.3,2]],"f":"","x":["B00D2","B00D4"]},{"c":"B00D4","t":"Rückhaltesystem-Störungsanzeige akustisch","e":"Restraint System Malfunction Audible Indicator","d":"B00D4 betrifft die akustische Rückhaltewarnung, den Ton, der einspringt, wenn die Leuchte einen Fehler nicht zeigen kann. Fords Handbuch zum F-150 von 2014 beschreibt das: Die Bereitschaft meldet die Warnleuchte oder, wenn sie ausgefallen ist, ein Ersatzton; ein Problem kündigt sich durch eine Folge von fünf Pieptönen an, die sich wiederholt, bis Fehler, Leuchte oder beides repariert sind. Ein Audi-Patent von 1986 erklärt, warum es eine solche Rückfallebene gibt: Eine durchgebrannte Sicherung konnte Airbag-Steuergerät und Leuchte zugleich lahmlegen, und der Fahrer hielte das System für intakt; als Alternative nennt es einen akustischen Alarm. Kein Hersteller veröffentlicht B00D4. Der Code heißt, das Rückhaltesteuergerät sieht einen Fehler im Pfad zu Gong oder Lautsprecher; ein späterer Lampenausfall bliebe dann unbemerkt.","u":[["m","Unterbrochene oder kurzgeschlossene Leitung zum Gong bzw. Lautsprecher der Rückhaltewarnung"],["m","Gongmodul oder Lautsprecher im Kombiinstrument ausgefallen"],["l","Tonanforderung des Rückhaltesteuergeräts kommt beim Tongeber nicht an"]],"s":["Kein Warnton, wo einer zu erwarten wäre; andere Warngongs können ebenfalls stumm sein","Airbag-Warnleuchte an","Sicherheitshinweis: Ersatzwarnung fehlt; an Kombiinstrument und Rückhalteleitungen nur spannungsfrei arbeiten (Zündung aus, Batterie ab, Wartezeit), Fachwerkstatt"],"k":["srs_audible_indicator","instrument_cluster","srs_control_module"],"r":["medium",0,[40,500],[0.3,2]],"f":"","x":["B00D2","B00D3"]},{"c":"B00D5","t":"Anzeige Beifahrer-Rückhaltesystem deaktiviert","e":"Restraint System Passenger Disable Indicator","d":"B00D5 betrifft die Leuchte, die den Vorderinsassen anzeigt, dass der Beifahrerairbag aus ist. FMVSS 208 verlangt sie gelb, beschriftet mit PASSENGER AIR BAG OFF oder PASS AIR BAG OFF und getrennt von der Bereitschaftsleuchte; Fords F-150 von 2014 setzt sie neben das Radio und lässt sie beim Start kurz zur Selbstprüfung leuchten. Mitsubishi definiert den Code im Airbag-Index 2022 als PASS A/B INDICATOR: Untertyp -11 für Masseschluss, -12 für Schluss nach Plus und -13 für Unterbrechung, jeweils bei Zündung an geprüft und nach 2 s gesetzt; als Ursachen gelten Kabelbaum, die Anzeige selbst oder das Airbag-Steuergerät. Ford fand B00D5:01 im Rückhaltesteuergerät von Edge und Nautilus 2021 unter Netzwerkfehlern, behoben durch ein Software-Update des Gateway-Moduls. Die Insassen werden womöglich über den Airbagzustand getäuscht.","u":[["h","Leitung zur Anzeige mit Masse oder Plus kurzgeschlossen oder unterbrochen (Mitsubishi -11/-12/-13)"],["m","Beifahrerairbag-Aus-Anzeige selbst defekt"],["l","Netzwerk- bzw. Gateway-Softwarefehler, wie bei Ford Edge/Nautilus 2021 (SSM 50127)"],["l","Interner Fehler im Ausgang des Airbag-Steuergeräts"]],"s":["Beifahrerairbag-Aus-Leuchte bleibt bei der Startprüfung dunkel oder zeigt den falschen Zustand","Airbag-Warnleuchte an","Sicherheitshinweis: Insassen sehen nicht, ob der Beifahrerairbag aus ist; bis zur Reparatur keinen rückwärts gerichteten Kindersitz einbauen, Leitungen nur spannungsfrei, Fachwerkstatt"],"k":["passenger_disable_indicator","srs_control_module","srs_wiring"],"r":["medium",0,[40,500],[0.3,2]],"f":"","x":["B00DF","B00A0","B00D2","B00C0"]},{"c":"B00DF","t":"Abschaltschalter Beifahrer-Rückhaltesystem","e":"Passenger Restraints Disable Switch","d":"B00DF betrifft den Schlüsselschalter, mit dem sich der Beifahrerairbag von Hand abschalten lässt. FMVSS 208 S4.5.4 erlaubte ihn bei Fahrzeugen vor September 2012 ohne nach vorn gerichtete Rücksitze oder mit kurzem Fond; er muss per Schlüssel bedient werden, getrennt vom Zündschloss sein und den Airbag aus lassen, bis er zurückgestellt wird. Nachrüstungen auf NHTSA-Schreiben regelt 49 CFR 595.5. Zwei Hersteller nutzen den Code. FCA beschreibt B00DF-95, falsche Bestückung, beim Jeep Wrangler 2018–2021 ohne Schalteroption CGZ: Ungenutzte Leitungen R167/R168 im Armaturenkabelbaum prüfen und am ORC abtrennen. Ford meldet B00DF:4A nach dem Selbsttest beim Nautilus 2024, verursacht durch einen internen Zähler und per Funk behoben, und beim Transit 2026–2027, löschbar mit FDRS. Ein echter Fehler schaltet die Airbag-Leuchte ein.","u":[["m","Schalterleitungen im Kabelbaum eines Fahrzeugs ohne Schalter beschädigt oder störanfällig (FCA B00DF-95)"],["m","Schlüsselschalter verschlissen oder seine Leitung unterbrochen bzw. kurzgeschlossen"],["l","Software-Zähler oder Konfigurationsfehler im Rückhaltesteuergerät (Ford B00DF:4A)"]],"s":["Airbag-Warnleuchte an","Beifahrerairbag folgt der Schalterstellung nicht, oder die Aus-Leuchte widerspricht ihr","Sicherheitshinweis: Zustand des Beifahrerairbags unklar; bis zur Prüfung keinen rückwärts gerichteten Kindersitz dort, Leitungen und Schalter nur spannungsfrei, Fachwerkstatt"],"k":["passenger_disable_switch","switch_wiring","srs_control_module"],"r":["medium",0,[0,400],[0.2,2]],"f":"","x":["B00D5","B00A0"]},{"c":"B00E0","t":"Gurtstraffer B dritte Reihe links Auslösesteuerung","e":"Third Row Left Seat Belt Pretensioner B Deployment Control","d":"B00E0 verweist auf eine zweite Straffer-Stufe (B) am linken Platz der dritten Reihe – ein zusätzliches Bauteil neben dem Aufroller, etwa ein Becken- oder Verankerungsstraffer am unteren Gurtende. Öffentlich nutzt kein Hersteller B00E0. Mercedes-Benz verbaut Straffer auch ganz hinten (das GLS-Handbuch 2017 nennt sie für alle Gurte der dritten Reihe), legt den linken Aufroller dort laut LI54.21-P-070658 aber unter B00E7 ab, also auf Stufe C; eine Stufe B taucht hinten nicht auf. GM beschreibt Verankerungsstraffer nur an Vordersitzen, Joyson kombiniert seinen Beckengurtstraffer mit einem Aufrollerstraffer gegen das Durchrutschen. Mit gespeichertem Code leuchtet die Airbag-Lampe, die Stufe gilt als nicht verfügbar.","u":[["h","Stecker des Becken- bzw. Verankerungsstraffers am linken Sitz der dritten Reihe locker, nicht verriegelt oder korrodiert"],["m","Leitung durch Umklappen und Versenken des Sitzes der dritten Reihe gedehnt oder durchgescheuert"],["m","Airbag-Steuergerät auf eine Stufe B codiert, die das Fahrzeug nicht hat (nach Tausch von Steuergerät oder Sitz)"],["l","Interne Unterbrechung oder Kurzschluss in der Zündpille des Straffers"]],"s":["Airbag-Warnleuchte leuchtet","Beckengurt am linken Platz der dritten Reihe wird bei einem Aufprall womöglich nicht gestrafft","Sicherheitshinweis: pyrotechnisches Bauteil – nur spannungsfrei (Batterie ab, Wartezeit abwarten) und am besten in der Fachwerkstatt daran arbeiten"],"k":["third_row_left_pretensioner_b","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,3]],"f":"","x":["B00E1","B00E2","B00E7","B0076"]},{"c":"B00E1","t":"Gurtstraffer B dritte Reihe rechts Auslösesteuerung","e":"Third Row Right Seat Belt Pretensioner B Deployment Control","d":"Am rechten Platz der dritten Reihe steht B00E1 für einen Straffer der Stufe B, dessen Zündkreis unterbrochen, kurzgeschlossen oder außerhalb des zulässigen Widerstands ist. Kein Hersteller verwendet B00E1 in einem öffentlich zugänglichen Werkstattdokument. Wo Mercedes-Benz dort einen Straffer verbaut, ist es der Aufroller, und das Airbag-Steuergerät meldet ihn als B00E6 (LI54.21-P-070658, Fassungen vom März und Juni 2020). Eine Stufe B wäre an dieser Stelle ein Schloss- oder Verankerungsstraffer; die NHTSA-Studie von 2013 beschreibt, wie ein Schlossstraffer das Gurtschloss beim Zünden über ein Seil nach unten zieht, und GM nennt Schloss, Aufroller und Verankerung als die drei Bauarten. Folge: Airbag-Lampe an, diese Stufe strafft bis zur Reparatur nicht.","u":[["h","Stecker des rechten Schloss- bzw. Verankerungsstraffers in der dritten Reihe nicht ganz eingerastet"],["m","Leitung unter dem Laderaumboden oder der Seitenverkleidung eingeklemmt oder durch Ladung beschädigt"],["l","Erhöhter Übergangswiderstand am Stecker des Airbag-Steuergeräts"],["l","Defekte Zündpille im Straffer"]],"s":["Airbag-Leuchte im Kombiinstrument an","Insasse rechts in der dritten Reihe erhält keine Straffung durch Stufe B","Sicherheitshinweis: Der Straffer enthält eine pyrotechnische Ladung; nur spannungsfrei (Batterie ab, Wartezeit) und durch eine Fachwerkstatt bearbeiten lassen"],"k":["third_row_right_pretensioner_b","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,3]],"f":"","x":["B00E0","B00E2","B00E6","B0078"]},{"c":"B00E2","t":"Gurtstraffer B dritte Reihe Mitte Auslösesteuerung","e":"Third Row Center Seat Belt Pretensioner B Deployment Control","d":"B00E2 meldet den Zündkreis eines Straffers der Stufe B am Mittelplatz der dritten Reihe. Das ist einer der seltensten Plätze der ganzen Straffertabelle: Ein Mittelsitz in Reihe drei ist schon ungewöhnlich, eine zweite Straffer-Stufe daran erst recht. Kein Hersteller dokumentiert den Code. Zum Vergleich: Die Straffer der dritten Reihe bei Mercedes erscheinen nur als linker und rechter Aufrollerkreis (B00E7/B00E6 in LI54.21-P-070658), und auch das GLS-Handbuch von 2017 spricht von Aufrollerstraffern. Eine Stufe B würde am Beckengurt wirken, wie Joysons Beckenstraffer im Verbund mit einem Aufroller. Taucht der Code auf, zuerst prüfen, ob die Ausstattungscodierung des Steuergeräts zu den tatsächlich eingebauten Sitzen passt.","u":[["h","Variantencodierung des Steuergeräts erwartet eine mittlere Stufe B, die nicht verbaut ist"],["m","Stecker unter dem Mittelsitz der dritten Reihe nach Sitzausbau nicht wieder gesteckt"],["l","Zündpille des mittleren Beckenstraffers intern unterbrochen oder kurzgeschlossen"]],"s":["Airbag-Kontrollleuchte bleibt nach dem Selbsttest an","Mittlerer Insasse der dritten Reihe hat bei einem Unfall womöglich keine Beckengurtstraffung","Sicherheitshinweis: pyrotechnisches Rückhaltebauteil – Batterie abklemmen, vorgeschriebene Wartezeit einhalten und die Arbeit einer Fachwerkstatt überlassen"],"k":["third_row_center_pretensioner_b","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,600],[0.3,3]],"f":"","x":["B00E0","B00E1","B00E8","B0077"]},{"c":"B00E3","t":"Gurtstraffer C zweite Reihe links Auslösesteuerung","e":"Second Row Left Seat Belt Pretensioner C Deployment Control","d":"B00E3 ist der Straffer der Stufe C am linken äußeren Rücksitz, und zwei Hersteller belegen ihn codegenau. Im Stellantis-Fall S2408000089 (Jeep Wrangler 2023) speichert das Rückhaltesteuergerät nach einem Werkstattbesuch B00E3-13 für den Aufrollerstraffer links in der zweiten Reihe; abgestellt wurde das durch sicheres Stecken des Verbinders D3244A (Drücken-Ziehen-Drücken), ohne Teile. Mercedes-Benz liest in LI54.21-P-070658 (A-Klasse, CLA, später GLB) B00E313 als Unterbrechung der Zündpille im linken hinteren Gurtstraffer-Aufroller, meist durch erhöhten Übergangswiderstand am Stecker des Airbag-Steuergeräts; erst neu stecken, ein neues Steuergerät nur bei Wiederkehr. Stufe C meint hier also den Aufroller, wie ihn Joyson als pyrotechnischen Gurtaufroller beschreibt. Airbag-Lampe an.","u":[["h","Stecker des Aufrollerstraffers nach Verkleidungs- oder Sitzarbeiten nicht eingerastet (Jeep Wrangler 2023, Verbinder D3244A)"],["m","Hoher Übergangswiderstand am Stecker des Airbag-Steuergeräts (Mercedes LI54.21-P-070658)"],["m","Leitung zum linken hinteren Aufroller an C-Säule oder Sitzrahmen durchgescheuert"],["l","Defekte Zündpille im Aufrollerstraffer"]],"s":["Airbag-Warnleuchte bzw. SRS-Meldung im Kombiinstrument","Schultergurt hinten links wird bei einem Unfall nicht eingezogen","Sicherheitshinweis: Der Aufrollerstraffer ist pyrotechnisch; nur bei spannungsfreiem System (Batterie ab, Wartezeit) und am besten in einer Fachwerkstatt arbeiten"],"k":["second_row_left_pretensioner_c","squib_circuit","srs_control_module"],"r":["shop_only",0,[50,700],[0.3,2.5]],"f":"","x":["B00E4","B00E5","B0073","B007B","B0053"]},{"c":"B00E4","t":"Gurtstraffer C zweite Reihe rechts Auslösesteuerung","e":"Second Row Right Seat Belt Pretensioner C Deployment Control","d":"B00E4 gehört zum rechten äußeren Rücksitz und dessen Straffer der Stufe C. Mercedes-Benz verwendet den Code so: Alle hier gelesenen Fassungen von LI54.21-P-070658 (Dezember 2019 bis Juni 2020) führen B00E413 als Unterbrechung an der Zündpille des rechten hinteren Gurtstraffer-Aufrollers. Als Ursache nennt die Information nicht den Straffer, sondern erhöhten Widerstand am Stecker des SRS-Steuergeräts: Leitung verfolgen, Stecker neu verbinden, das Steuergerät nur bei erneutem Auftreten tauschen. Der Aufroller sitzt hinter der Fondverkleidung oder im Sitz und spult beim Zünden Gurtband zurück, wie der Rettungsleitfaden von GM und Joyson erklären. Ein öffentliches Bulletin eines anderen Herstellers zu B00E4 gibt es nicht. Solange der Code gespeichert ist, bleibt Airbag-Lampe bzw. SRS-Meldung an.","u":[["h","Schlechter Kontakt am Stecker des SRS-Steuergeräts (Mercedes A-Klasse/CLA/GLB)"],["m","Stecker am rechten hinteren Aufroller nach Ausbau der Verkleidung locker"],["l","Airbag-Steuergerät selbst defekt (Fehler kehrt nach dem Neustecken zurück)"],["l","Zündpille im rechten hinteren Aufroller unterbrochen"]],"s":["SRS-Meldung oder Airbag-Lampe dauerhaft angezeigt","Fondpassagier rechts verliert die Straffung des Schultergurts","Sicherheitshinweis: pyrotechnischer Straffer – nur mit abgeklemmter Batterie und nach Ablauf der Wartezeit daran arbeiten, am besten in der Fachwerkstatt"],"k":["second_row_right_pretensioner_c","squib_circuit","srs_control_module"],"r":["shop_only",0,[50,900],[0.3,2.5]],"f":"","x":["B00E3","B00E5","B0075","B007C","B0055"]},{"c":"B00E5","t":"Gurtstraffer C zweite Reihe Mitte Auslösesteuerung","e":"Second Row Center Seat Belt Pretensioner C Deployment Control","d":"B00E5 betrifft einen Straffer der Stufe C am Mittelplatz der zweiten Reihe. Kein Hersteller veröffentlicht den Code. Straffer hinten in der Mitte sind selten: Das GLS-Handbuch von Mercedes (2017) nennt Straffer in der zweiten Reihe nur für die äußeren Gurte, und das Mercedes-Bulletin, das B00E3 und B00E4 den äußeren Aufrollern zuordnet, kennt keinen Mittelplatz. Laut einer IIHS-Auswertung zu Fondinsassen (2020) gibt es Gurtmaßnahmen für hinten zwar, verbreitet sind sie aber nicht – daher bleiben solche Plätze oft leer. Hat ein Fahrzeug doch einen mittleren Aufroll- oder Schlossstraffer, überwacht das Airbag-Steuergerät dessen Zündpille wie jede andere und setzt B00E5 bei Unterbrechung, Kurzschluss oder Widerstandsdrift; dann geht die Warnleuchte an, der Platz wird nicht gestrafft.","u":[["h","Stecker des Mittelstraffers unter der Rückbank nicht eingerastet"],["m","Steuergerät auf einen Mittelstraffer codiert, den das Fahrzeug nicht hat"],["m","Leitung am Gelenk der geteilten bzw. klappbaren Rückbank beschädigt"]],"s":["Airbag-Lampe an","Mittlerer Fondpassagier wird bei einem Frontalaufprall womöglich nicht früh zurückgehalten","Sicherheitshinweis: Der Straffer enthält eine pyrotechnische Ladung – Batterie ab, Wartezeit einhalten, Reparatur in der Fachwerkstatt"],"k":["second_row_center_pretensioner_c","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,700],[0.3,3]],"f":"","x":["B00E3","B00E4","B0074","B007D","B0054"]},{"c":"B00E6","t":"Gurtstraffer C dritte Reihe rechts Auslösesteuerung","e":"Third Row Right Seat Belt Pretensioner C Deployment Control","d":"Achtung, Reihenfolge: B00E6 ist der rechte Platz der dritten Reihe, B00E7 der linke. Mercedes-Benz belegt B00E6 mit dem Aufrollerstraffer an diesem Sitz: LI54.21-P-070658 (zuerst im Dezember 2019 für A-Klasse und CLA, in Fassung 4 auf den GLB erweitert) führt B00E613 als Unterbrechung an der Zündpille des Gurtstraffer-Aufrollers rechts in der dritten Sitzreihe. Als Ursache gilt auch hier der Übergangswiderstand am Stecker des Airbag-Steuergeräts. Dass die Marke den Gurten der dritten Reihe eigene Straffer und Kraftbegrenzer gibt, bestätigt das GLS-Handbuch von 2017. Andere Hersteller veröffentlichen den Code nicht. Ist B00E6 gespeichert, leuchtet die Airbag-Lampe, und der rechte Gurt der dritten Reihe wird nicht gestrafft.","u":[["h","Übergangswiderstand am Stecker des Airbag-Steuergeräts (Mercedes LI54.21-P-070658)"],["m","Stecker des rechten Aufrollers der dritten Reihe hinter der Laderaumverkleidung locker"],["l","Leitung im Bereich des hinteren Radhauses durch Verkleidung oder Ladung gequetscht"],["l","Zündpille des rechten Aufrollers der dritten Reihe defekt"]],"s":["SRS-Meldung oder Airbag-Warnleuchte","Rechter Gurt der dritten Reihe bleibt bei einem Unfall lose","Sicherheitshinweis: An diesem pyrotechnischen Aufroller nur spannungsfrei arbeiten (Batterie ab, Wartezeit), am besten durch eine Fachwerkstatt"],"k":["third_row_right_pretensioner_c","squib_circuit","srs_control_module"],"r":["shop_only",0,[50,900],[0.3,3]],"f":"","x":["B00E7","B00E8","B00E1","B0078","B0058"]},{"c":"B00E7","t":"Gurtstraffer C dritte Reihe links Auslösesteuerung","e":"Third Row Left Seat Belt Pretensioner C Deployment Control","d":"B00E7 kennzeichnet den Straffer der Stufe C am linken Sitz der dritten Reihe und folgt in der Liste auf den rechten Zwilling B00E6. Mercedes-Benz belegt ihn: LI54.21-P-070658 nennt B00E713 für eine Unterbrechung an der Zündpille des Gurtstraffer-Aufrollers links in der dritten Sitzreihe, in derselben Aufstellung wie die Aufroller hinten und am Fahrersitz. Die Abhilfe beginnt dort nicht beim Straffer, sondern beim Verfolgen der Leitung und neuem Stecken der Verbinder am Rückhaltesteuergerät; erst bei wiederkehrendem Fehler kommt ein neues Steuergerät mindestens im Stand Q4. Joyson beschreibt diese Art pyrotechnischer Aufroller, die in der Karosserie oder im Sitzgestell sitzen können. Kein anderer Hersteller veröffentlicht B00E7. Airbag-Lampe an, der Insasse links in Reihe drei wird nicht gestrafft.","u":[["h","Erhöhter Widerstand am Stecker des Rückhaltesteuergeräts"],["m","Verbinder des linken Aufrollers der dritten Reihe bei Verkleidungs- oder Sitzarbeiten gelöst"],["l","Steuergerät unter dem geforderten Stand, Fehler kehrt immer wieder"],["l","Zündpille im Aufroller intern unterbrochen"]],"s":["Airbag-Lampe oder dauerhafte SRS-Meldung","Keine Gurtstraffung am linken Sitz der dritten Reihe","Sicherheitshinweis: pyrotechnisches Bauteil – vor dem Anfassen Batterie abklemmen und warten; Wartung in einer Fachwerkstatt"],"k":["third_row_left_pretensioner_c","squib_circuit","srs_control_module"],"r":["shop_only",0,[50,900],[0.3,3]],"f":"","x":["B00E6","B00E8","B00E0","B0076","B0056"]},{"c":"B00E8","t":"Gurtstraffer C dritte Reihe Mitte Auslösesteuerung","e":"Third Row Center Seat Belt Pretensioner C Deployment Control","d":"B00E8 schließt die Reihe der Stufe C mit dem Mittelplatz der dritten Reihe ab. Kein Hersteller veröffentlicht ihn, und die einzige öffentliche Liste, die diesen Block nutzt – Mercedes-Benz LI54.21-P-070658 –, endet bei einem linken und einem rechten Aufroller der dritten Reihe (B00E7, B00E6). Ein mittlerer Straffer in Reihe drei käme vor allem in großen Vans oder SUVs mit Dreier-Bank ganz hinten vor. Joysons Aufrollerstraffer ist kompakt genug für den Einbau ins Sitzgestell – dort müsste ein Mittelstraffer sitzen. Das IIHS verglich 2019 in Frontalcrashs Fond-Dummys mit Standardgurt und mit Straffer plus Kraftbegrenzer und stellte fest, dass solche Maßnahmen hinten noch wenig verbreitet sind. Ist B00E8 gesetzt, leuchtet die Airbag-Lampe, und der mittlere Gurt wird nicht gestrafft.","u":[["h","Stecker des sitzintegrierten Mittelaufrollers nach Ausbau der hinteren Bank nicht gesteckt"],["m","Rückhaltesteuergerät auf eine Dreier-Bank in Reihe drei codiert, obwohl nur zwei Sitze verbaut sind"],["l","Zündpille des mittleren Aufrollers fehlerhaft"]],"s":["Airbag-Warnleuchte leuchtet","Mittelplatz der dritten Reihe ohne Gurtstraffung","Sicherheitshinweis: enthält eine pyrotechnische Ladung – keine Arbeiten ohne abgeklemmte Batterie und Wartezeit; Fachwerkstatt beauftragen"],"k":["third_row_center_pretensioner_c","squib_circuit","srs_control_module"],"r":["shop_only",0,[60,800],[0.3,3]],"f":"","x":["B00E6","B00E7","B00E2","B0077","B0057"]},{"c":"B00F0","t":"Aufblasbarer Sicherheitsgurt Fahrer Auslösesteuerung","e":"Driver Inflatable Seat Belt Deployment Control","d":"B00F0 ist der Zündkreis eines aufblasbaren Gurts am Fahrersitz – ein Gurtabschnitt, den eine Gasquelle bei einem Unfall füllt, damit sich die Last auf eine breitere Brustfläche verteilt. Die bekannten Seriengurte dieser Art von Ford und Mercedes-Benz sitzen nur an den äußeren Rücksitzen; B00F0 dokumentiert kein Hersteller. Für Vordersitze ist die Idee alt und in Patenten gut beschrieben, etwa ein Daimler-Entwurf von 2010 mit Gasgenerator am unteren Anker neben der B-Säule und gefaltetem, durch Reißfäden gehaltenem Gurtband, oder ein Autoliv-Entwurf mit Gasgeneratoren an der Sitzlehne. Auch Joyson führt ein am Gurt befestigtes Zusatz-Rückhaltekissen unter seinen Airbag-Neuheiten. Mit gesetztem Code brennt die Airbag-Lampe.","u":[["h","Variante des Airbag-Steuergeräts erwartet einen aufblasbaren Fahrergurt, der nicht verbaut ist"],["m","Stecker des Gurt-Gasgenerators am unteren Anker oder am Sitz locker oder korrodiert"],["m","Leitung zum Gasgenerator durch Sitzverstellung durchgescheuert"],["l","Zünder des Gurt-Gasgenerators defekt"]],"s":["Airbag-Warnleuchte an","Fahrergurt würde sich bei einem Unfall nicht aufblasen","Sicherheitshinweis: Der Gurt enthält einen pyrotechnischen Gasgenerator; nur spannungsfrei (Batterie ab, Wartezeit) und in einer Fachwerkstatt arbeiten"],"k":["driver_inflatable_belt","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,1200],[0.5,3]],"f":"","x":["B00F1","B0070","B007E"]},{"c":"B00F1","t":"Aufblasbarer Sicherheitsgurt Beifahrer Auslösesteuerung","e":"Passenger Inflatable Seat Belt Deployment Control","d":"B00F1 ist das Gegenstück zu B00F0 am Beifahrersitz und für einen aufblasbaren Gurt an diesem Platz vorgesehen. Kein Hersteller dokumentiert ihn, und öffentlich ist kein Serienfahrzeug mit aufblasbarem Beifahrergurt bekannt; das Handbuch der S-Klasse bietet den Beltbag nur für die äußeren Fondgurte an. Eine Beifahrer-Ausführung stünde vor denselben Entscheidungen, die Patente zeigen: Allied Chemical ließ schon 1972 ein Gurtschloss schützen, das Gas von einem am Boden verankerten Generator durch Schloss und Zunge in Becken- und Schultergurt leitet, sodass der Gurt selbst keine Leitungen braucht; Autolivs Entwurf von 2002 setzt getrennte Generatoren an die Sitzlehne. Das Airbag-Steuergerät würde den Zünderkreis überwachen und B00F1 bei Unterbrechung, Kurzschluss oder falschem Widerstand setzen.","u":[["h","Steuergerät auf einen aufblasbaren Beifahrergurt codiert, den das Auto nicht hat"],["m","Stecker am schlossseitigen Gasgenerator unter dem Beifahrersitz locker"],["l","Sitzkabelbaum durch Gegenstände unter dem Sitz oder durch Sitzbewegung beschädigt"]],"s":["Airbag-Leuchte im Kombiinstrument an","Beifahrergurt kann sich bei einem Unfall nicht aufblasen","Sicherheitshinweis: pyrotechnischer Gurt-Gasgenerator – Batterie abklemmen, Wartezeit beachten, Reparatur durch eine Fachwerkstatt"],"k":["passenger_inflatable_belt","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,1200],[0.5,3]],"f":"","x":["B00F0","B0072","B007F","B0052"]},{"c":"B00F2","t":"Aufblasbarer Sicherheitsgurt zweite Reihe links Auslösesteuerung","e":"Second Row Left Inflatable Seat Belt Deployment Control","d":"B00F2 betrifft den aufblasbaren Gurt am linken Außenplatz der zweiten Reihe – genau dort, wo solche Gurte in Serie kamen. Ford bot sie ab dem Explorer 2011 an; laut Betriebsanleitung 2018 sitzt der Luftsack im Schulterteil der äußeren Gurte der zweiten Reihe, wird mit gekühltem Gas bei geringerem Druck gefüllt, löst bei Frontal-, Seiten- und Überschlagunfällen aus und wird vom selben Steuergerät samt Warnleuchte überwacht wie die Vordergurte. Fehler legt Ford unter eigenen Codes ab (B141B/B141C): Das Programm 21B11 (Explorer 2014–2016) führt sie auf beschädigte Adern im Sitzkabelbaum am Gurtstecker zurück. Mercedes-Benz setzt seinen Beltbag an die äußeren Fondplätze der S-Klasse. B00F2 veröffentlicht keiner der beiden. Gesetzt: Airbag-Lampe an.","u":[["h","Innere Aderschäden im Sitzkabelbaum der zweiten Reihe am Gurtstecker (Ford-Programm 21B11)"],["m","Stecker des Gasgenerators unter dem linken Rücksitz nach Umklappen oder Ausbau locker"],["l","Fehler im Zünder des Gurt-Gasgenerators"]],"s":["Airbag-Warnleuchte an","Aufblasbarer Gurt hinten links löst bei einem Unfall womöglich nicht aus","Sicherheitshinweis: Der Gurt hat einen Kaltgas- bzw. pyrotechnischen Generator – Batterie ab, Wartezeit, Arbeiten nur in der Fachwerkstatt"],"k":["second_row_left_inflatable_belt","squib_circuit","srs_control_module"],"r":["shop_only",0,[100,1500],[0.5,3]],"f":"","x":["B00F4","B00F3","B0073","B0053"]},{"c":"B00F3","t":"Aufblasbarer Sicherheitsgurt zweite Reihe Mitte Auslösesteuerung","e":"Second Row Center Inflatable Seat Belt Deployment Control","d":"B00F3 bezieht sich auf einen aufblasbaren Gurt am Mittelplatz der zweiten Reihe. Kein Hersteller dokumentiert den Code, und die bekannten Systeme sparen diesen Platz aus: Das Explorer-Handbuch 2018 von Ford beschränkt die aufblasbaren Gurte auf die äußeren Plätze der zweiten Reihe, und Mercedes setzt den Beltbag an die äußeren Fondgurte (S-Klasse-Handbuch 2017); das E-Klasse-Handbuch desselben Jahres führt den Gurtairbag als Schutz beim Frontalaufprall. Eine Mittelausführung wäre schwerer unterzubringen, weil das Gas meist am Schloss oder am unteren Anker eintritt; die NHTSA-Zugversuchsstudie hält fest, dass der Explorer-Gurt von 2011 einen Aufroller in der Beckenschlaufe brauchte, weil der Generator am Schloss saß. Ist der Code gesetzt, leuchtet die Airbag-Lampe.","u":[["h","Rückhaltesteuergerät für einen mittleren aufblasbaren Gurt konfiguriert, der im Fahrzeug fehlt"],["m","Stecker am Gasgenerator des mittleren Gurtschlosses unter der Bank getrennt"],["l","Zünder des mittleren Gurt-Gasgenerators unterbrochen oder kurzgeschlossen"]],"s":["Airbag-Kontrollleuchte bleibt an","Mittlerer Fondgurt würde sich bei einem Unfall nicht füllen","Sicherheitshinweis: pyrotechnischer bzw. Kaltgas-Generator – nur mit abgeklemmter Batterie und nach Wartezeit, in einer Fachwerkstatt"],"k":["second_row_center_inflatable_belt","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,1500],[0.5,3]],"f":"","x":["B00F2","B00F4","B0074","B0054"]},{"c":"B00F4","t":"Aufblasbarer Sicherheitsgurt zweite Reihe rechts Auslösesteuerung","e":"Second Row Right Inflatable Seat Belt Deployment Control","d":"B00F4 ist der Kreis des aufblasbaren Gurts am rechten äußeren Rücksitz. Die Hardware gibt es in Serie, den Code dokumentiert aber kein Hersteller. Der Ford Explorer (2014–2016) legt Gurtfehler als B141B und/oder B141C ab; Nachtrag 2 zum Programm 21B11 (Juni 2022) betont, zuerst diese Codes zu prüfen, sieht eine eigene Arbeitszeit vor, wenn beide anliegen, und lässt dann das Anschlusskabel am Sitz neu verlegen oder ersetzen. Mercedes-Benz bietet den Beltbag für Fondgurte der E-Klasse an; das Handbuch warnt davor, einen Kindersitz mit einem Gurt mit BELTBAG-Etikett zu befestigen. Das Daimler-Patent von 2010 setzt den Gasgenerator an den unteren Gurtanker und faltet das Band mit Reißfäden. Mit gesetztem B00F4 leuchtet die Airbag-Lampe.","u":[["h","Verschlissene oder gebrochene Adern im Sitz-Anschlusskabel rechts in der zweiten Reihe (Ford Explorer 2014–2016)"],["m","Stecker des Gasgenerators am unteren Gurtanker bzw. unter dem Sitz nicht eingerastet"],["l","Zünder des Gasgenerators defekt"]],"s":["Airbag-Lampe leuchtet","Aufblasbarer Gurt hinten rechts nicht auslösebereit","Sicherheitshinweis: Gurt und Generator nicht öffnen oder anmessen; Batterie ab, Wartezeit, Arbeit einer Fachwerkstatt überlassen"],"k":["second_row_right_inflatable_belt","squib_circuit","srs_control_module"],"r":["shop_only",0,[100,1500],[0.5,3]],"f":"","x":["B00F2","B00F3","B0075","B0055"]},{"c":"B00F5","t":"Aufblasbarer Sicherheitsgurt dritte Reihe links Auslösesteuerung","e":"Third Row Left Inflatable Seat Belt Deployment Control","d":"B00F5 eröffnet mit dem linken Sitz den Teil des Blocks für aufblasbare Gurte in der dritten Reihe; B00F6 (Mitte) und B00F7 (rechts) folgen. Kein Hersteller dokumentiert B00F5, und die bekannten Systeme enden bei Reihe zwei: Der Ford Explorer hat seine aufblasbaren Gurte nur an den äußeren Plätzen der zweiten Reihe, obwohl er eine dritte Reihe hat, und Mercedes bietet den Beltbag für Fondgurte von S- und E-Klasse an (in der S-Klasse an den Außenplätzen). Auch der aufblasbare Gurt der NHTSA-Versuchsreihe von 2021 stammte aus der zweiten Reihe. Technisch würde eine Ausführung in Reihe drei genauso arbeiten – Luftsack im Schultergurt, Generator nahe Schloss oder Anker, wie das Autoliv-Patent skizziert. Ist der Code gespeichert, leuchtet die Airbag-Lampe, und dieser Gurt bläst sich nicht auf.","u":[["h","Airbag-Steuergerät mit einem aufblasbaren Gurt in Reihe drei codiert, der nicht eingebaut ist"],["m","Stecker am Gurt-Generator links in der dritten Reihe beim Umklappen des Sitzes gelöst"],["l","Defekter Zünder im Gurt-Generator der dritten Reihe"]],"s":["Airbag-Warnleuchte an","Aufblasbarer Gurt links in der dritten Reihe bei einem Unfall nicht verfügbar","Sicherheitshinweis: Gasgenerator mit Sprengzünder – Batterie abklemmen, warten und von einer Fachwerkstatt bearbeiten lassen"],"k":["third_row_left_inflatable_belt","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,1500],[0.5,3]],"f":"","x":["B00F6","B00F7","B00F2","B0076","B0056"]},{"c":"B00F6","t":"Aufblasbarer Sicherheitsgurt dritte Reihe Mitte Auslösesteuerung","e":"Third Row Center Inflatable Seat Belt Deployment Control","d":"B00F6 bezeichnet den Auslösekreis eines aufblasbaren Gurts auf dem Mittelplatz der dritten Reihe. Dort ist ein solcher Gurt am wenigsten zu erwarten: Die bekannten Seriensysteme sitzen an äußeren Fondplätzen, beim Ford Explorer nur in Reihe zwei, beim Mercedes-Beltbag an den äußeren Fondgurten. Das Handbuch des dreireihigen Mercedes GLS (2017) nennt für die Gurte der dritten Reihe Gurtstraffer und Gurtkraftbegrenzer, aber keinen Beltbag. Auch die NHTSA-Versuchsreihe zu Gurten prüfte den aufblasbaren Explorer-Gurt an einem Platz der zweiten Reihe. Joysons Studie zu gurtgebundenen Rückhaltesystemen für neue Innenraumkonzepte zeigt, wohin sich solche Luftsäcke ausbreiten könnten. Kein Hersteller veröffentlicht B00F6; ist er gesetzt, leuchtet die Airbag-Lampe, und dieser Gurt bliebe flach.","u":[["h","Airbag-Steuergerät auf einen aufblasbaren Mittelgurt in Reihe drei codiert, den das Fahrzeug nicht hat"],["m","Stecker am Gasgenerator des Mittelgurts beim Umklappen oder Ausbau der dritten Sitzreihe gelöst"],["l","Zünder im Gasgenerator des Mittelgurts außerhalb seines Widerstandsfensters"]],"s":["Airbag-Warnleuchte leuchtet","Aufblasbarer Mittelgurt der dritten Reihe würde sich bei einem Unfall nicht füllen","Sicherheitshinweis: Bauteil mit Zünder – Batterie ab, Wartezeit einhalten, nur in der Fachwerkstatt arbeiten"],"k":["third_row_center_inflatable_belt","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,1500],[0.5,3]],"f":"","x":["B00F5","B00F7","B00F2"]},{"c":"B00F7","t":"Aufblasbarer Sicherheitsgurt dritte Reihe rechts Auslösesteuerung","e":"Third Row Right Inflatable Seat Belt Deployment Control","d":"B00F7 schließt den Block der aufblasbaren Gurte mit dem rechten Platz der dritten Reihe ab. Kein Hersteller dokumentiert ihn. Der nächste reale Fall liegt eine Reihe weiter vorn: Beim Ford Explorer 2014–2016 nennt das Händlerbulletin zum Programm 21B11 B141C als Code des rechten und B141B als Code des linken Kabelbaums der zweiten Reihe und lässt bei einem davon das Sitz-Anschlusskabel neu verlegen oder instand setzen. Fords Handbuch von 2018 setzt die aufblasbaren Fondgurte nur in das Schulterband der äußeren Plätze der zweiten Reihe; rechts in Reihe drei gibt es Kindersitz-Anker, keinen Luftsack. Mercedes führt Beltbags an den äußeren Fondgurten der S-Klasse, und Autolivs Patent von 2002 speist Gurte über eine Gasführung aus einem Generator. Steht B00F7 an, bleibt die Airbag-Lampe an.","u":[["h","Durchgescheuerte Adern im Kabelbaum des rechten Fondsitzes, wie eine Reihe weiter vorn beim Explorer (B141C)"],["m","Variantencodierung des Rückhaltesteuergeräts erwartet einen aufblasbaren Gurt rechts in Reihe drei"],["l","Zünder im Gurt-Generator rechts in Reihe drei unterbrochen oder kurzgeschlossen"]],"s":["Airbag-Lampe bleibt nach dem Startcheck an","Aufblasbarer Gurt rechts in der dritten Reihe nicht scharf geschaltet","Sicherheitshinweis: Zünderkreis nie mit Prüflampe messen; Batterie trennen, warten, der Fachwerkstatt überlassen"],"k":["third_row_right_inflatable_belt","squib_circuit","srs_control_module"],"r":["shop_only",0,[80,1500],[0.5,3]],"f":"","x":["B00F5","B00F6","B00F4"]},{"c":"B0100","t":"Sensorreinigung Luftgebläse-Aktuator A","e":"Sensor Cleaning Air Blower Actuator A","d":"B0100 ist der Sammelfehler für Luftgebläse A einer Sensorreinigung, also für Lüfter oder Motoreinheit selbst und nicht für Ansteuerleitung oder Relais (dafür B0102 und B0104). Solche Gebläse halten Kameralinsen und Lidar-Fenster frei von Tropfen, Staub und Insekten. Fords Patent US12115948B2 setzt ein Gebläse an den Sensorhalter; es saugt Außenluft durch einen Ansaugkanal und bläst sie über ein zylindrisches Lidar-Fenster und eine Kameralinse. Beim Sensorträger („Tiara“) auf dem Dach von Fords Versuchsfahrzeugen für autonomes Fahren erzeugen Schlitze einen Luftvorhang, der die meisten Insekten ablenkt; Luft trocknet die Linse auch nach dem Waschen. Welches Gebläse A heißt, legt der Hersteller fest. Öffentlich dokumentiert kein Fahrzeughersteller B0100. Fällt das Gebläse aus, sammelt sich Schmutz, bis der Sensor sich als verdeckt meldet.","u":[["h","Motor von Gebläse A verschlissen, festgegangen oder Wicklung unterbrochen"],["m","Lüfterrad durch Eis, Laub oder Schmutz im Ansaugkanal blockiert"],["l","Korrodierter oder lockerer Stecker direkt an Gebläse A"]],"s":["Meldung „Sensor blockiert“ oder Störung der Sensorreinigung","Assistenz- oder automatisierte Fahrfunktionen eingeschränkt oder abgeschaltet","An den Luftauslässen am Sensor kein Luftstrom hörbar oder spürbar"],"k":["sensor_cleaning_air_blower_a","object_detection_maintenance_module_a"],"r":["medium",0,[100,900],[0.5,3]],"f":"L","x":["B0101","B0102","B0104","U022E"]},{"c":"B0101","t":"Sensorreinigung Luftgebläse-Aktuator B","e":"Sensor Cleaning Air Blower Actuator B","d":"B0101 meldet einen Fehler der zweiten Reinigungs-Luftquelle, Gebläse B. Eine zweite Einheit ist sinnvoll, wo Sensoren über die Karosserie verteilt sind: Dachmodul und Stoßfänger- oder Ecksensor brauchen getrennte Luftversorgung. Nicht jede Bauart nutzt einen Lüfter; Ubers Patent von 2016 (heute Aurora) speist die Luftmesser an Lidar und Kameras aus Kompressor und Speicher mit etwa 140–160 psi, mit je einem Magnetventil pro Auslass und einem Drucksensor, der bei Undichtigkeit warnt. Die Lidar-Düsen von AUMOVIO blasen mit Druckluft Wassertropfen ab und entfernen Staub ganz ohne Waschflüssigkeit; Kautex kombiniert in den Allegro-Systemen Wasser und Luft für Kamera und Lidar. Wie A und B aufgeteilt sind, veröffentlicht kein Autohersteller, ebenso wenig B0101 selbst.","u":[["h","Gebläse bzw. Kompressor B verschlissen oder mit zu hoher Stromaufnahme"],["m","Undichter oder gerissener Luftschlauch, Gebläse B baut keinen Druck auf"],["l","Wasser- oder Salzeintritt in Gebläse B an exponierter Einbaustelle"]],"s":["Reinigungsstörung für die Sensorgruppe, die Gebläse B versorgt","Wassertropfen oder Staub bleiben auf Lidar- oder Kamerafenster","Assistenzfunktionen eingeschränkt, sobald der betroffene Sensor erblindet"],"k":["sensor_cleaning_air_blower_b","object_detection_maintenance_module_b"],"r":["medium",0,[100,1200],[0.5,3]],"f":"L","x":["B0100","B0103","B0105","U022F"]},{"c":"B0102","t":"Sensorreinigung Luftgebläse-Aktuator A Ansteuerung","e":"Sensor Cleaning Air Blower Actuator A Control","d":"B0102 grenzt das Problem von Gebläse A auf die Ansteuerung ein: Das steuernde Modul misst auf der Leitung, die Gebläse A schaltet, falsche Spannung oder falschen Strom, meist Unterbrechung, Masse- oder Plusschluss. In Fords Lidar-Reinigungspatent US10569746B2 öffnet ein Rechner den Luftstrom aus Gebläse oder Kompressor über ein elektrisches Magnetventil und kann ihn dosieren; liegt die Trübung des Fensters über etwa 30 %, läuft zuerst Luft, und der autonome Modus kann enden. Fords späteres Patent US12115948B2 setzt das Gebläse neben den Sensor auf den Halter, die Zuleitung führt also in ein exponiertes Modul. Valeo weist darauf hin, dass eine verdeckte Linse den automatisierten Betrieb beenden kann. Kein Autohersteller veröffentlicht B0102. Anders als bei B0100 kann das Gebläse selbst hier intakt sein.","u":[["h","Gebrochene Steuerleitung oder Kontakt zwischen Modul und Gebläse A"],["m","Steuerleitung von Gebläse A mit Masse oder Batteriespannung kurzgeschlossen"],["l","Endstufe im Reinigungs- bzw. Wartungssteuergerät defekt"]],"s":["Gebläse A läuft trotz Reinigungsanforderung nie an","Gebläse A läuft dauernd, wenn die Leitung Plusschluss hat","Meldung „Sensor blockiert“ und eingeschränkte Assistenzfunktionen"],"k":["sensor_cleaning_air_blower_a","actuator_wiring","object_detection_maintenance_module_a"],"r":["medium",1,[50,500],[0.5,2.5]],"f":"L","x":["B0100","B0103","B0104"]},{"c":"B0103","t":"Sensorreinigung Luftgebläse-Aktuator B Ansteuerung","e":"Sensor Cleaning Air Blower Actuator B Control","d":"Bei B0103 meldet das Modul die Befehlsleitung von Gebläse B, nicht das Gebläse: offene Leitung, Kurzschluss oder eine Endstufe, die nicht schalten kann. Bei Druckluftanlagen ist das geschaltete Bauteil oft ein Ventilblock. In Ubers Patent öffnet die Steuerung einzelne Magnetventile für feste Zeiten, etwa ein Ventil drei Sekunden lang; eine einzige gestörte Ansteuerleitung lässt so nur einen Teil des Lidars oder eine Kamera ohne Luft. Die Tiara von Fords Versuchsfahrzeugen bläst durch Schlitze neben jeder Linse einen Luftvorhang, der Insekten abhält – fällt die Ansteuerung auf der B-Seite aus, setzt sich dort Schmutz ab. Laut Kautex priorisiert die Software Reinigungspunkte, indem sie die Aktoren koordiniert. Welche Auslässe zu B gehören, ist unveröffentlicht; kein Autohersteller dokumentiert B0103. Gegenstück auf der A-Seite ist B0102.","u":[["h","Beschädigter Kabelbaum oder Stecker im Ansteuerpfad von Gebläse B"],["m","Magnetspule des Luftventils B unterbrochen oder kurzgeschlossen, wo Luft über Ventile geschaltet wird"],["l","Ausgefallene Endstufe für Gebläse B im steuernden Modul"]],"s":["Nach dem Waschgang bleiben Schlieren oder Tropfen auf der Linse","Reinigungswarnung nur für Sensoren am Kreis B","Assistenzfunktionen bei Regen oder Staub zeitweise nicht verfügbar"],"k":["sensor_cleaning_air_blower_b","actuator_wiring","object_detection_maintenance_module_b"],"r":["medium",1,[50,500],[0.5,2.5]],"f":"L","x":["B0101","B0102","B0105"]},{"c":"B0104","t":"Sensorreinigung Luftgebläse-Aktuator A Steuerrelais","e":"Sensor Cleaning Air Blower Actuator A Control Relay","d":"B0104 verweist auf das Relais, das Gebläse A mit Strom versorgt. Ein Lüftermotor zieht mehr Strom, als ein Modulausgang tragen kann, deshalb liegt ein Relais nahe: Das Modul bestromt die Spule (Klemmen 85/86 nach HELLA-Schema), der Kontakt (30/87) speist den Motor. HELLAs Relais-Broschüre erklärt, dass Spulen eine Diode oder einen Widerstand gegen Abschaltspitzen tragen können und dass Relais auf Spulenwiderstand und Spannungsfall am Kontakt geprüft werden. Fehlerbilder sind eine offene oder kurzgeschlossene Spule, verschweißte oder verbrannte Kontakte oder eine fehlende Versorgung. Fords US12115948B2 setzt das Gebläse auf den Sensorhalter, und die Ford-Tiara nutzt diese Luft laut eeNews als Schutz der Linsen vor Insekten. Kein Autohersteller veröffentlicht B0104; das Relais der B-Seite ist B0105.","u":[["h","Verbrannte oder verschweißte Kontakte im Relais von Gebläse A"],["m","Relaisspule unterbrochen oder deren Ansteuerleitung getrennt"],["m","Durchgebrannte Sicherung oder lockerer Sockel auf der Versorgungsseite des Relais"]],"s":["Gebläse A ohne Funktion, oder es läuft ohne Befehl bei verschweißten Kontakten","Kein Relaisklicken bei Reinigungsanforderung","Warnung zur Sensorreinigung, Assistenzfunktionen können entfallen"],"k":["sensor_cleaning_air_blower_relay_a","relay_control_circuit","sensor_cleaning_air_blower_a"],"r":["easy",1,[20,200],[0.2,1]],"f":"L","x":["B0100","B0102","B0105"]},{"c":"B0105","t":"Sensorreinigung Luftgebläse-Aktuator B Steuerrelais","e":"Sensor Cleaning Air Blower Actuator B Control Relay","d":"B0105 ist der Relaisfehler auf der B-Seite der Luftversorgung für die Sensorreinigung. Ist B kein kleiner Lüfter, sondern ein Kompressor – wie in Ubers Patent, wo ein Kompressor einen Speicher füllt und bei etwa 130–140 psi nachlädt –, muss das Relais einen kräftigen Einschaltstrom tragen, und abgebrannte Kontakte werden zur typischen Schwachstelle. HELLA führt Wechsler- und Schließerrelais für Motoren wie Lüfter auf und nennt die Prüfungen: Abfallspannung, Kontakt-Spannungsfall, Spulenwiderstand. AUMOVIO betont, dass Luft ein Lidar bei schlechtem Wetter einsatzfähig hält, indem sie Tropfen abbläst – ein hängendes Relais fällt deshalb zuerst bei Regen auf. Kein Autohersteller hat B0105 oder die Aufgabe von B veröffentlicht.","u":[["h","Kontakte von Relais B durch hohen Anlaufstrom von Motor oder Kompressor abgebrannt"],["m","Spule von Relais B oder ihre Löschdiode ausgefallen"],["l","Korrodierter Relaissockel oder falscher Relaistyp eingesetzt"]],"s":["Gebläse bzw. Kompressor B startet nicht oder schaltet nicht ab","Bei Regen bleiben Tropfen auf den Sensorfenstern","Assistenzfunktionen fallen aus, wenn ein Sensor als blockiert gemeldet wird"],"k":["sensor_cleaning_air_blower_relay_b","relay_control_circuit","sensor_cleaning_air_blower_b"],"r":["easy",1,[20,250],[0.2,1]],"f":"L","x":["B0101","B0103","B0104"]},{"c":"B0106","t":"LIDAR-Wascher-Aktuator A","e":"LIDAR Washer Actuator A","d":"B0106 eröffnet eine Reihe von vier Lidar-Wascheraktoren (A bis D). Aktor ist, was die Flüssigkeit zum Lidar-Fenster bringt: eine Waschpumpe oder ein elektromagnetisches Ventil. In Fords Patent US10569746B2 schaltet ein Rechner die Waschpumpe für die Sprühdüse eines Dach-Lidars, nachdem eine Luftdüse etwa 5 s gelaufen ist und das Fenster noch mehr als rund 20 % trüb ist; ein Wischer folgt nur bei Bedarf. Solero baut 2/2- und 3/2-Wegeventile, die Waschflüssigkeit an einzelne Düsen verteilen, auch für Lidar. Die Lidar-Düsen von AUMOVIO reinigen die Kuppel mit Flüssigkeit unter Druck nach dem Coandă-Effekt. Welches Lidar oder welche Düse der Hersteller A nennt, ist nicht veröffentlicht, und kein Autohersteller dokumentiert B0106. Versagt die Wäsche, kann das Lidar eine verdeckte Sicht melden.","u":[["h","Waschpumpe bzw. Ventil A der Lidar-Düse festgegangen oder elektrisch unterbrochen"],["m","Leitungs- oder Steckerfehler an Aktor A"],["l","Gefrorene Waschflüssigkeit blockiert Pumpe A"]],"s":["Bei einem Reinigungsgang kommt an Lidar A keine Flüssigkeit an","Meldung „Lidar blockiert“ und geringere Verfügbarkeit des automatisierten Fahrens"],"k":["lidar_washer_actuator_a","washer_pump","object_detection_maintenance_module_a"],"r":["medium",1,[50,700],[0.3,2.5]],"f":"L","x":["B0107","B0108","B0109","B010A","B012F"]},{"c":"B0107","t":"LIDAR-Wascher-Aktuator B","e":"LIDAR Washer Actuator B","d":"B0107 ist der zweite Lidar-Wascheraktor. Wozu ein Fahrzeug mehrere braucht, zeigt Ubers Patent von 2016: Das Dach-Lidar wird dort von drei getrennten Düseneinheiten gewaschen, jede mit eigener Pumpe und Rückschlagventil, gespeist aus einem Behälter; die Steuerung sprüht normalerweise erst Flüssigkeit und trocknet dann mit Luft. Fällt eine Pumpe aus, bleibt nur dieser Abschnitt des Fensters verschmutzt. ARaymonds Broschüre zu Reinigungssystemen zeigt Lidar-Düsen mit mehreren Auslässen und integrierte elektromagnetische Ventile als Alternative zur Pumpe je Düse. Kautex liefert komplette Sätze aus Behälter, Pumpe und Düsen für Kamera- und Lidar-Reinigung. Bei keinem Fahrzeughersteller ist eine Bedeutung von B0107 veröffentlicht, und ob B ein zweites Lidar oder eine zweite Düse am selben Lidar ist, steht nirgends.","u":[["h","Waschpumpe B verschlissen oder ihr Motor unterbrochen"],["m","Rückschlagventil oder Leitung zu Düse B verstopft, Pumpe arbeitet gegen geschlossenen Weg"],["l","Durchgescheuerte Leitung zu Aktor B"]],"s":["Ein Abschnitt des Lidar-Fensters bleibt nach dem Waschen schmutzig","Wiederholte Reinigungsanforderungen und Warnung „Lidar eingeschränkt“"],"k":["lidar_washer_actuator_b","washer_pump","object_detection_maintenance_module_a"],"r":["medium",1,[50,700],[0.3,2.5]],"f":"L","x":["B0106","B0108","B0109","B011C"]},{"c":"B0108","t":"LIDAR-Wascher-Aktuator C","e":"LIDAR Washer Actuator C","d":"B0108 betrifft Lidar-Wascheraktor C. Robotaxis mit mehreren Lidars, etwa auf dem Dach und an den Ecken, sind der Ort, wo ein dritter Kreis passt. Valeo führt seine beheizte Teleskopdüse für Lidar (Finalist des PACE Award 2021) und liefert nach eigener Angabe Reinigungssysteme samt Steuergerät und Software für Privatfahrzeuge und Robotaxis; eine Teleskopdüse bringt ein bewegliches Teil mit, das bei Frost klemmen kann. Soleros 4/3-Wegeventil verteilt Flüssigkeit zentral, damit weniger Gleichstrompumpen nötig sind – Aktor C kann also auch eine Ventilstellung statt einer Pumpe sein. Jalopnik berichtete 2018, dass Waymo seine Lidar-Kuppeln mit kleinen Wischern reinigte und Cruise eigene Reinigungstechnik baute. Kein Hersteller vergibt C öffentlich oder dokumentiert B0108.","u":[["h","Teleskopdüse C durch Eis oder Schmutz festgesetzt, Aktor überlastet"],["m","Verteilventil schaltet Stellung C nicht"],["l","Düsenheizung oder gemeinsamer Stecker am Kreis C defekt"]],"s":["Lidar C wird nicht gereinigt, vor allem bei Frost oder Schnee","Automatisiertes Fahren lässt sich nicht aktivieren oder gibt die Kontrolle zurück"],"k":["lidar_washer_actuator_c","washer_pump","object_detection_maintenance_module_a"],"r":["medium",1,[60,800],[0.3,2.5]],"f":"L","x":["B0106","B0107","B0109","B012F"]},{"c":"B0109","t":"LIDAR-Wascher-Aktuator D","e":"LIDAR Washer Actuator D","d":"B0109 schließt die Gruppe der Lidar-Wascher mit Aktor D ab; ab B010A folgen die Kamera-Wascher. Vier Lidar-Kreise passen zu Flotten für fahrerlosen Betrieb: Kautex baut in jedes Zoox-Robotaxi zwei vollständige Allegro-Systeme zum Reinigen und Freihalten ein, die Wasser und Luft für Kameras und Lidars kombinieren. Bei Fords Versuchsfahrzeugen für autonomes Fahren sprühen Düsen neben jeder Linse bei Bedarf Waschflüssigkeit, und die Dachtiara mit Kameras und Lidar erzeugt zusätzlich einen Luftvorhang. In Fords US10569746B2 kann der Rechner den autonomen Modus sogar verlassen, solange ein Lidar-Fenster zu trüb ist. Öffentlich ist nicht festgelegt, welche Einheit D ist, und kein Autohersteller dokumentiert B0109. Ein ausgefallener Aktor D zeigt sich meist daran, dass ein Lidar verschmutzt bleibt, während die übrigen sauber werden.","u":[["h","Pumpe bzw. Ventil D für die vierte Lidar-Düse defekt"],["m","Schlauch zu Lidar D geknickt oder abgezogen, Aktor läuft trocken oder überlastet"],["l","Leitung zu Aktor D unterbrochen oder kurzgeschlossen"]],"s":["Ein Lidar bleibt verschmutzt, während die übrigen Sensoren gereinigt werden","Fahrzeug schränkt das automatisierte Fahren ein oder beendet es"],"k":["lidar_washer_actuator_d","actuator_wiring","object_detection_maintenance_module_a"],"r":["medium",1,[50,700],[0.3,2.5]],"f":"L","x":["B0106","B0107","B0108","B010A","U022E"]},{"c":"B010A","t":"Kamera-Wascher-Aktuator A","e":"Camera Washer Actuator A","d":"B010A eröffnet eine Reihe von achtzehn Kamera-Wascheraktoren, benannt von A bis S ohne I. Aktor ist das elektrisch angesteuerte Teil, das einer Kameralinse Flüssigkeit zuführt: eine eigene Pumpe oder ein Ventil an einer gemeinsamen Leitung. Continentals Patent US11673532B2 (angemeldet 2019) zeigt den Aufbau, den die Reihe nahelegt: Front-, Seiten- und Heckkamera mit je eigener Düse und eigenem Ventil, versorgt von einer oder mehreren Pumpen und geschaltet von einem Steuergerät, das bei verdecktem Bild wäscht und die Heckkamera im Rückwärtsgang immer reinigt. Solero bietet dafür elektromagnetische 2/2- und 3/2-Wegeventile an, Valeo komplette Kamerareinigungen samt Steuergerät. Die Kamera hinter Buchstabe A behalten die Hersteller für sich; B010A steht in keinem öffentlichen Herstellerdokument. Die Kamera bleibt nutzbar, nur ungereinigt.","u":[["h","Ventilspule oder Pumpenmotor von Aktor A unterbrochen oder kurzgeschlossen"],["m","Korrodierter oder lockerer Stecker an Aktor A, der im Spritzbereich nahe der Kamera sitzt"],["l","Endstufe im ansteuernden Steuergerät defekt"]],"s":["Die Aktor A zugeordnete Kamera wird weder auf Anforderung noch automatisch gewaschen","Kamerabild bleibt bei Regen, Schlamm oder Streusalz verschmutzt; eventuell Meldung „Kamera verdeckt“"],"k":["camera_washer_actuator_a","washer_pump","actuator_wiring"],"r":["medium",1,[30,400],[0.3,2]],"f":"","x":["B010B","B010C","B0106","B011C"]},{"c":"B010B","t":"Kamera-Wascher-Aktuator B","e":"Camera Washer Actuator B","d":"B010B betrifft Aktor B. Eine verbreitete Lösung für die Rückfahrkamera ist ein Abzweig von der Heckscheiben-Waschleitung mit elektrischem Umschaltventil. Asmos Anmeldung US20120266926A1 (2011) beschreibt ein Magnet-Schieberventil: stromlos versorgt es die Heckscheibendüse, bestromt lenkt es die Flüssigkeit zur Kameradüse um. Die Spule bekommt Strom, sobald der Rückwärtsgang eingelegt ist; der Waschschalter bespritzt dann die Kamera, im Beispiel etwa zwei Sekunden lang. Land Rovers Bulletin JLRTB02100NAS1 zum Range Rover 2022 zeigt die Leitungsseite: Ein gelöster Zwischenstecker der hinteren Waschleitungen legte Heckscheiben- und Kamerawäsche still, und dort vertauschte Schläuche ließen den Heckscheibenschalter stattdessen die Kamera waschen. Ob B eine Heckkamera ist, ist nicht veröffentlicht; kein Hersteller dokumentiert B010B.","u":[["h","Spule des Umschaltventils Heckscheibe/Kamera unterbrochen oder kurzgeschlossen"],["m","Aderbruch im Kabeldurchgang von Heckklappe oder Kofferraumdeckel zum Ventil"],["l","Rückwärtsgang-Signal, das die Kamerawäsche freigibt, kommt nicht im Steuergerät an"]],"s":["Im Rückwärtsgang bespritzt der Waschschalter die Rückfahrkamera nicht mehr","Statt der Kamera wird eventuell die Heckscheibe gewaschen, oder keines von beiden"],"k":["camera_washer_actuator_b","rear_camera","actuator_wiring"],"r":["medium",1,[30,350],[0.3,2]],"f":"","x":["B010A","B010C","B010D"]},{"c":"B010C","t":"Kamera-Wascher-Aktuator C","e":"Camera Washer Actuator C","d":"B010C bezeichnet Aktor C. Frontkameras sitzen im Kühlergrill und haben eine eigene Düse. Fords TSB 20-2267 (2020) gilt für F-150 2015–2020 außer Raptor, Super Duty 2017–2020 und Expedition 2018–2020 mit Frontkamera-Wascher: Die Düse tropfte im Ruhezustand wegen ihrer inneren Gummidichtung; Abhilfe ist eine neue Düse, wofür der Grill herunter muss und die 360-Grad-Kamera danach neu ausgerichtet wird. Asmos Anmeldung US20110292212A1 begründet, warum solche Düsen ein Rückschlagventil tragen: Es öffnet nur unter Pumpendruck, damit weder Flüssigkeit auf die Linse läuft noch Luft in die Leitung kommt. Eine undichte Dichtung erzeugt allein keinen elektrischen Code; B010C deutet auf den Aktor oder seinen Stromkreis. Die Kamera zu C bleibt offen, ebenso eine Herstellernutzung des Codes.","u":[["h","Beschädigte Leitung oder Stecker im Frontbereich, ausgesetzt Steinschlag, Wasser und Salz"],["m","Pumpe oder Ventil C festgegangen oder elektrisch defekt"],["l","Stecker nach Arbeiten an Grill oder Stoßfänger nicht wieder aufgesteckt"]],"s":["Frontkameralinse wird bei Waschanforderung nicht bespritzt","Bild der Front- bzw. 360-Grad-Kamera bleibt im Winter oder nach Geländefahrt verschmutzt"],"k":["camera_washer_actuator_c","washer_pump","actuator_wiring"],"r":["medium",1,[30,400],[0.5,2]],"f":"","x":["B010B","B010D","B010A"]},{"c":"B010D","t":"Kamera-Wascher-Aktuator D","e":"Camera Washer Actuator D","d":"B010D betrifft Aktor D. Audis TSB 2059228/2 (2022) zum e-tron 2019–2022 und e-tron Sportback 2020–2022 zeigt, was ein fehlendes Rückschlagventil bei der Heckkamerawäsche bewirkt: Die Leitung läuft während der Fahrt oder beim Öffnen der Heckklappe leer, das System bricht nach vier Betätigungen ab, um Flüssigkeit zu sparen, und vier Versuche reichen nicht, um sie wieder zu füllen und unter Druck zu setzen. Die Linse bleibt dann schmutzig, bis Klemme 15 aus- und wieder eingeschaltet wird. Abhilfe ist ein eingesetztes Ventil, Teil 4N0 955 481 A. ARaymond baut ein solches Rückschlagventil direkt in eine flache Heckkameradüse im Heckklappengriff ein. Dabei kommt kein Strahl, aber auch kein Fehlercode; B010D selbst deutet auf einen elektrischen Fehler an Aktor D, dessen Kamerazuordnung kein Hersteller veröffentlicht.","u":[["h","Pumpe oder Ventil D unterbrochen, kurzgeschlossen oder mit auffälliger Stromaufnahme"],["m","Aderbruch an der Biegestelle des Kabelbaums zur Heckklappe"],["l","Pumpe durch wiederholten Trockenlauf an leerer Leitung beschädigt"]],"s":["Waschanforderung für die Kamera muss mehrfach wiederholt werden, bis Flüssigkeit kommt, oder es kommt nichts","Rückfahrkamera bleibt nach Nutzung der Waschfunktion verschmiert"],"k":["camera_washer_actuator_d","washer_pump","actuator_wiring"],"r":["medium",1,[20,300],[0.3,1.5]],"f":"","x":["B010C","B010E","B0119"]},{"c":"B010E","t":"Kamera-Wascher-Aktuator E","e":"Camera Washer Actuator E","d":"B010E bezeichnet Aktor E, der auch eine eigene Pumpe statt eines Ventils sein kann. Audis TSB 2073568/1 (2024) zu e-tron, e-tron S und Q8/SQ8 e-tron meldet zu wenig Druck an der Heckkameradüse, um die Linse zu reinigen: Die Einfachpumpe brachte nicht genug Druck, in der Fertigung kam eine Doppelpumpe (1K6 955 651), deren freier Ausgang verschlossen wird. Vor dem Tausch schließt die Werkstatt zu wenig Flüssigkeit, ein verstopftes Pumpensieb, zu niedrige Bordspannung und geknickte Leitungen aus. AUMOVIO führt seine Waschpumpen mit einem oder zwei Ausgängen für 2,0 bis 4,0 bar. Eine Pumpe ohne oder mit zu hoher Stromaufnahme ist die Art Fehler, die ein Steuergerät erkennen kann; ob ein Hersteller diese Pumpe E nennt, bleibt offen; B010E belegt keiner öffentlich.","u":[["h","Motor der Kamerawaschpumpe E verschlissen, festgegangen oder unterbrochen"],["m","Zu niedrige Versorgungsspannung oder schlechte Masse an der Pumpe"],["l","Verstopftes Ansaugsieb lässt die Pumpe schwer laufen und viel Strom ziehen"]],"s":["Kameradüse tröpfelt nur; der Strahl reicht nicht über die Linse","Pumpe brummt ohne Strahl, oder bei Waschanforderung ist gar kein Pumpengeräusch zu hören"],"k":["camera_washer_actuator_e","washer_pump","actuator_wiring"],"r":["medium",1,[40,250],[0.5,1.5]],"f":"","x":["B010D","B010F","B011C"]},{"c":"B010F","t":"Kamera-Wascher-Aktuator F","e":"Camera Washer Actuator F","d":"B010F betrifft Aktor F. Bei Chevrolet Tahoe und Suburban sowie GMC Yukon 2021 mit Kamera-Innenspiegel (RPO DRZ) fand GMs Service-Update N202311260 in rund 630 Fahrzeugen einen geknickten Waschschlauch der Heckkamera hinter der Heckklappenblende; die Werkstatt prüft die Wäsche, kürzt den Schlauch auf höchstens 127 mm und schiebt 85 mm Schlitzwellrohr darüber. Ein Knick lässt die Düse trocken, ohne einen elektrischen Fehler zu erzeugen, und erklärt B010F daher nicht; der Code deutet auf den Stromkreis des Aktors. Die Kamera selbst fällt unter FMVSS 111, der ein Rückfahrbild binnen 2,0 s nach Einlegen des Rückwärtsgangs verlangt und äußere Kamerateile auf Korrosion und Feuchte prüft, für einen Wascher aber nichts vorschreibt. Welche Kamera F meint, ist nicht veröffentlicht; kein Hersteller dokumentiert B010F.","u":[["h","Unterbrochener oder kurzgeschlossener Stromkreis zu Ventil oder Pumpe F"],["m","Leitung beim Ausbau der Heckklappenverkleidung gequetscht oder abgezogen"],["l","Aktor F selbst defekt"]],"s":["Kameraspiegel bzw. Rückfahrbild bleibt verschmutzt, weil die Heckkamerawäsche nicht arbeitet","Das Rückfahrbild selbst erscheint beim Rückwärtsfahren weiterhin"],"k":["camera_washer_actuator_f","rear_camera","actuator_wiring"],"r":["medium",1,[20,300],[0.3,1.5]],"f":"","x":["B010E","B0110","B010B"]},{"c":"B0110","t":"Kamera-Wascher-Aktuator G","e":"Camera Washer Actuator G","d":"B0110 bezeichnet Aktor G. Nicht jede gewaschene Kamera arbeitet mit sichtbarem Licht. Bentleys Produktinformation 2051045 (2023) betrifft die Infrarot-Nachtsichtkamera im vorderen Stoßfänger von Bentayga, Continental GT/GTC und Flying Spur: Tropft Flüssigkeit aus ihrer Waschdüse, hilft ein neues Rückschlagventil, und die Kamera muss nur neu kalibriert werden, wenn sie selbst getauscht wird. Eine frühere Mitteilung (2021) ersetzte stattdessen den kurzen Verbindungsschlauch zwischen Düse und Zuleitungsanschluss. Auch Valeo nennt in seinem Reinigungsangebot Infrarotkameras neben sichtbaren Kameras und Lidar. Ob G für eine Nachtsichtkamera steht, ist nicht veröffentlicht, und kein Hersteller dokumentiert B0110. Ist er gesetzt, kann das Nachtsichtbild bei Regen oder Schneematsch verschwimmen.","u":[["h","Ventil oder Pumpe G der Kameradüse elektrisch unterbrochen oder kurzgeschlossen"],["m","Kabelbaumschaden im unteren Stoßfängerbereich nach Parkrempler oder Reparatur"],["l","Ausgang des ansteuernden Steuergeräts defekt"]],"s":["Bild der Nachtsicht- oder Frontkamera bleibt verschmiert; die Kameradüse spritzt nicht","Assistenzfunktionen, die diese Kamera nutzen, melden eventuell eingeschränkte Verfügbarkeit"],"k":["camera_washer_actuator_g","night_vision","actuator_wiring"],"r":["medium",0,[50,500],[0.5,2.5]],"f":"","x":["B010F","B0111","B010C"]},{"c":"B0111","t":"Kamera-Wascher-Aktuator H","e":"Camera Washer Actuator H","d":"B0111 ist in J2012 der Code für Kamera-Wascheraktor H, die Nummer hat aber ein älteres Zweitleben. Toyotas Bulletin T-SB-0069-12 (Revision 2, 2014) zum Sienna 2004–2009 führt B0111 zusammen mit B0116 als unterbrochenen Zündkreis des Seitenairbags bei leuchtender SRS-Lampe; repariert wird der Bodenkabelbaum. Bei diesem Van hat der Code nichts mit Waschen zu tun, und ein Diagnosegerät mit dem generischen Titel führt in die Irre. Im generischen Sinn ist Aktor H eine der Pumpen oder eines der Ventile, die Zulieferer wie Kautex für die ADAS-Reinigung anbieten, neben beheizten Düsen, beheizten Schläuchen, Verbindern und Füllstandsensoren. Kein Hersteller veröffentlicht, welche Kamera H meint, oder dokumentiert B0111 als Wascher-Code.","u":[["h","Pumpe oder Ventil H unterbrochen, kurzgeschlossen oder festgegangen"],["l","Wassereintritt oder Korrosion im Stecker von Aktor H"]],"s":["Die von Aktor H versorgte Kamera wird nicht gewaschen","Beim Auslösen der Wäsche tritt an der Düse von Aktor H keine Flüssigkeit aus"],"k":["camera_washer_actuator_h","washer_pump","actuator_wiring"],"r":["medium",1,[30,400],[0.3,2]],"f":"","x":["B0110","B0112","B0116"]},{"c":"B0112","t":"Kamera-Wascher-Aktuator J","e":"Camera Washer Actuator J","d":"B0112 betrifft Aktor J; der Buchstabe I fehlt in dieser Reihe, J ist also der neunte. Große Systeme waschen viele Kameras aus einem Leitungsnetz. Das Stellantis-TSB 23-028-23 (2023) zu Grand Wagoneer und Wagoneer 2022, gebaut bis 28. Februar 2022, nennt Rückfahrkamera-Wascher, Rundumsichtkameras, Nachtsicht und digitalen Innenspiegel als betroffene Ausstattung. Spritzen Kameras vorn oder hinten nicht mehr oder tritt Flüssigkeit hinter der Frontverkleidung, am Dachhimmel oder an der Heckklappe aus, hatten sich Schnellkupplungen gelöst; geprüft wird durch Drücken, Ziehen, Drücken. Eine Neuauflage von 2024 wiederholt das Verfahren. ARaymond liefert solche Schnellkupplungen für Reinigungskreise. Eine lose Kupplung ist kein elektrischer Fehler; B0112 deutet auf Aktor J oder seine Leitung. Welche Kamera J versorgt, ist nicht veröffentlicht.","u":[["h","Ventil oder Pumpe J elektrisch unterbrochen oder kurzgeschlossen"],["m","Waschflüssigkeit aus einer losen Kupplung läuft in den Aktorstecker und lässt ihn korrodieren"],["l","Durchgescheuerte Ader auf dem Weg zu Aktor J"]],"s":["Eine Kamera eines Mehrkamerasystems wird nicht bespritzt, die anderen schon","Feuchte Verkleidung oder Pfützen von Waschflüssigkeit im Innenraum, falls sich auch eine Kupplung gelöst hat"],"k":["camera_washer_actuator_j","washer_pump","actuator_wiring"],"r":["medium",1,[30,400],[0.3,2.5]],"f":"","x":["B0111","B0113","B0115"]},{"c":"B0113","t":"Kamera-Wascher-Aktuator K","e":"Camera Washer Actuator K","d":"B0113 bezeichnet Aktor K. Selbst ein funktionierender Aktor nützt nichts, wenn der Strahl die Linse verfehlt. Das Stellantis-TSB 23-049-22 Rev. A zum Jeep Grand Cherokee (WL) 2022–2023, gebaut zwischen 13. April und 15. September 2022, fand die Heckklappendüse der Kamera des digitalen Innenspiegels falsch ausgerichtet; sie wird ausgeclipst, um 180 Grad gedreht und wieder eingesetzt, danach wird der Spiegel durch etwa 15 s Halten seiner Plus- und Minustaste zurückgesetzt. Bowles' Anmeldung US20140060582A1 erklärt die Geometrie: Die Düse sitzt rund 10 bis 30 mm seitlich der Linse, zielt in etwa 1 bis 20 Grad zu deren Oberfläche und bleibt außerhalb des Bildfelds. Ein schief zielender Strahl setzt keinen Code; B0113 betrifft den Stromkreis des Aktors einer nicht veröffentlichten Kamera.","u":[["h","Unterbrechung oder Kurzschluss im Stromkreis von Ventil oder Pumpe K"],["m","Ermüdete Leitung im Bereich der Heckklappenscharniere"],["l","Stecker nach Aus- und Einbau von Kamera oder Düse nicht wieder aufgesteckt"]],"s":["Kamerawäsche läuft für die von Aktor K versorgte Kamera nicht","Digitaler Spiegel oder Rückfahrbild bleibt nach Waschanforderung verschmutzt"],"k":["camera_washer_actuator_k","rear_camera","actuator_wiring"],"r":["medium",1,[20,350],[0.3,1.5]],"f":"","x":["B0112","B0114","B010B"]},{"c":"B0114","t":"Kamera-Wascher-Aktuator L","e":"Camera Washer Actuator L","d":"B0114 betrifft Aktor L. Der Stellantis-STAR-Fall S2123000051 (2021, Jeep Grand Cherokee) beschreibt eine Frontkamera-Waschpumpe, die bei niedrigem Behälterstand nicht mehr spritzte, obwohl das Kombiinstrument keinen Flüssigkeitsmangel meldete; neue Pumpe, neuer Behälter oder Füllstandsensor halfen nicht, die Entwicklung untersuchte noch. Fords deutsche Anmeldung DE102018109892A1 zeigt einen ganz anderen Aktor: Ein Magnet drückt eine flexible Kammer neben der Kamera zusammen, mit Einwegventilen an Ein- und Auslass, ausgelöst bei Zündung an, im Rückwärtsgang oder über den Wischerhebel, dazu ein optionaler Schwimmer für den Mindeststand. Füllstandscodes bilden ab B011C eine eigene Reihe. Welche Kamera L versorgt, ist nicht veröffentlicht; kein Hersteller dokumentiert B0114.","u":[["h","Pumpe bzw. Aktor L nach Betrieb mit fast leerem Behälter beschädigt"],["m","Unterbrochene oder kurzgeschlossene Leitung zu Aktor L"],["l","Füllstandsensor warnt nicht rechtzeitig, der Aktor läuft ohne Flüssigkeit"]],"s":["Kamerawäsche fällt bei niedrigem Behälterstand aus, ohne Warnung vor Flüssigkeitsmangel","Frontkamerabild bleibt nach Waschanforderung verschmutzt"],"k":["camera_washer_actuator_l","washer_pump","actuator_wiring"],"r":["medium",1,[10,300],[0.2,1.5]],"f":"","x":["B0113","B0115","B011C"]},{"c":"B0115","t":"Kamera-Wascher-Aktuator M","e":"Camera Washer Actuator M","d":"B0115 bezeichnet Aktor M. Teilen sich mehrere Kameras eine Pumpe, ist der Aktor oft ein Verteilventil. Soleros SCV43 ist ein spannungsgesteuertes 4/3-Wegeventil mit einem Eingang und drei unabhängig geschalteten Ausgängen; so versorgt eine Pumpe bis zu drei Düsen, und im Behälter werden weniger Gleichstrompumpen gebraucht. Die Allegro-Systeme von Kautex reinigen mehrere Kamerapunkte und Lidar mit Wasser und Luft, ihre Software legt fest, welcher Punkt zuerst bedient wird. Bei einem gemeinsamen Ventilblock kann eine ausgefallene Spule die Wäsche an einer Kamera stoppen, während die anderen weiter spritzen – genau so würde sich ein Einzelbuchstaben-Code wie B0115 zeigen. Kein Hersteller veröffentlicht B0115 oder die Kamera hinter M.","u":[["h","Spule für Ausgang M in einem gemeinsamen Ventilblock unterbrochen oder kurzgeschlossen"],["m","Ventil M durch Ablagerungen oder gefrorene Flüssigkeit blockiert, mit auffälliger Stromaufnahme"],["l","Leitungs- oder Steckerfehler auf dem Weg zu Ventil M"]],"s":["Eine Kamera bleibt ungewaschen, während andere Kameras an derselben Pumpe bespritzt werden","Bei schlechtem Wetter Meldung „Kamera verdeckt“ für diese Kamera"],"k":["camera_washer_actuator_m","washer_pump","actuator_wiring"],"r":["medium",1,[40,450],[0.5,2]],"f":"","x":["B0114","B0116","B0112"]},{"c":"B0116","t":"Kamera-Wascher-Aktuator N","e":"Camera Washer Actuator N","d":"B0116 betrifft Aktor N. Wie B0111 taucht er auch beim Toyota Sienna 2004–2009 auf, wo Bulletin T-SB-0069-12 ihn für einen unterbrochenen Zündkreis des Seitenairbags nutzt, nicht für einen Wascher. Im generischen Sinn ist Kälte eine typische Belastung für Kamerawascher. Densos Patent US9180840B2 mischt Luft aus einer Pumpe mit Flüssigkeit, die ein elektromagnetisches Ventil zulässt, und passt sich dem Wetter an: Bei oder unter einer Schwelle wie 2 °C senkt es die Pumpenspannung, damit größere Tropfen entstehen, die auf der Linse weniger leicht gefrieren, und verlängert Sprüh- und Blaszeiten. Kautex bietet gegen dasselbe Problem beheizte Düsen und beheizte Schläuche an. Gefrorene Flüssigkeit kann Pumpe oder Ventil blockieren und eine auffällige Stromaufnahme bewirken. Welche Kamera N versorgt, ist nicht veröffentlicht.","u":[["h","Waschflüssigkeit mit zu wenig Frostschutz in Pumpe oder Ventil N gefroren"],["m","Aktor N elektrisch unterbrochen oder kurzgeschlossen"]],"s":["Kamerawäsche fällt vor allem bei Frost aus und funktioniert nach dem Aufwärmen wieder","Eis- oder Salzfilm bleibt auf der Linse der von Aktor N versorgten Kamera"],"k":["camera_washer_actuator_n","washer_pump","actuator_wiring"],"r":["medium",1,[10,400],[0.2,2]],"f":"","x":["B0115","B0117","B0111"]},{"c":"B0117","t":"Kamera-Wascher-Aktuator O","e":"Camera Washer Actuator O","d":"B0117 bezeichnet Aktor O; anders als I wird O in dieser Reihe verwendet. Nicht jeder stumme Wascher ist defekt. Continentals Patent US11673532B2 (erteilt 2023, heute bei Aumovio) lässt das Steuergerät die Kameraventile absichtlich zurückhalten: Im Geländemodus werden nur ausgewählte Kameras gewaschen, und bei zugeschaltetem Allrad unter etwa 20 km/h bleiben alle Ventile zu, damit Schlamm nicht die Flüssigkeit aufbraucht; ein Zeitmodus wäscht höchstens einmal je Intervall, in den Beispielen zwei oder fünf Minuten. AUMOVIO entfernt Staub zudem nur mit Luft, um Flüssigkeit zu sparen. Ein absichtlich gesperrter Aktor sollte keinen Code setzen; B0117 deutet auf einen Fehler an Aktor O selbst. Welche Kamera O meint, ist nicht veröffentlicht, und kein Hersteller dokumentiert B0117.","u":[["h","Ventil oder Pumpe O unterbrochen, kurzgeschlossen oder festgegangen"],["m","Leitung zu einem tief sitzenden Kamera-Aktor durch Schlamm, Wasser oder Geländeeinsatz beschädigt"],["l","Software- oder Konfigurationsfehler in der Ansteuerung von Aktor O; Update nach Herstellervorgabe"]],"s":["Kamera bleibt auch im normalen Straßenmodus ungewaschen, nicht nur bei gewollter Waschpause","Meldung „Kamera verdeckt“ bei Schlamm oder Regen"],"k":["camera_washer_actuator_o","washer_pump","actuator_wiring"],"r":["medium",1,[30,400],[0.3,2]],"f":"","x":["B0116","B0118","B010A"]},{"c":"B0118","t":"Kamera-Wascher-Aktuator P","e":"Camera Washer Actuator P","d":"B0118 betrifft Aktor P. Ausstattung kann mitten im Modelljahr entfallen. Fords SSM 51564 hält fest, dass Explorer und Police Interceptor Utility 2022–2023 sowie Lincoln Aviator 2023 ab Baudatum Mitte Juli bzw. August 2022 keine Waschfunktion der hinteren Einparkkamera mehr haben; die Düse kann ohne Schlauch noch vorhanden sein, das ist normal und keine Reparatur nötig. Wäre ein Steuergerät auf einen Aktor codiert, den das Auto nicht mehr hat, könnte ein solcher Code wegen fehlender Last folgen. Asmos US20110292212A1 zeigt die Varianten, zwischen denen Konstrukteure wählen: ein T-Stück an der Heckscheibenleitung, eine eigene Pumpe je Düse oder ein Umschaltventil. Kein Hersteller dokumentiert B0118 oder die Kamera hinter P.","u":[["h","Steuergerät auf einen Kamerawasch-Aktor codiert, mit dem das Fahrzeug nicht gebaut ist"],["m","Aktor P oder seine Zuleitung unterbrochen"],["l","Ersatzsteuergerät mit falschen Variantendaten verbaut"]],"s":["Fehler gespeichert, obwohl die Kamera keine funktionierende Wäsche oder nur eine Düse ohne Schlauch hat","Kamerabild und Einparkhilfe funktionieren ansonsten normal"],"k":["camera_washer_actuator_p","washer_pump","actuator_wiring"],"r":["medium",0,[0,300],[0.2,1.5]],"f":"","x":["B0117","B0119","B010B"]},{"c":"B0119","t":"Kamera-Wascher-Aktuator Q","e":"Camera Washer Actuator Q","d":"B0119 bezeichnet Aktor Q. Land Rovers SSM76076 (2023) zum Defender (L663) ab Modelljahr 2020 führt tropfende Scheinwerfer-Waschdüsen und eine tropfende Heckkamera-Waschdüse auf ein Einwegventil in der Zuleitung zurück, das nicht mehr dichtet; das Werkstattgerät führt durch einen Lecktest und verlangt gegebenenfalls einen neuen Heckkamera-Waschschlauch samt Ventil. Scheinwerfer- und Kamerawäsche teilen sich also oft Flüssigkeit und Bauteile. Die Reinigungsbroschüre von ARaymond nennt Rückschlagventile, Schnellkupplungen und beheizte Düsen als Bausteine solcher Kreise. Ein undichtes Ventil ist ein hydraulischer, kein elektrischer Fehler; B0119 selbst deutet auf Aktor Q oder seine Leitung. Welche Kamera Q versorgt, ist nicht veröffentlicht, und kein Hersteller dokumentiert den Code.","u":[["h","Pumpe oder Ventil Q elektrisch unterbrochen oder kurzgeschlossen"],["m","Aus undichter Düse oder Ventil tropfende Flüssigkeit lässt den nahen Aktorstecker korrodieren"],["l","Durchgescheuerte Ader zwischen Steuergerät und Aktor Q"]],"s":["Kamerawäsche der von Aktor Q versorgten Kamera reagiert nicht","Waschflüssigkeit nimmt schneller ab als üblich, wenn zusätzlich ein Ventil undicht ist"],"k":["camera_washer_actuator_q","rear_camera","actuator_wiring"],"r":["medium",1,[30,350],[0.3,2]],"f":"","x":["B0118","B011A","B010D"]},{"c":"B011A","t":"Kamera-Wascher-Aktuator R","e":"Camera Washer Actuator R","d":"B011A betrifft Aktor R. Manche Kamerareiniger arbeiten mit Luft und Flüssigkeit, der Aktor kann also ebenso ein Gebläse wie eine Pumpe sein. Thunder Powers Patent US9539988B2 setzt eine Wasser- und eine Luftdüse an eine Rückfahrkamera: Zuerst kommt ein Luftstoß, dann unbeheizte Flüssigkeit und unter etwa 0 °C beheizte, während ein Infrarot-Tropfensensor hinter der Linse entscheidet, wann gereinigt wird. Densos US9180840B2 öffnet sein Flüssigkeitsventil erst nach dem Start der Luft und hält es 0,1 bis 0,5 s offen; in den Versuchen mussten mindestens etwa 70 % des salzigen Schlamms weichen, damit das Bild brauchbar war. Luftgebläse für Sensoren haben ab B0100 eigene Codes. Welche Kamera R versorgt, ist nicht veröffentlicht; kein Hersteller dokumentiert B011A.","u":[["h","Pumpe, Ventil oder Luftgebläse R elektrisch unterbrochen oder kurzgeschlossen"],["m","Heizelement im Kamerawaschkreis defekt, beeinträchtigt den Betrieb bei Kälte"],["l","Korrodierter Stecker an Aktor R"]],"s":["Die von Aktor R versorgte Kamera wird weder freigeblasen noch sauber gespritzt","Tropfen oder Schlamm bleiben auf der Linse; Assistenzfunktionen warnen eventuell vor verdeckter Kamera"],"k":["camera_washer_actuator_r","washer_pump","actuator_wiring"],"r":["medium",1,[40,450],[0.5,2]],"f":"","x":["B0119","B011B","B0100"]},{"c":"B011B","t":"Kamera-Wascher-Aktuator S","e":"Camera Washer Actuator S","d":"B011B schließt die Reihe mit Aktor S ab. Elektrisch ist jeder Aktor der Reihe eine Spule oder ein Motor, geschaltet von einem Steuergerät oder Relais. HELLAs Relais-Broschüre erklärt die Schaltseite: Eine Steuerspule an den Klemmen 85 und 86 zieht den Anker an und legt den Kontakt von 87a auf 87 um; manche Typen haben einen Widerstand oder eine Diode parallel zur Spule, um die Spannungsspitze beim Abschalten zu dämpfen. Asmos US20120266926A1 bestromt sein Kamera-Waschventil über ein Relais, das am Rückfahrleuchten-Kreis hängt; ein Fehler dort kann also ebenfalls die Wäsche lahmlegen. Eine unterbrochene Spule, ein klemmendes Relais oder eine gebrochene Zuleitung an diesem letzten Aktor ist, worauf B011B zielt. Keine öffentliche Quelle ordnet S einer bestimmten Kamera zu oder meldet B011B aus einem echten Fahrzeug.","u":[["h","Spule oder Motor von Aktor S unterbrochen oder kurzgeschlossen"],["m","Relais für Aktor S klemmt oder hat einen verbrannten Kontakt"],["l","Durchgebrannte Sicherung oder gebrochene Versorgungsleitung zu Relais oder Aktor"]],"s":["Kamerawäsche für die von Aktor S versorgte Kamera bewirkt nichts","Bei verschweißtem Relaiskontakt läuft die Wäsche eventuell dauerhaft oder hört nicht auf"],"k":["camera_washer_actuator_s","actuator_wiring","relay_control_circuit"],"r":["medium",1,[10,300],[0.2,1.5]],"f":"","x":["B011A","B0119","B010A"]},{"c":"B011C","t":"Flüssigkeitsbehälter Füllstandssensor A","e":"Fluid Reservoir Level Sensor A","d":"B011C ist der erste von sechs Füllstandssensoren für Flüssigkeitsbehälter, A bis F. Welcher Behälter zu welchem Buchstaben gehört, legt J2012 nicht fest; die Nachbarcodes betreffen das Waschen von Scheiben, Kameras und anderen Sensoren, naheliegend sind also Waschwasserbehälter. Klassisch arbeitet ein Schwimmer mit Magnet neben einem Reedkontakt: Sinkt der Pegel, sinkt der Schwimmer, und der Kontakt schaltet um. Die Anmeldung US20040200278A1 zeigt einen solchen Geber, der durch eine Gummitülle in der Seitenwand steckt. FCA nennt im Teile-Hinweis 9003109 einen typischen Fehler: Ein aus seiner Verdrehsicherung gedrehter Schwimmer meldet trotz voller Flasche Wassermangel. Öffentlich dokumentiert kein Hersteller B011C; die Folge ist eine falsche oder fehlende Warnung.","u":[["h","Schwimmer klemmt, aus seiner Führung gedreht oder vollgesogen"],["m","Reedkontakt im Geber gebrochen oder verklebt"],["m","Undichte Tülle, Flüssigkeit am Stecker, korrodierte Kontakte"]],"s":["Warnung Waschwasser niedrig bleibt trotz vollem Behälter an","Keine Warnung, obwohl der Behälter leer läuft"],"k":["fluid_reservoir_level_sensor_a","sensor_wiring"],"r":["medium",1,[20,150],[0.3,1.5]],"f":"","x":["B011D","B011E","B011F","B0120","B0121"]},{"c":"B011D","t":"Flüssigkeitsbehälter Füllstandssensor B","e":"Fluid Reservoir Level Sensor B","d":"B011D betrifft Füllstandssensor B. Nicht jeder Waschbehälter misst mit Schwimmer. Volkswagen beschreibt im Bulletin 2037322 (2015) den Füllstandsgeber G33 als Bauteil, dessen Messung von der Flüssigkeit selbst abhängt: Falsches Mischungsverhältnis oder Zusätze lagern sich ab, senken die Empfindlichkeit und lassen die Leuchte bei vollem Behälter brennen. Abhilfe ist Ablassen, Reinigen des Gebers und Befüllen mit freigegebenem Mittel. In den Behälter eingespritzte Geber lassen sich nicht einzeln tauschen. Berührungslos arbeitet dagegen der kapazitive Einpunktmelder aus Patent US5017909A, außen an der Behälterwand auf Höhe des Mindeststands befestigt; die Flüssigkeit verändert dort die Kapazität. Welches Prinzip hinter B steckt, ist nicht veröffentlicht; B011D dokumentiert kein Hersteller.","u":[["h","Ablagerungen aus ungeeignetem Waschmittel oder Zusätzen auf der Messfläche"],["m","Geberelektronik oder Elektroden defekt"],["l","Unterbrechung oder Kurzschluss in der Geberleitung"]],"s":["Warnleuchte bei vollem Behälter an, oft nach Wechsel des Waschmittels","Füllstandswarnung kommt spät oder gar nicht"],"k":["fluid_reservoir_level_sensor_b","sensor_wiring"],"r":["medium",1,[10,200],[0.3,1.5]],"f":"","x":["B011C","B011E","B011F","B0120","B0121"]},{"c":"B011E","t":"Flüssigkeitsbehälter Füllstandssensor C","e":"Fluid Reservoir Level Sensor C","d":"B011E betrifft Füllstandssensor C. Fahrzeuge, die sich auf Kamera und Lidar stützen, brauchen einen eigenen Reinigungsvorrat, und dort wird der Füllstand zur Betriebsbedingung. Ubers Anmeldung US20180015907A1 zeigt einen Behälter für die Sensorreinigung mit eigenem Füllstandsgeber, der an den Fahrzeugrechner meldet; unter einer Schwelle schaltet der Rechner eine Anzeige ein oder bittet einen Fernbetreuer ums Nachfüllen. Das verwandte Patent US10220817B2 ergänzt Kompressor und Magnetventile und behandelt Druck- und Füllwerte außerhalb ihrer Grenzen auf dieselbe Weise. Ob Behälter C ein solcher Reinigungstank ist, steht nirgends; B011E taucht in keinem öffentlichen Herstellerdokument auf. Bei einem Fehler weiß das System nicht mehr sicher, ob es seine Sensoren noch reinigen kann.","u":[["h","Füllstandsgeber C defekt oder Signal unplausibel"],["m","Beschädigte Leitung oder Stecker zwischen Geber und Rechner"],["l","Schmutz oder Eis im Behälter stört die Messung"]],"s":["Aufforderung zum Nachfüllen oder Warnung der Reinigungsanlage ohne erkennbaren Grund","Sensorreinigung bleibt eventuell aus, Assistenzfunktionen schränken sich bei verschmutzten Sensoren ein"],"k":["fluid_reservoir_level_sensor_c","sensor_wiring"],"r":["medium",1,[30,300],[0.3,2]],"f":"","x":["B011C","B011D","B011F","B0120","B0121","B012F"]},{"c":"B011F","t":"Flüssigkeitsbehälter Füllstandssensor D","e":"Fluid Reservoir Level Sensor D","d":"B011F meldet Füllstandssensor D. Eine bekannte Schwäche von Schwimmerschaltern in Waschflaschen ist Bewegung: Schwappende Flüssigkeit in Kurven oder beim Bremsen hebt und senkt den Schwimmer und kann ihn ins Drehen bringen. Continentals Patent US9003878B2 setzt dagegen einen Schwimmer in einem schräg stehenden Träger, Rippen gegen Verdrehen und einen wahlweisen Schwallschutz; dieselbe Bauform passt so für Seiten- und Bodeneinbau. Die zweite Schwachstelle ist die Leitung: FCA rät im Teile-Hinweis 68225064A, bei falscher Meldung zuerst die Kreise W1 und W11 an einem 48-poligen Stecker zu prüfen, bevor der Schwimmergeber getauscht wird. Was Buchstabe D bezeichnet, lassen die Hersteller offen; öffentlich dokumentiert niemand B011F. Zu erwarten sind flackernde oder falsche Füllstandsmeldungen.","u":[["h","Lockere oder korrodierte Kontakte an einem Zwischenstecker des Kabelbaums"],["m","Schwimmer folgt dem Schwappen, Führung oder Schwallschutz gebrochen"],["l","Füllstandsgeber D selbst defekt"]],"s":["Füllstandswarnung geht während der Fahrt an und aus, vor allem in Kurven","Falsche Meldung „Füllstand niedrig“ bei vollem Behälter"],"k":["fluid_reservoir_level_sensor_d","sensor_wiring"],"r":["medium",1,[20,200],[0.3,2]],"f":"","x":["B011C","B011D","B011E","B0120","B0121"]},{"c":"B0120","t":"Flüssigkeitsbehälter Füllstandssensor E","e":"Fluid Reservoir Level Sensor E","d":"B0120 betrifft Füllstandssensor E. Fords Anmeldung US20190265715A1 beschreibt einen Behälter für die Sensorreinigung, dessen Geber in fester Höhe die Leitfähigkeit misst: Luft ergibt einen Widerstand über etwa 1000 Ohm, die schwach leitende Flüssigkeit einen darunter. Weil die Flüssigkeit mit dem Fahrzeug schwappt, filtert der Rechner das Signal anhand von Beschleunigung und Gierrate, schätzt danach die Restmenge über die Pumpenlaufzeit und vermutet ein Leck, wenn der Pegel ohne Waschanforderung fällt; dann kann er das Fahrzeug zur Werkstatt lenken. Fords Patent US10569746B2 setzt einen solchen Behälter aufs Dach neben das Lidar. Buchstabe E ist öffentlich keinem Behälter zugeordnet, B0120 dokumentiert kein Hersteller. Ohne Signal lässt sich die Restmenge nur schätzen.","u":[["h","Elektroden verschmutzt oder Flüssigkeit mit ungeeigneter Leitfähigkeit (z. B. reines destilliertes Wasser)"],["m","Unterbrechung oder Kurzschluss im Geberkreis"],["l","Undichter Behälter oder Schlauch lässt den Pegel unerwartet fallen"]],"s":["Nachfüllwarnung zu früh, zu spät oder dauerhaft","Reinigung der Außensensoren wird eventuell eingeschränkt"],"k":["fluid_reservoir_level_sensor_e","sensor_wiring"],"r":["medium",1,[20,250],[0.3,2]],"f":"","x":["B011C","B011D","B011E","B011F","B0121"]},{"c":"B0121","t":"Flüssigkeitsbehälter Füllstandssensor F","e":"Fluid Reservoir Level Sensor F","d":"B0121 schließt die Reihe mit Füllstandssensor F. Kleine Einzelbehälter sind ein Grund, warum ein Fahrzeug sechs Füllstandsgeber haben könnte: Fords Anmeldung DE102018109892A1 beschreibt eine Kamerawäsche mit eigenem Behälter nahe der Linse und einem Schwimmer-Füllstandsgeber, der meldet, wenn die Flüssigkeit eine festgelegte Untergrenze erreicht hat und nachgefüllt werden muss. Wie das Ergebnis beim Fahrer ankommt, ist eine eigene Frage; Mannesmann VDO verlegte im Patent US6588270B1 die Anzeige des Waschwasserstands sogar neben den Tankstutzen, damit sie beim Tanken auffällt. Welchen Behälter F meint, veröffentlicht kein Hersteller, und B0121 dokumentiert niemand. Das Fahren bleibt unberührt, doch die überwachte Wäsche kann unbemerkt leerlaufen.","u":[["h","Schwimmer von Geber F durch Ablagerungen oder Eis blockiert"],["m","Leitung zum Kleinbehälter durchgescheuert oder Stecker korrodiert"],["l","Füllstandsgeber F defekt"]],"s":["Fehlende oder dauerhafte Nachfüllmeldung für den betroffenen Behälter","Die von diesem Behälter versorgte Wäsche läuft ohne Warnung trocken"],"k":["fluid_reservoir_level_sensor_f","sensor_wiring"],"r":["medium",1,[20,200],[0.3,2]],"f":"","x":["B011C","B011D","B011E","B011F","B0120"]},{"c":"B0122","t":"Fußgänger-Warnlautsprecher A","e":"Pedestrian Alert Speaker A","d":"B0122 meldet Fußgänger-Warnlautsprecher A. Hybrid- und Elektroautos sind bei Schritttempo fast lautlos und müssen deshalb künstlich Geräusch erzeugen. In den USA gilt FMVSS 141 für solche Fahrzeuge bis 4.536 kg zulässiger Gesamtmasse und schreibt Mindestpegel vor: im Stand mit aktivem Antrieb, beim Rückwärtsfahren und bis 30 km/h. GMs Vorab-Information PIC6478 zum Cadillac Lyriq 2023 zeigt einen typischen Frontlautsprecher hinter dem Stoßfänger: Er klingt vom Stand bis etwa 25 mph, lässt sich zur Diagnose über die Sicherung F46UA stilllegen, und sein Halter kann am Stoßfängerträger schnarren. Welcher Lautsprecher A ist, ist nicht veröffentlicht; B0122 dokumentiert kein Hersteller. Fällt er aus, fehlt das vorgeschriebene Warngeräusch, gefahren werden kann normal.","u":[["h","Lautsprecher A durch Wasser, Salz oder Steinschlag im Frontbereich ausgefallen"],["m","Unterbrechung oder Kurzschluss der Lautsprecherleitung, oft nach Stoßfängerarbeiten"],["l","Endstufe des Klangerzeugers oder dessen Sicherung defekt"]],"s":["Kein künstliches Fahrgeräusch bei langsamer Fahrt von der betroffenen Seite","Je nach Marke Meldung zum Fußgänger-Warnsystem im Kombiinstrument","Fahrzeug erfüllt die gesetzliche Mindestlautstärke nicht mehr; zügig reparieren"],"k":["pedestrian_alert_speaker_a","speaker_wiring","pedestrian_alert_control_module"],"r":["medium",1,[60,400],[0.5,2]],"f":"","x":["B0123"]},{"c":"B0123","t":"Fußgänger-Warnlautsprecher B","e":"Pedestrian Alert Speaker B","d":"B0123 prüft dasselbe für Fußgänger-Warnlautsprecher B und setzt damit einen zweiten Schallgeber voraus. Fords Service-Mitteilung SSM 48451 zu Hybrid- und Plug-in-Modellen 2020 beschreibt Lautsprecher vorn und hinten, die vorwärts wie rückwärts zwischen 0 und 30 km/h tönen. In der EU schreibt die Verordnung 540/2014 seit Juli 2021 für alle neuen Hybrid- und Elektrofahrzeuge ein akustisches Warnsystem (AVAS) vor, das vom Anfahren bis etwa 20 km/h und beim Rückwärtsfahren klingt. Stellantis speichert innere Fehler seines Fußgänger-Warnmoduls als B2779-04, einen eigenen Herstellercode. Welcher Lautsprecher B ist, legt kein Hersteller öffentlich fest. Schweigt B, fehlt in einer Richtung die Warnung, und die gesetzliche Geräuschpflicht ist nicht mehr erfüllt.","u":[["h","Lautsprecher B defekt, etwa durch Feuchtigkeit im Bereich Heckstoßfänger oder Radhaus"],["m","Lockerer oder korrodierter Stecker an Lautsprecher B oder klappernder Innenstecker am Modul"],["l","Fehler im Klangerzeugermodul oder dessen Software"]],"s":["Kunstgeräusch fehlt vorn oder hinten, etwa nur beim Vorwärtsanfahren hörbar","Eventuell Warnmeldung zum Fußgänger-Warnsystem","Gesetzlich vorgeschriebenes Warngeräusch unvollständig; bald reparieren lassen"],"k":["pedestrian_alert_speaker_b","speaker_wiring","pedestrian_alert_control_module"],"r":["medium",1,[60,400],[0.5,2]],"f":"","x":["B0122"]},{"c":"B0124","t":"Nachtsichtkamera","e":"Night Vision Camera","d":"B0124 betrifft die Nachtsichtkamera, meist einen Ferninfrarot-Wärmesensor hinter dem Kühlergrill oder im Stoßfänger; Teledyne FLIR gibt an, über eine Million solcher Fahrzeug-Wärmesensoren geliefert zu haben. Die ausgesetzte Lage verursacht die meisten Fehler. GMs PIC6352A zu Cadillac CT6, XT5 und XT6 führt misslungene Kamera-Anlernvorgänge auf lockere oder korrodierte LVDS-Stecker zwischen Kamera B276 und Steuergerät zurück, oft nachdem Wasser in eine beschädigte Kamera gelangt war. Bentleys 2055858/1 zum Bentayga nennt Steinschläge, durch die Wasser eindringt und das Kamerakabel korrodiert; Stellantis warnt im Fall S2408000119, dass eine gesprungene Linse das Bild verzerrt. B0124 selbst nennt keines dieser Bulletins. Die Nachtsicht fällt aus, das Fahren bleibt normal.","u":[["h","Wassereintritt durch Steinschlag oder Riss im Kamerafenster"],["m","Lockerer oder korrodierter LVDS-Videostecker zwischen Kamera und Steuergerät"],["l","Kamera getauscht, aber nicht angelernt oder kalibriert"]],"s":["Nachtsichtbild fehlt, ist verzerrt oder verpixelt","Meldung wie „Nachtsicht nicht verfügbar, Service erforderlich“"],"k":["night_vision_camera","camera_wiring"],"r":["medium",0,[100,3000],[0.5,3]],"f":"","x":["B0125"]},{"c":"B0125","t":"Nachtsicht-Steuergerät","e":"Night Vision Control Module","d":"B0125 betrifft das Nachtsicht-Steuergerät, das das Kamerabild aufbereitet und an die Anzeige gibt. Stellantis nutzt den Code: Beim Jeep Grand Cherokee 2023 speichert das Kombiinstrument B0125-02 (allgemeiner Signalfehler des Nachtsicht-Steuergeräts), dazu das BCM U02BD (Kommunikation verloren). Fall S2208000163 nennt verschobene oder nicht eingerastete Kontakte im Stecker D3944A des Verarbeitungsmoduls; Fall S2408000119 ergänzt B14FB-31 (kein Videosignal) in diesem Modul und eine gesprungene Kameralinse als Ursache. GMs PIT5785 zu Cadillac XT5 und XT6 zeigt dieselbe Strecke vom Kombiinstrument aus: Ein dort abgezogener schwarzer LVDS-Stecker hinterlässt ein grün verpixeltes Bild. Die Nachtsicht entfällt, das Fahren nicht.","u":[["h","Verschobene, verbogene oder nicht eingerastete Kontakte am Modulstecker"],["m","Videoverbindung (LVDS) zum Kombiinstrument locker oder beschädigt"],["m","Kamera liefert kein brauchbares Bild, etwa bei gesprungener Linse"],["l","Steuergerät intern defekt"]],"s":["Meldung „Nachtsicht nicht verfügbar“ im Kombiinstrument","Kein, eingefrorenes oder verpixeltes Nachtsichtbild"],"k":["night_vision_module","instrument_cluster","wiring_harness"],"r":["medium",0,[80,2500],[0.5,3]],"f":"","x":["B0124"]},{"c":"B0126","t":"Fahrerbeobachtungskamera","e":"Driver Monitoring Camera","d":"B0126 gehört zur Fahrerbeobachtungskamera, einer auf den Fahrer gerichteten Infrarotkamera, die Blick und Kopfhaltung für Freihand- und Aufmerksamkeitsfunktionen verfolgt. GM nutzt den Code: Die Vorab-Information PIC6556 (Fassungen B bis H, 2024–2025) für Super-Cruise-Modelle vom Cadillac Lyriq bis zum Silverado EV nennt B0126 mit Symptom 82 im Bildverarbeitungsmodul, oft zusammen mit B1DD0; vorgesehen sind 30 Minuten Abklemmen, Prüfen des LVDS-Kabels und zuletzt eine neue Kamera. PIT6229 beschreibt softwarebedingte Abschaltungen wegen angeblich zu langen Wegschauens. In der EU verlangt die Delegierte Verordnung 2023/2590 Ablenkungswarnungen ab 20 km/h und eine Fehlerwarnung bei defektem oder verdecktem Sensor. Solange der Fehler aktiv ist, steht das freihändige Fahren nicht zur Verfügung.","u":[["h","Fahrerbeobachtungskamera intern defekt"],["m","LVDS-Kabel zum Bildverarbeitungsmodul beschädigt oder schlecht gesteckt"],["l","Softwarefehler oder Kamerasicht durch Gegenstände bzw. Einbaufehler verdeckt"]],"s":["Freihand-Assistent wie Super Cruise nicht verfügbar oder schaltet ab","Aufmerksamkeits- oder Ablenkungswarnung inaktiv, Fehlermeldung angezeigt"],"k":["driver_monitoring_camera","driver_monitoring_module","camera_wiring"],"r":["medium",0,[100,1500],[0.5,3]],"f":"","x":["B0124","B0125"]},{"c":"B0127","t":"DC/AC-Wandler A Hochvolt-Steckdose „A“ Stromkreis/Unterbrechung","e":"DC/AC Converter A High Voltage Power Outlet \"A\" Circuit/Open","d":"B0127 meldet eine Unterbrechung zur Steckdose A von DC/AC-Wandler A, einer der Netzspannungs-Steckdosen, die der Wandler versorgt. Fords Patent US11043801B2, Grundlage von Pro Power Onboard, gibt jeder Steckdose eine eigene Leitung, einen Ein/Aus-Schalter und einen Fehlerstromschutz; gespeist wird aus einem Wechselrichter, der Traktionsbatterie, Motor-Generator oder beide nutzt. Sensoren vor und hinter jedem Schalter erlauben der Steuerung, den Pfad zu prüfen. GMs Programm N222385490 zeigt, wie unmittelbar die Steckdosen am Wandler hängen: Silverado und Sierra 1500 von 2023 ohne funktionierenden Wechselrichter hatten stromlose Steckdosen in Armaturenbrett und Ladefläche bis zur Nachrüstung. Welche Steckdose A ist, ist nicht veröffentlicht; B0127 dokumentiert kein Hersteller. Steckdose A bleibt tot, das Fahren nicht betroffen.","u":[["h","Leitung oder Kontakt in der Zuleitung zu Steckdose A gebrochen oder herausgedrückt"],["m","Steckdoseneinsatz oder dessen eingebauter Schutz defekt"],["l","Ausgangsschalter oder Relais für Steckdose A im Wandler defekt"]],"s":["Steckdose A liefert keinen Strom, andere Steckdosen arbeiten eventuell weiter","Meldung, dass Bordnetzstrom oder die Steckdose nicht verfügbar ist","Steckdosenkreise führen 120/240 V Wechselspannung aus einer Hochvoltquelle; nur spannungsfrei arbeiten"],"k":["dc_ac_converter_a","hv_outlet_a"],"r":["shop_only",0,[60,800],[0.5,3]],"f":"","x":["B0128","B0129","B012A","B012B","B012C","P2DA8"]},{"c":"B0128","t":"DC/AC-Wandler A Hochvolt-Steckdose „B“ Stromkreis/Unterbrechung","e":"DC/AC Converter A High Voltage Power Outlet \"B\" Circuit/Open","d":"B0128 ist der Unterbrechungsfehler für Steckdose B. Eine Unterbrechung muss von einer ausgelösten Schutzeinrichtung unterschieden werden. In Fords Patent US11043801B2 hat jede Steckdose einen Fehlerstromschutz, dessen Schalter bei ungleichen Strömen öffnet und normalerweise von Hand zurückgesetzt wird; Ford ergänzt einen Stellantrieb für das Rücksetzen aus der Ferne und Prüftaster für die Schutzschalter. Fords SSM 49709 zum F-150 Hybrid 2021 zeigt die Praxis: Nach dem eingebauten Pro-Power-Test meldet der Bildschirm einen Erdschluss, bis die Reset-Taste gedrückt wird – das ist normal. Vor der Leitungssuche also einen ausgelösten Schutz ausschließen. Wo Steckdose B sitzt, ist nicht veröffentlicht; B0128 dokumentiert kein Hersteller. Bis zur Reparatur bleibt B stromlos.","u":[["h","Zuleitung zu Steckdose B an einem Stecker oder im Kabelbaum unterbrochen"],["m","Fehlerstromschutz von Steckdose B defekt oder dessen Rücksetzantrieb hängt"],["l","Feuchtigkeit oder Schmutz in Steckdose B"]],"s":["Steckdose B tot, Meldung zu Erdschluss oder Steckdose am Bildschirm","Zurücksetzen bringt Steckdose B nicht zurück","Steckdosenkreise führen 120/240 V Wechselspannung aus einer Hochvoltquelle; nur spannungsfrei arbeiten"],"k":["dc_ac_converter_a","hv_outlet_b"],"r":["shop_only",0,[60,800],[0.5,3]],"f":"","x":["B0127","B0129","B012A","B012B","B012C"]},{"c":"B0129","t":"DC/AC-Wandler A Hochvolt-Steckdose „C“ Stromkreis/Unterbrechung","e":"DC/AC Converter A High Voltage Power Outlet \"C\" Circuit/Open","d":"B0129 betrifft Steckdose C. Neben Leitungsfehlern schaltet der Wandler Steckdosen auch absichtlich ab, wenn die Last zu hoch ist. Fords Patent US11043801B2 nennt Grenzen von 20 A für die 120-V-Steckdosen und 30 A für die 240-V-Steckdose; übersteigt die Gesamtleistung die Obergrenze, werden Steckdosen nach Rangfolge abgeschaltet, die unwichtigste zuerst. Fords SSM 51498 zur Super Duty 2023 beschreibt die Meldung „Pro Power Onboard ausgeschaltet“ nach überschrittener Leistungsschwelle, die sich erst nach Abziehen des Verbrauchers quittieren ließ. Eine solche Abschaltung ist keine Unterbrechung: B0129 heißt, der Wandler findet keinen intakten Weg zu Steckdose C. Welche Steckdose das ist und ob ein Hersteller B0129 nutzt, ist nicht öffentlich.","u":[["h","Kontakt an Steckdose C durch hohe Last überhitzt oder verschmort, Verbindung verloren"],["m","Kabelbaum zu Steckdose C unterbrochen"],["l","Schaltelement für Steckdose C im Wandler defekt"]],"s":["Steckdose C bleibt auch ohne angeschlossenen Verbraucher tot","Steckdosenmeldung lässt sich durch Abziehen und Zurücksetzen nicht beheben","Steckdosenkreise führen 120/240 V Wechselspannung aus einer Hochvoltquelle; nur spannungsfrei arbeiten"],"k":["dc_ac_converter_a","hv_outlet_c"],"r":["shop_only",0,[60,800],[0.5,3]],"f":"","x":["B0127","B0128","B012A","B012B","B012C"]},{"c":"B012A","t":"DC/AC-Wandler A Hochvolt-Steckdose „D“ Stromkreis/Unterbrechung","e":"DC/AC Converter A High Voltage Power Outlet \"D\" Circuit/Open","d":"B012A betrifft Steckdose D. Steckdosen auf der Ladefläche eines Pick-ups sitzen rauer als im Innenraum: Staub, Regen, Waschanlage und Kabel, die stecken bleiben. Fords Kundenzufriedenheitsprogramm 21B52 zeigt, wie eng die Ladeflächen-Steckdosen ins Fahrzeug eingebunden sind: Bei bestimmten F-150 Raptor 2021 mit Pro Power Onboard verhinderte eine mehr als etwa 17 Grad offene Steckdosenklappe das Auslegen aus P, bis das PCM neu programmiert war. In Fords Patent US11043801B2 trägt die Ladeflächen-Einheit mehrere Steckdosen mit je eigenem Schalter und Schutz, eine zweite Einheit sitzt im Innenraum. Ob D eine Ladeflächen-Steckdose ist, ist nicht veröffentlicht; B012A dokumentiert kein Hersteller. Feuchtigkeit in Steckdose oder Stecker ist eine naheliegende Ursache.","u":[["h","Wasser oder Korrosion in Steckdose D oder ihrem Stecker, typisch für Außen- und Ladeflächensteckdosen"],["m","Kabelbaum zu Steckdose D in Karosserie oder Ladefläche durchgescheuert oder gequetscht"],["l","Steckdoseneinsatz mechanisch beschädigt"]],"s":["Steckdose D ohne Strom, andere Steckdosen arbeiten eventuell","Meldung, dass Bordnetzstrom oder eine Steckdose nicht verfügbar ist","Steckdosenkreise führen 120/240 V Wechselspannung aus einer Hochvoltquelle; nur spannungsfrei arbeiten"],"k":["dc_ac_converter_a","hv_outlet_d"],"r":["shop_only",0,[60,800],[0.5,3]],"f":"","x":["B0127","B0128","B0129","B012B","B012C"]},{"c":"B012B","t":"DC/AC-Wandler A Hochvolt-Steckdose „E“ Stromkreis/Unterbrechung","e":"DC/AC Converter A High Voltage Power Outlet \"E\" Circuit/Open","d":"B012B ist der letzte Steckdosenkreis-Code, für Steckdose E. Viele Pick-ups haben neben den Ladeflächen-Steckdosen eine im Innenraum. Fords SSM 49562 zum F-150 2021 mit 7,2-kW-System weist darauf hin, dass eine Meldung über einen ausgelösten Schutzschalter der Ladefläche in Wahrheit vom Schalter über der 120-V-Steckdose im Armaturenbrett stammen konnte – oder von deren nicht ganz eingerastetem Stecker; ein Software-Update per Funk korrigierte die Anzeige. Fords Patent US11043801B2 erlaubt außerdem, jede Steckdose einzeln über Bildschirm oder Taster zu schalten. Welche Steckdose E ist, bleibt unveröffentlicht; B012B steht in keinem Herstellerdokument. Vor dem Wandler sind Schutzschalter, Stecker und Steckdose des betroffenen Ausgangs zu prüfen.","u":[["h","Stecker an Steckdose E nicht ganz eingerastet, etwa nach Arbeiten am Armaturenbrett"],["m","Schutzschalter von Steckdose E ausgelöst oder defekt"],["l","Leitung zwischen Wandler und Steckdose E unterbrochen"]],"s":["Steckdose E tot, eventuell mit irreführender Schutzschalter-Meldung zu einer anderen Steckdose","Steckdosenkreise führen 120/240 V Wechselspannung aus einer Hochvoltquelle; nur spannungsfrei arbeiten"],"k":["dc_ac_converter_a","hv_outlet_e"],"r":["shop_only",0,[40,800],[0.5,3]],"f":"","x":["B0127","B0128","B0129","B012A","B012C"]},{"c":"B012C","t":"DC/AC-Wandler A Hochvolt-Steckdosen-Steuermodul „A“","e":"DC/AC Converter A High Voltage Power Outlet Control Module \"A\"","d":"B012C nennt Steckdosen-Steuermodul A von Wandler A ohne Fehlerart; verdächtig ist also das Modul selbst, nicht eine einzelne Steckdose. Ford nennt seine Einheit DCACA; beim F-150 mit 2,0-kW-System sitzt sie im Innenraum unter dem linken Rücksitz. Fords SSM 50167 führte einen lauten Lüfter bei frühen Fahrzeugen von 2021 auf DCACA-Software zurück, SSM 52213 zu F-150 2022–2023 und Super Duty 2023 eine Werkstatt-Meldung mit P0A93:96 im DCACA; beides behob eine Neuprogrammierung. Keines der Bulletins nennt B012C, und kein Hersteller dokumentiert den Code; offen bleibt, ob Modul A den Wechselrichter selbst oder eine eigene Steckdosensteuerung meint. Meist fallen alle Steckdosen des Wandlers aus.","u":[["h","Veraltete oder beschädigte Modulsoftware; Neuprogrammierung nach Herstellerbulletin"],["m","Versorgung, Masse oder Netzwerkverbindung von Modul A gestört"],["l","Modul A intern defekt, etwa Lüfter oder Leistungsteil"]],"s":["Bordnetzstrom nicht verfügbar oder Service-Meldung im Zentralbildschirm","Ungewöhnliches Lüftergeräusch am Einbauort des Moduls","Modul verarbeitet 120/240 V Wechselspannung aus einer Hochvoltquelle; nur spannungsfrei arbeiten"],"k":["hv_outlet_module_a","dc_ac_converter_module_a"],"r":["shop_only",0,[100,2500],[0.5,3]],"f":"","x":["B012D","B012E","B0127","P2DA8","P2EA9"]},{"c":"B012D","t":"DC/AC-Wandler A Hochvolt-Steckdosen-Steuermodul „B“","e":"DC/AC Converter A High Voltage Power Outlet Control Module \"B\"","d":"B012D betrifft Steckdosen-Steuermodul B. Ein Wandler für Haushaltssteckdosen wirkt elektrisch und per Funk auf das übrige Fahrzeug. Fords TSB 23-2218 zu F-150 2021–2023 mit DCACA-Wechselrichter zeigt Funkstörungen des Wechselrichters, die das Reifendrucksystem stören: Das BCM speichert B124D und schaltet die TPMS-Leuchte ein; das Verfahren bestätigt den Wechselrichter als Quelle und dämpft die Störung. Das Patent US10050558B2 von Toyota Industries beschreibt einen am 12-V-Netz hängenden Wechselrichter, der nur zwischen etwa 11 und 16 V läuft und bei Überspannung oder überhitzten Leistungsbauteilen abschaltet. Welche Einheit Modul B ist, bleibt unveröffentlicht; B012D dokumentiert kein Hersteller. Versorgung, Masse und Datenleitungen kommen vor einem neuen Modul.","u":[["h","Versorgungsspannung außerhalb des zulässigen Fensters, schwache 12-V-Batterie oder schlechte Masse"],["m","Modul B überhitzt, Luftweg verstellt oder Lüfter ausgefallen"],["l","Modul B intern defekt oder strahlt Störungen ab"]],"s":["Steckdosen schalten ab oder sind nicht verfügbar","Nebenwirkungen auf Funksysteme wie die Reifendrucküberwachung","Modul verarbeitet 120/240 V Wechselspannung aus einer Hochvoltquelle; nur spannungsfrei arbeiten"],"k":["hv_outlet_module_b","dc_ac_converter_module_a"],"r":["shop_only",0,[100,2500],[0.5,3]],"f":"","x":["B012C","B012E","P2EA7","P2EA8","P2EA9"]},{"c":"B012E","t":"DC/AC-Wandler A Hochvolt-Steckdosen-Steuermodul „C“","e":"DC/AC Converter A High Voltage Power Outlet Control Module \"C\"","d":"B012E betrifft Steckdosen-Steuermodul C. GM nennt das Teil Zubehör-Stromsteuermodul für Wechsel- und Gleichstrom: Im Programm N222385490 erhielten Silverado und Sierra 1500 von 2023, die ab September 2022 wegen Chipmangels ohne funktionierenden Wechselrichter gebaut wurden, dieses Modul, eine Sicherung und eine BCM-Programmierung; für 110 V (RPO KI4) und 230 V (KI5) gibt es eigene Wechselrichter. Fords Patent US11043801B2 beschreibt die Steuerseite: Relais für jede Steckdose, Laufzeit-Timer und Leistungsgrenzen, verwaltet von der DCACA-Steuerung. Ob Modul C eine dritte Einheit oder eine weitere Funktion ist, ist nicht veröffentlicht; B012E dokumentiert kein Hersteller. Typische Ursachen sind Versorgung, Masse, Netzwerkfehler oder fehlende Konfiguration nach dem Tausch.","u":[["h","Modul C oder BCM nach Einbau oder Tausch nicht konfiguriert oder programmiert"],["m","Sicherung, Versorgung oder Masse von Modul C fehlerhaft"],["l","Modul C intern defekt"]],"s":["Steckdosen in Innenraum und Ladefläche ohne Funktion","Steckdosenfunktionen fehlen im Bildschirmmenü","Modul verarbeitet 120/240 V Wechselspannung aus einer Hochvoltquelle; nur spannungsfrei arbeiten"],"k":["hv_outlet_module_c","body_control_module"],"r":["shop_only",0,[100,2500],[0.5,3]],"f":"","x":["B012C","B012D","B0127"]},{"c":"B012F","t":"A/V-Sensor-Waschflüssigkeit A Steuerkreis","e":"A/V Sensor Washer Fluid A Control Circuit","d":"B012F meldet einen Fehler im Steuerkreis für A/V-Sensor-Waschflüssigkeit A, den ersten von sechs solchen Kreisen; B0130 bis B0134 folgen. A/V steht sehr wahrscheinlich für autonomes Fahrzeug; der Kreis schaltet Pumpe oder Ventil, das einem Sensor Flüssigkeit zuführt. Ubers Patentfamilie (US20180015907A1, US10220817B2) zeigt den Aufbau: ein Behälter, mehrere Pumpen, die der Fahrzeugrechner für jede Kamera- oder Lidar-Reinigung einzeln startet, dazu Druckluft über Magnetventile. In Fords US10569746B2 setzt der Rechner eine Waschpumpe in Gang, sobald er ein Sensorfenster für verschmutzt hält. Welchen Sensor A versorgt, ist nicht veröffentlicht; B012F dokumentiert kein Hersteller. Fällt der Kreis aus, bleibt Sensor A ungereinigt, und automatisierte Fahrfunktionen schränken sich gegebenenfalls ein.","u":[["h","Pumpenmotor oder Ventilspule für Flüssigkeitskreis A unterbrochen oder kurzgeschlossen"],["m","Beschädigte Leitung oder korrodierter Stecker im Steuerkreis"],["l","Endstufe im ansteuernden Steuergerät defekt"]],"s":["Sensor A wird nicht mehr gewaschen, Kamera- oder Lidarsicht bleibt verschmutzt","Assistenz- oder automatisierte Fahrfunktionen melden Sensor verdeckt oder sind nicht verfügbar"],"k":["av_washer_fluid_pump_a","pump_wiring"],"r":["medium",1,[30,400],[0.3,2]],"f":"","x":["B0130","B0131","B0132","B0133","B0134","B011E"]},{"c":"B0130","t":"A/V-Sensor-Waschflüssigkeit B Steuerkreis","e":"A/V Sensor Washer Fluid B Control Circuit","d":"B0130 meldet einen Fehler im Steuerkreis der A/V-Sensor-Waschflüssigkeit B, dem zweiten von sechs Kanälen zwischen B012F (A) und B0134 (F). A/V bedeutet mit großer Wahrscheinlichkeit autonomes Fahrzeug. Was ein solcher Kanal schaltet, zeigt Ubers Reinigungsaufbau (US20180015907A1): Ein Kompressor lädt einen Druckluftspeicher, ein Behälter mit Füllstandssensor nimmt die Flüssigkeit auf, und mehrere Pumpen versorgen die Reinigungsdüsen, jede vom Fahrzeugrechner einzeln gestartet. Kautex bietet sein Allegro-System für Kameras und Lidar in Fahrzeugen der Stufen 1 bis 5 an und kombiniert dabei Wasser- und Luftstrahl. Welchen Sensor Kanal B bedient, ist nicht veröffentlicht; B0130 dokumentiert kein Hersteller. Ist der Kreis unterbrochen oder kurzgeschlossen, wird der Sensor an Kanal B nicht mehr gewaschen.","u":[["h","Pumpenmotor oder Ventilspule an Flüssigkeitskanal B unterbrochen oder kurzgeschlossen"],["m","Korrodierter oder lockerer Stecker an der Pumpe, Sprühwasser und Streusalz ausgesetzt"],["l","Endstufe für Kanal B im ansteuernden Steuergerät ausgefallen"]],"s":["Kamera oder Lidar an Kanal B bleibt verschmutzt, während die übrigen gereinigt werden","Assistenz- oder automatisierte Fahrfunktion meldet verdeckten Sensor oder steht nicht zur Verfügung"],"k":["av_washer_fluid_pump_b","pump_wiring"],"r":["medium",1,[30,400],[0.3,2]],"f":"","x":["B012F","B0131","B0132","B0133","B0134"]},{"c":"B0131","t":"A/V-Sensor-Waschflüssigkeit C Steuerkreis","e":"A/V Sensor Washer Fluid C Control Circuit","d":"B0131 betrifft den Steuerkreis der A/V-Sensor-Waschflüssigkeit C, den dritten Kanal der Reihe B012F bis B0134 für Sensoren autonomer Fahrzeuge. Fords Patent US10569746B2 beschreibt eine drehbare Sensorabdeckung: Der Rechner versucht es zuerst berührungslos mit Flüssigkeit oder Luft und setzt erst dann einen Wischer ein, wenn die gemessene Trübung des Fensters über einem Grenzwert bleibt. Eine koreanische Laborstudie an Lidar-Fenstern sprühte mit 0,5 bar Waschflüssigkeit und 2 bar Luft; am stärksten wirkten sich Art des Schmutzes, dessen Menge und sein Antrocknen aus. In dieser Bedeutung dokumentiert kein Hersteller B0131. General Motors führt B0131 im Bulletin PIP5094 von 2013 als Stichwort einer älteren, sachfremden Nummerierung. Folge des Fehlers: Sensor C wird nicht gewaschen.","u":[["h","Pumpe oder Magnetventil von Kanal C mit unterbrochener oder kurzgeschlossener Wicklung"],["m","Leitung zur Sensorreinigungseinheit an einer Halterung durchgescheuert oder eingeklemmt"],["l","Ausgang für Kanal C im ansteuernden Steuergerät defekt"]],"s":["Sensor C wird nicht mehr gewaschen; Schmutz, Salz oder Insekten bleiben auf dem Fenster","Ein vorhandener Wischer oder Luftstrahl muss allein reinigen"],"k":["av_washer_fluid_pump_c","pump_wiring"],"r":["medium",1,[30,400],[0.3,2]],"f":"","x":["B012F","B0130","B0132","B0133","B0134"]},{"c":"B0132","t":"A/V-Sensor-Waschflüssigkeit D Steuerkreis","e":"A/V Sensor Washer Fluid D Control Circuit","d":"B0132 betrifft Waschflüssigkeitskanal D für die Sensoren eines autonomen Fahrzeugs, den vierten der Reihe ab B012F. In Ubers Patent US10173646B1 beurteilt der Fahrzeugrechner, wie verschmutzt jeder Sensor ist, und legt daraus eine Reinigungsreihenfolge fest; die Reinigungseinheiten arbeiten dann nacheinander statt gleichzeitig. Fällt ein Kanal aus, fehlt ein Sensor in diesem Ablauf. Genannt werden dort Regen, Schnee, Streusalz, Pollen, Insektenreste und Vogelkot. Eine KTH-Abschlussarbeit für Scania verglich Reinigungsverfahren für schwere autonome Lkw und stimmte den Flüssigkeitsverbrauch über die Pumpenleistung ab. Welcher Sensor an Kanal D hängt, wird nirgends genannt; B0132 dokumentiert kein Hersteller. Typisch sind ein unterbrochener Pumpenkreis oder ein Kurzschluss in der Versorgung.","u":[["h","Unterbrechung in Pumpe oder Ventil von Kanal D, oft eine durchgebrannte Wicklung"],["m","Versorgungs- oder Steuerleitung von Kanal D mit Kurzschluss nach Masse oder Plus"],["l","Pumpe durch eingefrorene oder verunreinigte Flüssigkeit blockiert, Stromaufnahme zu hoch"]],"s":["Sensor D wird im Reinigungsablauf übersprungen und bleibt verschmutzt","Automatisierte Fahrfunktion schränkt sich womöglich ein oder fordert zur Übernahme auf"],"k":["av_washer_fluid_pump_d","pump_wiring"],"r":["medium",1,[30,400],[0.3,2]],"f":"","x":["B012F","B0130","B0131","B0133","B0134"]},{"c":"B0133","t":"A/V-Sensor-Waschflüssigkeit E Steuerkreis","e":"A/V Sensor Washer Fluid E Control Circuit","d":"B0133 gilt dem Steuerkreis von A/V-Sensor-Waschflüssigkeit E, den fünften Kanal nach B012F bis B0132. Autonome Fahrzeuge tragen viele Kameras und Lidar-Einheiten, deshalb ist die Reinigung auf mehrere getrennt geschaltete Flüssigkeitswege verteilt. Ubers Patent US10220817B2 zeigt eine Sensorplattform mit Kanälen und erhöhtem Rand, die Flüssigkeit und Luft zu den Sensorköpfen führen. Kautex gibt an, dass die Allegro-Steuersoftware beim Abstimmen der Aktoren festlegt, welcher Sensor Vorrang hat. Eine Laborstudie an Lidar-Fenstern fand, dass der Erfolg vor allem von Art, Dichte und Antrocknung der Ablagerung abhing. Welcher Sensor an Kanal E hängt, ist nicht offengelegt; B0133 dokumentiert kein Hersteller. Bleibt der Kanal abgeschaltet, werden Ablagerungen auf diesem Sensor nicht mehr entfernt.","u":[["h","Pumpe oder Ventil von Kanal E defekt, Spule unterbrochen oder kurzgeschlossen"],["m","Wassereintritt oder Korrosion im Stecker von Kanal E"],["l","Ausgang für Kanal E im Reinigungssteuergerät beschädigt"]],"s":["Am Sensor von Kanal E bleibt ein Schmutzfilm oder angetrockneter Sprühnebel","Meldung, dass ein Sensor verdeckt oder eine Assistenzfunktion nicht verfügbar ist"],"k":["av_washer_fluid_pump_e","pump_wiring"],"r":["medium",1,[30,400],[0.3,2]],"f":"","x":["B012F","B0130","B0131","B0132","B0134"]},{"c":"B0134","t":"A/V-Sensor-Waschflüssigkeit F Steuerkreis","e":"A/V Sensor Washer Fluid F Control Circuit","d":"B0134 ist der letzte der sechs A/V-Sensor-Waschflüssigkeitskreise (B012F für A bis B0134 für F) und betrifft Kanal F. Das Steuergerät schaltet hier eine Pumpe oder ein Ventil und legt den Code ab, wenn es einen offenen oder kurzgeschlossenen Ausgang feststellt. In Fords US10569746B2 entscheidet der Rechner anhand der gemessenen Trübung eines Sensorfensters, ob Sprühen reicht oder ein Wischer folgen muss. Ubers US10173646B1 lässt die Reinigungseinheiten in einer Reihenfolge laufen, die sich aus dem Sensorzustand ergibt. Die KTH-Arbeit für Scania zeigte, dass sich die Flüssigkeitsfront auf einer Sensorblende über die Pumpenleistung verschieben lässt. Welchen Sensor Kanal F versorgt, ist nicht veröffentlicht; B0134 dokumentiert kein Hersteller. Bis zur Reparatur fehlt Sensor F die Waschflüssigkeit.","u":[["h","Wicklung von Pumpe oder Ventil an Kanal F unterbrochen oder kurzgeschlossen"],["m","Leitung von Kanal F beschädigt, etwa nach Karosseriearbeiten nahe der Sensorhalterung"],["l","Endstufe für Kanal F im Steuergerät ausgefallen"]],"s":["Sensor F erhält keine Waschflüssigkeit mehr; nur Luft oder ein vorhandener Wischer arbeiten noch","Assistenzfunktionen, die auf Sensor F angewiesen sind, melden eingeschränkte Verfügbarkeit"],"k":["av_washer_fluid_pump_f","pump_wiring"],"r":["medium",1,[30,400],[0.3,2]],"f":"","x":["B012F","B0130","B0131","B0132","B0133"]},{"c":"B0140","t":"Gurtkraftsensor Beifahrer Stromkreis","e":"Passenger Seatbelt Tension Sensor Circuit","d":"Weder die verfügbaren J2012-Listen noch öffentliche Herstellerunterlagen enthalten B0140; sein Wortlaut wiederholt B0061, den J2012-Code für den Gurtkraftsensor des Beifahrers, und ähnelt B0182. Das Bauteil selbst ist gut beschrieben. Bei Delphi (US6554318B2) läuft das Gurtband durch einen Schieber, der sich gegen Federn bewegt; ein Hallelement zwischen zwei Magneten erfasst den Weg. Ein zweites Delphi-Patent (US6605877B1) überträgt die Gurtkraft über eine Zweidrahtleitung an ein Steuergerät zur Insassenerkennung, das damit einen fest verzurrten Kindersitz von einem Erwachsenen unterscheidet. FMVSS 208 erlaubt, den Beifahrerairbag bei kleinen Insassen automatisch abzuschalten. Ein Fehler in diesem Kreis schaltet meist die Airbag-Leuchte ein.","u":[["h","Lockerer oder korrodierter Stecker am Gurtkraftsensor des Beifahrers"],["m","Sensorsignal außerhalb des Bereichs, etwa durch klemmenden Schieber"],["m","Sensorleitung unter dem Sitz oder an der Schwellerverkleidung eingeklemmt"]],"s":["Airbag-Warnleuchte an","Anzeige des Beifahrerairbag-Status zeigt womöglich einen unerwarteten Zustand","Sicherheitshinweis: Der Sensor liegt nahe Straffer- und Seitenairbagsteckern; nur spannungsfrei trennen – Batterie abklemmen, Wartezeit einhalten"],"k":["seat_belt_tension_sensor","occupant_detection_module","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,600],[0.5,2]],"f":"","x":["B0061","B0182","B0060"]},{"c":"B0150","t":"Klima-Betriebsartklappe Bereich/Funktion","e":"HVAC Mode Door Range/Performance","d":"B0150 fehlt in allen öffentlich zugänglichen J2012-Codelisten, und kein Hersteller veröffentlicht ihn mit dieser Bedeutung. Die Betriebsartklappe bestimmt, ob die Luft an den Gesichtsdüsen, im Fußraum oder an der Frontscheibe austritt. Ein Fehler der Art Bereich/Funktion heißt: Die Klappe erreicht die befohlene Stellung nicht, oder ihre Rückmeldung passt nicht zum Befehl. Viele Stellmotoren tragen ein mit dem Getriebe gekoppeltes Potentiometer, das etwa 0 bis 5 V zurückgibt, wie ein Fachartikel des Motor-Magazins erläutert; Calsonics Patent EP0771679A2 koppelt jeden Klappenmotor mit einem solchen Stellungsgeber. GMs Global-A-Klimaanlage arbeitet laut Handbuch des Saab 9-5 (2011) mit Schrittmotoren und legt Kreisfehler des Betriebsartstellers unter B0233 ab. Zu erwarten sind Luft aus den falschen Düsen oder eine pendelnde Klappe.","u":[["h","Betriebsartklappe oder Gestänge schwergängig, gebrochener Hebel oder abgenutztes Zahnrad"],["m","Stellmotor der Betriebsartklappe verschlissen, Potentiometerbahn verschmutzt"],["l","Endlagen nach Tausch des Stellmotors nicht neu angelernt"]],"s":["Luft kommt aus den falschen Düsen, oder die gewählte Verteilung wird nicht erreicht","Klicken oder Klopfen hinter der Instrumententafel, während sich die Klappe bewegt","Scheibe beschlägt leichter, weil zu wenig Luft an die Defrostdüsen gelangt"],"k":["mode_door_actuator","mode_door_linkage","hvac_control_module"],"r":["medium",1,[60,600],[0.5,4]],"f":"","x":["B0170","B0268","B0205"]},{"c":"B0152","t":"Gurtschlossschalter Fahrer Stromkreis Fehlfunktion","e":"Driver Buckle Switch Circuit Malfunction","d":"B0152 findet sich weder in einer J2012-Liste noch in einer öffentlichen Herstellerunterlage. Nach J2012 ist der Gurtschlosssensor des Fahrers B0050; der Titel doppelt also diesen Code. Der Schalter meldet, ob die Gurtzunge eingerastet ist. TRWs Patent US5898366A setzt Hallelement, Magnet und Anker ins Gurtschloss; die Bewegung der Verriegelung verändert den Magnetfluss und damit das Ausgangssignal. US5966784A nutzt dafür eine Umkehr der Feldrichtung und erwähnt, dass das Signal die Airbagauslösung mitsteuern kann. FMVSS 208 S7.3 verlangt eine Gurtwarnung am Fahrerplatz: Leuchte mit 4 bis 8 Sekunden Signalton oder eine Leuchte über mindestens 60 Sekunden. Ein Kreisfehler kann die Warnung bei angelegtem Gurt anlassen oder ohne Gurt verstummen lassen.","u":[["h","Gurtschlossstecker unter dem Fahrersitz locker oder korrodiert"],["m","Gurtschlossleitung durch Sitzverstellung eingeklemmt oder gebrochen"],["m","Hallsensor oder Kontakt im Gurtschloss defekt, Gurtschloss muss getauscht werden"]],"s":["Gurtwarnung für den Fahrer bleibt an oder kommt nicht","Airbag-Warnleuchte an, wenn das Airbagsteuergerät das Gurtschloss auswertet","Sicherheitshinweis: Der Gurtschlossstecker liegt unter dem Sitz nahe Airbag- und Strafferstecker; nur spannungsfrei trennen, Wartezeit einhalten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[60,400],[0.5,2]],"f":"","x":["B0050","B0154","B00D0"]},{"c":"B0154","t":"Gurtschlossschalter Beifahrer Stromkreis Fehlfunktion","e":"Passenger Buckle Switch Circuit Malfunction","d":"B0154 hat in den durchsuchten J2012-Listen keinen Eintrag, und Hersteller beschreiben ihn nicht öffentlich; J2012 vergibt den Gurtschlosssensor des Beifahrers an B0052, den dieser Titel doppelt. Auf der Beifahrerseite steuert das Gurtschlosssignal nicht nur eine Erinnerung: Zusammen mit der Sitzbelegung hilft es dem Rückhaltesteuergerät zu entscheiden, wie Beifahrerairbag und Gurtstraffer wirken. TRWs US5966784A liest den Verriegelungszustand aus der Richtung eines Magnetfelds am Hallelement; US5898366A führt den Fluss über einen gefederten Anker, der die Verriegelung berührt. Für Pkw ab Baudatum 1. September 2028 wendet FMVSS 208 seine neuen Gurtwarnregeln (S7.5) auch auf die äußeren Vordersitze an. Typische Folge: falsche oder fehlende Gurtwarnung für den Beifahrer, oft mit Airbag-Leuchte.","u":[["h","Gurtschlossstecker unter dem Beifahrersitz locker, korrodiert oder abgetreten"],["m","Gurtschlossleitung an der Sitzschiene oder durch Sitzverstellung durchgescheuert"],["m","Schalter im Gurtschloss verschlissen oder durch verschüttete Getränke verschmutzt"]],"s":["Gurtwarnung für den Beifahrer falsch, dauerhaft an oder fehlend","Airbag-Warnleuchte an","Sicherheitshinweis: Sitzstecker liegen neben Airbag- und Straffer-Leitungen; vor dem Trennen Batterie abklemmen und Wartezeit abwarten"],"k":["seat_belt_buckle_switch","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[60,400],[0.5,2]],"f":"","x":["B0052","B0152","B00D1"]},{"c":"B0156","t":"Sonnensensor Stromkreis","e":"Sun Load Sensor Circuit","d":"Die geprüften J2012-Listen überspringen B0156, und öffentliche Herstellerunterlagen erwähnen ihn nicht; dieselbe Bedeutung hat bereits der Code B0305. Ein Sonnensensor oben auf der Instrumententafel meldet der Klimaautomatik, wie stark die Sonne den Innenraum aufheizt, damit sie frühzeitig mehr kühlt. HELLAs Solarsensor sitzt mittig auf dem Armaturenbrett, erfasst die Einstrahlung für verschiedene Zonen und meldet über LIN. Das Patent US6888120B2 verwendet zwei lichtsammelnde Linsen mit je einer eigenen Fotodiode, um Fahrer- und Beifahrerseite zu trennen. GM führt diesen Sensor stattdessen unter B0183: Beim Saab 9-5 (2011) setzt das Klimasteuergerät ihn, wenn der 5-V-Kennimpuls ausbleibt, und rechnet dann mit einer Sonnenintensität von null.","u":[["h","Sensorstecker unter der Abdeckung oben am Armaturenbrett locker oder nach Scheibentausch beschädigt"],["m","Fotodiode oder Elektronik im Sonnensensor ausgefallen"],["l","Signal- oder Versorgungsleitung hinter der Instrumententafel kurzgeschlossen oder unterbrochen"]],"s":["Innenraum wird bei starker Sonne zu warm, weil die Anlage nicht nachkühlt","Automatisches Gebläse und Temperatur reagieren nur noch auf die Lufttemperatur"],"k":["sun_load_sensor","hvac_control_module"],"r":["medium",1,[30,200],[0.3,1.5]],"f":"","x":["B0162","B0305"]},{"c":"B0158","t":"Außentemperaturfühler Stromkreis","e":"Ambient Air Temperature Sensor Circuit","d":"Obwohl B0158 in den geprüften J2012-Listen fehlt, nutzen General Motors und Saab ihn genau mit dieser Bedeutung. Beim Saab 9-4X (2011) liest das Kombiinstrument den Außentemperaturfühler und legt B0158 02 ab, wenn das Signal mehr als 88 °C ergibt, B0158 05 unter −40 °C; die Anzeige zeigt dann Striche. In den Handbüchern des Saab 9-3 wertet das Karosseriesteuergerät den Fühler aus: Unter 0,25 V gilt als Masseschluss, über 5 V als Unterbrechung oder Plusschluss, und der letzte bekannte Wert bleibt stehen. GM-Bulletin PIC5656F (LaCrosse 2010–13, Verano 2012–16, Malibu 2013–16, Cascada 2017) verbindet B0158 mit fehlender Außentemperatur und einer Klimaanzeige, die auf Celsius hängt, und beginnt die Suche am Fühlerstecker und an den Leitungen 61 und 636.","u":[["h","Fühler am vorderen Stoßfänger abgesteckt oder Stecker nach Frontarbeiten beschädigt"],["m","Thermistor im Außentemperaturfühler unterbrochen oder kurzgeschlossen, oft nach Steinschlag"],["m","Signal- oder Masseleitung zum Kombiinstrument beschädigt"]],"s":["Außentemperaturanzeige fehlt oder zeigt Striche","Klimaautomatik rechnet mit einem gespeicherten oder festen Ersatzwert","Bei einigen GM-Modellen springt die Klimaanzeige auf Celsius"],"k":["ambient_air_temperature_sensor","instrument_cluster","hvac_control_module"],"r":["medium",1,[20,150],[0.3,1]],"f":"","x":["B0159","B0255"]},{"c":"B0159","t":"Außentemperaturfühler Bereich/Funktion","e":"Outside Temperature Sensor Range/Performance","d":"B0159 taucht in den öffentlich zugänglichen J2012-Codelisten nicht auf. General Motors nutzt ihn: Das Bulletin PIP5094 von 2013 führt B0159 unter seinen Stichwörtern aus der Serviceinformation, allerdings ohne Beschreibung, sodass kein öffentlicher GM-Text die genaue Fehlerlogik nennt. Der Nachbarcode B0158 ist bei GM der Kreis des Außentemperaturfühlers. Der Fühler ist ein NTC-Thermistor hinter dem vorderen Stoßfänger; laut Handbuch des Saab 9-5 (2011) speist das Kombiinstrument ihn mit 5 V und sieht bei Kälte hohen Widerstand und hohe Spannung, bei Wärme niedrige Werte. Anders als bei B0158 geht es hier um ein Signal innerhalb der elektrischen Grenzen, das aber unplausibel ist, etwa auf einem Wert festhängt oder weit von anderen Temperaturen abweicht. Folge: falsche Außentemperatur.","u":[["h","Außentemperaturfühler gealtert oder träge, liefert plausible, aber falsche Werte"],["m","Fühler sitzt so, dass Motor- oder Straßenwärme ihn erreicht, etwa nach Stoßfängerreparatur"],["l","Korrodierter Kontakt erhöht den Widerstand und verschiebt den Messwert"]],"s":["Angezeigte Außentemperatur deutlich zu hoch oder zu niedrig","Klimaautomatik oder Klimakompressor verhalten sich wegen des falschen Außenwerts ungewohnt"],"k":["outside_temperature_sensor","hvac_control_module"],"r":["medium",1,[20,150],[0.3,1]],"f":"","x":["B0158","B0255"]},{"c":"B0160","t":"Innenraumtemperaturfühler Stromkreis","e":"In-Vehicle Temperature Sensor Circuit","d":"B0160 zählt nicht zu den öffentlich zugänglichen J2012-Einträgen, und mit dieser Bedeutung veröffentlicht ihn kein Hersteller; einen ähnlichen Titel trägt B0250. Der Innenraumfühler meldet der Klimaautomatik die tatsächliche Innentemperatur. Damit er echte Kabinenluft misst, wird er meist belüftet: In Densos Patent US20040016537A1 saugt ein vom Klimagehäuse gespeister Ansauger Innenraumluft über den Fühler, sodass in jeder Betriebsart Luft strömt. Die Hersteller verwenden für diesen Kreis andere Nummern. In GMs Global-A-System, etwa beim Saab 9-5 (2011), deckt B0163 den Innenraumfühler mit Grenzen von 0,1 und 4,9 V ab. Ältere Saab 9-3 nutzen B0165 für Masseschluss unter 0,2 V und B0166 für Unterbrechung.","u":[["h","Thermistor im Innenraumfühler unterbrochen oder kurzgeschlossen"],["m","Fühlerstecker hinter Instrumententafel oder Dachhimmel locker oder korrodiert"],["l","Signal- oder Bezugsleitung bei Innenraumarbeiten beschädigt"]],"s":["Klimaautomatik heizt oder kühlt den Innenraum zu stark","Gebläsedrehzahl beruhigt sich nicht, wenn der Innenraum die Solltemperatur erreicht"],"k":["in_vehicle_temperature_sensor","hvac_control_module"],"r":["medium",1,[30,250],[0.5,2]],"f":"","x":["B0250","B0164"]},{"c":"B0162","t":"Sonnensensor 2 Stromkreis","e":"Sun Load Sensor 2 Circuit","d":"Weder eine erreichbare J2012-Liste noch eine öffentliche Herstellerquelle führt B0162. Der Titel deutet auf einen zweiten Sonnenkanal, wie ihn Zweizonen-Klimaanlagen nutzen: Eatons Patent US5957375A beschreibt einen Sensor, der erkennt, wie viel Sonne einzelne Bereiche des Innenraums trifft, damit jede Seite für sich gekühlt wird. US6888120B2 löst das mit zwei Linsen und zwei Fotodioden, getrennt durch einen lichtundurchlässigen Steg, je eine für Fahrer- und Beifahrerseite. GM deckt dagegen seinen ganzen Mehrzonensensor mit einem Code ab, B0183, so beim Saab 9-4X (2011); fehlt ein Wert, rechnet das Steuergerät mit 0 W/m², 45° Höhe und −75° Azimut. Fällt der zweite Kanal aus, wird eine Seite schlecht ausgeglichen.","u":[["h","Zweite Fotodiode bzw. zweiter Kanal eines Zweizonen-Sonnensensors ausgefallen"],["m","Stecker des Sensors in der Abdeckung des Armaturenbretts locker oder beschädigt"],["l","Signalleitung des zweiten Kanals unterbrochen oder kurzgeschlossen"]],"s":["Eine Seite des Innenraums wird bei Sonne zu warm, die andere nicht","Zweizonen-Automatik reagiert nur auf einer Seite auf Sonneneinstrahlung"],"k":["sun_load_sensor_2","hvac_control_module"],"r":["medium",1,[30,200],[0.3,1.5]],"f":"","x":["B0156","B0305"]},{"c":"B0164","t":"Airbag-Innenraumtemperaturfühler Stromkreis","e":"Air Bag In-Vehicle Temperature Sensor Circuit","d":"B0164 taucht in den zugänglichen J2012-Codelisten nicht auf. General Motors verwendet die Nummer: Das Bulletin PIP5094 von 2013 führt sie als Stichwort der Serviceinformation, doch kein öffentlicher GM-Text nennt ihren Wortlaut. Die Airbag-Bedeutung des Titels dokumentiert kein Hersteller. GMs Nachbarcode B0163 ist der Innenraumfühler der Klimaanlage, was eher für eine Klima- als für eine Airbag-Bedeutung spricht. Temperaturmessung für Airbags gibt es durchaus: Delphis US7000946B2 passt die Rückhaltewirkung an die gemessene Gasgeneratortemperatur an und nimmt dafür die Chiptemperatur des Steuer-ICs als Anhalt; Boschs US5697639A setzt einen Temperatursensor direkt ins Airbagmodul. Einen B0164 nach der Definition der jeweiligen Marke behandeln.","u":[["m","Temperaturfühler oder seine Leitung unterbrochen oder kurzgeschlossen"],["m","GM: Fehler in der Klimafühlergruppe um B0163 statt am Airbag"],["l","Interne Temperaturmessung des Steuergeräts fehlerhaft"]],"s":["Airbag- oder Klimawarnung, je nachdem, welches Steuergerät den Code abgelegt hat","Klimaautomatik arbeitet womöglich mit einer Ersatz-Innentemperatur","Sicherheitshinweis: Ist das Airbagsteuergerät beteiligt, nur spannungsfrei arbeiten – Batterie abklemmen, Wartezeit einhalten"],"k":["in_vehicle_temperature_sensor","srs_control_module"],"r":["shop_only",0,[50,400],[0.5,2]],"f":"","x":["B0160","B0250"]},{"c":"B0166","t":"Klima-Ausblastemperaturfühler","e":"HVAC Discharge Air Temperature Sensor","d":"Die öffentlichen J2012-Listen enthalten B0166 nicht, und keine Marke beschreibt ihn als Ausblasfühler. Saab nutzt ihn, allerdings für den Innenraum statt für den Luftaustritt: In den Klimahandbüchern des 9-3 von 2003 bis 2012 kennzeichnet B0166 05 den Innenraumtemperaturfühler als unterbrochen oder mit Plusschluss, sobald der Eingang des Steuergeräts über 4,8 V steigt; geprüft wird ständig bei eingeschalteter Zündung. B0165 02 ist der zugehörige Masseschluss. Ausblas- bzw. Kanaltemperaturfühler sind NTC-Thermistoren in den Luftkanälen, mit denen das Steuergerät prüft, was es tatsächlich liefert. GMs Global-A-System, dokumentiert für den Saab 9-5 (2011), nummeriert sie B0173, B0178, B0509 und B0514. Ein B0166 braucht deshalb die Definition der jeweiligen Marke.","u":[["h","Fühler unterbrochen oder Signal mit Plusschluss (Innenraumfühler Saab 9-3)"],["m","Fühlerstecker locker oder nach Arbeiten an der Instrumententafel nicht aufgesteckt"],["l","Bei anderen Marken der Fühler im Ausblaskanal selbst defekt"]],"s":["Klimaautomatik schätzt Innen- oder Ausblastemperatur falsch ein und regelt zu stark oder zu schwach nach","Eingestellte Temperatur wird nicht gleichmäßig gehalten"],"k":["discharge_air_temp_sensor","in_vehicle_temperature_sensor","hvac_control_module"],"r":["medium",1,[30,250],[0.5,2]],"f":"","x":["B0160","B0250","B0173"]},{"c":"B0168","t":"Klima-Mischklappe Funktion","e":"HVAC Air Mix Door Performance","d":"B0168 taucht weder in den geprüften J2012-Listen noch mit dieser Bedeutung in öffentlichen Herstellerunterlagen auf; Kreise der Mischklappe haben die Codes B0258 und B0263. Die Misch- bzw. Temperaturklappe teilt den Luftstrom zwischen Heizungswärmetauscher und Bypass auf und bestimmt so die Ausblastemperatur. Ein Funktionsfehler heißt, dass sie ihr Ziel nicht erreicht oder nicht hält. Ein älteres japanisches Patent (CA1266779A) zeigt, wie fein das ist: Im Bereich, in dem schon eine kleine Bewegung die Lufttemperatur stark ändert, bekommt der Motor weniger Spannung, damit die Klappe nicht pendelt. In US5529112A fährt der Motor der Temperaturklappe auf Anschlag und bleibt dort blockiert stehen. GMs Global-A-Klimaanlage bewegt diese Klappe mit einem Schrittmotor und führt sie unter B0408.","u":[["h","Welle oder Hebel der Mischklappe gebrochen oder rutscht am Stellmotor durch"],["m","Getriebe des Mischklappenstellers verschlissen oder Motor schwach"],["l","Fremdkörper oder Schmutz im Klimagehäuse blockiert die Klappe"]],"s":["Ausblasluft bleibt heiß oder kalt, egal wie die Temperatur eingestellt ist","Temperatur schwankt, oder hinter der Instrumententafel klickt es"],"k":["air_mix_door_actuator","hvac_control_module"],"r":["medium",1,[60,800],[0.5,6]],"f":"","x":["B0258","B0263"]},{"c":"B0170","t":"Klima-Betriebsartklappe Positionssensor","e":"HVAC Mode Door Position Sensor","d":"Die Suche in den verfügbaren J2012-Listen und öffentlichen Herstellerunterlagen ergab für B0170 keinen Eintrag mit diesem Titel. Anders als B0150, der die Bewegung der Betriebsartklappe betrifft, zielt dieser Code auf den Geber, der ihre Stellung meldet. In den meisten elektronischen Klimastellern ist das ein Potentiometer am Getriebe; ein Fachartikel des Motor-Magazins nennt rund 0 bis 5 V als Signal und erwähnt, dass einfache Umluftsteller oft keinen haben. Hyundais Patent US9960727B2 fährt die Motoren von Ansaug-, Temperatur-, Betriebsart- und Defrostklappe, bis die Rückmeldespannung dem Ziel entspricht, und überwacht den Motorstrom auf Blockieren. Fehlt das Stellungssignal oder rauscht es, weiß das Steuergerät nicht, wo die Klappe steht, und stellt sie womöglich nicht mehr.","u":[["h","Verschlissene oder verschmutzte Potentiometerbahn im Betriebsartsteller"],["m","Rückmeldesignal, 5-V-Versorgung oder Bezugsleitung unterbrochen oder kurzgeschlossen"],["l","Verbogener oder zurückgeschobener Pin im Stellerstecker"]],"s":["Luftverteilung bleibt in einer Stellung stehen","Steller läuft nach dem Einschalten wiederholt an oder tickt"],"k":["mode_door_position_sensor","mode_door_actuator","hvac_control_module"],"r":["medium",1,[60,500],[0.5,4]],"f":"","x":["B0150","B0268"]},{"c":"B0173","t":"Luftkanal-Temperaturfühler oben links Stromkreis","e":"Upper Left Duct Air Temperature Sensor Circuit","d":"Für B0173 hat keine öffentliche J2012-Quelle einen Eintrag, General Motors dokumentiert ihn aber eindeutig in seiner Global-A-Klimaanlage. In den Handbüchern von Saab 9-5 und 9-4X (2011) betrifft er den Luftkanal-Temperaturfühler oben links: B0173 02 für Masseschluss, 05 für zu hohe Spannung oder Unterbrechung; das Steuergerät erkennt ein Signal unter 0,1 V oder über 4,9 V und arbeitet mit einem Ersatzwert weiter. B0178 ist der Fühler unten links, B0509 und B0514 die rechte Seite. GM-Bulletin 17-NA-049 (Bolt EV 2017, Opel Ampera-e) führt B0173 und B0178 auf einen Kabelstrang der Kanalfühler zurück, der zwischen Klimagehäuse und Querträger eingeklemmt ist; PIT5383 nennt B0173 für 2015er Modelle mit neuer K33-Software. Die Ansaugklappe führt GM unter B022A.","u":[["h","Kabelstrang der Kanalfühler zwischen Klimagehäuse und Querträger eingeklemmt (GM 17-NA-049)"],["m","Thermistor des Kanalfühlers oben links unterbrochen oder kurzgeschlossen"],["l","Kalibrierung des Klimasteuergeräts braucht ein Update (GM PIT5383, Modelle 2015)"]],"s":["Linke Düsen zu warm oder zu kalt, oder Heizen bzw. Kühlen scheint nicht zu funktionieren","Klimaautomatik arbeitet mit einem Ersatzwert für die Kanaltemperatur"],"k":["discharge_air_temp_sensor","hvac_control_module"],"r":["medium",1,[30,300],[0.5,3]],"f":"","x":["B0166","B0175"]},{"c":"B0175","t":"Klima-Umluftklappe Funktion","e":"HVAC Recirculation Door Performance","d":"Die vorliegenden J2012-Tabellen lassen B0175 aus, und keine Marke verbindet ihn mit der Umluftklappe; ein Kreis der Umluftklappe hat den Code B0273. Saab nutzt die Nummer für einen Temperaturfühler: In den Klimahandbüchern des 9-3 bedeutet B0175 02 Masseschluss am Mischluftfühler der linken Düse, das Handbuch von 2003 nennt einen Eingang unter 0,2 V, und das Steuergerät übernimmt dann den Wert des linken Fußraumfühlers; B0176 ist dessen Unterbrechung. GMs Global-A-System legt Fehler des Umluftstellers dagegen unter B0223 und B022A ab. Die Umluftklappe schaltet zwischen Frisch- und Innenluft, und laut HELLA kann ein Luftgütesensor sie selbsttätig verstellen. Zuerst die Definition der Marke prüfen.","u":[["m","Umluftklappe schwergängig oder Zahnrad des Stellers abgenutzt"],["m","Saab 9-3: Mischluftfühler der linken Düse oder seine Leitung mit Masseschluss"],["l","Leitungs- oder Steckerfehler am Steller hinter dem Handschuhfach"]],"s":["Umluft lässt sich nicht schalten, oder Scheiben beschlagen, weil die Klappe auf Umluft bleibt","Saab 9-3: Temperatur am linken Luftaustritt wird ungenauer geregelt"],"k":["recirculation_door_actuator","hvac_control_module"],"r":["medium",1,[40,400],[0.5,3]],"f":"","x":["B0273","B0173","B0166"]},{"c":"B0181","t":"Frontgebläsemotor Stromkreis niedrig","e":"Front Blower Motor Circuit Low","d":"B0181 fehlt in allen öffentlich zugänglichen J2012-Listen, und kein Hersteller veröffentlicht ihn als Code für das vordere Gebläse. Saab vergibt die Nummer anders: Die Klimaautomatik des 9-3 legt B0181 05 ab, wenn der Eingang des linken Mischluftfühlers im Fußraum über 4,8 V steigt, also bei Unterbrechung oder Schluss nach Plus. Bei GMs späterer Global-A-Klimaregelung heißt der Drehzahlkreis des Frontgebläses B0193; ein allgemeiner Gebläsekreis hat den Code B0283. Wörtlich genommen bedeutet „Stromkreis niedrig“, dass Versorgung oder Drehzahlleitung des Gebläses zu wenig Spannung führen. Im Saab 9-5 von 2011 schickt das Klimasteuergerät ein PWM-Signal, aus dem das Gebläsemodul 2 bis 13 V am Motor macht; liegt diese Leitung an Masse oder ist sie offen, steht das Gebläse. Ältere Anlagen schalten die Stufen über Vorwiderstände.","u":[["h","Drehzahlleitung zwischen Klimasteuergerät und Gebläsemodul unterbrochen oder an Masse durchgescheuert"],["m","Gebläsemodul oder Vorwiderstand durchgebrannt, oft nachdem ein schwergängiger Motor zu viel Strom zog"],["l","Durchgebrannte Sicherung oder angeschmolzener Stecker in der Gebläseversorgung"]],"s":["Vorderes Gebläse läuft gar nicht oder nur auf der höchsten Stufe","Frontscheibe beschlägt länger, weil kaum Luft ankommt"],"k":["front_blower_motor","blower_resistor_or_module","hvac_control_module"],"r":["medium",1,[40,400],[0.5,2]],"f":"","x":["B0283","B0186","B0184"]},{"c":"B0182","t":"Gurtkraftsensor rechts vorn/Beifahrerseite Stromkreis","e":"Right Front/Passenger Side Buckle Tension Sensor Circuit","d":"B0182 ist weder in einer J2012-Liste noch in öffentlichen Unterlagen eines Herstellers zu finden; der Code lässt sich also nicht nachweisen. Seine Bedeutung deckt sich mit B0061, dem Gurtkraftsensor des Beifahrers, und mit B0140. Ein solcher Sensor sitzt am unteren Gurtanker und meldet der Insassenerkennung, wie stark am Gurt gezogen wird. Im Delphi-Patent US6605877B1 versorgen dieselben zwei Leitungen den Sensor und übertragen seine Messwerte; eine Gurtkraft über einem kalibrierten Wert deutet auf einen fest verzurrten Kindersitz, und das gemessene Sitzgewicht wird um die Gurtkraft bereinigt. FMVSS 208 erlaubt, den Beifahrerairbag für kleine Kinder selbsttätig abzuschalten – dafür wird dieses Signal gebraucht. Bei einem Kreisfehler weiß das Steuergerät nicht, ob es den Airbag freigeben darf, und schaltet die Airbagleuchte ein.","u":[["h","Stecker am Gurtankersensor locker, korrodiert oder beim Verstellen des Sitzes abgezogen"],["m","Zweidrahtleitung zum Insassenerkennungsmodul unter dem Sitz gequetscht oder durchgescheuert"],["l","Sensorelektronik defekt, etwa nach Unfallbelastung des Gurts"]],"s":["Airbag-Warnleuchte leuchtet","Anzeige „Beifahrerairbag aus“ verhält sich mit Kindersitz oder Erwachsenem auf dem Sitz unerwartet","Sicherheitshinweis: Airbag- und Gurtstrafferstecker liegen nah; vor dem Trennen Batterie abklemmen und Wartezeit einhalten"],"k":["passenger_seatbelt_tension_sensor","occupant_detection_module","srs_seat_wiring","srs_control_module"],"r":["shop_only",0,[80,500],[0.5,2]],"f":"","x":["B0061","B0140","B0052"]},{"c":"B0184","t":"Heckgebläsemotor Stromkreis","e":"Rear Blower Motor Circuit","d":"Keine öffentliche J2012-Liste enthält B0184, und kein Hersteller dokumentiert ihn als Code für das hintere Gebläse. In der Klimaautomatik des Saab 9-3 gehört die Nummer dem Sonnensensor: B0184 06 bedeutet, dass dieser Kreis offen ist oder an Masse liegt; die Anlage regelt dann wie bei bedecktem Himmel. GMs Global-A-Modelle melden einen Fehler im Drehzahlkreis des hinteren Gebläses als B0208; das GM-Bulletin PIT5383A führt B0208 unter den Klimacodes mehrerer GM-Modelle des Jahrgangs 2015. Heckgebläse versorgen die zweite und dritte Sitzreihe in Vans und großen SUVs. Im Saab 9-5 von 2011 setzt ein Zusatz-Gebläsemodul ein PWM-Signal in 2 bis 13 V am Motor um; ist die Steuerleitung offen oder kurzgeschlossen, steht das hintere Gebläse. Ein Hyundai-Patent nennt für blockierte Klimamotoren einige hundert mA. Verwandt ist außerdem B0330.","u":[["h","Lange Leitung zum Heckgebläse unterbrochen oder kurzgeschlossen, oft an Karosseriestößen oder unter Verkleidungen"],["m","Zusatz-Gebläsemodul oder hinterer Vorwiderstand ausgefallen"],["m","Hinterer Gebläsemotor verschlissen oder durch angesaugten Schmutz blockiert"]],"s":["Aus den hinteren Dach- oder Fußraumdüsen kommt keine Luft","Fond bleibt im Sommer warm oder im Winter kalt, während vorn alles passt"],"k":["rear_blower_motor","rear_blower_resistor","hvac_control_module"],"r":["medium",1,[50,450],[0.5,2.5]],"f":"","x":["B0330","B0181","B0186"]},{"c":"B0186","t":"Frontgebläsemotor Drehzahl Bereich/Funktion","e":"Front Blower Motor Speed Performance","d":"B0186 steht nicht in den durchsuchten J2012-Listen, und kein Hersteller nutzt ihn für die Drehzahl des Frontgebläses. Saab ordnet ihn beim 9-3 dem Sonnensensor zu: B0186 01 ist ein Schluss nach Plus, danach rechnet die Klimaregelung mit bewölktem Wetter. Ein Drehzahl-Funktionsfehler unterscheidet sich von den Kreisfehlern B0181 und B0283: Die Leitungen sind heil, aber das Gebläse erreicht die befohlene Drehzahl nicht. Wie ein Gebläsemodul das per Hallsensor prüft, zeigt Densos US10300764B2: Steht der Rotor nach etwa 2,7 s noch, meldet es dem Klimasteuergerät einen blockierten Läufer, der Strom wird abgeschaltet und im Beispiel nach 20 s erneut versucht, höchstens fünfmal bis zum nächsten Start. US5554913A nennt die typische Ursache: angesaugte Fremdkörper verklemmen das Lüfterrad.","u":[["h","Laub oder andere Fremdkörper über den Lufteinlass angesaugt, bremsen oder verklemmen das Lüfterrad"],["m","Lager oder Kohlen des Gebläsemotors verschlissen, Motor läuft zu langsam oder bleibt stehen"],["l","Stark zugesetzter Innenraumfilter belastet den Motor"]],"s":["Gebläsedrehzahl passt nicht zur gewählten Stufe oder schwankt","Gebläse bleibt stehen und läuft nach einer Pause wieder an, teils mit Schleifgeräusch"],"k":["blower_motor","blower_resistor","cabin_air_filter"],"r":["medium",1,[30,350],[0.3,2]],"f":"","x":["B0181","B0283","B0184"]},{"c":"B0188","t":"Heckwischermotor Stromkreis","e":"Rear Wiper Motor Circuit","d":"B0188 lässt sich nicht nachweisen: Er steht in keiner öffentlich zugänglichen J2012-Liste und in keiner öffentlichen Herstellerunterlage. Die Bedeutung wiederholt B0910 („Wiper Motor Rear Circuit“). Bosch beschreibt das Bauteil: Anders als vorn hat der Heckwischer nur einen Arm, den der Antrieb direkt bewegt, bei 88 bis 177 Grad Wischwinkel und 250 bis 500 mm Radius. Motor und Leitungen liegen in der Heckklappe und müssen Scharnierbewegung und Feuchtigkeit aushalten. Audi führte ausgefallene oder aussetzende Heckwischer beim Q5 (2010–2015) auf Korrosion an der Verbindungsstelle B538 im Ansteuerkreis zurück; der Spannungsabfall trieb das Steuersignal aus dem zulässigen Bereich, repariert wurde die Verbindung. Ist der Kreis offen oder kurzgeschlossen, bleibt die Heckscheibe ungewischt.","u":[["h","Leitungen im Gummischlauch zwischen Karosserie und Heckklappe nach jahrelangem Öffnen gebrochen"],["m","Korrodierte Verbindungsstelle oder Stecker im Heckwischerkreis mit Spannungsabfall"],["m","Heckwischermotor festgegangen, etwa durch korrodierte Welle, oder innen kurzgeschlossen"]],"s":["Heckwischer bewegt sich nicht oder nur ab und zu","Heckwischer bleibt außerhalb seiner Ruhestellung stehen"],"k":["rear_wiper_motor","body_control_module","tailgate_harness"],"r":["medium",1,[30,300],[0.5,2]],"f":"","x":["B0910","B0190"]},{"c":"B0190","t":"Frontwischer Parkschalter Stromkreis","e":"Front Wiper Park Switch Circuit","d":"Keine bekannte öffentliche Quelle führt B0190 – weder eine J2012-Tabelle noch eine Herstellerunterlage. Das Bauteil ist verbreitet: Ein Nocken am Wischergetriebe öffnet oder schließt Kontakte; so erkennt die Steuerung die Ruhestellung und lässt den Motor bis dorthin weiterlaufen. Das Signal dient auch dem Schutz. In US5694011A schaltet ein Zeitglied, länger als ein Wischzyklus, den Motor ab, wenn sich das Parksignal nicht mehr ändert – so fallen festgefrorene Blätter auf. US4320329A wertet eine fehlende Parkstellung nach einem Zyklus als blockierten Motor und verlängert die Pause. Ein FCA-Patent, US8598828B2, filtert das Kontaktsignal gegen Störungen. Bei defektem Kreis bleiben die Wischer irgendwo stehen, laufen nach dem Ausschalten weiter, oder der Intervallbetrieb spinnt.","u":[["h","Parkkontakte im Getriebegehäuse des Wischermotors verschlissen, verschmutzt oder durch Wasser korrodiert"],["m","Parksignalleitung oder Stecker am Wischermotor unterbrochen oder kurzgeschlossen"],["l","Sicherung oder Relais im Parkstromkreis ausgefallen"]],"s":["Wischer bleiben im Sichtfeld statt unten an der Scheibe stehen","Wischer laufen nach dem Ausschalten weiter oder der Intervallbetrieb fällt aus"],"k":["wiper_motor","wiper_park_switch","body_control_module"],"r":["medium",1,[40,350],[0.5,2]],"f":"","x":["B0192","B0220","B0900"]},{"c":"B0192","t":"Frontwischer Geschwindigkeit Bereich/Funktion","e":"Front Wiper Speed Performance","d":"B0192 ist öffentlich nicht nachweisbar: Weder eine J2012-Liste noch ein Hersteller führt ihn. Ein Funktionsfehler heißt – anders als der Kreisfehler B0220 –, dass die Leitungen heil sein können, die Wischer aber zu langsam oder ungleichmäßig laufen. Gemessen wird das Tempo meist am Parkkontakt, der einmal je Umdrehung schließt. So arbeitet US5216340A bei Autos mit zwei Wischermotoren: Aus Zeitverlauf und Gegenspannung an den Parkkontakten erkennt die Schaltung den schnelleren Motor und bremst ihn kurz, bis beide gleich laufen. US5694011A zeigt den Extremfall: Festgefrorene Blätter belasten den Motor so, dass das Parksignal ausbleibt. Bosch bietet auch bürstenlose und reversierende Antriebe an, deren Elektronik Tempo und Endlagen selbst regelt. Folge: schmierendes, langsames oder ungleiches Wischen.","u":[["h","Gelenke des Wischergestänges trocken, korrodiert oder schwergängig, der Motor wird gebremst"],["m","Kohlen oder Kollektor des Motors verschlissen, Drehmoment und Tempo sinken"],["l","Wischblätter an der Scheibe festgefroren oder durch Schnee stark belastet"]],"s":["Wischer laufen spürbar langsamer als gewohnt, vor allem auf der schnellen Stufe","Wischerarme ruckeln, stocken oder laufen nicht im Gleichtakt"],"k":["wiper_motor","wiper_linkage"],"r":["medium",1,[30,350],[0.5,2]],"f":"","x":["B0220","B0190","B0900"]},{"c":"B0200","t":"Airbagsystem Versorgungsspannung außerhalb Bereich","e":"Air Bag System Voltage Out of Range","d":"B0200 ist öffentlich nicht dokumentiert: Keine öffentlich zugängliche J2012-Liste und kein Hersteller verwendet ihn so. Was der Titel beschreibt, gibt es aber. Ein Airbagsteuergerät hängt an der Bordbatterie und braucht stabile Spannung, um sicher auszulösen; Bosch gibt sein Nutzfahrzeuggerät für 8,5 bis 32 V an. Ein Energiereserve-Kondensator, dort 2 × 4,2 mF, hält es für eine festgelegte Autarkiezeit am Leben, wenn die Batterie beim Unfall abreißt (Bosch EP1526986B1). Systembausteine wie der Bosch CG903 überwachen ihre Spannungen und prüfen den Reservekondensator laufend. Ein Patent für ein Airbagsteuergerät (US20140142812A1) zeichnet auf, wie lange die Versorgung in einem Bereich lag, etwa bei Einbrüchen beim Starten. Liegt sie außerhalb, leuchtet die nach FMVSS 208 vorgeschriebene Bereitschaftsanzeige.","u":[["h","Schwache Batterie oder Ladefehler lässt die Bordspannung einbrechen, oft beim Starten"],["m","Schlechte Masse oder lockerer Versorgungskontakt am Stecker des Airbagsteuergeräts oder korrodierter Sicherungskontakt"],["l","Airbagsteuergerät defekt, etwa interne Versorgung oder Reservekondensator"]],"s":["Airbag-Warnleuchte an, manchmal nur nach Kaltstart oder Starthilfe","Weitere Steuergeräte speichern womöglich ebenfalls Unterspannungsfehler","Sicherheitshinweis: Airbags lösen bei diesem Fehler womöglich nicht aus; nur bei abgeklemmter Batterie und nach Wartezeit am System arbeiten"],"k":["srs_control_module","vehicle_battery","srs_power_circuit"],"r":["shop_only",0,[50,800],[0.5,3]],"f":"","x":["B00D2","B00D3"]},{"c":"B0205","t":"HVAC Defrosterklappe Position","e":"HVAC Defroster Door Position","d":"Für B0205 gibt es in den geprüften J2012-Listen keinen Eintrag, und kein Hersteller dokumentiert ihn für die Defrosterklappe; ein Kreis dieser Klappe hat den Code B0278. Saab legt den Defrostermotor des 9-3 unter B0240 06 und B0241 01 ab: Ist der Motorkreis offen, an Masse oder an Plus, stimmt die Luftverteilung nicht. Die Klappe lenkt Luft auf die Frontscheibe. Laut MOTOR-Magazin melden die meisten elektronischen Klimastellmotoren ihre Stellung über ein mitlaufendes Potentiometer als etwa 0 bis 5 V. Ältere Aufbauten kommen ohne aus: Bei Hitachi (CA1266779A) schaltet ein Zweistellungs-Stellmotor nur zwischen Belüftungsdüsen und Defroster um, und in US4819715A öffnet eine Klappe entweder die oberen Düsen oder die Defrosterdüse. Positionsfehler heißt: Die Klappe steht nicht wie befohlen.","u":[["h","Stellmotor der Defrosterklappe mit abgenutzten Zahnrädern oder verschlissenem Rückmeldepotentiometer"],["m","Klappe oder Gestänge schwergängig, gebrochen oder durch Fremdkörper blockiert"],["l","Rückmelde- oder Referenzleitung unterbrochen oder kurzgeschlossen"]],"s":["Im Entfrostungsbetrieb kommt wenig oder keine Luft an der Frontscheibe an","Luft kommt aus den falschen Düsen oder hinter dem Armaturenbrett klackt es"],"k":["hvac_defrost_actuator","hvac_control_module"],"r":["medium",1,[40,400],[0.5,3]],"f":"","x":["B0278","B0170","B0150"]},{"c":"B0210","t":"Regensensormodul","e":"Rain Sensor Module","d":"B0210 steht in keiner öffentlich zugänglichen J2012-Tabelle, und kein Hersteller dokumentiert ihn; verlorene oder ungültige Kommunikation mit einem Regensensormodul decken U0231 und U0532 ab. Der Sensor sitzt innen an der Frontscheibe im Wischfeld. Nach HELLA strahlen Leuchtdioden Infrarotlicht über ein Prisma in das Glas; bei trockener Scheibe wird es vollständig zu einer Fotodiode reflektiert, Tropfen lassen einen Teil austreten. Ein Gelkissen koppelt den Sensor optisch an die Scheibe, schlecht sitzend kann es Fehlfunktionen auslösen. Aus dem empfangenen Licht schätzt die Elektronik die Regenmenge und stellt das Intervall ein, bei starker Gischt auch die höchste Stufe. HELLAs vierte Generation erkennt zudem Schlieren und Schmutz. Fällt der Sensor aus, übernimmt das Wischermodul den normalen Intervallbetrieb.","u":[["h","Gelkissen gealtert oder mit Luftblasen, häufig nach einem Scheibentausch"],["m","Elektronik des Regensensors ausgefallen oder Feuchtigkeit im Gehäuse"],["l","Versorgungs- oder Datenleitung zum Sensor am Dachhimmel beschädigt"]],"s":["Automatisches Wischen reagiert nicht auf Regen oder wischt bei trockener Scheibe","Wischer arbeiten nur noch im festen Intervall oder in den Handstufen","Bei kombinierten Regen-Licht-Sensoren fällt womöglich auch die Fahrlichtautomatik aus"],"k":["rain_sensor","body_control_module","windshield"],"r":["medium",1,[60,400],[0.3,1.5]],"f":"","x":["U0231","U0532","B0192"]},{"c":"B0220","t":"Frontwischermotor Drehzahl Stromkreis","e":"Front Wiper Motor Speed Circuit","d":"Keine öffentlich zugängliche J2012-Liste und keine Herstellerunterlage enthält B0220; öffentlich ist der Code nicht nachweisbar. Der Kreis des Frontwischermotors selbst hat den Code B0900. Der Drehzahlkreis wählt zwischen langsamem und schnellem Wischen. Klassische Wischermotoren haben drei Kohlen: langsam, schnell und gemeinsam. Im Stand der Technik von Densos US6917173B2 speist ein Relais die Schnell-Kohle, ein MOSFET schaltet die Langsam-Kohle, beides vom Wischersteuergerät befohlen; das Patent ersetzt das durch einen Zweibürstenmotor mit PWM-Tastverhältnis, 100 % heißt schnell. Auch US5216340A zeigt Langsam- und Schnell-Kohle. Boschs bürstenloser EC-Antrieb braucht gar keine Kohlen. Ist die Drehzahlleitung offen, fällt eine Stufe aus; ein Kurzschluss kann die Wischer auf einem Tempo festhalten.","u":[["h","Relais für schnell/langsam oder dessen Kontakte im Sicherungskasten oder Steuergerät ausgefallen"],["m","Leitung oder Stecker zur Langsam- oder Schnell-Kohle des Motors unterbrochen oder kurzgeschlossen"],["m","Eine Drehzahlkohle im Wischermotor abgenutzt oder verbrannt"]],"s":["Wischer laufen nur noch in einer Stufe, langsam oder schnell","Wischer laufen in einer Stufe weiter und lassen sich nicht umschalten"],"k":["front_wiper_motor","body_control_module","wiper_relay"],"r":["medium",1,[30,350],[0.3,2]],"f":"","x":["B0192","B0190","B0900"]},{"c":"B0223","t":"Umluftklappe Stellbefehl 1 Stromkreis","e":"Recirculate Position Command 1 Circuit","d":"B0223 steht in keiner öffentlich zugänglichen J2012-Liste, General Motors nutzt ihn aber für den Stellmotor der Umluftklappe. In Saab 9-5 und 9-4X von 2011 (GM Global A) ist das ein Schrittmotor mit vier Steuerleitungen; B0223 01 heißt, Steuerkreis 1 hat Schluss nach Plus, B0223 06, er ist offen oder führt zu wenig Spannung. Das Steuergerät prüft die Ausgänge nur beim Anlaufen des Motors, nicht während der Fahrt der Klappe oder in Zielstellung; danach schaltet es den Ausgang ab und legt den Motor still. B022A ist der zweite Umluft-Stellkreis. Das GM-Bulletin PIT5383A für Buick-, Cadillac-, Chevrolet- und GMC-Modelle des Jahrgangs 2015 nennt B0223 unter den Klimacodes und eine nicht funktionierende Umluft; abgestellt wird das durch Neuprogrammieren des Klimasteuergeräts. Die frühere Bedeutung Airbag-Warnleuchte gehört in J2012 zu B00D2.","u":[["h","Schrittmotor der Umluftklappe defekt oder dessen Zahnräder ausgeschlagen"],["m","Steuerleitung 1 zum Stellmotor unterbrochen, an Masse oder mit Batteriespannung kurzgeschlossen"],["l","Software des Klimasteuergeräts wie im GM-Bulletin PIT5383A oder dessen Endstufe"]],"s":["Umluft lässt sich nicht ein- oder ausschalten","Scheiben beschlagen oder Außengerüche dringen ein, weil die Klappe festsitzt"],"k":["recirculation_door_actuator","hvac_control_module"],"r":["medium",1,[40,350],[0.5,2]],"f":"","x":["B0273","B0175","B00D2"]},{"c":"B0226","t":"Leuchtweitenregelung Sensor vorn","e":"Headlamp Auto-Leveling Front Sensor","d":"In den geprüften J2012-Listen fehlt B0226, und kein Hersteller dokumentiert ihn für die Leuchtweitenregelung. Saab nutzt die Nummer in der Klimaautomatik des 9-3: B0226 01 ist ein Schluss nach Plus im Kreis des Umluftmotors, mit möglicher Folge verbrauchter Luft oder beschlagener Scheiben. Die automatische Leuchtweitenregelung hält laut HELLA die Hell-Dunkel-Grenze trotz Beladung gleich: Ein Steuergerät vergleicht Achssensoren vorn und hinten mit Sollwerten und verstellt Stellmotoren in den Scheinwerfern; dynamische Anlagen, bei Xenonlicht fast immer verbaut, gleichen auch Bremsen und Beschleunigen aus. Kompaktwagen haben oft keinen vorderen Sensor. Jeder Achssensor ist ein Winkelgeber mit Hebel am Querlenker, älter mit Potentiometer, neuer induktiv. Fällt er aus, bleibt der Lichtkegel stehen.","u":[["h","Hebel oder Koppelstange des vorderen Achssensors verbogen, gebrochen oder ausgehängt"],["m","Stecker oder Leitung am Sensor durch Spritzwasser korrodiert oder beschädigt"],["m","Sensor innen verschlissen oder nach Tausch bzw. Fahrwerksarbeiten nicht angelernt"]],"s":["Warnung der Leuchtweitenregelung erscheint und die Leuchtweite passt sich nicht mehr an","Entgegenkommende blinken auf, weil der Lichtkegel bei Beladung zu hoch steht"],"k":["front_ride_height_sensor","headlamp_leveling_module","body_control_module"],"r":["medium",0,[80,450],[0.5,2]],"f":"","x":["U0181","U0482"]},{"c":"B0228","t":"Nebelscheinwerfer vorn Stromkreis","e":"Front Fog Lamp Circuit","d":"In den öffentlich zugänglichen J2012-Listen fehlt B0228, und als Nebelscheinwerfer-Code veröffentlicht ihn kein Hersteller. GM vergibt die Nummer allerdings in der Klimaregelung: Das Bulletin PIT5383 nennt B0228 unter den Klimacodes von Cadillac-, Chevrolet- und GMC-Modellen des Jahrgangs 2015, deren K33-Klimasteuergerät neue Software brauchte; den genauen Wortlaut veröffentlicht GM nicht. Nach dem Titel geht es um die Ansteuerung der vorderen Nebelscheinwerfer. Im Patent US8125101B1 legt der Nebellichtschalter eigene Signalleitungen an Masse, die direkt auf die Nebellichtrelais wirken; in US7230350B2 verschiebt ein Nebellichtschalter die Spannung an der Widerstandskette des Lichtschalters, worauf das Steuergerät die Nebelfunktion zuschaltet. Bei einem Kreisfehler bleiben die Leuchten dunkel, oder die Anforderung kommt nicht an.","u":[["h","Nebellichtrelais oder Sicherung defekt, die Leuchten bekommen trotz eingeschaltetem Schalter keinen Strom"],["m","Tief verlegter Kabelstrang im vorderen Stoßfänger abgerissen oder korrodiert, oft nach Parkrempler oder Wassereintritt"],["m","Leuchtmittel durchgebrannt oder Scheinwerfergehäuse durch gerissene Abdeckscheibe vollgelaufen"],["l","Nebellichtstellung des Lichtschalters verschlissen oder ihre Signalleitung unterbrochen"]],"s":["Vordere Nebelscheinwerfer bleiben trotz eingeschaltetem Schalter dunkel","Kontrollleuchte für Nebellicht leuchtet, aber nur eine oder keine Leuchte brennt"],"k":["front_fog_lamp","fog_lamp_relay","body_control_module"],"r":["easy",1,[20,250],[0.3,1.5]],"f":"","x":["B0240","B0800"]},{"c":"B0231","t":"Vordere Begrenzungsleuchte Stromkreis","e":"Front Marker Lamp Circuit","d":"Für B0231 gibt es weder einen J2012-Eintrag noch öffentliche Herstellerangaben; der Code bleibt unbelegt. Der Titel meint die vorderen Begrenzungs- bzw. Positionsleuchten. FMVSS 108 versteht unter Seitenmarkierungsleuchten Leuchten nahe der vorderen und hinteren Fahrzeugkante, die von der Seite die Länge des Fahrzeugs zeigen. HELLA führt vordere Begrenzungsleuchten als weiß, bei gelben Scheinwerfern gelb, und als Pflicht ab 1600 mm Fahrzeugbreite. Sie brennen meist in der Parklichtstellung des Lichtschalters. Ein Steuergerät, das sie elektronisch schaltet, kann eine fehlende Last erkennen: Im Ford-Patent US4667187A wird jede Leuchte für etwa 300 µs umgeschaltet; folgt keine Stromänderung, gilt der Kreis als fehlerhaft. Folge: eine dunkle Leuchte und, wo vorhanden, eine Lampenwarnung.","u":[["h","Glühlampe oder LED-Modul der Begrenzungsleuchte ausgefallen"],["m","Korrodierte Lampenfassung oder Stecker im Scheinwerferbereich, wo Spritzwasser hinkommt"],["l","Versorgungs- oder Masseleitung zur vorderen Leuchte unterbrochen oder kurzgeschlossen"]],"s":["Eine vordere Begrenzungs- oder Positionsleuchte bleibt bei Standlicht dunkel","Lampenausfall-Warnung im Kombiinstrument, sofern vorhanden"],"k":["marker_lamp","body_wiring_harness"],"r":["easy",1,[10,120],[0.2,1]],"f":"","x":["B0239","B0830"]},{"c":"B0233","t":"Luftverteilungssteuerung Stromkreis","e":"Air Flow Control Circuit","d":"Öffentliche J2012-Listen lassen B0233 aus, GM vergibt ihn aber in der Global-A-Klimaregelung für den Stellmotor der Luftverteilung. Beim Saab 9-5 und 9-4X des Modelljahrs 2011 ist das ein Schrittmotor: Das Klimasteuergerät versorgt ihn mit 12 V Referenz und legt seine vier Spulen taktweise an Masse. B0233 01 heißt, eine seiner Steuerleitungen hat Schluss nach Plus, B0233 06, eine Leitung ist offen oder führt zu wenig Spannung. Geprüft werden die Ausgänge nur beim Anlaufen einer Bewegung, nicht während der Fahrt oder in Zielstellung. Das GM-Bulletin PIT5383 nennt B0233 unter den Klimacodes von 2015er Modellen, bei denen eine Neuprogrammierung des K33-Steuergeräts half. Der hintere Verteilungssteller meldet sich stattdessen mit B3531. Fällt der vordere Steller aus, kommt die Luft weiter aus den zuletzt gewählten Düsen.","u":[["h","Schrittmotor der Luftverteilung intern defekt, etwa Spule durchgebrannt oder Getriebe verschlissen"],["m","Eine der vier Steuerleitungen oder die 12-V-Referenz hinter dem Armaturenbrett durchgescheuert, offen oder kurzgeschlossen"],["l","Softwarefehler im Klimasteuergerät bei betroffenen GM-Modellen, behoben durch Neuprogrammierung"]],"s":["Luft kommt aus den falschen Düsen, die gewählte Verteilung wird ignoriert","Frontscheibe lässt sich nicht freiblasen, weil die Luft nicht auf Defrost umschaltet"],"k":["mode_door_actuator","hvac_control_module"],"r":["medium",1,[60,450],[0.5,3]],"f":"","x":["B0268","B0150","B0170"]},{"c":"B0235","t":"Bremsleuchte Stromkreis","e":"Brake Lamp Circuit","d":"Keine öffentlich zugängliche J2012-Liste enthält B0235, und kein Hersteller dokumentiert ihn; der Code ist öffentlich nicht nachweisbar. Seitengenaue Bremslicht-Codes sind B0850 und B0851. Bremsleuchten zeigen nach hinten ein ruhiges rotes Signal, solange gebremst wird; FMVSS 108 verlangt dazu eine hochgesetzte dritte Bremsleuchte. Ausgelöst werden sie vom Bremslichtschalter am Pedal, direkt oder über ein Karosseriesteuergerät. HELLA beschreibt einen Golf V, bei dem eine 21-W-Lampe als Schlusslicht mit einem PWM-Signal von rund 5,7 V und als Bremslicht mit vollen 13,5 V arbeitet; ein Leitungsfehler trifft dort beide Funktionen. Beim Mitsubishi Grandis ließ Feuchtigkeit im Bremslichtschalter sogar die Warnleuchten von Traktions- und Stabilitätsregelung angehen. Fehlt das Bremslicht, steigt die Gefahr eines Auffahrunfalls.","u":[["h","Bremslichtlampe oder LED-Einheit ausgefallen"],["m","Bremslichtschalter verstellt, verschlissen oder innen feucht"],["m","Sicherung durchgebrannt oder Leitung gebrochen, oft im Kabelstrang zur Heckklappe oder zum Kofferraumdeckel"],["l","Korrodierte Lampenfassung oder Stecker in der Heckleuchte"]],"s":["Eine oder mehrere Bremsleuchten bleiben beim Treten des Pedals dunkel","Lampenwarnung erscheint, teils zusammen mit Warnleuchten von Traktions- oder Stabilitätsregelung","Sicherheitshinweis: Nachfolgende sehen kein Bremssignal; vor der Weiterfahrt reparieren"],"k":["brake_lamp","brake_light_switch","body_wiring_harness"],"r":["easy",1,[10,200],[0.2,1.5]],"f":"","x":["B0850","B0851"]},{"c":"B0237","t":"Rückfahrleuchte Stromkreis","e":"Backup Lamp Circuit","d":"B0237 taucht weder in einer öffentlichen J2012-Liste noch in öffentlichen Herstellerunterlagen auf; belegbar ist er nicht. Nach FMVSS 108 beleuchten Rückfahrleuchten die Fahrbahn hinter dem Auto und warnen Fußgänger und andere Fahrer, dass es zurücksetzt oder gleich zurücksetzen wird. HELLA weist darauf hin, dass der Kreis nur bei eingeschalteter Zündung und eingelegtem Rückwärtsgang Spannung führen darf. Schaltgetriebe schließen im Rückwärtsgang einen Stößelschalter, bei Automatikgetrieben liefert der Wählhebelsensor oder das Getriebesteuergerät das Signal. Im Patent US5065135A von Automotive Products wertet eine Logik die Wählstellung aus und zieht ein Relais an, das die Leuchte versorgt, solange Rückwärts gemeldet wird. Bei einem Fehler bleiben die Leuchten im Rückwärtsgang dunkel oder brennen bei Schluss nach Plus auch sonst.","u":[["h","Rückfahrscheinwerferschalter am Getriebe verschlissen oder sein Stecker durch Spritzwasser korrodiert"],["m","Glühlampe der Rückfahrleuchte durchgebrannt oder LED-Einheit ausgefallen"],["l","Fehlendes Rückwärtssignal von Wählhebelsensor oder Getriebesteuergerät bei Automatik"],["l","Gebrochene Leitung im Kabelstrang der Heckklappe zur Leuchte"]],"s":["Rückfahrleuchten bleiben bei eingelegtem Rückwärtsgang dunkel","Rückfahrleuchten brennen auch bei Vorwärtsfahrt"],"k":["backup_lamp","reverse_switch","body_wiring_harness"],"r":["easy",1,[10,180],[0.2,1.5]],"f":"","x":["B0239","B0235"]},{"c":"B0239","t":"Kennzeichenleuchte Stromkreis","e":"License Plate Lamp Circuit","d":"B0239 findet sich in keiner J2012-Quelle und keinem Werksdokument; seine Verwendung ist unbewiesen. Denselben Titel trägt B0860. Die Kennzeichenleuchte beleuchtet das hintere Nummernschild und hängt meist am Schlusslichtkreis. FMVSS 108 verlangt, dass sie das Schild ohne Abschattung durch Karosserieteile ausleuchtet. HELLA nennt die europäische Vorgabe, dass das Kennzeichen aus 25 m lesbar sein und auf ganzer Fläche mindestens 2,5 cd/m² erreichen muss. Karosseriesteuergeräte überwachen heute ihre Lichtausgänge; HELLAs Golf-6-Beispiel zeigt die Kehrseite: Nach dem Einbau von LED-Heckleuchten muss das Steuergerät umcodiert werden, sonst meldet es Lampenfehler. Ein Kreisfehler lässt das Kennzeichen dunkel, was zu einer Polizeikontrolle führen kann.","u":[["h","Glühlampe oder LED-Einheit der Kennzeichenleuchte ausgefallen, oft durch Wasser im Gehäuse"],["m","Leitung im Schutzschlauch zwischen Karosserie und Heckklappe oder Kofferraumdeckel gebrochen"],["l","Nachgerüstete LED-Leuchte passt nicht zur Codierung des Karosseriesteuergeräts"]],"s":["Hinteres Kennzeichen ist bei eingeschaltetem Licht nicht beleuchtet","Lampenwarnung im Kombiinstrument, sofern diese Leuchte überwacht wird"],"k":["license_plate_lamp","body_wiring_harness"],"r":["easy",1,[10,100],[0.2,1]],"f":"","x":["B0860","B0237"]},{"c":"B0240","t":"Scheinwerferschalter Stromkreis","e":"Headlamp Switch Circuit","d":"Die J2012-Quellen kennen B0240 nicht, und kein Hersteller setzt ihn für den Lichtschalter ein; den gleichen Titel trägt B0800. Saab vergibt die Nummer anders: In der Klimaautomatik des 9-3 bedeutet B0240 06, dass der Kreis des Defrost-Klappenmotors offen ist oder an Masse liegt, mit falscher Luftverteilung als Folge; B0241 01 meldet Schluss nach Plus an diesem Motor. Nach dem Titel betrifft der Code den Eingang des Lichtschalters. Heutige Schalter führen selten den Lampenstrom. In US7230350B2 erhält jede Stellung (Auto, Aus, Standlicht, Abblendlicht) über eine Widerstandskette ein eigenes Spannungsband, das ein 8-Bit-Wandler liest; die Bänder halten Abstand zu 0 und 255, damit Masse- oder Plusschluss in keines fällt. US8125101B1 wählt dann die Lichtfunktion, die dem Fahrerwunsch am nächsten kommt.","u":[["h","Verschlissene oder verschmutzte Kontakte bzw. Widerstandsbahn im Lichtschalter"],["m","Stecker des Schalters hinter der Armaturenbrettblende locker oder korrodiert"],["l","Signalleitung zum Karosseriesteuergerät mit Masse- oder Plusschluss"]],"s":["Licht folgt der Schalterstellung nicht oder fällt in eine feste Ersatzstellung","Lichtautomatik oder Standlicht lässt sich nicht wählen"],"k":["headlamp_switch","body_control_module"],"r":["medium",1,[50,400],[0.5,2]],"f":"","x":["B0800","B0228","B0278"]},{"c":"B0245","t":"Fahrer-Fensterheberschalter Stromkreis","e":"Driver Window Switch Circuit","d":"B0245 steht in keiner öffentlichen J2012-Liste, und kein Hersteller dokumentiert ihn; öffentlich nachweisbar ist er nicht. Fehler am Fensterheber des Fahrers haben den Code B0500. In der Fahrertür sitzt meist der Hauptschalterblock, der das eigene Fenster und über Signalleitungen oder einen Bus auch die anderen Türen steuert. Im Honda-Patent US7145299B2 ersetzt eine einzige Leitung die zwei dicken Drähte je Tür: Der Hauptschalter legt sie für Auf an Plus, für Ab an Masse und lässt sie zum Anhalten offen; so belasten weder Kontaktabbrand noch Relaisspitzen den Schalter. Ein Kreiscode bedeutet hier, dass das Steuergerät einen unmöglichen Schalterzustand sieht, etwa einen durch Korrosion dauerhaft geschlossenen Kontakt oder eine gebrochene Leitung. Selbsttätig schließende Fenster müssen nach FMVSS 118 vor 100 N Klemmkraft umkehren.","u":[["h","Kontakte im Hauptschalter korrodiert oder klemmend, oft nachdem Getränke oder Regen in die Türverkleidung kamen"],["m","Leitungen in der Gummitülle zwischen Karosserie und Fahrertür gebrochen"],["l","Stecker des Schalterblocks locker oder mit zurückgeschobenen Kontakten"]],"s":["Fahrerfenster oder andere Fenster reagieren nicht auf den Hauptschalter","Ein Fenster fährt von selbst oder die Antippfunktion arbeitet fehlerhaft"],"k":["window_switch","door_wiring_harness","body_control_module"],"r":["easy",1,[30,250],[0.5,1.5]],"f":"","x":["B0247","B0252","B0500"]},{"c":"B0247","t":"Beifahrer-Fensterheberschalter Stromkreis","e":"Passenger Window Switch Circuit","d":"B0247 steht in keiner der geprüften J2012-Quellen, und kein Hersteller veröffentlicht ihn; Kreisfehler am Beifahrerfenster haben den Code B0501. Der Beifahrerschalter ist der einfachere Partner des Hauptschalters in der Fahrertür: Er bewegt nur sein eigenes Fenster, und der Fahrer kann ihn übersteuern oder sperren. Im Honda-Patent US7145299B2 liegen die eigenen Auf- und Ab-Taster der Beifahrertür parallel zu deren Treibertransistoren und arbeiten deshalb auch, wenn die Leitung vom Hauptschalter ruht; befiehlt der Fahrer Auf, während der Beifahrer Ab drückt, nimmt ein Relais eine Motorklemme von Masse. Ein Kreiscode deutet daher auf den Beifahrerschalter, seinen Stecker in der Tür oder die Leitung zum Hauptschalter. FMVSS 118 regelt, wann sich ein solches Fenster ohne Zündschlüssel bewegen darf.","u":[["h","Fensterheberschalter auf der Beifahrerseite verschlissen oder verschmutzt"],["m","Signalleitung zwischen Beifahrertür und Hauptschalter am Türscharnier gebrochen"],["l","Fenstersperrtaste am Hauptschalter hängt oder ihr Kreis ist defekt"]],"s":["Beifahrerfenster lässt sich vom Fahrerschalter bedienen, aber nicht vom eigenen Schalter","Beifahrerschalter bewegt das Fenster nur in eine Richtung"],"k":["window_switch","door_wiring_harness"],"r":["easy",1,[25,200],[0.5,1.5]],"f":"","x":["B0245","B0501"]},{"c":"B0250","t":"Innenraum-Lufttemperatursensor (HVAC) Stromkreis","e":"HVAC Air Temperature Internal Sensor Circuit","d":"Unter den durchsuchten J2012-Listen enthält keine B0250. Saab nutzt die Nummer, allerdings für einen Stellmotor: In der Klimaautomatik des 9-3 bedeutet B0250 06, dass der Kreis des Fußraum-Klappenmotors offen ist oder an Masse liegt, was die Luftverteilung stört; B0251 01 steht für den Plusschluss. Dem Titel nach geht es um den Innenraumtemperaturfühler, der auch den Code B0160 hat. Solche Fühler sind NTC-Elemente (HELLA): Ihr Widerstand sinkt, wenn sie wärmer werden. Damit der Fühler echte Kabinenluft misst und nicht stehende Luft hinter dem Armaturenbrett, saugt im TGK-Patent US6622924B2 ein kleiner bürstenloser Lüfter Luft am Thermistor vorbei und meldet seine Drehung über einen eigenen Pin. Fällt der Kreis aus, regelt die Klimaautomatik mit einem Ersatzwert, und der Innenraum wird zu warm oder zu kalt.","u":[["h","Stecker oder Leitung des Fühlers hinter dem Armaturenbrett offen oder mit Masseschluss"],["m","NTC-Element im Fühler beschädigt"],["l","Ansauglüfter festgegangen oder Ansauggitter verstopft, der Messwert hinkt der Innenraumtemperatur hinterher"]],"s":["Klimaautomatik hält eine falsche Innenraumtemperatur","Gebläsestufe und Ausblastemperatur passen sich beim Aufheizen nicht mehr an"],"k":["cabin_air_temperature_sensor","hvac_control_module"],"r":["easy",1,[40,220],[0.3,1.5]],"f":"","x":["B0160","B0255","B0164"]},{"c":"B0252","t":"Fahrer-Fensterhebermotor Abwärts Stromkreis","e":"Driver Window Motor Down Circuit","d":"Zu B0252 gibt es weder einen J2012-Eintrag noch eine Werksbeschreibung; der Code ist unbestätigt. Der Titel nennt eine Laufrichtung des Fensterhebermotors in der Fahrertür. Ein umpolbarer Gleichstrommotor bewegt die Scheibe; der Abwärtszweig ist die Hälfte der Ansteuerung, die eine Motorklemme an Plus und die andere an Masse legt. Im Patent US6906487B2 (International Rectifier, heute Infineon) bilden zwei intelligente High-Side-Schalter und zwei Low-Side-MOSFETs diese H-Brücke, messen den Motorstrom und schalten bei Kurzschluss oder Überhitzung ab. Fällt nur der Abwärtszweig aus, schließt das Fenster noch, öffnet aber nicht – ein Hinweis auf eine Treiberstufe, einen Relaiskontakt oder eine Motorleitung. Der Einklemmschutz nach FMVSS 118 fährt die Scheibe nach unten zurück und fällt damit ebenfalls aus.","u":[["h","Relaiskontakt oder Treibertransistor für Abwärts im Türsteuergerät verbrannt"],["m","Eine Motorleitung in der Tür oder am Motorstecker gebrochen"],["l","Verschlissene Motorbürsten oder Kollektor mit Totpunkt in einer Richtung"]],"s":["Fahrerfenster schließt, fährt aber nicht nach unten","Einklemmschutz oder automatisches Öffnen funktioniert nicht mehr"],"k":["window_motor","door_wiring_harness"],"r":["medium",1,[80,500],[0.5,2.5]],"f":"","x":["B0245","B0500"]},{"c":"B0255","t":"Außentemperatursensor (HVAC) Stromkreis","e":"HVAC Air Temperature External Sensor Circuit","d":"B0255 taucht in keiner herangezogenen J2012-Quelle auf. Saab verwendet ihn beim 9-3 für einen Klappenmotor: B0255 06 meldet den Kreis des rechten Belüftungsklappenmotors offen oder an Masse, B0256 01 Schluss nach Plus. Nach dem Titel geht es um den Außentemperaturfühler; dieses Bauteil hat auch die Codes B0158 und B0159. Der Außenfühler von HELLA ist ein NTC-Widerstand in einem Spannungsteiler, ausgelegt für −40 bis +65 °C mit einer Zeitkonstante unter 35 s; das Steuergerät rechnet seinen Widerstand über die Kennlinie in eine Temperatur um. Hinter dem Kühlergrill oder unter einem Spiegel leidet er unter Steinschlag, Salz und eingeklemmten Leitungen. Die Klimaregelung wählt mit dem Wert Betriebsart und Gebläse; ein Fehler bedeutet schlechte Regelung und eine leere oder falsche Außentemperaturanzeige.","u":[["h","Außenfühler durch Steinschlag beschädigt oder durch Streusalz korrodiert"],["m","Fühlerleitung hinter dem Stoßfänger gequetscht oder abgerissen, oft nach Frontreparaturen"],["l","Feuchtigkeit im Fühlerstecker verfälscht den gemessenen Widerstand"]],"s":["Außentemperaturanzeige zeigt Striche oder einen unplausiblen Wert","Klimaautomatik regelt schlecht, vor allem bei Kälte oder Hitze"],"k":["ambient_temperature_sensor","hvac_control_module"],"r":["easy",1,[25,150],[0.2,1]],"f":"","x":["B0158","B0159","B0250"]},{"c":"B0258","t":"HVAC Mischklappe 1 Stromkreis","e":"HVAC Air Mix Door 1 Circuit","d":"B0258 findet sich weder in den öffentlichen J2012-Listen noch in öffentlichen Herstellerunterlagen; der Code lässt sich nicht nachweisen. GMs Global-A-System meldet den linken bzw. Haupt-Temperatursteller stattdessen unter B0408, wie das Handbuch des Saab 9-5 von 2011 zeigt. Mischklappe 1 ist in der Regel die Haupt- oder Fahrerseiten-Klappe und teilt die Luft zwischen Heizungswärmetauscher und Umgehung auf. In Zweizonen-Geräten hat jede Seite eigene Klappen: Valeo setzt in US6484755B1 beide Zonensteller auf dieselbe Gehäuseseite, damit ein Zugang für beide reicht. Meist ist der Steller ein umpolbarer Gleichstrommotor, dessen Getriebe ein Potentiometer mitnimmt; dessen Rückmeldung liegt laut MOTOR-Magazin zwischen etwa 0 und 5 V. Bei einem Kreisfehler bleibt die Klappe stehen, und die Ausblastemperatur folgt der Einstellung nicht mehr.","u":[["h","Motor des Mischklappenstellers oder sein Rückmeldepotentiometer ausgefallen"],["m","Stecker oder Leitungen des Stellers unter dem Armaturenbrett locker, durchgescheuert oder kurzgeschlossen"],["l","Klappe durch Fremdkörper oder gebrochene Welle blockiert, die Motoransteuerung wird überlastet"]],"s":["Luft aus den Düsen bleibt heiß oder kalt, egal welche Temperatur eingestellt ist","Klicken oder Klopfen hinter dem Armaturenbrett beim Verstellen der Temperatur"],"k":["hvac_air_mix_actuator","hvac_control_module"],"r":["medium",1,[80,500],[1,4]],"f":"","x":["B0263","B0168"]},{"c":"B0260","t":"Innenraumbeleuchtung Stromkreis","e":"Interior Light Circuit","d":"Keine öffentlich zugängliche J2012-Liste enthält B0260 mit dieser Bedeutung; denselben Titel trägt B0970. Beim Saab 9-3 des Jahrgangs 2003 gehört die Nummer zur Klimaanlage: B0260 06 steht für einen offenen oder an Masse liegenden Kreis des linken Belüftungsklappenmotors, B0261 01 für Plusschluss. Gemeint ist laut Titel die Versorgung der Innenleuchten. Türkontaktschalter legen beim Öffnen einen Eingang an Masse; im Ford-Patent US6133827A schaltet ein Steuergerät daraufhin Decken- und Fußraumleuchten ein, lässt sie nach dem Schließen der letzten Tür 25 s nachleuchten und trennt sie nach 40 Minuten über ein Batterieschutzrelais. Die Betriebsanleitung des Ram nennt eine Abschaltung nach 10 Minuten bei offener Tür. Ein Kreisfehler bedeutet Leuchten, die dunkel bleiben, nie ausgehen oder über Nacht die Batterie leeren.","u":[["h","Türkontakt- oder Schlosskontaktschalter hängt, das Steuergerät sieht eine offene Tür"],["m","Leuchtenversorgung im Dachhimmel kurzgeschlossen oder Leuchte mit Wasserschaden"],["l","Batterieschutzrelais oder Endstufe im Karosseriesteuergerät defekt"]],"s":["Innenleuchten gehen beim Öffnen einer Tür nicht an","Innenleuchten bleiben an, oder die Batterie ist nach einer Nacht leer"],"k":["interior_lamp","door_jamb_switch","body_wiring_harness"],"r":["easy",1,[10,180],[0.2,1.5]],"f":"","x":["B0970","B0540","B0510"]},{"c":"B0263","t":"HVAC Mischklappe 2 Stromkreis","e":"HVAC Air Mix Door 2 Circuit","d":"B0263 fehlt wie sein Geschwister B0258 in den geprüften J2012-Listen, und kein Hersteller veröffentlicht ihn. Die zweite Mischklappe bedient meist die Beifahrerseite oder die Fondzone. GMs Global-A-Klimaregelung, wie sie die Saab-Unterlagen zu 9-5 und 9-4X zeigen, führt den rechten Temperatursteller unter B0418 und den hinteren unter B0428; beide sind Schrittmotoren, die auf Plusschluss und Unterbrechung geprüft werden. Manche Bauarten sparen den zweiten Motor: Im Denso-Patent US7793706B2 bewegt ein einziger Servomotor über Kurvenscheiben und eine Wippe die vordere Klappe und ein hinteres Klappenpaar, ein Defekt träfe dort beide Zonen. Fällt der Kreis der zweiten Klappe aus, bleibt die Beifahrer- oder Fondseite auf fester Temperatur, während die Fahrerseite weiter regelt.","u":[["h","Mischklappensteller der Beifahrerseite oder des Fonds ausgefallen"],["m","Leitung zum zweiten Steller offen oder kurzgeschlossen, oft im Bereich der Mittelkonsole"],["l","Gemeinsames Gestänge oder Klappenwelle gebrochen, die Ansteuerung wird überlastet"]],"s":["Beifahrerseite oder Fonddüsen bleiben auf einer Temperatur, egal was eingestellt ist","Deutlicher Temperaturunterschied zwischen linken und rechten Düsen"],"k":["hvac_air_mix_actuator_2","hvac_control_module"],"r":["medium",1,[80,500],[1,4]],"f":"","x":["B0258","B0168"]},{"c":"B0265","t":"Fahrertür Verriegelungs-/Entriegelungsschalter Stromkreis","e":"Driver Door Lock/Unlock Switch Circuit","d":"B0265 steht in keiner geprüften J2012-Liste und in keinen öffentlichen Herstellerunterlagen; nachweisen lässt er sich nicht. Verwandt sind B0270 und B0272. Die Ver-/Entriegelungstaste in der Fahrertür fordert beim Karosserie- oder Türsteuergerät an, alle Schlossmotoren zu betätigen, wie HELLAs Übersicht zur Zentralverriegelung beschreibt. Im Sumitomo-Patent US6365986B1 zieht der Schalter einen von zwei hochgelegten Eingängen auf Masse, und das Steuergerät reagiert auf den Wechsel von High nach Low statt auf den Pegel; nach einem Reset nimmt es an, der Schalter sei gedrückt, damit kein zweiter, falscher Schließvorgang folgt. Ein Kreisfehler bedeutet daher eine dauerhaft auf Masse liegende Leitung, die andere Befehle blockieren oder die Schlösser takten lassen kann, oder eine offene Leitung, die die Taste wirkungslos macht.","u":[["h","Ver-/Entriegelungstaste klemmt oder ist durch Feuchtigkeit in der Türverkleidung kurzgeschlossen"],["m","Schalterleitungen in der Tülle zwischen Karosserie und Fahrertür gebrochen"],["l","Eingangsstufe im Karosserie- oder Türsteuergerät beschädigt"]],"s":["Türen lassen sich mit der Innentaste nicht ver- oder entriegeln","Schlösser schalten von selbst oder reagieren nicht auf die Funkfernbedienung"],"k":["door_lock_switch","body_control_module","door_harness"],"r":["medium",1,[40,300],[0.5,2]],"f":"","x":["B0270","B0272","B0530"]},{"c":"B0268","t":"HVAC Modusklappe 1 Stromkreis","e":"HVAC Mode Door 1 Circuit","d":"B0268 steht in keiner der geprüften J2012-Listen, General Motors nutzt die Nummer aber: Das Bulletin PIP5094 für GM-Pkw und leichte Nutzfahrzeuge bis Baujahr 2014 führt sie in seiner Stichwortliste von Karosseriecodes, ohne Klartext. Die Betriebsartklappe lenkt die Luft zu den Gesichtsdüsen, in den Fußraum oder auf die Frontscheibe. GMs späteres Global-A-System meldet den Betriebsartsteller unter B0233; für diese Klappe gibt es zudem B0150 und B0170. Laut MOTOR-Magazin sind solche Steller oft ein Gleichstrommotor mit mitlaufendem Potentiometer, das etwa 0 bis 5 V liefert; neuere zählen stattdessen Kollektorimpulse. Im Patent US4819715A von Nissan Shatai stellt ein Stellmotor eine Klappe so, dass entweder die oberen Düsen, der Defroster oder keins von beiden offen ist. Ein Kreisfehler lässt die Klappe in ihrer letzten Stellung stehen.","u":[["h","Motor oder Stellungsrückmeldung des Betriebsartstellers ausgefallen"],["m","Steller fährt über den Anschlag oder klemmt an der Klappe und überlastet die Ansteuerung"],["l","Stecker oder Leitung des Stellers hinter dem Armaturenbrett offen oder kurzgeschlossen"]],"s":["Luft bleibt auf einer Düsengruppe, etwa Defrost, egal welche Betriebsart gewählt ist","Ein Druck auf die Betriebsarttaste ändert nicht mehr, wo die Luft austritt"],"k":["hvac_mode_actuator","hvac_control_module"],"r":["medium",1,[80,500],[1,4]],"f":"","x":["B0150","B0170","B0233","B0278"]},{"c":"B0270","t":"Beifahrertür Verriegelungsschalter Stromkreis","e":"Passenger Door Lock Switch Circuit","d":"Für B0270 fehlt jeder öffentliche Beleg: Er steht in keiner der geöffneten J2012-Listen, und kein Hersteller beschreibt ihn. Gemeint ist laut Titel die Ver-/Entriegelungswippe in der Beifahrertür. Saab führt diesen Taster beim 9-3 (2003–2012) unter der eigenen Nummer B3270: Liest das Beifahrertürmodul eine Masseverbindung auf der Schalterleitung, wird die Taste verworfen, und die Zentralverriegelung gehorcht nur noch den übrigen Bedienelementen. Bei der masseschaltenden Eingangsstufe aus US5619075A zieht der gedrückte Taster den Moduleingang auf Masse. Ein Kreisfehler bedeutet also: Das Modul sieht eine dauernd gedrückte, nie betätigte oder unplausible Taste. Funkschlüssel und Fahrerschalter funktionieren meist weiter; der Fahrerschalter hat mit B0265 einen eigenen Code.","u":[["h","Verriegelungswippe in der Beifahrertür verschlissen, klemmend oder verschmutzt"],["m","Schaltersignalleitung im Türscharnierdurchgang an Masse gescheuert oder gebrochen"],["m","Wassereintritt oder Korrosion am Schalterstecker in der Türverkleidung"],["l","Eingangsstufe des Tür- oder Karosseriesteuergeräts defekt"]],"s":["Verriegelungstaste an der Beifahrertür wirkt nicht auf die Zentralverriegelung","Türen ver- oder entriegeln von selbst, wenn die Schalterleitung kurzgeschlossen ist","Funkschlüssel und Fahrerschalter verriegeln weiterhin normal"],"k":["door_lock_switch","body_control_module","door_harness"],"r":["easy",1,[30,250],[0.4,1.5]],"f":"","x":["B0265","B0272","B0531"]},{"c":"B0272","t":"Zentralverriegelungsschalter Stromkreis","e":"Power Door Lock Switch Circuit","d":"Weder die erreichbaren J2012-Listen noch Herstellerunterlagen nennen B0272 – der Code bleibt unbewiesen. Der Titel meint allgemein die Zentralverriegelungstaste im Innenraum, ohne eine Tür zu nennen. Saab speichert eine hängende Taste im Fahrertürmodul des 9-3 als B3270 61: Bleibt der Eingang auf niedrigem Pegel, reagiert das Modul erst wieder, wenn die Taste losgelassen und neu gedrückt wird. In US6365986B1 ist ein solcher Handschalter an der Türinnenseite neben dem Schließzylinderkontakt einer von zwei Eingängen, aus denen das Steuergerät die Stellmotoren ansteuert. In US6157090A hat jede Schalterstellung einen eigenen Widerstand, sodass das Karosseriemodul die Stellung als Strompegel liest. Die türbezogenen Schaltercodes sind B0265 und B0270, Stellmotorfehler B0530 ff.","u":[["h","Zentralverriegelungstaste mechanisch hängend oder Kontakte verschlissen"],["m","Schalterleitung zwischen Taster und Modul an Masse oder unterbrochen"],["l","Verschüttete Flüssigkeit oder Kondenswasser im Schalterfeld"],["l","Tür- oder Karosseriemodul wertet den Schaltereingang falsch aus"]],"s":["Innenraum-Verriegelungstaste ver- oder entriegelt die Türen nicht","Schlösser schalten unerwartet oder reagieren nur noch auf den Funkschlüssel"],"k":["door_lock_switch","door_wiring_harness","body_control_module"],"r":["easy",1,[30,200],[0.5,1.5]],"f":"","x":["B0265","B0270","B0530"]},{"c":"B0273","t":"HVAC Umluftklappe Stromkreis","e":"HVAC Recirculation Door Circuit","d":"B0273 ließ sich weder in den vorliegenden Code-Listen noch in einer Herstellerveröffentlichung finden. Der Titel betrifft den Stromkreis des Stellmotors, der die Ansaugklappe zwischen Frischluft und Innenraumluft umlegt. Saab nutzt dafür eigene Nummern: Im Klimasteuergerät des 9-3 steht B0225 06 für einen offenen oder an Masse liegenden Umluftmotorkreis, B0226 01 für Schluss nach Plus; der Saab 9-5 von 2011 (GM) meldet die Schrittmotor-Ansteuerung als B0223/B022A. Patente wie US5181553A und US8641490B2 zeigen die Ansaugklappe mit eigenem Motor, den der Klimaregler befehligt. Fällt der Kreis aus, bleibt die Klappe in der letzten Stellung – verbrauchte Luft, beschlagene Scheiben oder schwache Kühlung sind die Folge. B0175 betrifft die Klappenfunktion, nicht den Kreis.","u":[["h","Stellmotor der Umluftklappe durchgebrannt oder innen unterbrochen"],["m","Stellmotorleitung hinter dem Handschuhfach durchgescheuert, kurzgeschlossen oder abgezogen"],["l","Klappe durch Laub oder Fremdkörper blockiert, Motor blockiert mit hohem Strom"],["l","Endstufe im Klimasteuergerät defekt"]],"s":["Umlufttaste ändert nichts an der Luftansaugung","Scheiben beschlagen oder Außengerüche dringen in den Innenraum","Schwächere Kühlung an heißen Tagen"],"k":["hvac_recirculation_actuator","hvac_control_module"],"r":["medium",1,[60,400],[0.5,2.5]],"f":"","x":["B0175","B0278"]},{"c":"B0274","t":"Kofferraumdeckel-Entriegelungsschalter Stromkreis","e":"Trunk Lid Release Switch Circuit","d":"Öffentlich bestätigt nichts B0274 – die öffentlich zugänglichen J2012-Tabellen lassen ihn aus, kein Hersteller erklärt ihn. Gemeint ist der Taster, mit dem Fahrer oder Außenstehende den Kofferraumdeckel elektrisch entriegeln. Saab behandelt die Taste beim 9-3 getrennt: Das Fahrertürmodul setzt B2730 61, wenn die Kofferraumtaste länger als 20 s betätigt bleibt, danach öffnet der Deckel nicht. Den Entriegelungsausgang selbst führen Saab und GM gesondert (9-3 B3265, 9-5 von 2011 B3265 02 bei Masseschluss der Relaisansteuerung). Patente zur Fernentriegelung wie US4979384A und US3917330A zeigen den Grundaufbau: Ein Schalter bestromt einen Magneten oder Motor im Schloss. Ein Fehler im Schalterkreis hält den Deckel verschlossen oder lässt ihn bei Kurzschluss unerwartet aufspringen.","u":[["h","Außen liegender Entriegelungstaster korrodiert oder voller Wasser und Schmutz"],["m","Leitungen im beweglichen Kabelschlauch am Deckelscharnier gebrochen"],["m","Innenraum-Entriegelungstaste durch Verkleidung gedrückt oder verklemmt"],["l","Eingang des Tür- oder Karosseriemoduls für den Taster defekt"]],"s":["Kofferraumdeckel lässt sich nicht per Taste öffnen, nur mit Schlüssel oder Fernbedienung","Deckel entriegelt, ohne dass jemand die Taste drückt"],"k":["trunk_release_switch","body_wiring_harness"],"r":["easy",1,[30,200],[0.3,1.5]],"f":"","x":["B0272"]},{"c":"B0278","t":"HVAC Defrostklappe Stromkreis","e":"HVAC Defrost Door Circuit","d":"B0278 fand sich weder in J2012-Tabellen noch in Werkstattunterlagen; ob es ihn gibt, ist offen. Laut Titel geht es um die elektrische Seite des Stellmotors der Defrostklappe, die Luft auf die Frontscheibe lenkt. Das Klimasteuergerät des Saab 9-3 legt den passenden Fehler als B0240 06 (Stellmotorkreis offen oder an Masse) und B0241 01 (Schluss nach Plus oder zu hoher Strom) ab; beides verstellt die Luftverteilung. Hitachi treibt in US5181553A die Defrosterklappe mit einem eigenen Stellmotor an, und das MOTOR-Magazin beschreibt die elektrische Prüfung solcher Stellmotoren. Ist der Kreis tot, bleibt die Klappe stehen: Die Scheibe wird schlecht frei oder wird ständig angeblasen. Lagefehler ohne elektrischen Defekt gehören zu B0205.","u":[["h","Stellmotor der Defrostklappe innen unterbrochen oder kurzgeschlossen"],["m","Stellmotorleitung unter dem Armaturenbrett beschädigt oder Stecker locker"],["l","Klappe oder Gestänge fest, Motor zieht zu viel Strom"],["l","Stellmotor-Endstufe im Klimasteuergerät ausgefallen"]],"s":["Frontscheibe wird langsam frei, weil kaum Luft ankommt","Luft strömt unabhängig von der Wahl ständig auf die Frontscheibe"],"k":["hvac_defrost_actuator","hvac_control_module"],"r":["medium",1,[60,400],[0.5,3]],"f":"","x":["B0205","B0273"]},{"c":"B0283","t":"Heckscheibenheizung Relais-Steuerkreis","e":"Rear Defogger Relay Control Circuit","d":"B0283 steht in keiner der zugänglichen J2012-Code-Listen; belegt ist er bei Saab/GM – dort als Relais der Heckscheibenheizung, nicht als Gebläse. Beim Saab 9-3 (2003–2012) setzt die hintere Elektrozentrale B0283 01, wenn der Relaisausgang bei eingeschalteter Heizung über 6 V liegt, und B0283 06, wenn er unter 6 V bleibt (Leitung offen oder an Masse). Die von GM gebauten Saab 9-5 und 9-4X von 2011 prüfen im Klimasteuergerät bei 9–16 V: 02 heißt Masseschluss der Relaisansteuerung, die Scheibe heizt ununterbrochen; 05 heißt offen oder Schluss nach Plus, die Scheibe bleibt kalt. Ein gespeicherter Code verschwindet nach 50 Zündzyklen. Wie US4673797A zeigt, laufen solche Relais meist über einen Zeitgeber. Frontgebläsefehler gehören zu B0181/B0186, das Heizgitter selbst zu B0950.","u":[["h","Relais der Heckscheibenheizung mit offener Spule oder verschweißten Kontakten"],["m","Relais-Steuerleitung offen, an Masse oder an Batteriespannung"],["m","Schlechte Masse oder korrodierter Sockel am Relais"],["l","Ausgangsstufe des Klimasteuergeräts oder der Elektrozentrale defekt"]],"s":["Heckscheibenheizung funktioniert nach dem Einschalten nicht","Heckscheibe heizt dauernd und lässt sich nicht abschalten","Batterie entladen, wenn das Heizgitter weiterheizt"],"k":["rear_defrost_relay","rear_window_heating_element","hvac_control_module"],"r":["easy",1,[20,250],[0.3,1.5]],"f":"","x":["B0290","B0950"]},{"c":"B0288","t":"HVAC Klimadrucksensor Stromkreis","e":"HVAC A/C Pressure Sensor Circuit","d":"Die Suche fand B0288 in keiner J2012-Liste und in keinen Herstellerdaten; er bleibt unbestätigt. Der genannte Kältemitteldrucksensor sitzt in der Hochdruckleitung; sein Signal entscheidet, ob der Kompressor laufen darf und wie schnell der Kühlerlüfter dreht. Meist liest ihn das Motorsteuergerät und speichert P0530–P0533. Beim Saab 9-3 mit Trionic 8 etwa gilt P0532 unter 0,25 V und P0533 über 4,2 V, jeweils länger als 1 s bei laufendem Motor und über −7 °C Außentemperatur; danach schaltet das Gerät das Klimarelais ab. Das Patent US9259992B2 führt den Sensor ebenso ans Motorsteuergerät, US5623835A steuert damit den Lüfter. Ein Karosseriecode käme nur dort infrage, wo das Klimasteuergerät den Sensor selbst einliest.","u":[["h","Kältemitteldrucksensor ausgefallen oder Signal driftet"],["m","Sensorstecker nahe dem Kondensator durch Spritzwasser korrodiert"],["m","5-V-Referenz, Masse- oder Signalleitung offen oder kurzgeschlossen"],["l","Sehr wenig Kältemittel mit unplausiblem Messwert"]],"s":["Klimaanlage bläst warm, weil der Kompressor gesperrt ist","Kühlerlüfter läuft dauernd oder mit falscher Drehzahl"],"k":["ac_refrigerant_pressure_sensor","ac_compressor_relay","hvac_control_module"],"r":["easy",1,[50,250],[0.3,1.5]],"f":"","x":["P0530","P0532","P0533","B0292"]},{"c":"B0290","t":"Heckscheibenheizungsschalter Stromkreis","e":"Rear Defrost Switch Circuit","d":"Für B0290 gibt es keine öffentliche Quelle: Die geprüften J2012-Tabellen kennen ihn nicht, die Werkstattliteratur schweigt. Der Titel meint die Taste, mit der die Heckscheibenheizung angefordert wird. Beim Saab 9-5 von 2011 (GM) sitzt sie im Bedienteil der Klimaanlage, das die Anforderung an das Klimasteuergerät weiterreicht; einen eigenen Code hat dort nur der Relaisausgang (B0283). Der Saab 9-3 überwacht die Kontrollleuchte der Taste getrennt als B0969 02. Die Patente US4555743A und US4673797A beschreiben die übliche Logik: Ein Tastimpuls startet einen Zeitgeber von rund zehn Minuten und kann ihn wieder beenden. Ein Schalterfehler lässt Anforderungen verloren gehen oder dauerhaft anstehen – die Heckscheibe heizt nie oder startet von selbst neu.","u":[["h","Kontakte der Heckscheibenheizungstaste verschlissen oder Taste im Bedienteil verklemmt"],["m","Klimabedienteil oder dessen Platine defekt"],["l","Signal- oder Datenleitung zwischen Bedienteil und Steuergerät unterbrochen"]],"s":["Druck auf die Heckscheibenheizungstaste bleibt ohne Wirkung","Heckscheibenheizung schaltet sich selbst ein oder lässt sich nicht beenden","Kontrollleuchte in der Taste bleibt dunkel oder leuchtet dauernd"],"k":["rear_defrost_switch","body_control_module"],"r":["easy",1,[30,300],[0.3,1.5]],"f":"","x":["B0283","B0950"]},{"c":"B0292","t":"HVAC Klimakompressorkupplung Stromkreis","e":"HVAC A/C Compressor Clutch Circuit","d":"Ob B0292 irgendwo verwendet wird, ist unbekannt; keine herangezogene J2012-Liste führt ihn, kein Hersteller dokumentiert ihn. Der Titel zielt auf die Magnetkupplung, die einen riemengetriebenen Kompressor mit seiner Riemenscheibe verbindet, und auf das Relais, das die Kupplungsspule speist. Meist gehört dieser Kreis dem Motorsteuergerät, das P0645–P0647 ablegt; am Trionic-8-Motor des Saab 9-3 beispielsweise gilt P0646, wenn der Relaisausgang länger als 1 s unter 2 V bleibt – der Kompressor kann dann ohne Pause laufen. Nach US20040211197A1 erkennt das Klimagerät eine ausgefallene Kupplung nur über einen zusätzlichen Rückmeldeweg; US4481784A zeigt die klassische Kette Batterie–Relais–Spule. Elektrische Kompressoren ohne Kupplung nutzen einen solchen Code nicht.","u":[["h","Kupplungsspule unterbrochen oder kurzgeschlossen, oft nach Überhitzung"],["m","Klimakupplungsrelais ausgefallen oder Kontakte verschweißt"],["m","Zu großer Luftspalt, die Ankerscheibe zieht nicht an"],["l","Versorgungs- oder Masseleitung am Kompressor durch Hitze beschädigt"]],"s":["Keine Kühlung, Kompressornabe dreht bei eingeschalteter Klima nicht mit","Kompressor läuft dauernd, auch bei ausgeschalteter Klimaanlage"],"k":["ac_compressor_clutch","ac_compressor_relay","hvac_control_module"],"r":["medium",1,[30,600],[0.3,3]],"f":"","x":["P0645","P0646","P0647","B0288"]},{"c":"B0300","t":"HVAC Verdampfertemperaturfühler Stromkreis","e":"HVAC Evaporator Temperature Sensor Circuit","d":"Die durchsuchten Code-Listen zeigen B0300 nicht, und Werksunterlagen dazu fehlen ebenfalls. Der Verdampfertemperaturfühler ist ein Thermistor am oder direkt hinter dem Verdampferblock; damit taktet oder drosselt der Klimaregler den Kompressor, damit der Block nicht vereist (US6427465B1, US4326386A). Saab nutzt beim 9-3 eigene Nummern: B0521 02 unter 0,2 V und B0522 05 über 4,8 V am Moduleingang, danach dient die Außentemperatur als Ersatzwert. HELLA berichtet, dass ein schlecht abgedichteter oder driftender Fühler den Verdampfer zufrieren und den Luftstrom abwürgen kann. Ein Kreisfehler kostet daher eher Kühlkomfort, als dass die Lüftung ganz ausfällt.","u":[["h","Verdampferthermistor unterbrochen, kurzgeschlossen oder außer Toleranz"],["m","Fühler aus dem Block gerutscht oder nach Arbeiten schlecht abgedichtet"],["m","Stecker am Klimakasten locker oder durch Kondenswasser korrodiert"],["l","Fühlereingang im Klimasteuergerät defekt"]],"s":["Kühlung schwach oder schwankend, besonders bei Hitze","Luftmenge sinkt nach längerer Fahrt, weil der Verdampfer vereist"],"k":["evaporator_temperature_sensor","hvac_control_module"],"r":["medium",0,[60,500],[0.5,4]],"f":"","x":["B0292","B0288"]},{"c":"B0305","t":"HVAC Sonnenlichtsensor Stromkreis","e":"HVAC Sun Load Sensor Circuit","d":"B0305 ist durch keine öffentliche J2012-Liste und keinen Hersteller bestätigt; sein Thema deckt sich mit B0156. Der Sonnenlichtsensor ist eine Fotodiode oben auf dem Armaturenbrett, die der Klimaautomatik meldet, wie viel Sonnenwärme in den Innenraum fällt (US6888120B2, US5957375A). Echte Codes dafür tragen andere Nummern: Saab legt beim 9-3 ein unplausibles Signal als B0183 08 und einen offenen oder an Masse liegenden Kreis als B0184 06 ab und regelt dann wie bei bedecktem Himmel; der von GM gebaute Saab 9-5 von 2011 meldet B0183 02/05. Ein Kreisfehler legt die Anlage selten still, doch bei praller Sonne wird es im Innenraum oft zu warm, und das Gebläse reagiert spät.","u":[["h","Fotodiode des Sonnenlichtsensors gealtert oder beschädigt"],["m","Sensor aus dem Armaturenbrettgitter gelöst, Stecker abgezogen"],["l","Signal- oder Masseleitung zum Sensor offen oder kurzgeschlossen"]],"s":["Innenraum bei Sonnenschein mit Klimaautomatik zu warm","Gebläsestufe steigt nicht, wenn die Sonne herauskommt"],"k":["sun_load_sensor","hvac_control_module"],"r":["easy",1,[30,200],[0.3,1]],"f":"","x":["B0156","B0162"]},{"c":"B0310","t":"Fahrersitz Positionssensor Stromkreis","e":"Driver Seat Position Sensor Circuit","d":"Zu B0310 gibt es weder einen Eintrag in einer J2012-Liste noch eine auffindbare Herstellerbeschreibung. Gemeint ist die Stellungsrückmeldung des elektrischen Fahrersitzes. Beim GM-Saab 9-5 von 2011 sitzt in jedem Sitzmotor ein Hallsensor; das Memory-Modul versorgt ihn mit 12 V und zählt seine Impulse (0–65.535), um die Sitzlage zu kennen – die Codes dort heißen B1825, B2355, B2365 und B2375. Der Saab 9-3 führt den Längsweg-Sensor als B2375: 04 über 0,5 V bei offener Leitung, 29 wenn keine Impulse kommen. Dann fällt das Abrufen gespeicherter Stellungen aus, und die gelernten Endanschläge gehen verloren. US5751129A nennt Potentiometer, Hallsensor und Kommutatorimpulse als gängige Prinzipien. Von Hand verstellen lässt sich der Sitz meist weiter.","u":[["h","Hallsensor in einem Sitzmotor ausgefallen"],["h","Leitungen unter dem Sitz von den Schienen gequetscht oder abgerissen"],["m","Versorgungs- oder Massekreis der Sensoren offen oder kurzgeschlossen"],["l","Eingangsfehler im Sitz-Memory-Modul"]],"s":["Memory-Tasten rufen gespeicherte Sitzstellungen nicht ab","Sitz fährt ruckelnd oder hält vor der Endstellung an","Einstiegshilfe fährt den Sitz nicht zurück"],"k":["seat_position_sensor","seat_control_module","seat_harness"],"r":["medium",1,[60,500],[0.5,2.5]],"f":"","x":["B0320","B0322","B0325","B0580"]},{"c":"B0312","t":"Fahrersitz Vor-/Zurück-Schalter Stromkreis","e":"Driver Seat Forward/Back Switch Circuit","d":"B0312 ist öffentlich undokumentiert: Keine zugängliche Code-Liste enthält ihn, kein Autohersteller definiert ihn. Gemeint ist der Schalter, der den Fahrersitz nach vorn und hinten fährt. Der GM-Saab 9-5 von 2011 führt ihn als B1755 (vor) und B1760 (zurück): Liegt eine Schalterleitung an Masse oder ist eine Richtung aktiv, während die Gegenrichtung gedrückt wird, sperrt das Modul diesen Motor in beide Richtungen und ignoriert Memory-Abrufe. Das Sitzmodul des Saab 9-3 meldet B1755 01/B1760 01 bei Schluss nach Plus; der Sitz fährt dann nur noch weg von der gestörten Richtung. In US4467252A treibt eine Reihe umpolender Handschalter, je Verstellrichtung einer, den Sitzmotor neben der Memory-Logik. Motor- und Leitungsfehler derselben Achse gehören zu B0560.","u":[["h","Kontakte des Sitzschalters verschlissen oder Knopf in einer Richtung verklemmt"],["m","Getränk in den seitlich montierten Schalter gelaufen"],["m","Schalterleitungen unter der Sitzverkleidung durchgescheuert"],["l","Sitzmodul wertet die Schaltereingänge falsch aus"]],"s":["Fahrersitz fährt nur noch vor oder nur noch zurück","Längsverstellung tot, andere Achsen funktionieren","Memory-Abruf wird ignoriert"],"k":["seat_adjust_switch","seat_control_module"],"r":["easy",1,[40,300],[0.4,1.5]],"f":"","x":["B0560","B0310"]},{"c":"B0320","t":"Beifahrersitz Positionssensor Stromkreis","e":"Passenger Seat Position Sensor Circuit","d":"Keine der vorliegenden J2012-Listen nennt B0320, und kein Fahrzeughersteller veröffentlicht eine Definition. Der Titel betrifft die Stellungsrückmeldung eines elektrischen Beifahrersitzes, wie es sie vor allem bei Memory oder Einstiegshilfe gibt. Das Beifahrersitzmodul des Saab 9-3 führt den Längsweg-Sensor unter B2375: 01, wenn der Eingang über 7 ± 0,2 V liegt, 04 bei offener Leitung; in beiden Fällen ruhen die Memory-Funktionen, und die kalibrierten Endanschläge gehen verloren. US6320341B1 kommt ohne eigenen Sensor aus und zählt die Stromwelligkeit des Gleichstrommotors, US5751129A setzt die Sensoren ins Memory-Modul. Das Gegenstück auf der Fahrerseite ist B0310, Motorfehler der Längsverstellung dieses Sitzes gehören zu B0570.","u":[["h","Positionssensor im Beifahrersitzmotor ausgefallen"],["h","Sitzkabelbaum durch Gegenstände oder Füße unter dem Sitz beschädigt"],["m","Sensorsignal mit Versorgungsspannung kurzgeschlossen"],["l","Eingang des Beifahrersitzmoduls defekt"]],"s":["Memory oder Einstiegshilfe am Beifahrersitz funktioniert nicht","Sitz ruckt beim Anfahren oder Anhalten"],"k":["seat_position_sensor","seat_control_module","seat_harness"],"r":["medium",1,[60,500],[0.5,2.5]],"f":"","x":["B0310","B0327","B0570"]},{"c":"B0322","t":"Fahrersitz Neigungs-Positionssensor","e":"Driver Seat Tilt Position Sensor","d":"Für B0322 fehlt jede öffentliche Definition, sei es in J2012-Listen oder von einem Hersteller. Der Titel beschreibt den Sensor für die Neigung des Sitzkissens am elektrischen Fahrersitz, meist erzeugt durch Heben oder Senken der Vorderkante. Das Fahrersitzmodul des Saab 9-3 nennt ihn Neigungssensor und speichert B3923: 01 über 7 ± 0,2 V, 02 bei Masseschluss, 04 bei offener Leitung und 29, wenn bei laufendem Motor keine Impulse kommen. Dann ruht der Memory-Abruf, und die Endlagenkalibrierung des Neigungsmotors geht verloren. US4682088A misst die Kissenhöhe vorn und hinten mit Potentiometern, US6320341B1 stellt den vorderen Kissenteil über Impulszählung wieder her. Die Längsrückmeldung ist B0310.","u":[["h","Sensor im Neigungsmotor des Sitzkissens ausgefallen"],["m","Leitung des Neigungsmotors im Sitzgestell eingeklemmt"],["m","Gemeinsame Sensorversorgung kurzgeschlossen oder offen"],["l","Eingangsstufe des Sitzmoduls defekt"]],"s":["Kissenneigung wird beim Memory-Abruf nicht wiederhergestellt","Neigungsverstellung ruckt oder stoppt vor dem Ende"],"k":["seat_position_sensor","seat_module"],"r":["medium",0,[80,500],[0.5,2.5]],"f":"","x":["B0310","B0561"]},{"c":"B0325","t":"Fahrersitz Memory-Speichertaste","e":"Driver Seat Memory Set Switch","d":"Die Suche ergab B0325 in keiner J2012-Liste und in keiner Werksdokumentation. Der Titel nennt die SET- oder M-Taste, mit der die aktuelle Sitzstellung unter einer Memory-Taste abgelegt wird. Das Fahrersitzmodul des Saab 9-3 kennt sie als Speichertaste: B2765 01 bei Schluss nach Plus, B2765 61, wenn sie länger als 60 s gedrückt bleibt oder klemmt; das Modul wertet sie dann als losgelassen, bis sie neu betätigt wird. US4682088A und US4463426A beschreiben den klassischen Ablauf – erst SET, dann kurz darauf Taste 1 oder 2 –, US4264849A nutzt dieselben Tasten zum Abrufen und zusammen mit einer Speichertaste zum Sichern. Eine defekte Speichertaste verhindert das Ablegen, nicht aber das Verstellen von Hand.","u":[["h","Memory-Speichertaste in Tür- oder Sitzblende verklemmt"],["m","Tasterkontakte verschlissen oder verschmutzt"],["l","Tasterleitung an Versorgungsspannung oder gebrochen"]],"s":["Neue Sitzstellungen lassen sich nicht speichern","Memory-Tasten rufen nur alte Einstellungen ab"],"k":["memory_switch","seat_module"],"r":["easy",1,[30,250],[0.3,1.5]],"f":"","x":["B0580","B0310","B0327"]},{"c":"B0327","t":"Beifahrersitz Positionsspeicher","e":"Passenger Seat Position Memory","d":"Keine bekannte öffentliche Liste und kein Herstellerdokument definiert B0327. Der Titel ist unscharf: Er deutet auf einen Fehler beim Speichern oder Wiederherstellen von Stellungen eines elektrischen Beifahrersitzes. Dafür braucht das Modul eine funktionierende Stellungsrückmeldung; im Beifahrersitzmodul des Saab 9-3 schaltet ein fehlendes Signal des Längsweg-Sensors (B2375) alle Memory-Funktionen ab und löscht die Endlagenkalibrierung. US4264849A zeigt per Taste abrufbare Speicherstellungen für beliebige Fahrzeugsitze, US6320341B1 stellt mehrere Kissen- und Lehnenstellungen aus Impulszählungen wieder her. Ohne Herstellerdefinition bleibt der genaue Auslöser offen; vermutlich verlorene Speicherdaten oder ein gescheiterter Abruf.","u":[["h","Fehlende Stellungsrückmeldung eines Beifahrersitzmotors"],["m","Gespeicherte Stellungen nach Batterietrennung oder Unterspannung verloren"],["m","Endanschläge nach Sitz- oder Motortausch nicht neu angelernt"],["l","Speicher des Beifahrersitzmoduls defekt"]],"s":["Beifahrersitz fährt nicht in die gespeicherte Stellung","Gespeicherte Einstellungen nach dem Ausschalten vergessen"],"k":["seat_module","seat_position_sensor"],"r":["medium",0,[0,500],[0.3,2.5]],"f":"","x":["B0320","B0325"]},{"c":"B0330","t":"HVAC hinterer Gebläsemotor Stromkreis","e":"HVAC Rear Blower Motor Circuit","d":"B0330 ist weder in zugänglichen J2012-Listen noch in Herstellerquellen zu finden und überschneidet sich inhaltlich mit B0184. Das hintere Gebläse fördert klimatisierte Luft zu den hinteren Reihen, oft als zweiter Lüfter in einem Heckkanal (US6915650B2) oder als eigene Heckeinheit mit eigener Drehzahlstellung (US4949779A). GM führt den Kreis bei Saab 9-5 und 9-4X (Baujahr 2011) als B0208: Das Klimasteuergerät schickt einen PWM-Drehzahlbefehl an ein Zusatz-Gebläsesteuergerät, das daraus 2–13 V am Motor macht; 01 heißt, die Leitung ist ständig hoch, 06 ständig niedrig oder offen, und das hintere Gebläse steht. Typisch sind ein festgegangener Motor, ein durchgebrannter Drehzahlsteller oder eine gebrochene Befehlsleitung.","u":[["h","Drehzahlsteller oder Vorwiderstand des hinteren Gebläses durchgebrannt"],["m","Hinterer Gebläsemotor festgegangen oder Kohlen verschlissen"],["m","Drehzahl-Befehlsleitung zwischen den Modulen offen oder kurzgeschlossen"],["l","Sicherung oder Versorgungsrelais des hinteren Gebläses ausgefallen"]],"s":["Aus den hinteren Düsen kommt keine Luft","Hinteres Gebläse läuft nur in einer Stufe oder lässt sich nicht abschalten"],"k":["rear_blower_motor","rear_blower_resistor","hvac_control_module"],"r":["medium",1,[60,450],[0.5,3]],"f":"","x":["B0184","B0181"]},{"c":"B0335","t":"Fahrersitzheizung Stromkreis","e":"Driver Seat Heater Circuit","d":"B0335 wird weder von J2012-Listen noch von Werkstattinformationen gestützt; das Thema ist doppelt zu B0341. Gemeint ist die Heizmatte in Sitzfläche und Lehne des Fahrersitzes samt Versorgung. Echte Codes stehen anderswo: Das Klimasteuergerät des Saab 9-3 legt B2428 01 bei Schluss nach Plus und B2429 06 bei offener linker Heizung ab; der GM-Saab 9-5 von 2011 misst alle 10 s Strom und Spannung und setzt B2425 0B/0D/0E für zu hohen Strom, zu hohen oder zu niedrigen Widerstand. Chrysler tauschte laut Bulletin 08-049-14 (Wrangler 2011–12) Heizelemente, deren Widerstand unter −12 °C aus dem Sollbereich fiel (B1092). Das Patent US5229579A schaltet bei erkanntem Kurzschluss oder Unterbrechung ab, damit nichts überhitzt.","u":[["h","Heizdraht im Fahrersitzkissen durch ständiges Walken gebrochen"],["m","Sitzheizungsstecker unter dem Sitz locker oder verschmort"],["m","Heizelement oder Zuleitung mit Sitzgestell kurzgeschlossen"],["l","Endstufe des Sitzheizungs- oder Klimasteuergeräts defekt"]],"s":["Fahrersitz bleibt trotz eingeschalteter Heizung kalt","Sitzheizungsanzeige blinkt oder erlischt nach wenigen Sekunden","Nur Lehne oder nur Sitzfläche wird warm"],"k":["seat_heater_element","seat_wiring_harness"],"r":["medium",0,[80,700],[0.5,4]],"f":"","x":["B0337","B0339","B0341"]},{"c":"B0337","t":"Beifahrersitzheizung Stromkreis","e":"Passenger Seat Heater Circuit","d":"Von B0337 gibt es keine öffentliche Spur in J2012-Listen oder Werksdaten; sein Gegenstand wiederholt B0342. Er betrifft die Heizmatte des Beifahrersitzes samt Zuleitung. Weil dieser Sitz oft leer bleibt, fällt ein Fehler mitunter lange nicht auf. Das Klimasteuergerät des Saab 9-3 meldet B2433 01 bei Schluss nach Plus an der rechten Heizung und B2434 06 bei offenem oder an Masse liegendem Kreis; der GM-Saab 9-5 von 2011 nutzt B2430 0B/0D/0E. Chryslers Bulletin 08-049-14 betraf beide Vordersitze (rechts B1096). US6252208B1 zeigt, wie eine Steuerschaltung Heizstrom und einen NTC-Sitzfühler kombiniert; ein gebrochenes Element oder eine unterbrochene Zuleitung lässt den Beifahrersitz schlicht kalt.","u":[["h","Heizdraht in Sitzfläche oder Lehne des Beifahrersitzes gebrochen"],["m","Stecker unter dem Beifahrersitz abgetreten oder korrodiert"],["l","Beschädigung bei Arbeiten an der Sitzbelegungsmatte im selben Kissen"],["l","Heizungsausgang im steuernden Modul defekt"]],"s":["Beifahrersitzheizung wird nicht warm","Heizung schaltet kurz nach dem Einschalten ab"],"k":["seat_heater_element","seat_wiring_harness"],"r":["medium",0,[80,700],[0.5,4]],"f":"","x":["B0335","B0339","B0342"]},{"c":"B0339","t":"Rücksitzheizung Stromkreis","e":"Rear Seat Heater Circuit","d":"B0339 taucht weder in den benutzten Code-Listen noch in veröffentlichtem Werkstattmaterial auf. Rücksitzheizung ist eine Option größerer Fahrzeuge; der von GM gebaute Saab 9-4X von 2011 mit beheizten Rücksitzen hat dafür ein eigenes Steuergerät hinter der Rücksitzlehne. Es speist beide Matten über eine gemeinsame Versorgung, regelt durch PWM-Takten der Masse und prüft alle 10 s Strom und Spannung: B2425/B2430 0D heißt Widerstand zu hoch, 0B/0E zu viel Strom oder zu wenig Widerstand. Jeder Rücksitz trägt zudem einen NTC-Fühler (B1925/B2170), und B2345 13 meldet die gemeinsame Abschaltleitung. US5229579A zeigt, warum solche Regler bei Kurzschluss oder Unterbrechung abschalten.","u":[["h","Heizmatte in einem Rücksitzkissen gebrochen"],["m","Stecker beim Umklappen oder Ausbau der Rückbank beschädigt"],["m","Rücksitzheizungs-Steuergerät oder dessen Versorgung defekt"],["l","Sitztemperaturfühler unplausibel, Heizung wird gesperrt"]],"s":["Eine oder beide Rücksitzheizungen bleiben kalt","Anzeige der Rücksitzheizung blinkt oder erlischt"],"k":["seat_heater_element","rear_seat_wiring"],"r":["medium",0,[80,700],[0.5,4]],"f":"","x":["B0335","B0337"]},{"c":"B0341","t":"HVAC Sitzheizung Fahrer Stromkreis","e":"HVAC Heated Seat Driver Circuit","d":"B0341 stützt keine J2012-Liste und kein bekannter Herstellertext; er behandelt dasselbe wie B0335. Der HVAC-Zusatz passt zu Fahrzeugen, deren Klimasteuergerät auch die Sitzheizung betreibt. Der Saab 9-3 ist so gebaut: Sein Klimasteuergerät treibt die linke Sitzheizung und liest einen Sitztemperaturfühler; B1927 02 (Eingang unter 0,2 V) schaltet die linke Heizung ab, B2429 06 meldet ein offenes Heizelement. US6252208B1 zeigt einen solchen Aufbau, bei dem ein NTC-Fühler im Sitz einen Spannungsteiler bildet, dessen Abgriff der Regler zur Steuerung des Heizstroms liest. Die Matten sind dieselben wie bei einem eigenen Sitzheizungsmodul; anders ist nur, wer den Ausgang treibt und den Code setzt.","u":[["h","Heizmatte des Fahrersitzes unterbrochen"],["m","Sitztemperaturfühler kurzgeschlossen oder offen, Heizung gesperrt"],["m","Lange Leitung vom Klimasteuergerät zum Sitz an der Sitzschiene beschädigt"],["l","Sitzheizungsausgang im Klimasteuergerät ausgefallen"]],"s":["Fahrersitzheizung tot, Klimaregelung arbeitet","Heizung beginnt, hört aber nach kurzer Zeit auf"],"k":["driver_seat_heater","heated_seat_module"],"r":["medium",1,[80,600],[1,4]],"f":"","x":["B0335","B0342"]},{"c":"B0342","t":"HVAC Sitzheizung Beifahrer Stromkreis","e":"HVAC Heated Seat Passenger Circuit","d":"Keine zugängliche J2012-Liste und keine Herstellerquelle erwähnt B0342; inhaltlich entspricht er B0337. Wie auf der Fahrerseite deutet der HVAC-Zusatz auf ein Klimasteuergerät, das auch die Beifahrersitzheizung treibt. Beim Saab 9-3 liest es auch einen rechten Sitztemperaturfühler: B2172 02 unter 0,2 V oder B2173 05 über 4,8 V (geprüft bei Innenraumtemperatur über −10 °C) schaltet die rechte Heizung ab, B2434 06 meldet einen offenen oder an Masse liegenden Heizungsausgang. US5229579A setzt einen Thermistor in den Sitz, damit der Regler regeln und Fehler erkennen kann. Ein ausgefallener Fühler kann deshalb eine an sich heile Heizmatte stilllegen.","u":[["h","Rechter Sitztemperaturfühler offen oder kurzgeschlossen"],["m","Heizmatte des Beifahrersitzes gebrochen"],["m","Stecker unter dem Beifahrersitz locker"],["l","Sitzheizungstreiber oder Fühlereingang im Klimasteuergerät defekt"]],"s":["Beifahrersitzheizung schaltet sofort wieder ab","Beifahrersitz bleibt kalt"],"k":["passenger_seat_heater","heated_seat_module"],"r":["medium",1,[60,600],[0.5,4]],"f":"","x":["B0337","B0341"]},{"c":"B0420","t":"Audiosystem interner Fehler","e":"Audio System Internal Failure","d":"In keiner öffentlichen J2012-Liste steht B0420 mit dieser Bedeutung, und kein Hersteller beschreibt darunter einen Audiofehler. Belegt ist nur eine fremde Belegung: Saab führt B0420 06 in der Klimaautomatik des 9-3 (2003–2012) als Unterbrechung oder Masseschluss am Stellmotor der rechten Mischluftklappe, was die Temperaturregelung stört. Wörtlich genommen meint der Titel einen Defekt im Radio bzw. Haupt-Steuergerät selbst, das alle Lautsprecherkanäle versorgt. Wie solche Geräte ihre Ausgänge bewerten, zeigt der Saab 9-5 von 2011: Das Radio speichert B1025–B1055 bei kurzgeschlossener oder offener Lautsprecherleitung und schaltet nur diesen Kanal stumm. Klippel beschreibt, wie DSP, Verstärker und eingebaute Mikrofone das ganze System selbst prüfen könnten. Fehlt die Buskommunikation zum Radio, gilt U0184.","u":[["h","Elektronik oder Software im Radio/Haupt-Steuergerät defekt"],["m","Zu niedrige oder schwankende Versorgung bzw. schlechte Masse am Radio"],["l","Gerät überhitzt, weil die Belüftung hinter dem Armaturenbrett verlegt ist"]],"s":["Kein Ton aus allen Lautsprechern oder das Radio startet von selbst neu","Radio bleibt hängen oder reagiert nicht auf seine Tasten","Code steht zusammen mit weiteren Infotainment-Fehlern im Speicher"],"k":["audio_head_unit","infotainment_module"],"r":["medium",0,[150,2000],[0.5,3]],"f":"","x":["B0425","B0455","U0184"]},{"c":"B0425","t":"Audio-Verstärker interner Fehler","e":"Audio Amplifier Internal Failure","d":"B0425 fehlt in allen zugänglichen J2012-Listen, und kein Hersteller dokumentiert ihn – der Code selbst ist unbelegt. Der Titel meint einen Defekt im separaten Audio-Verstärker, nicht in seiner Verkabelung. Verstärker-ICs wie der TAS6424E-Q1 von TI prüfen jeden Kanal auf offene oder kurzgeschlossene Last sowie Schluss nach Batterie oder Masse und warnen bei Übersteuerung und Übertemperatur. In der Global-A-Elektronik von GM (Saab 9-5 und 9-4X, 2011) speichert der Verstärker keine eigenen Codes; das Radio überwacht die PWM-Stummschaltleitung und setzt B1287, wenn sie 0,4 s nach dem Einschalten des Verstärkers offen oder kurzgeschlossen ist. Erkennbar ist das an Stille oder Knacken auf allen verstärkten Kanälen. Kommunikationsverlust zum Verstärker ist U0186, ein Radiodefekt B0420.","u":[["h","Endstufe oder interne Elektronik des Verstärkers ausgefallen"],["m","Verstärker überhitzt, etwa unter dem Sitz oder im Kofferraum ohne Luftzug"],["m","Feuchtigkeit oder Wasser im Verstärkergehäuse oder Stecker"],["l","Kurzgeschlossener Lautsprecher oder Leitung hat die Endstufe überlastet"]],"s":["Kein Ton oder nur sehr leise Wiedergabe aus den verstärkten Lautsprechern","Knacken, Brummen oder Verzerrung, oft schlimmer im warmen Zustand","Subwoofer oder Kanäle des Sound-Systems fallen aus"],"k":["audio_amplifier","infotainment_module"],"r":["medium",0,[150,1500],[0.5,2.5]],"f":"","x":["B0420","U0186","U0262"]},{"c":"B0440","t":"Bluetooth-Modul Fehler","e":"Bluetooth Module Fault","d":"B0440 steht in keiner öffentlichen J2012-Quelle, und kein Hersteller erklärt ihn; der Code lässt sich nicht belegen. Gemeint ist die Bluetooth-Einheit, die ein Telefon für Freisprechen und Musikwiedergabe koppelt. Fahrzeugtaugliche Chips wie der AW300 von NXP (AEC-Q100) bedienen die Profile HFP und A2DP; die WiLink-8Q-Familie von TI vereint Bluetooth mit WLAN und GNSS für Infotainment-Geräte. Häufig steckt der Funkteil im Telematik- oder Radiosteuergerät: Beim Saab 9-5 (2011) liegt er im OnStar-Modul, das Bluetooth abschaltet, sobald B2485 eine offene oder an Masse liegende Antenne meldet. Ein Moduldefekt zeigt sich durch scheiternde Kopplung, abbrechende Gespräche oder fehlendes Streaming. Für den Antennenkreis gibt es B0460, für das Mikrofon B0450; Busverlust zur Telematik ist U0198.","u":[["h","Softwarefehler oder hängender Zustand der Bluetooth-/Telematikeinheit"],["m","Bluetooth-Chip bzw. das Modul intern ausgefallen"],["l","Schlechte Versorgung oder Masse am Modul"]],"s":["Telefon lässt sich nicht koppeln oder wird nicht gefunden","Freisprechgespräche brechen ab oder die Musikwiedergabe stoppt","Bluetooth-Menü ausgegraut oder nicht vorhanden"],"k":["bluetooth_module","infotainment_module","bluetooth_antenna"],"r":["medium",0,[100,900],[0.5,2.5]],"f":"","x":["B0460","B0450","U0198"]},{"c":"B0445","t":"USB-Hub Fehler","e":"USB Hub Fault","d":"B0445 taucht in keiner erreichbaren J2012-Liste auf, und kein Hersteller beschreibt ihn, daher ist er unbelegt. Ein USB-Hub im Fahrzeug verteilt einen Host-Anschluss des Radios auf mehrere Buchsen für Medien und Laden. Weil ein loses Kabel Batteriespannung abbekommen kann, schützt der TPD3S714-Q1 von TI in Hubs und Radios die Busversorgung und beide Datenleitungen gegen Schlüsse bis 18 V; der TPS254900A-Q1 schaltet bei einem solchen Schluss rasch ab, damit Wandler und Hub-Datenleitungen heil bleiben. TIs Übersicht zu Ladeanschlüssen fasst Spannungswandlung, USB-PD und diesen Schutz für Media-Hubs zusammen. Ein Hub-Fehler lässt Buchsen ohne Daten oder Ladestrom, oder ein Telefon verbindet sich nur zeitweise. Busfehler des Radios selbst laufen unter eigenen U-Codes.","u":[["h","Buchse beschädigt oder verschmutzt, Schluss zwischen den Kontakten"],["m","Kabel zwischen Hub und Radio lose oder durchgescheuert"],["m","Hub-Elektronik oder Schutzschalter ausgefallen"],["l","Angeschlossenes Gerät oder Kabel zieht zu viel Strom"]],"s":["USB-Stick oder Telefon wird nicht erkannt","Buchse lädt, überträgt aber keine Daten, oder umgekehrt","Smartphone-Spiegelung bricht wiederholt ab"],"k":["usb_hub","infotainment_module"],"r":["easy",1,[40,400],[0.3,1.5]],"f":"","x":["B0420","B0440"]},{"c":"B0450","t":"Mikrofon Stromkreis","e":"Microphone Circuit","d":"In den öffentlich zugänglichen J2012-Listen fehlt B0450, und kein Hersteller veröffentlicht ihn – unbelegt. Der Titel betrifft die Leitung des Freisprechmikrofons. Das Steuergerät legt eine Vorspannung auf die Signalader und liest über dieselbe Ader die Sprache zurück. Beim Saab 9-5 und 9-4X (2011) setzt das OnStar-Modul B2455, wenn 10 s lang eine Unterbrechung, ein Schluss nach Masse oder Plus oder eine offene Bezugsmasse vorliegt; die Status-LED wird rot, und der Gesprächspartner hört nichts. Audio-Wandler wie der PCM6240-Q1 von TI liefern 5–9 V Mikrofonspeisung und melden offene oder kurzgeschlossene Eingänge sowie Schlüsse nach Masse, Speisung oder Batterie. Anrufe und Sprachbedienung starten trotzdem, nur kommt die eigene Stimme nicht an. Kopplungsprobleme gehören zu B0440.","u":[["h","Mikrofon im Dachhimmel oder Spiegel ausgefallen"],["m","Mikrofonleitung im Dachhimmel oder in der A-Säule gequetscht oder gebrochen"],["m","Stecker an Mikrofon oder Steuergerät lose oder korrodiert"]],"s":["Gesprächspartner hört den Fahrer beim Freisprechen nicht","Sprachbedienung reagiert nicht auf Befehle","Notruf- bzw. Telematik-Statuslampe zeigt einen Fehler"],"k":["microphone","infotainment_module","telematics_module"],"r":["easy",1,[40,300],[0.3,1.5]],"f":"","x":["B0440","U0198"]},{"c":"B0455","t":"Anzeigemodul interner Fehler","e":"Display Module Internal Failure","d":"Keine öffentlich verfügbare J2012-Liste enthält B0455, und kein Hersteller beschreibt ihn; der Code ist unbelegt. Gemeint ist ein Defekt im Inneren eines Anzeigemoduls, etwa des Zentral- oder Instrumentenbildschirms, nicht in Leitung oder Datenverbindung. Beim Saab 9-5 von 2011 setzt das Radio B1020 bei fehlerhafter Statusantwort der Anzeigeeinheit – Elektronikdefekt oder klemmende Taste; beim 9-4X gilt dieselbe Nummer für das Bedienteil von Radio und Klima. In Densos US11348495B2 prüft jede Anzeige ihre eigene Schaltung, meldet an das Bild-Steuergerät und übergibt bei Ausfall Tempo und Warnungen an einen anderen Bildschirm. Hyundai Mobis (US11961434B2) erkennt ein eingefrorenes Bild an verborgenen Testpixeln. Busverlust zu einer Anzeige ist U0162 oder U0255; dunkler Schirm bei laufendem Inhalt deutet auf B0490.","u":[["h","Anzeige-Controller oder Panel-Elektronik ausgefallen"],["m","Softwarefehler, oft per Update behebbar"],["l","Taste an der Anzeigeeinheit klemmt und wird als Fehler gemeldet"]],"s":["Bildschirm bleibt schwarz, flackert oder friert auf einem Bild ein","Touch-Eingabe oder Tasten am Bildschirm reagieren nicht","Informationen wandern auf eine andere Anzeige oder eine Warnung erscheint"],"k":["display_module","instrument_cluster"],"r":["medium",0,[200,1800],[0.5,2.5]],"f":"","x":["B0490","U0162","U0255"]},{"c":"B0460","t":"Bluetooth-Antenne Stromkreis","e":"Bluetooth Antenna Circuit","d":"B0460 kommt in keiner zugänglichen J2012-Liste und in keiner Herstellerunterlage vor und bleibt damit unbelegt. Der Titel betrifft den Stromkreis der Bluetooth-Antenne. Die Global-A-Elektronik von GM im Saab 9-5 und 9-4X (2011) führt dasselbe Bauteil unter der eigenen Nummer B2485: Die kleine Antenne sitzt ohne Kabel direkt am OnStar-Modul, wird jede Sekunde geprüft, und bei Unterbrechung oder Masseschluss schaltet das Modul Bluetooth ab und die Status-LED auf Rot. Visteons US20040116084A1 speist Gleichstrom in die Antennenzuleitung und erkennt Unterbrechung oder Kurzschluss am aufgenommenen Strom; Delphis US6999858B2 bemerkt eine entfernte Antenne an einem frei schwebenden Gleichspannungsknoten oder an einer Fehlanpassung am Senderausgang. Geringe Reichweite oder Verbindungsabbrüche deuten hierher, ein toter Bluetooth-Chip auf B0440.","u":[["h","Antennenkontakt oder Stecker am Modul lose oder korrodiert"],["m","Antenne oder Zuleitung beschädigt, etwa nach Arbeiten am Armaturenbrett"],["l","Antennenerkennung oder Funkstufe im Modul defekt"]],"s":["Telefon koppelt nur aus nächster Nähe oder gar nicht","Bluetooth vom Modul abgeschaltet, Statuslampe rot","Gespräche und Musik brechen immer wieder ab"],"k":["bluetooth_antenna","infotainment_module","telematics_module"],"r":["medium",0,[50,600],[0.5,2]],"f":"","x":["B0440","U0198"]},{"c":"B0490","t":"Display-Hintergrundbeleuchtung Stromkreis","e":"Display Backlight Circuit","d":"B0490 steht in keiner zugänglichen J2012-Quelle, und kein Hersteller dokumentiert ihn – öffentlich unbelegt. Gemeint ist die Hintergrundbeleuchtung einer Anzeige, heute meist LED-Stränge an einem Hochsetz-Treiber. Die Treiber LP8866-Q1 und LP8872-Q1 von TI erkennen offene Stränge, kurzgeschlossene LEDs und LED-Schluss nach Masse und melden das an den Steuerrechner; laut TI verhindert die schnelle Masseschluss-Erkennung eine Blendung, die nachts den Fahrer stören könnte. Beim 9-4X von 2011 setzt das Radio B1289, wenn die PWM-Helligkeitsleitung zu den Fond-Bildschirmen 400 ms nach dem Freischalten offen oder kurzgeschlossen ist; die Bildschirme laufen dann mit fester Helligkeit. Ein dunkler Schirm, dessen Bild im Sonnenlicht noch schwach zu sehen ist, spricht für diesen Code statt B0455.","u":[["h","LED-Strang oder einzelne LED der Hintergrundbeleuchtung ausgefallen"],["m","Beleuchtungstreiber oder dessen Hochsetzstufe defekt"],["l","Helligkeits-Steuerleitung unterbrochen oder kurzgeschlossen"]],"s":["Bildschirm dunkel, Inhalt bei hellem Licht nur schwach erkennbar","Helligkeit lässt sich nicht regeln oder folgt keinem Tag-/Nachtwechsel","Ungleichmäßige, flackernde oder teilweise dunkle Beleuchtung"],"k":["display_module","backlight_circuit"],"r":["medium",0,[150,1200],[0.5,3]],"f":"","x":["B0455"]},{"c":"B0500","t":"Fensterheber Fahrer Stromkreis Fehlfunktion","e":"Driver Power Window Circuit Malfunction","d":"B0500 steht in keiner öffentlichen J2012-Liste, und kein Hersteller dokumentiert ihn; der Code ist unbelegt. Gemeint ist der Fensterheberkreis der Fahrertür. Saab nutzt dafür eigene Nummern: Beim 9-3 (2003–2012) speichert das Fahrertürmodul B3205/B3210 für einen offenen, kurzgeschlossenen oder überlasteten Ab- bzw. Aufwärtszweig und versucht es in jedem neuen Fahrzyklus erneut; beim 9-5 von 2011 setzt das Karosseriesteuergerät B3205 für einen unpassenden, intern defekten oder nicht angelernten Motor, im letzten Fall ohne Automatiklauf. In US6906487B2 misst eine H-Brücke den Motorstrom für den Einklemmschutz. FMVSS 118 verlangt, dass ein selbsttätig schließendes Fenster vor 100 N umkehrt; ein Fehler kann das automatische Schließen daher sperren. Schalterfehler sind B0245, der Abwärtszweig allein B0252.","u":[["h","Fensterhebermotor verschlissen, schwergängig oder mit Totpunkt"],["m","Leitungen in der Gummitülle zwischen Karosserie und Tür gebrochen"],["m","Fensterheber-Mechanik oder Führungen klemmen, Motor wird überlastet"],["l","Endlagen nach Abklemmen der Batterie verloren, Neuanlernen nötig"]],"s":["Fahrerfenster bewegt sich nicht oder nur in eine Richtung","Automatiklauf und Einklemmschutz ohne Funktion","Fenster bleibt unterwegs stehen oder fährt grundlos zurück"],"k":["driver_window_motor","driver_window_switch","door_module","body_control_module"],"r":["medium",1,[80,500],[0.5,3]],"f":"","x":["B0245","B0252","B0501","U0222"]},{"c":"B0501","t":"Fensterheber Beifahrer Stromkreis Fehlfunktion","e":"Passenger Power Window Circuit Malfunction","d":"Für B0501 liefern weder die erreichbaren J2012-Listen noch ein Hersteller eine Definition; der Code ist unbelegt. Der Titel meint den Fensterheberkreis der Beifahrertür. Das Beifahrertürmodul des Saab 9-3 nutzt B3205/B3210 für die Motorzweige und B3932, wenn es Strom misst, obwohl der Motor stillstehen sollte; der Automatiklauf entfällt dann. Beim 9-4X von 2011 setzt GM B3210 für den Beifahrermotor, wenn dessen Kompatibilitätskennung nicht zum Karosseriesteuergerät passt. Hondas US7145299B2 zeigt den klassischen Aufbau, bei dem der Hauptschalter in der Fahrertür die Beifahrertür über eine einzige Leitung steuert – der Fehler kann also im Hauptschalter, in der Leitung oder im Schalter vor Ort liegen. Ohne funktionierende Umkehr verbietet die 100-N-Grenze aus FMVSS 118 das automatische Schließen. Der Beifahrer-Schalterkreis ist B0247.","u":[["h","Fensterhebermotor Beifahrer verschlissen oder intern defekt"],["m","Beifahrertaste im Hauptschalter der Fahrertür defekt"],["m","Leitungen im Scharnierdurchgang der Beifahrertür gebrochen"],["l","Ersatzmotor nicht codiert oder nicht an das Karosseriesteuergerät angepasst"]],"s":["Beifahrerfenster weder per eigener Taste noch per Hauptschalter bedienbar","Fenster fährt nur, solange die Taste gedrückt bleibt","Fenster läuft langsam oder bleibt unterwegs stehen"],"k":["passenger_window_motor","passenger_window_switch","door_module","body_control_module"],"r":["medium",1,[80,500],[0.5,3]],"f":"","x":["B0247","B0500","U0223"]},{"c":"B0502","t":"Fensterheber hinten links Stromkreis Fehlfunktion","e":"Left Rear Power Window Circuit Malfunction","d":"B0502 hat in keiner zugänglichen J2012-Liste einen Eintrag, und kein Hersteller beschreibt ihn – der Code bleibt unbelegt. Gemeint ist der Fensterheberkreis hinten links. Beim Saab 9-3 speichert das Türmodul hinten links B3210 04, wenn der Aufwärtszweig des Motors unterbrochen ist und die Scheibe nicht schließt, sowie B3543, wenn die beiden Hall-Signale 150 ms lang in falscher Reihenfolge kommen; dann fällt der Automatiklauf weg. GM vergibt beim 9-5 von 2011 für diesen Motor B3215. Die Microchip-Applikationsschrift AVR480 zeigt, wozu die Hall-Impulse dienen: Drehzahl, Strom und Scheibenposition speisen die Einklemmprüfung. FMVSS 118 fordert für jedes selbsttätig schließende Fenster die Umkehr vor 100 N. Viele Fondtüren haben eine Kindersicherung; ein gesperrter Fondschalter ist gewollt und kein Fehler.","u":[["h","Hall-Geber im Motor oder dessen Versorgung defekt"],["m","Fensterhebermotor hinten links verschlissen oder Wicklung unterbrochen"],["m","Leitungen im Scharnierdurchgang der Fondtür gebrochen"]],"s":["Fenster hinten links schließt oder öffnet nicht","Automatiklauf und Einklemmschutz nicht verfügbar","Fenster fährt ohne Hindernis von selbst zurück"],"k":["left_rear_window_motor","rear_door_module","body_control_module"],"r":["medium",1,[80,450],[0.5,3]],"f":"","x":["B0503","B0500","U0224"]},{"c":"B0503","t":"Fensterheber hinten rechts Stromkreis Fehlfunktion","e":"Right Rear Power Window Circuit Malfunction","d":"Öffentliche J2012-Listen enthalten B0503 nicht, und kein Hersteller veröffentlicht eine Beschreibung; der Code ist unbelegt. Der Titel nennt den Fensterheberkreis hinten rechts. Beim 9-3 setzt Saabs Türmodul hinten rechts B3205 04 bei unterbrochenem Abwärtszweig und b3992 11, wenn die Scheibe zwischen den Endlagen weiter läuft als erwartet; Automatik-Schließen und Einklemmschutz arbeiten dann nicht mehr. GM vergibt beim 9-4X von 2011 für diesen Motor B3220, etwa bei einem internen Motordefekt. Nach FMVSS 118 darf ein Fenster nur dann selbsttätig schließen, wenn es vor 100 N umkehrt – ein Modul, das die Scheibenposition verloren hat, kann das nicht sicherstellen. In US6906487B2 von International Rectifier treibt eine H-Brücke mit Kurzschluss- und Übertemperaturabschaltung einen solchen Motor.","u":[["h","Seilzug oder Führung des Fensterhebers verrutscht, Weg stimmt nicht mehr"],["m","Fensterhebermotor hinten rechts verschlissen oder intern defekt"],["m","Motor- oder Türstecker durch Wasser in der Tür korrodiert"]],"s":["Fenster hinten rechts öffnet nicht oder läuft nur ruckweise","Automatik-Schließen und Einklemmschutz abgeschaltet","Fenster bleibt vor der Dichtung stehen oder läuft geräuschvoll darüber hinaus"],"k":["right_rear_window_motor","rear_door_module","body_control_module"],"r":["medium",1,[80,450],[0.5,3]],"f":"","x":["B0502","B0501","U0225"]},{"c":"B0510","t":"Fahrertür-Kontaktschalter","e":"Driver Door Open Switch","d":"In den öffentlich zugänglichen J2012-Listen fehlt B0510, und kein Hersteller erklärt ihn in frei einsehbaren Unterlagen. GM nennt B0510 zwar im Bulletin PIP5094 (Pkw und leichte Nutzfahrzeuge bis Modelljahr 2014) als Stichwort für Stromkreisprüfungen, jedoch ohne Bezeichnung. Laut Titel geht es um den Schalter, der das Öffnen der Fahrertür meldet. Beim Saab 9-5 von 2011 entspricht dem der Außengriffschalter Fahrerseite mit B3849 02: Ist die Leitung länger als 180 s an Masse oder geschlossen, verwirft das Keyless-Modul den Griff. Wozu das Signal dient, zeigt Toyotas EP2372055A1: Meldet der Türkontakt das Öffnen nicht, kann die Auto-Verriegelung den Schlüssel im Auto einschließen. Für die Beifahrertür gibt es B0520.","u":[["h","Schalter an der Fahrertür verschlissen, verschmutzt oder in einer Stellung hängend"],["m","Leitung im Scharnierdurchgang der Fahrertür gebrochen oder durchgescheuert"],["m","Feuchtigkeit oder Korrosion am Schalterstecker"],["l","Eingangsstufe des Karosserie- oder Keyless-Steuergeräts defekt"]],"s":["Innenlicht bleibt beim Öffnen der Fahrertür aus","Schlüsselloses Öffnen am Fahrertürgriff reagiert nicht","Tür-offen-Meldung oder Warnton fehlt oder steht dauernd an"],"k":["door_jamb_switch","door_wiring_harness","body_control_module"],"r":["easy",1,[20,200],[0.3,1.5]],"f":"","x":["B0520","B0540","B0260"]},{"c":"B0520","t":"Beifahrertür-Kontaktschalter","e":"Passenger Door Open Switch","d":"B0520 steht in keiner zugänglichen J2012-Liste, seine Bedeutung veröffentlicht kein Autohersteller. Vorhanden ist der Code bei GM: Das Bulletin PIP5094 zur Stromkreisprüfung (GM-Fahrzeuge bis 2014) führt ihn als Stichwort, beschreibt ihn aber nicht. Der Titel meint den Schalter, der das Öffnen der Beifahrertür meldet. Der GM-Saab 9-5 von 2011 überwacht den entsprechenden Außengriffschalter vorn rechts als B1474 02 und sperrt diesen Griff, sobald die Leitung über 60 s an Masse liegt oder geschlossen bleibt. Toyotas EP2372055A1 ergänzt eine Plausibilitätsprüfung für sporadische Fehler: Liegt nach dem Entriegeln per Smart-Key der Schlüssel im Innenraum, ohne dass je ein Türöffnen gemeldet wurde, gilt der Schalter als gestört. Fahrerseite: B0510.","u":[["h","Kontakte des Beifahrertürschalters verschlissen, verharzt oder eingefroren"],["m","Leitungsbruch im Scharnierdurchgang der Beifahrertür"],["m","Außengriffschalter durch eingedrungenes Wasser kurzgeschlossen"],["l","Eingang des Karosserie- oder Keyless-Steuergeräts defekt"]],"s":["Öffnen der Beifahrertür wird von Innenlicht oder Alarmanlage nicht erkannt","Außengriff der Beifahrertür wird vom Keyless-System ignoriert","Auto-Verriegelung kann das Auto mit dem Schlüssel im Innenraum wieder verschließen"],"k":["door_jamb_switch","door_wiring_harness","body_control_module"],"r":["easy",1,[20,200],[0.3,1.5]],"f":"","x":["B0510","B0541","B0260"]},{"c":"B0530","t":"Türschloss-Stellmotor Fahrer Stromkreis","e":"Driver Door Lock Actuator Circuit","d":"In den öffentlich zugänglichen J2012-Listen kommt B0530 nicht vor. GM führt ihn in PIP5094 als Stichwort für Stromkreisprüfungen ohne Bezeichnung, und der Saab 9-3 aus der GM-Zeit (2003–2012) belegt B0530 mit etwas ganz anderem, dem linken Blinker: Die vordere Elektrozentrale speichert B0530 04, wenn die Lampe weniger als 50 mA aufnimmt, die hintere B0530 02 bei Masseschluss des Ausgangs – die Blinker laufen dann doppelt schnell. Für den im Titel genannten Stellmotor des Fahrertürschlosses nutzt derselbe 9-3 im Fahrertürmodul eigene Nummern: B3135 02 (Motorleitung an Masse) und B3130 02 (gemeinsame Leitung), beide mit dem Symptom ausgefallene Zentralverriegelung. HELLA nennt Versorgung, Masse, Leitungsbruch und schwergängige Schlossmechanik als typische Fehler.","u":[["h","Schlossmotor im Fahrertürschloss verschlissen oder festgegangen"],["m","Leitungsbruch im Scharnierdurchgang der Tür"],["m","Schwergängige oder verschmutzte Schlossmechanik überlastet den Motor"],["l","Endstufe des Tür- oder Karosseriesteuergeräts defekt"]],"s":["Fahrertür ver- oder entriegelt weder per Funk noch per Schalter","Übrige Türen verriegeln weiterhin normal","Beim Saab 9-3 gehört der Code stattdessen zu einem Fehler am linken Blinker"],"k":["driver_door_lock_actuator","body_control_module","driver_door_module"],"r":["medium",1,[80,400],[1,3]],"f":"","x":["B0531","B0532","B0533","B0265"]},{"c":"B0531","t":"Türschloss-Stellmotor Beifahrer Stromkreis","e":"Passenger Door Lock Actuator Circuit","d":"B0531 findet sich weder in den zugänglichen J2012-Listen noch in einer öffentlichen Herstellerunterlage; der Code selbst ist nicht nachweisbar. Der Titel meint den Schlossmotor der Beifahrertür. Der Saab 9-3 prüft diesen Motor im Beifahrertürmodul und speichert B3135 02, wenn die Leitung bei einer Ver- oder Entriegelungsanforderung an Masse liegt. Beim GM-Saab 9-5 von 2011 steuert dagegen das Karosseriesteuergerät gebündelte Ver- und Entriegelungsleitungen (B3125, B3130, B3135 02) bei 9–18 V an; ein Masseschluss legt die Zentralverriegelung still, ein gespeicherter Code erlischt nach 50 Zündzyklen. Mitsubas US7218120B2 zeigt, wie eine Endstufe vor dem Einschalten mit kleinem Prüfstrom auf Schluss nach Plus oder Masse getestet wird. Fahrertür: B0530.","u":[["h","Schlossmotor der Beifahrertür durchgebrannt oder festgegangen"],["m","Schlossmotorleitung in der Tür an Masse gescheuert"],["m","Wassereintritt am Schlossstecker"],["l","Ausgang des Tür- oder Karosseriesteuergeräts defekt"]],"s":["Beifahrertür bleibt ver- oder entriegelt, während die anderen folgen","Gesamte Zentralverriegelung ausgefallen, wenn eine gemeinsame Leitung an Masse liegt","Hörbares Klicken ohne Bewegung des Schlosses"],"k":["passenger_door_lock_actuator","body_control_module"],"r":["medium",1,[80,400],[1,3]],"f":"","x":["B0530","B0532","B0533","B0270"]},{"c":"B0532","t":"Türschloss-Stellmotor hinten links Stromkreis","e":"Left Rear Door Lock Actuator Circuit","d":"Öffentliche J2012-Listen enthalten B0532 nicht. Bei GM existiert er nur als unerklärtes Stichwort in PIP5094, dem allgemeinen Bulletin zur Stromkreisprüfung für GM-Pkw und leichte Nutzfahrzeuge bis Modelljahr 2014. Der Titel nennt den Schlossmotor der linken Hintertür. Hintertüren haben dabei eine Zusatzaufgabe: Nach FMVSS 206 braucht jede hintere Seitentür eine Verriegelung, die im eingelegten Zustand auch den Innengriff sperrt. Der Saab 9-3 ordnet diesen Motor dem Türmodul hinten links zu und speichert B3135 02, wenn dessen Eingang beim Verriegeln Masseschluss sieht; ist der Fehler weg, versucht der Motor es erneut. Meist bleibt dann nur diese eine Tür im falschen Zustand. Hinten rechts: B0533.","u":[["h","Schlossmotor hinten links verschlissen oder blockiert"],["m","Leitungsbruch in der Gummitülle der linken Hintertür"],["m","Schlossgestänge durch Schmutz oder Korrosion schwergängig"],["l","Ausgang des Hintertür- oder Karosseriemoduls defekt"]],"s":["Linke Hintertür folgt der Zentralverriegelung nicht","Fahrzeug lässt sich von außen nicht vollständig sichern","Sperrung des Innengriffs an dieser Tür funktioniert womöglich nicht"],"k":["left_rear_door_lock_actuator","body_control_module"],"r":["medium",1,[80,400],[1,3]],"f":"","x":["B0530","B0531","B0533","B0272"]},{"c":"B0533","t":"Türschloss-Stellmotor hinten rechts Stromkreis","e":"Right Rear Door Lock Actuator Circuit","d":"B0533 fehlt in den öffentlich einsehbaren J2012-Listen; GMs PIP5094 nennt ihn nur als Stichwort zur Stromkreisprüfung für Modelle bis 2014, ohne zu sagen, wofür er steht. Der Titel ordnet ihn dem Schlossmotor der rechten Hintertür zu. Beim Saab 9-3 überwacht das Türmodul hinten rechts diesen Motor und meldet B3135 02, wenn dessen Leitung beim Ver- oder Entriegeln an Masse liegt. Hintertüren haben oft einen zweiten Stellmotor: Der Saab 9-5 von 2011 versorgt über ein Kindersicherungs-Relais beide hinteren Schlösser und speichert B3930 02 bei Masseschluss dieses Kreises – dann ist auch die Zentralverriegelung außer Betrieb. Erster Diagnoseschritt ist deshalb, Kindersicherung und Hauptschlossmotor auseinanderzuhalten. Hinten links: B0532.","u":[["h","Schlossmotor hinten rechts verschlissen oder blockiert"],["m","Elektrische Kindersicherung oder deren Leitung kurzgeschlossen"],["m","Leitungsbruch in der Gummitülle der rechten Hintertür"],["l","Ausgang des Hintertür- oder Karosseriemoduls defekt"]],"s":["Rechte Hintertür bleibt ver- oder entriegelt","Elektrische Kindersicherung hinten rastet womöglich nicht ein","Zentralverriegelung ausgefallen, wenn ein gemeinsamer hinterer Kreis an Masse liegt"],"k":["right_rear_door_lock_actuator","body_control_module"],"r":["medium",1,[80,400],[1,3]],"f":"","x":["B0530","B0531","B0532","B0272"]},{"c":"B0540","t":"Türkontaktschalter Fahrertür Stromkreis","e":"Driver Door Ajar Switch Circuit","d":"Weder die öffentlichen J2012-Listen noch eine zugängliche Herstellerunterlage definieren B0540; der Code ist unbelegt. Laut Titel geht es um den Stromkreis des Schalters, der meldet, dass die Fahrertür nicht ganz geschlossen ist. Beim Saab 9-3 (GM-Ära) überwacht das Karosseriesteuergerät diesen Eingang als B2976: Untertyp 02 unter 2,9 V (Masseschluss), 05 über 10,2 V (Unterbrechung oder Schluss nach Plus), geprüft bei eingeschalteter Zündung oder scharfer Alarmanlage; im Display erscheint eine Meldung. In Fords US6133827A ist jeder Türkontakt bei geschlossener Tür offen und legt den Eingang beim Öffnen auf Masse; ein defekter Schalter kann das Innenlicht dauerhaft brennen lassen. Für den Tür-offen-Schalter gibt es B0510.","u":[["h","Türkontakt im Schloss oder Türrahmen klemmt oder ist korrodiert"],["m","Schalterleitung im Scharnierdurchgang an Masse gescheuert"],["m","Offene Leitung oder lockerer Kontakt am Schlossstecker"],["l","Eingang des Karosseriesteuergeräts defekt"]],"s":["Tür-offen-Warnung, obwohl die Fahrertür geschlossen ist","Innenlicht bleibt an und kann die Batterie entladen","Alarmanlage oder automatische Verriegelung verhält sich unstet"],"k":["driver_door_ajar_switch","body_control_module"],"r":["easy",1,[40,250],[0.4,1.5]],"f":"","x":["B0541","B0510","B0260"]},{"c":"B0541","t":"Türkontaktschalter Beifahrertür Stromkreis","e":"Passenger Door Ajar Switch Circuit","d":"B0541 lässt sich weder in öffentlichen J2012-Listen noch in veröffentlichten Herstellerdaten nachweisen. Dem Titel nach betrifft er den Türkontakt-Stromkreis der Beifahrertür. Der Saab 9-3 überwacht diesen Schalter im Karosseriesteuergerät als B2991 mit den Schwellen der Fahrerseite: 02 für eine Leitung an Masse unter 2,9 V, 05 für offene Leitung oder Plusschluss über 10,2 V. Viele neuere Türen haben keinen eigenen Kontaktstößel mehr; in ArvinMeritors US20030182863A1 sitzt der Schalter an der Schlossfalle und schaltet etwa auf halbem Weg zwischen Vollrast und Sicherheitsrast – eine nur in der Vorrast gehaltene Tür gilt also weiter als offen. Oft ist deshalb das Türschloss selbst zu tauschen. Fahrerseite: B0540.","u":[["h","Türkontakt im Schloss der Beifahrertür verschlissen"],["m","Tür erreicht wegen verstelltem Schließbolzen nur die Vorrast"],["m","Schalterleitung im Scharnierdurchgang offen oder an Masse"],["l","Eingang des Karosseriesteuergeräts defekt"]],"s":["Beifahrertür wird während der Fahrt als offen gemeldet","Innenlicht reagiert nicht auf die Beifahrertür","Alarmanlage lässt sich nicht schärfen oder löst fälschlich aus"],"k":["passenger_door_ajar_switch","body_control_module"],"r":["easy",1,[40,300],[0.4,2]],"f":"","x":["B0540","B0520","B0260"]},{"c":"B0560","t":"Elektrischer Sitz Fahrer Vor/Zurück Stromkreis","e":"Driver Power Seat Forward/Back Circuit","d":"B0560 gehört nicht zu den öffentlich zugänglichen J2012-Listen. GM verwendet den Code: Die Vorabinformation PIT5404 für Tahoe, Suburban, Yukon und Escalade (2015) lässt bei Dröhnen der aktiven Geräuschkompensation B0560 zusammen mit B1277, B127C und B127D prüfen, nennt aber keine Bezeichnung – eine Sitz-Bedeutung lässt sich daraus nicht ableiten. Für den Längsverstellmotor des Titels nutzt das Fahrersitzmodul des Saab 9-3 B1770: Untertyp 04, wenn ein Ausgang unter 6 V bleibt (in Gegenrichtung unter Batteriespannung minus 0,7 V), 0B über 40 A; die Memory-Funktion ist dann gesperrt. Aisins US8781691B2 zählt Hall-Impulse dieses Motors, um die Längsposition zu bestimmen.","u":[["h","Sitzschiene durch Gegenstände oder Schmutz blockiert, Motor überlastet"],["m","Längsverstellmotor oder dessen Getriebe verschlissen"],["m","Leitungen unter dem Sitz eingeklemmt oder Stecker locker"],["l","Relais oder Endstufe im Sitzmodul defekt"]],"s":["Fahrersitz fährt nicht vor oder zurück","Gespeicherte Sitzpositionen lassen sich nicht abrufen","Sitz bleibt nach kurzem Weg stehen oder fährt nur in eine Richtung"],"k":["driver_seat_track_motor","seat_control_module"],"r":["medium",1,[100,500],[1,3.5]],"f":"","x":["B0561","B0562","B0570","B0312","B0310"]},{"c":"B0561","t":"Elektrischer Sitz Fahrer Hoch/Runter Stromkreis","e":"Driver Power Seat Up/Down Circuit","d":"Für B0561 gibt es keinen Eintrag in den zugänglichen J2012-Listen und keine öffentliche Herstellerdefinition. Gemeint ist der Motor, der den Fahrersitz hebt und senkt; Chryslers US4682088A teilt das auf einen vorderen und einen hinteren Polstermotor mit rund 1,5 Zoll Hub auf. Das Fahrersitzmodul des Saab 9-3 nennt den Höhenmotor-Kreis B1765: 04 bei offenem Ausgang, 0B bei mehr als 40 A; der Ausgang wird abgeschaltet und je Zündzyklus einmal neu versucht. Der GM-Saab 9-5 von 2011 prüft dagegen vor jedem Motorlauf einen gemeinsamen Bezugspunkt von etwa 2,5 V und setzt B3920, wenn dieser 100 ms lang über 2,78 V oder unter 1,47 V liegt – dann stehen alle Motoren dieser Versorgungsschiene. Ein Fehler der Höhenachse legt deshalb oft weitere Achsen still.","u":[["h","Höhenverstellmotor oder Spindelgetriebe festgegangen"],["m","Motorleitungen beim Absenken vom Sitzgestell eingeklemmt"],["m","Kurzschluss auf einer mit anderen Sitzachsen geteilten Motorleitung"],["l","Endstufe des Sitzmoduls defekt"]],"s":["Höhe des Fahrersitzes lässt sich nicht verstellen","Andere Sitzachsen können ebenfalls ausfallen","Memory-Abruf unvollständig oder gesperrt"],"k":["driver_seat_lift_motor","seat_control_module"],"r":["medium",1,[100,500],[1,3.5]],"f":"","x":["B0560","B0562","B0580"]},{"c":"B0562","t":"Elektrischer Sitz Fahrer Lehnenneigung Stromkreis","e":"Driver Power Seat Recline Circuit","d":"B0562 fehlt in öffentlichen J2012-Listen, kein Hersteller dokumentiert ihn. Der Titel meint den Stromkreis des Lehnenneigungsmotors im Fahrersitz, der in Chryslers US4682088A die Rückenlehne um rund 38 Grad schwenkt. Der Saab 9-3 meldet diesen Motor im Fahrersitzmodul als B1785: 04, wenn eine Ausgangsspannung zu niedrig bleibt (Unterbrechung), 0B bei mehr als 40 A Stromaufnahme, etwa bei verklemmtem Lehnenversteller; gespeicherte Positionen lassen sich dann nicht abrufen. Beim GM-Saab 9-5 von 2011 steckt zusätzlich ein Hall-Sensor im Lehnenmotor, versorgt mit 12 V; dessen Signalfehler laufen getrennt unter B1825 01/06. Für den Fahrer bleibt die Lehne meist in der zuletzt eingestellten Neigung stehen.","u":[["h","Lehnenversteller verklemmt oder verschlissen, Motor zieht zu viel Strom"],["m","Lehnenmotor mit offener Wicklung oder verschlissenen Bürsten"],["m","Leitung zwischen Sitzunterteil und Lehne gebrochen"],["l","Ausgang des Sitzmoduls defekt"]],"s":["Neigung der Fahrerlehne lässt sich nicht ändern","Memory-Positionen werden nicht angefahren","Motor brummt oder klickt, ohne dass die Lehne sich bewegt"],"k":["driver_seat_recline_motor","seat_control_module"],"r":["medium",1,[100,550],[1,3.5]],"f":"","x":["B0560","B0561","B0322"]},{"c":"B0570","t":"Elektrischer Sitz Beifahrer Vor/Zurück Stromkreis","e":"Passenger Power Seat Forward/Back Circuit","d":"B0570 ist in keiner öffentlich zugänglichen J2012-Liste und in keiner veröffentlichten Herstellerunterlage zu finden. Der Titel betrifft den Längsverstellmotor des Beifahrersitzes. Wie ein solcher Kreis überwacht wird, zeigt das Beifahrersitzmodul des Saab 9-3: B1770 04 bei offenem Ausgang, 0B über 40 A und 61 bei einem an Masse klebenden Relais, erkannt direkt nach dem Sanftanlauf, weil der Ausgang über 6 V liegt. Im letzten Fall fährt der Sitz nicht mehr in die gewählte, wohl aber in die Gegenrichtung; in allen Fällen fällt die Memory-Funktion aus. Laut TIs Artikel über Memory-Sitze erfassen meist Hall-Sensoren am Motor die Umdrehungen, aus denen der Sitzweg berechnet wird. Fahrerseite: B0560.","u":[["h","Gegenstände unter dem Beifahrersitz blockieren die Schiene"],["m","Relais im Sitzmodul klebt, Sitz fährt nur in eine Richtung"],["m","Längsverstellmotor unterbrochen oder Bürsten verschlissen"],["l","Stecker unter dem Sitz locker oder korrodiert"]],"s":["Beifahrersitz lässt sich nicht vor- oder zurückschieben","Sitz fährt nur in eine Richtung","Memory- oder Einstiegshilfe-Funktion des Beifahrersitzes nicht verfügbar"],"k":["passenger_seat_track_motor","seat_control_module"],"r":["medium",1,[100,500],[1,3.5]],"f":"","x":["B0560","B0320","B0327"]},{"c":"B0580","t":"Sitzspeicher-Modul Fahrer Fehlfunktion","e":"Driver Seat Memory Module Malfunction","d":"B0580 fehlt in den öffentlich zugänglichen J2012-Listen, eine öffentliche Herstellerdefinition gibt es nicht. Der Titel beschreibt einen internen Fehler des Memory-Moduls am Fahrersitz. Was ein solches Modul an sich selbst prüft, zeigt der GM-Saab 9-5 von 2011: B3920 42, wenn die Kalibrierung nie programmiert wurde, B3920 00, wenn hinaus- und zurückfließender Strom einer Motorschiene nicht übereinstimmen, dazu Spannungsfehler der Schiene; das Modul sperrt dann diese Motoren, ein gespeicherter Code erlischt nach 40 fehlerfreien Zündzyklen. Beim Saab 9-3 legt B3920 01 (Ausgang über 12 V, obwohl nicht angesteuert) alle Memory-Funktionen still, eine klemmende Speichertaste (B2755 01) wird dagegen nur ignoriert. Chryslers US4682088A legt gespeicherte Positionen in nichtflüchtigem Speicher ab.","u":[["m","Ersatzmodul ohne Kalibrierung oder Einrichtung verbaut"],["m","Interner Elektronikfehler des Memory-Moduls"],["m","Flüssigkeit unter dem Sitz erreicht das Modul"],["l","Niedrige Batteriespannung oder schlechte Modulmasse"]],"s":["Speichertasten rufen keine Sitz- oder Spiegelpositionen ab","Elektrischer Sitz teilweise oder ganz ohne Funktion","Gespeicherte Positionen nach Spannungsunterbrechung verloren"],"k":["driver_seat_memory_module"],"r":["hard",0,[150,800],[0.5,3]],"f":"","x":["B0560","B0561","B0562","B0325","B0327"]},{"c":"B0600","t":"Spiegelverstellung Fahrerseite Stromkreis","e":"Mirror Adjustment Driver Side Circuit","d":"B0600 steht in keiner öffentlich zugänglichen J2012-Tabelle, und kein Hersteller erläutert ihn. Gemeint ist der Verstellkreis des Fahrer-Außenspiegels, den FMVSS 111 vom Fahrersitz aus waagrecht und senkrecht neigbar verlangt. Der Saab 9-3 überwacht beide Spiegelmotoren im Fahrertürmodul: B1723 01 bei Schluss des Links/Rechts-Ausgangs nach Plus, B1724 02 bei Masseschluss des Hoch/Runter-Ausgangs; ausgewertet wird nur, solange die gemeinsame Motorleitung (B1600) fehlerfrei ist. Das Modul versucht die betroffene Achse dann je Fahrzyklus viermal. Memory-Spiegel erfassen zusätzlich die Glasstellung; in Britax' US6254242B1 übernimmt das ein direkt mit dem Glas verbundenes Potentiometer.","u":[["h","Spiegelverstellmotor durch Korrosion oder Eis festgegangen"],["m","Spiegelleitungen im Scharnierdurchgang gebrochen"],["m","Wasser im Spiegelgehäuse schließt Motor oder Sensor kurz"],["l","Ausgang des Fahrertürmoduls defekt"]],"s":["Fahrerspiegel bewegt sich in einer oder beiden Achsen nicht","Gespeicherte Spiegelposition wird nicht angefahren","Sicht nach hinten auf der Fahrerseite eingeschränkt, bis von Hand eingestellt"],"k":["driver_mirror_motor","door_module"],"r":["medium",1,[80,450],[0.5,2.5]],"f":"","x":["B0601","B0610"]},{"c":"B0601","t":"Spiegelverstellung Beifahrerseite Stromkreis","e":"Mirror Adjustment Passenger Side Circuit","d":"B0601 ist weder in öffentlichen J2012-Listen noch in zugänglichen Herstellerunterlagen erfasst. Dem Titel nach betrifft er den Verstellkreis des Beifahrer-Außenspiegels; nach FMVSS 111 muss dieser nicht vom Fahrersitz aus einstellbar sein, ist aber meist motorisch verstellbar. TIs Anwendungsbeschreibung zeigt den üblichen Aufbau: zwei kleine Bürstenmotoren unter 1 A an drei Halbbrücken mit einem gemeinsamen Zweig. Das Beifahrertürmodul des Saab 9-3 speichert B1723 02 oder B1724 01 bei kurzgeschlossenem Motorausgang. Im GM-Saab 9-5 (2011) übernimmt der Beifahrer-Fensterschalter die Spiegelansteuerung; ein interner Fehler dort setzt B154B 39 und stoppt die Spiegelverstellung, solange er besteht; der gespeicherte Code erlischt nach 40 Zyklen.","u":[["h","Spiegelmotor auf der Beifahrerseite festgegangen oder verschlissen"],["m","Gemeinsame Motorleitung kurzgeschlossen, beide Achsen betroffen"],["m","Leitungsbruch im Scharnierdurchgang der Beifahrertür"],["l","Elektronik von Beifahrertürmodul oder Fensterschalter defekt"]],"s":["Beifahrerspiegel lässt sich nicht elektrisch verstellen","Absenken beim Rückwärtsgang oder Memory-Position des Spiegels fehlt","Fahrerspiegel funktioniert meist weiter"],"k":["passenger_mirror_motor","door_module"],"r":["medium",1,[80,450],[0.5,2.5]],"f":"","x":["B0600","B0610"]},{"c":"B0610","t":"Spiegelheizung Stromkreis","e":"Mirror Heater Circuit","d":"Öffentliche J2012-Listen, Werkstattunterlagen und NHTSA-Bulletins kennen B0610 nicht; seine Verwendung ist unbelegt. Gemeint ist das Heizelement hinter dem Glas des Außenspiegels. Beim Saab 9-3 (2003–2012) überwacht das jeweilige Türmodul diese Last selbst: Fließt beim Einschalten zu viel Strom, legt es B1640 02 ab und versucht es erst im nächsten Fahrzyklus erneut. Magnas Patent US9481304B2 nennt als Beispiel eine Heizfolie von rund 23 W (1,8 A bei 13 V), oft als PTC-Element, deren Leistung im Stand zurückgenommen wird. TI zählt die Fehlerüberwachung von Klappmotor und Heizung zu den Grundaufgaben eines Spiegelmoduls. Ein Ausfall betrifft nur das Abtauen; die Verstellung hat eigene Codes (B0600, B0601).","u":[["h","Heizfolie hinter dem Spiegelglas unterbrochen oder kurzgeschlossen"],["m","Korrodierter Stecker am Spiegelglas oder im Spiegelfuß"],["m","Leitung im Scharnierdurchgang der Tür durchgescheuert"],["l","Heizungsausgang des Tür- oder Karosseriesteuergeräts defekt"]],"s":["Außenspiegel bleibt beschlagen oder vereist, während die Heckscheibe frei wird","Spiegelglas wird bei eingeschalteter Heizung nicht warm","Code kehrt nach jedem Neustart zurück"],"k":["mirror_heater_element","body_control_module"],"r":["easy",1,[40,300],[0.3,2]],"f":"","x":["B0600","B0601","B0950"]},{"c":"B0700","t":"Schiebedach Öffnen/Schließen Stromkreis","e":"Sunroof Open/Close Circuit","d":"Weder eine zugängliche J2012-Liste noch eine öffentliche Herstellerunterlage oder ein NHTSA-Bulletin enthält B0700; der Code ist nicht nachweisbar. Der Titel meint den Stromkreis, der ein elektrisches Schiebedach auf- und zufährt. Saab-Modelle aus der GM-Zeit melden solche Fehler unter eigenen Nummern: Das Dachmodul des 9-3 speichert B3661 0E bei zu hohem Motorstrom und B3664 04 bei unterbrochener Schalterleitung, danach ignoriert es Tastendrücke; B3664 0A folgt, wenn eine Schalterstellung länger als 30 s anliegt. Beim 9-5 von 2011 liest das Modul den Schalter als Widerstandskette und meldet B3664 per LIN an das Karosseriesteuergerät. FMVSS 118 verlangt, dass ein schließendes Dach vor 100 N Klemmkraft umkehrt – deshalb wird der Motorstrom überhaupt überwacht. Positionsrückmeldung: B0710.","u":[["h","Verschmutzte oder trockene Führungsschienen erhöhen den Motorstrom"],["m","Schiebedachschalter oder dessen Leitung defekt"],["m","Schiebedachmotor oder Getriebe verschlissen"],["l","Steuerelektronik des Schiebedachs defekt"]],"s":["Schiebedach bewegt sich bei Tastendruck nicht","Dach bleibt beim Schließen stehen oder fährt von selbst zurück","Motor brummt, ohne dass sich der Deckel bewegt"],"k":["sunroof_motor","sunroof_control_module"],"r":["medium",1,[50,900],[0.5,4]],"f":"","x":["B0710"]},{"c":"B0710","t":"Schiebedach Positionssensor Stromkreis","e":"Sunroof Position Sensor Circuit","d":"Nichts Öffentliches bestätigt B0710 – weder J2012-Auszüge noch Werkstatthandbücher oder Rückruf-Bulletins. Der Titel betrifft die Positionsrückmeldung eines elektrischen Schiebedachs. Üblich ist ein Hall-Sensor an der Motorwelle, dessen Impulse gezählt werden: Nedaps NL1001829C2 gewinnt aus den Polwechseln Lage und Geschwindigkeit des Deckels, Boschs DE19815960A1 setzt einen solchen Zähler an einem mechanischen Anschlag zurück und unterscheidet damit Schiebe- und Ausstellbereich. Fehlen gültige Impulse, arbeiten weder der von FMVSS 118 geforderte Einklemmschutz noch die Tipp-Automatik. Beim Saab 9-5 von 2011 meldet die Motoreinheit eine fehlende Kalibrierung als B3697 4B; der 9-3 schaltet bei falsch montiertem Motor oder blockierter Mechanik mit B3696 0B die Automatik ab. Antrieb: B0700.","u":[["h","Endlagen nach Abklemmen der Batterie oder Motortausch nicht neu angelernt"],["m","Hall-Sensor oder Motorelektronik defekt"],["m","Schwergängige Mechanik oder falsch montierter Motor"],["l","Signalleitung oder Stecker am Motor beschädigt"]],"s":["Tipp-Automatik zum Öffnen oder Schließen funktioniert nicht mehr","Dach stoppt vor der Endlage oder fährt unerwartet zurück","Dach lässt sich bis zum Neuanlernen nur schrittweise bewegen"],"k":["sunroof_position_sensor","sunroof_control_module"],"r":["medium",1,[20,700],[0.3,3]],"f":"","x":["B0700"]},{"c":"B0800","t":"Lichtschalter Stromkreis","e":"Headlamp Switch Circuit","d":"Für B0800 gibt es keinen öffentlichen Beleg; kein J2012-Auszug und keine Serviceunterlage erwähnt ihn. Der Titel betrifft den Lichtschalter, über den das Karosseriesteuergerät erfährt, welche Leuchten es einschalten soll. Beim Saab 9-3 der zweiten Generation prüft das BCM die Schalterstellungen 1 und 2 und speichert B2585 05 bzw. B2575 05, wenn die jeweilige Leitung über 10,2 V steigt; das Abblendlicht leuchtet dann unabhängig von der Schalterstellung. Der GM-Saab 9-5 von 2011 vergleicht seine Eingänge für Licht an und Licht aus, legt bei unplausibler Kombination B257A ab und schaltet auf Lichtautomatik. FMVSS 108 schreibt Abblendschalter und Fernlichtkontrolle vor. Beide Ersatzreaktionen halten das Licht nutzbar – auffällig ist vor allem die fehlende Handbedienung.","u":[["h","Verschlissene oder korrodierte Kontakte im Lichtschalter"],["m","Signalleitung des Schalters mit Plus kurzgeschlossen"],["m","Lockerer oder beschädigter Stecker hinter dem Schalter"],["l","Schaltereingang des Karosseriesteuergeräts defekt"]],"s":["Abblendlicht bleibt unabhängig von der Schalterstellung an","Licht arbeitet nur noch im Automatikbetrieb","Standlicht lässt sich nicht getrennt einschalten"],"k":["headlamp_switch","body_control_module"],"r":["easy",1,[30,250],[0.3,1.5]],"f":"","x":["B0240","B0810","B0811"]},{"c":"B0810","t":"Abblendlicht links Stromkreis","e":"Left Headlamp Low Beam Circuit","d":"Ob ein Hersteller B0810 setzt, ist offen – die Nummer erscheint in keinem J2012-Auszug und keiner Werkstattliteratur. Der Titel betrifft den Ausgang für das linke Abblendlicht. Der Saab 9-3 aus der GM-Zeit kontrolliert ihn in der vorderen Elektrozentrale unter der Nummer B2575: Bei Lichtschalter in Stellung 2 führt eine Stromaufnahme unter 0,8 A zu B2575 04 (Unterbrechung), eine zwischen 7,9 und 30 A zu B2575 0B – das kann auch auf eine Lampe falscher Leistung hindeuten. Bei Xenonlicht muss die Zündung 30 s eingeschaltet sein, bevor die Prüfung läuft. HELLA erklärt den Grund: Das Vorschaltgerät zündet die Lampe mit bis zu 30 kV und regelt sie erst danach auf konstant 35 W. Ein dunkles linkes Abblendlicht ist ein Sicherheitsmangel; vor einer Nachtfahrt instand setzen. Rechte Seite: B0811.","u":[["h","Glühlampe des Abblendlichts durchgebrannt"],["m","Lampe mit falscher Leistung eingesetzt"],["m","Xenon-Vorschaltgerät oder Zündgerät defekt"],["m","Korrodierter Scheinwerferstecker oder schlechte Masse"],["l","Lampenausgang des Licht- oder Karosseriesteuergeräts defekt"]],"s":["Linkes Abblendlicht dunkel, Lampenausfall-Meldung im Display","Schlechtere Sicht auf den linken Fahrbahnrand bei Nacht; vor Fahrten im Dunkeln reparieren","Licht flackert oder fällt erst nach dem Warmwerden aus"],"k":["left_low_beam_lamp","body_control_module"],"r":["easy",1,[10,600],[0.2,2]],"f":"","x":["B0811","B0800","B0820"]},{"c":"B0811","t":"Abblendlicht rechts Stromkreis","e":"Right Headlamp Low Beam Circuit","d":"Kein J2012-Auszug und kein veröffentlichter Servicetext verwendet B0811; der Code bleibt undokumentiert. Der Titel nennt den Stromkreis des rechten Abblendlichts. Beim GM-Saab 9-5 von 2011 versorgt das Karosseriesteuergerät Abblend- oder Tagfahrlicht, und ein eigenes Scheinwerfersteuergerät legt B2699 ab (02 Masseschluss, 04 Unterbrechung, 00 Fehlfunktion), wenn eine angesteuerte Leuchte dunkel bleibt. Der ältere 9-3 verwendet dieselbe Nummer B2699 für sein rechtes Abblendlicht und setzt 04 unter 0,8 A bzw. 0B zwischen 7,9 und 30 A, etwa nach Einbau einer Lampe falscher Leistung. FMVSS 108 regelt die Anforderungen an das Abblendlicht jedes Fahrzeugs. Fällt es rechts aus, ist der Fahrbahnrand nachts schlecht ausgeleuchtet – zügig reparieren. Linke Seite: B0810.","u":[["h","Lampe oder LED-Einheit des rechten Abblendlichts ausgefallen"],["m","Falsche Lampenleistung nach einem Tausch"],["m","Versorgungsleitung zum Scheinwerfer unterbrochen oder an Masse"],["l","Ausgang des Scheinwerfer- oder Karosseriesteuergeräts defekt"]],"s":["Rechtes Abblend- oder Tagfahrlicht bleibt dunkel","Lampenwarnung im Kombiinstrument","Fahrbahnrand nachts schlecht ausgeleuchtet; umgehend reparieren lassen"],"k":["right_low_beam_lamp","body_control_module"],"r":["easy",1,[10,600],[0.2,2]],"f":"","x":["B0810","B0800","B0821"]},{"c":"B0820","t":"Fernlicht links Stromkreis","e":"Left Headlamp High Beam Circuit","d":"B0820 ist undokumentiert: Weder offene J2012-Unterlagen noch Werks- oder NHTSA-Papiere führen ihn. Der Titel betrifft den Ausgang des linken Fernlichts. Beim Saab 9-3 der Baureihe 9440 meldet die vordere Elektrozentrale B2580 04, wenn das eingeschaltete linke Fernlicht weniger als 0,8 A aufnimmt, und B2580 0B bei 7,9 bis 30 A. Der GM-Saab 9-5 von 2011 ist anders aufgebaut: Beide Fernlichter hängen an einem Relais, dessen Spule das Karosseriesteuergerät nach Masse schaltet; ein Schluss nach Plus auf dieser Steuerleitung ergibt B2580 01, und beide Fernlichter bleiben aus. Laut HELLA erzeugen Bi-Xenon-Module beide Lichtarten über eine bewegliche Blende – der Fehler kann auch dort liegen. FMVSS 108 verlangt eine Fernlichtkontrolle. Rechte Seite: B0821.","u":[["h","Glühlampe des linken Fernlichts durchgebrannt"],["m","Fernlichtrelais oder dessen Steuerleitung defekt"],["m","Blendenversteller im Bi-Xenon-Modul klemmt"],["l","Korrodierter Scheinwerferstecker"]],"s":["Linkes Fernlicht bleibt beim Aufblenden dunkel","Beide Fernlichter fallen aus, wenn der gemeinsame Relaiskreis betroffen ist","Lampenausfall-Meldung im Display"],"k":["left_high_beam_lamp","body_control_module"],"r":["easy",1,[10,500],[0.2,2]],"f":"","x":["B0821","B0810","B0800"]},{"c":"B0821","t":"Fernlicht rechts Stromkreis","e":"Right Headlamp High Beam Circuit","d":"Zu B0821 findet sich keine öffentliche Spur in J2012-Auszügen, Werkshandbüchern oder NHTSA-Akten. Der Titel beschreibt den Stromkreis des rechten Fernlichts. Der Saab 9-3 der GM-Ära überwacht ihn unter eigener Nummer B3866: Unterbrechung (04), wenn die Lampe bei eingeschaltetem Fernlicht unter 0,8 A aufnimmt, Überstrom (0B) zwischen 7,9 und 30 A; außer der Warnung reagiert das Modul nicht. Da Fernlicht nur auf freier Strecke genutzt wird, fällt ein einseitiger Ausfall oft spät auf, meist als dunklerer rechter Fahrbahnrand. Beim GM-Saab 9-5 von 2011 schaltet dagegen ein Fehler im gemeinsamen Relaiskreis (B2580 01) beide Seiten zugleich ab. FMVSS 108 zählt Abblendschalter und Fernlichtkontrolle zur Pflichtausstattung. Linke Seite: B0820.","u":[["h","Lampe des rechten Fernlichts ausgefallen"],["m","Versorgungsleitung zum rechten Scheinwerfer unterbrochen oder kurzgeschlossen"],["m","Lampe höherer Leistung eingesetzt, Überstrom erkannt"],["l","Fernlichtausgang des Lichtsteuergeräts defekt"]],"s":["Rechtes Fernlicht bleibt dunkel, linkes funktioniert","Lampenwarnung im Display beim Aufblenden"],"k":["right_high_beam_lamp","body_control_module"],"r":["easy",1,[10,500],[0.2,2]],"f":"","x":["B0820","B0811"]},{"c":"B0830","t":"Blinker vorn links Stromkreis","e":"Left Front Turn Signal Circuit","d":"Offene J2012-Quellen enthalten B0830 nicht, und kein Werkstatt- oder NHTSA-Text zitiert ihn – er bleibt unbestätigt. Der Titel betrifft den linken vorderen Blinker. Der Saab 9-3 der zweiten Generation überwacht diese Leuchte in der vorderen Elektrozentrale als B0530: Mehr als 6 A für länger als 6 ms gilt als Masseschluss, und der Ausgang wird abgeschaltet; unter 50 mA gilt als Unterbrechung. FMVSS 108 (S9.3.6) verlangt, dass eine ausgefallene Blinkleuchte über die Kontrollleuchte erkennbar wird – durch Dauerlicht, Dunkelbleiben oder deutlich geänderte Blinkfrequenz. HELLA rät, zuerst Lampe, Korrosion in der Fassung, Sicherung und Stecker zu prüfen, bevor die Elektronik in Verdacht gerät. Ein toter vorderer Blinker verbirgt die Abbiegeabsicht vor dem Gegenverkehr. Übrige Ecken: B0831, B0840, B0841.","u":[["h","Blinkerlampe durchgebrannt"],["m","Korrodierte Fassung oder Stecker im Scheinwerfergehäuse"],["m","Versorgungsleitung mit Masse kurzgeschlossen, Ausgang abgeschaltet"],["l","Blinkerausgang der Elektrozentrale defekt"]],"s":["Linker vorderer Blinker dunkel, Warnung im Display","Kontrollleuchte leuchtet dauernd oder blinkt deutlich schneller","Abbiegeabsicht für Gegenverkehr nicht erkennbar; umgehend reparieren"],"k":["left_front_turn_signal","body_control_module"],"r":["easy",1,[5,250],[0.2,1.5]],"f":"","x":["B0831","B0840","B0841"]},{"c":"B0831","t":"Blinker vorn rechts Stromkreis","e":"Right Front Turn Signal Circuit","d":"B0831 hat keine veröffentlichte Definition; J2012-Auszüge, Werksliteratur und NHTSA-Bestände schweigen dazu. Der Titel nennt den Stromkreis des rechten vorderen Blinkers. Beim Saab 9-3 aus der GM-Zeit prüft die vordere Elektrozentrale diese Leuchte als B0525 mit denselben Grenzen wie links: weniger als 50 mA wertet sie als Unterbrechung (04), mehr als 6 A über 6 ms hinaus als Masseschluss (02) mit Abschaltung des Ausgangs. Dieselbe Nummer B0525 nutzt die hintere Zentrale für die rechte Heckleuchte – entscheidend ist also, welches Modul den Code meldet. FMVSS 108 schreibt jedem Fahrzeug Blinkgeber, Kontrollleuchte und Warnblinkanlage vor. HELLA nennt defekte Lampen, korrodierte Kontakte und beschädigte Stecker als häufigste Ursachen. Vorn links: B0830; hinten rechts: B0841.","u":[["h","Lampe des rechten vorderen Blinkers ausgefallen"],["m","Wasser im Leuchtengehäuse korrodiert die Kontakte"],["m","Leitung nach Frontschaden oder Reparatur beschädigt"],["l","Ausgang der vorderen Elektrozentrale defekt"]],"s":["Rechter vorderer Blinker bleibt beim Rechtsblinken dunkel","Geänderte Blinkfrequenz oder Dauerlicht der Kontrollleuchte","Warnblinkanlage vorn rechts unvollständig"],"k":["right_front_turn_signal","body_control_module"],"r":["easy",1,[5,250],[0.2,1.5]],"f":"","x":["B0830","B0841","B0840"]},{"c":"B0840","t":"Blinker hinten links Stromkreis","e":"Left Rear Turn Signal Circuit","d":"Weder J2012-Auszüge noch eine Hersteller- oder NHTSA-Veröffentlichung nennen B0840; seine Verwendung ist unbewiesen. Der Titel betrifft den linken hinteren Blinker. Beim Saab 9-3 (2003–2012) überwacht die hintere Elektrozentrale diese Leuchte unter der Nummer B0530: Eine Unterbrechung (04) oder ein Masseschluss (02) zeigt sich als Warnmeldung und als doppelt schnelles Blinken der übrigen Blinker – genau das Verhalten der Kontrollleuchte, das FMVSS 108 für eine ausgefallene Blinkleuchte zulässt. Laut HELLA steuern heute Karosserie- oder Lichtsteuergeräte die Heckleuchten an, oft mit LED-Segmenten; zur Diagnose gehören Fehlerspeicher, Stecker und Versorgung. Ein ausgefallener hinterer Blinker verbirgt Spurwechsel vor dem nachfolgenden Verkehr. Hinten rechts: B0841.","u":[["h","Lampe oder LED-Segment des hinteren Blinkers ausgefallen"],["m","Korrodierter Stecker oder Lampenträger in der Heckleuchte"],["m","Leitungsbruch im Kabelstrang von Kofferraumdeckel oder Heckklappe"],["l","Ausgang der hinteren Elektrozentrale defekt"]],"s":["Blinker blinken beim Linksblinken doppelt so schnell","Linker hinterer Blinker dunkel, Warnmeldung im Display","Spurwechsel für nachfolgenden Verkehr nicht erkennbar; umgehend reparieren"],"k":["left_rear_turn_signal","body_control_module"],"r":["easy",1,[5,300],[0.2,1.5]],"f":"","x":["B0841","B0830","B0850"]},{"c":"B0841","t":"Blinker hinten rechts Stromkreis","e":"Right Rear Turn Signal Circuit","d":"Einen öffentlichen Nachweis für B0841 gibt es weder in J2012-Listen noch in Handbüchern oder Bulletins. Der Titel betrifft den Stromkreis des rechten hinteren Blinkers. Der Saab 9-3 der Baureihe 9440 führt diese Leuchte in der hinteren Elektrozentrale als B0525: eine Stromaufnahme unter 50 mA steht für Unterbrechung (04); fließen länger als 6 ms über 6 A, erkennt sie Masseschluss (02) und schaltet ab. In beiden Fällen sieht der Fahrer eine Meldung und verdoppelte Blinkfrequenz. FMVSS 108 lässt eine solche Frequenzänderung als vorgeschriebene Ausfallanzeige zu. HELLA empfiehlt, Lampe, Fassung und Stecker auf Korrosion zu prüfen und bei PWM-angesteuerten Leuchten das Signal mit Oszilloskop oder Tester zu messen. Ein dunkler Blinker hinten rechts kündigt Abbiegen und Spurwechsel nicht an. Hinten links: B0840.","u":[["h","Lampe des rechten hinteren Blinkers durchgebrannt"],["m","Korrodierte Kontakte im Lampenträger"],["m","Eingeklemmte Leitung mit Masseschluss zur Karosserie"],["l","Lampentreiber im hinteren Steuergerät defekt"]],"s":["Blinker blinken beim Rechtsblinken doppelt so schnell","Rechter hinterer Blinker leuchtet nicht, Meldung im Display"],"k":["right_rear_turn_signal","body_control_module"],"r":["easy",1,[5,300],[0.2,1.5]],"f":"","x":["B0840","B0831","B0851"]},{"c":"B0850","t":"Bremsleuchte links Stromkreis","e":"Left Brake Lamp Circuit","d":"B0850 lässt sich aus keiner offenen Quelle bestätigen – J2012-Tabellen, Herstellerdoku und NHTSA-Bulletins lassen ihn aus. Der Titel betrifft die linke Bremsleuchte. Beim Saab 9-3 der GM-Ära prüft die hintere Elektrozentrale sie beim Bremsen unter eigener Nummer B3445: unter 50 mA erkennt sie eine Unterbrechung (04), über 6 A länger als 6 ms einen Masseschluss (02) und schaltet den Ausgang ab. Die hochgesetzte dritte Bremsleuchte hat dort einen eigenen Code (B3884). FMVSS 108 schreibt Bremsleuchten vor und beschreibt die hochgesetzte Leuchte als dauerhafte Bremswarnung, die durch andere Fahrzeuge hindurch sichtbar ist. HELLA nennt Lampe, Fassung, Sicherung und Steckverbindung als erste Prüfpunkte. Eine fehlende Bremsleuchte schwächt die Warnung an den Hintermann – sofort reparieren. Rechte Seite: B0851.","u":[["h","Lampe oder Glühfaden der linken Bremsleuchte ausgefallen"],["m","Korrodierter Lampenträger in der Heckleuchte"],["m","Leitung zur linken Heckleuchte unterbrochen oder an Masse"],["l","Bremslichtausgang des hinteren Steuergeräts defekt"]],"s":["Linke Bremsleuchte bleibt beim Bremsen dunkel, Warnung im Display","Schwächere Warnung an den nachfolgenden Verkehr; vor Weiterfahrt reparieren","Bei Zweifadenlampen kann auch das Rücklicht derselben Seite betroffen sein"],"k":["left_brake_lamp","body_control_module"],"r":["easy",1,[5,250],[0.2,1.5]],"f":"","x":["B0851","B0235"]},{"c":"B0851","t":"Bremsleuchte rechts Stromkreis","e":"Right Brake Lamp Circuit","d":"Veröffentlichte J2012-Tabellen überspringen B0851, und auch Serviceliteratur und NHTSA-Akten nennen ihn nie. Der Titel nennt den Stromkreis der rechten Bremsleuchte. Der Saab 9-3 der zweiten Generation prüft diese Leuchte bei jedem Bremsen und speichert B3878 04, sobald die rechte Lampe weniger als 50 mA aufnimmt; die hochgesetzte Leuchte bewertet er getrennt unter B3884 mit einer Grenze von 20 mA. Bleiben beide Seiten und die dritte Leuchte zugleich dunkel, liegt die Ursache meist davor – am Bremslichtschalter oder an einer gemeinsamen Sicherung – und nicht in einem einzelnen Leuchtenkreis. HELLA nennt bei heutigen, vernetzt angesteuerten Heckleuchten ausgefallene LED-Segmente und defekte Stecker als typische Befunde. FMVSS 108 verlangt funktionierende Bremsleuchten. Unverzüglich reparieren; links: B0850.","u":[["h","Lampe oder LED-Segment der rechten Bremsleuchte ausgefallen"],["m","Lockerer oder korrodierter Stecker an der rechten Heckleuchte"],["m","Leitung zur rechten Heckleuchte gebrochen"],["l","Lampentreiber im hinteren Steuergerät defekt"]],"s":["Rechte Bremsleuchte dunkel, linke und dritte Bremsleuchte funktionieren","Bremslichtwarnung im Display","Schwächeres Bremssignal an nachfolgende Fahrer; sofort reparieren"],"k":["right_brake_lamp","body_control_module"],"r":["easy",1,[5,300],[0.2,1.5]],"f":"","x":["B0850","B0235"]},{"c":"B0860","t":"Kennzeichenleuchte Stromkreis","e":"License Plate Lamp Circuit","d":"B0860 ist in öffentlichen J2012-Auszügen nicht auffindbar, und kein Hersteller- oder Behördentext bezieht sich darauf. Der Titel beschreibt die Leuchte, die das hintere Kennzeichen anstrahlt. Im GM-Saab 9-5 (Modelljahr 2011) schaltet das Karosseriesteuergerät sie ein, sobald der Lichtschalter auf Stand- oder Abblendlicht steht, und speichert B3883 02 bei Masseschluss bzw. B3883 04 bei Unterbrechung. Der ältere Saab 9-3 verwendet dieselbe Nummer in der hinteren Elektrozentrale mit genannten Grenzen: Unterbrechung unter 20 mA, Kurzschluss über 3,5 A für mehr als 10 ms, danach wird der Ausgang abgeschaltet. FMVSS 108 definiert die Kennzeichenleuchte und schreibt sie vor. Eine dunkle Kennzeichenleuchte gefährdet die Fahrt nicht, ist aber ein Mangel, der bei Kontrollen auffällt.","u":[["h","Lampe der Kennzeichenleuchte durchgebrannt"],["m","Wasser im Leuchtengehäuse korrodiert die Kontakte"],["m","Leitungsbruch im Scharnierbereich des Kofferraumdeckels"],["l","Lampenausgang des Karosserie- oder Hecksteuergeräts defekt"]],"s":["Kennzeichen bei eingeschaltetem Licht nicht beleuchtet","Lampenwarnung im Display","Kennzeichenleuchte bleibt bei manchen Kurzschlüssen dauernd an"],"k":["license_plate_lamp","body_control_module"],"r":["easy",1,[5,150],[0.2,1]],"f":"","x":["B0239","B0850"]},{"c":"B0900","t":"Scheibenwischermotor vorn Stromkreis","e":"Wiper Motor Front Circuit","d":"Offene J2012-Unterlagen, Werkshandbücher und NHTSA-Bulletins haben keinen Eintrag für B0900; er ist unbestätigt. Der Titel betrifft den Stromkreis des Frontwischermotors. Saab-Modelle aus der GM-Zeit prüfen ihn an den Relais: Der 9-3 setzt B3874 06 bzw. B3875 06, wenn der Ausgang für das Relais der langsamen oder schnellen Stufe unter 6 V bleibt – die Wischer stehen, laufen dauernd oder nur schnell. Der GM-Saab 9-5 von 2011 meldet B3715 und B3875 für die Relais-Steuerleitungen und B371A, wenn das Signal des Parkschalters nicht zur Schalterstellung passt. FMVSS 104 verlangt zwei Stufen: eine mit mindestens 45 Takten pro Minute, eine langsamere mit mindestens 20, Abstand 15. Bosch baut bürstenlose und reversierende Antriebe; TI fordert Positionsregelung mit Blockiererkennung. Heckwischer: B0910.","u":[["h","Wischerrelais klebt oder hat verbrannte Kontakte"],["m","Wischermotor verschlissen oder Parkschalter defekt"],["m","Festgegangenes Gestänge überlastet den Motor"],["l","Beschädigte Leitung im Wasserkasten"]],"s":["Wischer laufen nicht, laufen dauernd oder nur in einer Stufe","Wischer bleiben außerhalb der Parkstellung stehen","Schlechte Sicht bei Regen; bei Nässe erst nach Reparatur fahren"],"k":["front_wiper_motor","wiper_relay","body_control_module"],"r":["medium",1,[20,500],[0.3,2.5]],"f":"","x":["B0910","B0920","B0220","B0190","B0192"]},{"c":"B0910","t":"Scheibenwischermotor hinten Stromkreis","e":"Wiper Motor Rear Circuit","d":"Eine öffentliche Definition von B0910 fehlt in J2012-Auszügen ebenso wie in Hersteller- und NHTSA-Dokumenten. Der Titel betrifft den Stromkreis des Heckwischermotors. Beim Saab 9-3 der Baureihe 9440 steuert die hintere Elektrozentrale ihn über ein Relais an und speichert B3720: 01, wenn der Ausgang bei Ansteuerung über 6 V liegt – der Wischer arbeitet nicht –, und 06, wenn er bei ausgeschaltetem Wischer über 6 V liegt; ein Masseschluss lässt den Wischer dann dauernd laufen, eine Unterbrechung legt ihn still. Beim Bosch-Heckwischer treibt eine kompakte Antriebseinheit einen einzelnen Wischarm direkt an. TI fordert für Wischerantriebe Blockiererkennung und geringe Verluste. Anders als vorn (B0900) schreibt keine Sicherheitsnorm ihn vor; ein Ausfall betrifft Komfort und Sicht nach hinten.","u":[["h","Leitungsbruch im Kabelstrang am Heckklappenscharnier"],["m","Heckwischermotor oder Welle durch Korrosion festgegangen"],["m","Heckwischerrelais defekt"],["l","Relaistreiber im hinteren Steuergerät defekt"]],"s":["Heckwischer läuft beim Einschalten nicht","Heckwischer läuft nach dem Ausschalten weiter"],"k":["rear_wiper_motor","body_control_module"],"r":["easy",1,[20,350],[0.3,2]],"f":"","x":["B0900","B0188","B0920"]},{"c":"B0920","t":"Wischwasserpumpe Stromkreis","e":"Washer Pump Circuit","d":"B0920 hat keine prüfbare Quelle: Er fehlt in J2012-Auszügen und in jeder veröffentlichten Serviceinformation. Der Titel betrifft den Stromkreis der Wischwasserpumpe. Beim GM-Saab 9-5 von 2011 startet das Karosseriesteuergerät die Pumpe zusammen mit der langsamen Wischstufe, sobald der Waschschalter schließt; bei 9 bis 16 V Bordspannung überwacht es die Relais-Steuerleitung, legt bei Masseschluss B3873 02 ab und setzt das Waschen aus. Die Scheinwerferreinigung ist dort ein eigener Kreis (B3810), läuft nur bei Abblend- oder Fernlicht und pausiert danach für 4 Waschvorgänge oder 48 Stunden. Der 9-3 setzt B3873 06, wenn sein Relaisausgang unter 6 V bleibt. FMVSS 104 schreibt Pkw eine Scheibenwaschanlage vor; HELLA beschreibt Kreiselpumpen im Behälter solcher Anlagen. Wischer: B0900, B0910.","u":[["h","Pumpenmotor festgegangen, oft nach Trockenlauf oder Frost"],["m","Korrodierter Stecker an der Pumpe im Radhaus"],["m","Waschrelais oder dessen Steuerleitung defekt"],["l","Relaistreiber im Karosseriesteuergerät defekt"]],"s":["Beim Betätigen des Waschschalters kommt kein Wasser","Waschpumpe läuft dauernd","Bei gemeinsamem Kreis fällt auch die Scheinwerferreinigung aus"],"k":["washer_pump","body_control_module"],"r":["easy",1,[20,200],[0.3,1.5]],"f":"","x":["B0900","B0910"]},{"c":"B0950","t":"Heckscheibenheizung Stromkreis","e":"Heated Rear Window Circuit","d":"Keine der zugänglichen J2012-Listen, Werkstattunterlagen oder NHTSA-Bulletins erwähnt B0950; er ist daher unbelegt. Der Titel betrifft die elektrisch beheizte Heckscheibe. Saab-Modelle aus der GM-Zeit überwachen diese Heizung unter anderen Nummern: Beim 9-5 von 2011 bestromt das Klimasteuergerät die Relaisspule, die Batteriespannung auf das Heizgitter schaltet, und Fehler dieser Steuerleitung erscheinen als B0283. Der 9-3 prüft den Relaisausgang in der hinteren Elektrozentrale (B0283 06 unter 6 V) und die Kontrollleuchte im Taster getrennt (B0969 02 über 1 A). Ein gerissener Heizfaden lässt meist nur einen Teil der Fläche kalt, Relais- oder Versorgungsfehler legen die Heizung ganz still. Folge ist vor allem schlechte Sicht nach hinten bei Kälte oder Nässe.","u":[["h","Unterbrochener Heizfaden oder gelöste Anschlussfahne an der Scheibe"],["m","Relais der Heckscheibenheizung defekt"],["m","Leitungsbruch im Kabelstrang von Heckklappe oder Kofferraumdeckel"],["l","Ausgang des Klima- oder Karosseriesteuergeräts defekt"]],"s":["Heckscheibe wird bei eingeschalteter Heizung nicht frei","Nur einige Heizfäden werden warm","Kontrollleuchte im Taster leuchtet nicht"],"k":["rear_window_heating_element","rear_defrost_relay","body_control_module"],"r":["easy",1,[10,400],[0.3,2]],"f":"","x":["B0283","B0610"]},{"c":"B0960","t":"Einparkhilfe Sensor hinten rechts Mitte Stromkreis","e":"Parking Assist Rear Sensor Right Middle Circuit","d":"B0960 steht in keiner der zugänglichen J2012-Listen; belegt ist er bei GM und den Saab-Modellen der GM-Zeit als mittlerer rechter Parksensor hinten. Der Saab 9-5 und 9-4X von 2011 führen B0960 01 (Schluss nach Plus), 06 (Spannung zu niedrig oder Unterbrechung), 08 (ungültiges Signal), 21 (falsche Periode) und 3A (falsches Bauteil verbaut); B0958, B0959 und B0961 decken die übrigen Sensoren hinten ab. Der ältere 9-3 nutzt B0960 für seinen rechten mittleren Abstandssensor und prüft ihn bei eingelegtem Rückwärtsgang und mehr als 9 V; bei einem Fehler stellt die Anlage die Messung ein und schaltet die Warntöne ab. Laut Bosch senden solche Sensoren kurze Ultraschallimpulse aus und geben die Echos an ein zentrales Steuergerät weiter, Reichweite bis 5,5 m. Das Hupenrelais überwachen dieselben Hersteller dagegen als B2750.","u":[["h","Sensorfläche verschmutzt, vereist oder abgedeckt"],["m","Ultraschallsensor defekt oder falsches Teil verbaut"],["m","Stoßfänger-Kabelstrang nach Parkrempler oder Reparatur beschädigt"],["l","Steuergerät der Einparkhilfe defekt"]],"s":["Einparkhilfe schaltet sich beim Rückwärtsfahren mit Meldung ab","Keine Warntöne, obwohl ein Hindernis nah ist","Hindernisse hinter dem Auto bis zur Reparatur selbst prüfen"],"k":["parking_assist_sensor","parking_assist_module"],"r":["medium",1,[20,400],[0.3,2]],"f":""},{"c":"B0970","t":"Innenraumbeleuchtung Stromkreis","e":"Interior Light Circuit","d":"B0970 ist nirgends öffentlich dokumentiert, weder in J2012-Auszügen noch in Werkstattliteratur oder NHTSA-Bulletins. Der Titel betrifft den Stromkreis der Innenbeleuchtung. Im Saab 9-3 (2003–2012) wacht das Karosseriesteuergerät darüber: B2556 02, wenn mehr als 10 A über die Lampenversorgung fließen, B2555 0F, wenn die Leuchten Spannung führen, obwohl sie aus sein sollten, und B2610 02, wenn die gedimmte PWM-Leitung unter 2,0 V fällt. Im GM-Saab 9-5 (2011) wird eine an Masse liegende Versorgung der Innenleuchten als B2615 02 gemeldet; das Steuergerät schaltet sie dann nicht mehr an und löscht den gespeicherten Eintrag nach 100 fehlerfreien Zündzyklen. HELLA warnt, dass Lampen höherer Leistung Leuchte und Verkleidung überhitzen. Eine dauernd brennende Innenleuchte kann die Batterie über Nacht entladen.","u":[["h","Türkontaktschalter hängt und hält die Leuchten an"],["m","Kurzschluss in Dach- oder Fußraumleuchte, oft nach Lampentausch"],["m","Durchgescheuerte Leitung im Dachhimmel oder an der A-Säule"],["l","Leuchtenausgang des Karosseriesteuergeräts defekt"]],"s":["Innenbeleuchtung bleibt beim Öffnen einer Tür aus","Innenbeleuchtung leuchtet dauernd","Batterie nach einer Nacht Standzeit leer"],"k":["interior_lamp","body_control_module"],"r":["easy",1,[10,250],[0.3,2]],"f":"","x":["B0260"]},{"c":"B0980","t":"Zündschalter Run/Start-Position Stromkreis","e":"Ignition Switch Run/Start Position Circuit","d":"Öffentliche Quellen geben B0980 keine Bedeutung: J2012-Auszüge sowie Hersteller- und NHTSA-Dokumente lassen ihn aus. Der Titel betrifft das Signal, mit dem der Zündschalter die Stellungen Fahrt und Start meldet. Saab-Fahrzeuge aus der GM-Zeit nutzen dafür andere Nummern: Das Lenksäulenmodul des 9-3 setzt B1440 0F, wenn die Klemme-15-Versorgung vom Zündschaltermodul unterbrochen ist, und B1368 00 bei Schluss dieses Eingangs nach Plus; in beiden Fällen sperrt es den Anlasser und deaktiviert die Lenkradsperre. Der GM-Saab 9-5 von 2011 bestromt in Fahrt- und Startstellung ein Zündungsrelais und speichert B144A 02 bei Masseschluss der Steuerleitung – der Motor springt nicht an oder läuft nach Abziehen des Schlüssels weiter. FMVSS 114 regelt das schlüsselbetätigte Startsystem und dessen Diebstahlschutz.","u":[["h","Verschlissene Kontakte im Zündschalter"],["m","Zündungsplus-Leitung unterbrochen oder kurzgeschlossen"],["m","Zündungsrelais oder dessen Steuerleitung defekt"],["l","Niedrige Batteriespannung erzeugt unplausible Signale"]],"s":["Anlasser dreht nicht, obwohl der Schlüssel gedreht wird","Zündung lässt sich nicht ausschalten oder Schlüssel nicht abziehen","Lenkradsperre oder Verbraucher verhalten sich unstet"],"k":["ignition_switch","body_control_module"],"r":["medium",0,[60,600],[0.5,3]],"f":"","x":["B0990"]},{"c":"B0990","t":"Karosserie-Steuergerät Interner Fehler","e":"Body Control Module Internal Fault","d":"Für B0990 existiert weder in J2012-Listen noch in Hersteller- oder NHTSA-Unterlagen ein öffentlicher Beleg. Der Titel beschreibt einen selbst erkannten Fehler im Inneren des Karosseriesteuergeräts. Saab-Modelle aus der GM-Zeit melden das als B1000 oder B101D: Beim 9-5 von 2011 läuft der interne Test bei jedem Einschalten, das Gerät nimmt bei einem Fehler keine weiteren Eingaben an, und ein gespeicherter Eintrag erlischt nach 50 fehlerfreien Zündzyklen; getauscht wird nur, wenn der Code aktuell ansteht. Das BCM des 9-3 speichert B1000 37 bei einem internen Zeitüberlauf, und sein Lenksäulenmodul legt B3985 ab, wenn der Wegfahrsperren-Code nicht ins BCM geschrieben werden kann. TI zählt Leerlauf- und Kurzschlusserkennung sowie Notlauf zu den Kernaufgaben eines BCM. Vor dem Tausch Versorgung und Masse prüfen.","u":[["h","Schlechte Versorgungsspannung oder Masse am Steuergerät"],["m","Feuchtigkeit oder Korrosion im Steuergerät"],["m","Beschädigte oder veraltete Steuergeräte-Software"],["l","Interner Elektronikdefekt des Steuergeräts"]],"s":["Mehrere Karosseriefunktionen fallen zugleich aus, etwa Licht, Schlösser oder Wischer","Fahrzeug startet nicht, wenn die Wegfahrsperren-Daten nicht lesbar sind","Code nur als Historie gespeichert, ohne spürbare Auswirkung"],"k":["body_control_module"],"r":["hard",0,[100,1200],[1,4]],"f":"","x":["B0980"]}];
